UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parlez à Kanrethad pour que vos talents, votre arme et votre monture vous soient rendus.' WHERE l.`ID` = 1 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La quête de Kanrethad' WHERE l.`ID` = 1 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Bon retour du monde des morts.$B$BIl y a bien longtemps, vous étiez $gdroit et fier, un héros:droite et fière, une héroïne; parmi les vôtres. Aujourd’hui, vous êtes $gdéchu et brisé:déchue et brisée;, une relique du passé. Tenez-vous devant moi, pendant que j’éveille la légende que vous étiez autrefois.$B$BJe vous rendrai les armes et les pouvoirs que vous avez perdus, et vous serez à nouveau $gcomplet:complète;.' WHERE l.`ID` = 1 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez 12 Champignons magenta à Ghak Touchesoins, à Thelsamar.' WHERE l.`ID` = 17 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Rechercher les composants à Uldaman' WHERE l.`ID` = 17 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'On a découvert récemment une nouvelle plante : les champignons magenta. Ils poussent en grappes au site de fouilles d\'Uldaman ; on les trouve dans les premiers tunnels et loin dans des zones moins explorées. Je veux étudier leur utilité éventuelle en alchimie, et c\'est là que vous entrez en scène.$B$BTrouvez les champignons magenta et rapportez-m\'en une douzaine. Attention, les grappes peuvent projeter des spores vénéneuses quand on les manipule !$B$BRendez-moi ce service et je sortirai pour vous un petit élixir revigorant de derrière les fagots.' WHERE l.`ID` = 17 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parlez à Dendrite Brasétoile, au village de Havrenuit, à Reflet-de-Lune.' WHERE l.`ID` = 26 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Une leçon à apprendre' WHERE l.`ID` = 26 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '$n, j\'ai suivi votre progression avec beaucoup de plaisir. Vous êtes assurément en train de devenir $gun véritable gardien et protecteur:une véritable gardienne et protectrice; de la nature.$B$BLe temps est venu pour vous d\'en apprendre plus à propos de l\'une des nombreuses formes animales que nous pouvons revêtir et dont nous gratifie Cénarius. Un aspect qui vous permettra de maîtriser l\'eau. Pour cela, vous devez voyager jusqu\'au village de Havrenuit, à Reflet-de-Lune, et parler à Dendrite Brasétoile, du Cercle cénarien. Il vous guidera plus avant.' WHERE l.`ID` = 26 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`AreaDescription` = 'Accomplir l\'épreuve du lac' WHERE l.`ID` = 28 AND l.`locale` = 'frFR' AND (l.`AreaDescription` IS NULL OR l.`AreaDescription` = '' OR BINARY l.`AreaDescription` = BINARY q.`AreaDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Trouvez un Colifichet du sanctuaire dans le Lac Élune\'ara, et apportez-le au sanctuaire de Remulos, au nord-ouest de Reflet-de-Lune. Une fois sur place, utilisez le Colifichet du sanctuaire.$B$BVous devez parler à Tajarri, au sanctuaire, afin de terminer l’épreuve.' WHERE l.`ID` = 28 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'épreuve du lac' WHERE l.`ID` = 28 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir Tajarri au Sanctuaire de Remulos, en Reflet-de-Lune.' WHERE l.`ID` = 28 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Pour la première épreuve, vous devrez aller fouiller les profondeurs du lac Élune\'ara, et trouver un Colifichet du sanctuaire. Attention, il se corrompt rapidement ; aussi, ne tardez pas à l\'apporter au sanctuaire de Remulos. Utilisez le Colifichet sur le sanctuaire puis parlez à Tajarri ; elle est l\'un des gardiens les plus fiables de Reflet-de-Lune.$B$BVous devez réussir cette quête avant l\'expiration du temps imparti, et vous serez peut-être en concurrence avec d\'autres druides, également à la recherche de colifichets. Il vous faudra user de ruse et de dextérité pour réussir dans cette mission.$B$BBonne chance, $n.' WHERE l.`ID` = 28 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez le Rapport à Zilzibin Kongadok, à Orgrimmar.' WHERE l.`ID` = 32 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'ascension des silithides' WHERE l.`ID` = 32 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Voici votre rapport. Je vous demande de l\'apporter de toute urgence à quelqu\'un qui a de l\'expérience dans ce domaine.$B$BJe connais un troll érudit du nom de Zilzibin Kongadok. Il a passé beaucoup de temps à étudier les formes de vie exceptionnelles de l\'écologie d\'Azeroth ; de plus, c\'est un historien ! Si vous voulez rencontrer quelqu\'un capable de comprendre la nature de ce danger et comment l\'arrêter, apportez-lui ce rapport. Nous allons avoir besoin de toute l\'aide disponible.$B$BZil réside dans une maison sur le niveau supérieur de la Herse, à Orgrimmar.' WHERE l.`ID` = 32 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Rapportez de l\'Eau de source sacrée à Tristevin Tonnebière.' WHERE l.`ID` = 48 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Doux whisky' WHERE l.`ID` = 48 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Dans la campagne du Sud, là où la vigne pousse, en rampant et se tordant$bSe cache un puits où l\'eau coule profondément$bAussi pure que la Sœur sacrée de la Lumière, elle est$bApportez-moi un peu de cette eau sacrée.' WHERE l.`ID` = 48 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Tristevin Tonnebière vous a demandé un Sac d\'orge, un Sac de seigle et un Sac de maïs.' WHERE l.`ID` = 49 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Doux whisky' WHERE l.`ID` = 49 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Le whisky, de ma vie est le plus ancien amour$bComme les étoiles qui durent pour toujours$bRapportez-moi, pour que mon amour revienne majestueux tel un aigle$bUn sac de chacune de ces céréales : orge, maïs et seigle.' WHERE l.`ID` = 49 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Abattez la Manifestation d\'eau corrompue et placez les Bracelets de manifestation corrompue avec le reste d\'eau pure sur le brasero de la Fontaine éternelle, dans la forêt des Pins-Argentés.' WHERE l.`ID` = 63 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'appel de l\'eau' WHERE l.`ID` = 63 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Le long de la côte de la forêt des Pins-Argentés, à l\'ouest du Sépulcre, vous trouverez un autel qui a été corrompu. Les esprits n\'y parlent plus aux gens. Vous devez résoudre le problème en purifiant l\'autel.$B$BPrenez ces bracelets élémentaires et la potion de Brine, placez-les sur le brasero de l’autel. Ce rituel devrait suffire à invoquer un esprit pur à qui vous pourrez parler.$B$BRapportez-moi une preuve de votre réussite, et je vous récompenserai avec un totem.' WHERE l.`ID` = 63 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Allez voir le Greffier Daltry, à l\'hôtel de ville de Sombre-Comté.' WHERE l.`ID` = 66 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La légende de Stalvan' WHERE l.`ID` = 66 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'La nuit dernière, j\'ai eu un mauvais pressentiment concernant ma petite-fille Alyssa. Elle serait en grand danger. J\'ai tiré les cartes et la lame de la Faucheuse est sortie.$b$bAprès une longue et sombre transe, j’ai obtenu un indice. Un nom est apparu : Stalvan.$b$bAllez voir un greffier de la mairie et trouvez plus de détails sur ce personnage. J\'ai peur pour tout le monde…' WHERE l.`ID` = 66 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Recherchez un indice dans le tas d\'affaires.' WHERE l.`ID` = 72 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La légende de Stalvan' WHERE l.`ID` = 72 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Mon père fut le gardien de cette propriété bien avant que je ne le sois. Il a dû tout nettoyer après le massacre.$b$bLes derniers fonds des Silecrête ont fondu comme neige au soleil. Le reste des affaires de la famille va partir aux enchères. La faute à ces vautours des impôts. J\'imagine que vous êtes $gimpatient:impatiente; de voir ce qu\'il y a, vous pouvez regarder dans le tas de vieilleries. Si ça se trouve, quelque chose vous intéressera.' WHERE l.`ID` = 72 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Récupérez 10 bouteilles de Houle au miel des Hinterlands dans des caisses se trouvant aux environs de la base abandonnée de la Horde, au rocher de l’Affût.' WHERE l.`ID` = 77 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Une situation délicate' WHERE l.`ID` = 77 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Je possède l’emballage d’origine nécessaire pour conditionner la Houle que Dran Droffers recherche. Je vais vous aider à l’emballer pour le père de Malton, à l\'humeur si caustique… contre deux bouteilles de la susnommée Houle. Les bouteilles se trouvent dans une caisse, dans une base abandonnée de la Horde, près du rocher de l’Affût.$B$BLa tâche sera ardue : d’immondes gelées et même des limons infestent les ruines. On dit que ces créatures seraient commandées par une sorte de limon en chef. Quoi qu’il en soit, procurez-vous la Houle et revenez me voir ici pour la conditionner.' WHERE l.`ID` = 77 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Prenez la Page de journal décolorée et montrez-la à Smitts l\'aubergiste à Sombre-Comté, au Bois de la Pénombre.' WHERE l.`ID` = 78 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La légende de Stalvan' WHERE l.`ID` = 78 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Je connais quelqu’un qui pourra peut-être vous aider. Quand je commandais les gardes de Hurlevent, nous avions l\'habitude d\'aller boire un coup à la taverne du Corbeau écarlate, à Sombre-Comté. L\'aubergiste, Smitts, connaît nombre d\'histoires sur la région. Montrez-lui cette page, et voyez ce qu\'il vous dira.' WHERE l.`ID` = 78 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Portez les pages au Commandant Bouclenoire.' WHERE l.`ID` = 79 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La légende de Stalvan' WHERE l.`ID` = 79 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Je m\'intéresse à l\'histoire de ce personnage, Stalvan, depuis des années. Le jour où ces nobles de passage furent massacrés, il y a quelques années, je suis venu avec Haggard pour enquêter. J\'ai trouvé ces pages boueuses, mais je n\'ai jamais pu faire le lien avec l\'écriture de cet homme fou dans les bois. Ce que vous m\'apportez là, prouve de toute évidence qu\'il est coupable. Portez immédiatement cela au commandant Bouclenoire et racontez-lui ce que vous avez découvert !' WHERE l.`ID` = 79 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Montrez au Greffier Daltry la Page de journal maculée de sang.' WHERE l.`ID` = 80 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La légende de Stalvan' WHERE l.`ID` = 80 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'J\'avais déjà l\'œil sur ce sale type, Stalvan. Mais si les écritures concordent, alors cela prouve sans l\'ombre d\'un doute qu\'il est coupable.$b$bAvec toutes ces journées à tenir le registre de la ville, le Greffier Daltry est devenu un expert dans l\'identification des écritures. Montrez-lui ces pages pour vérifier si les écritures concordent avec la signature présente sur le registre.' WHERE l.`ID` = 80 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Livrez le tonneau à Dran Droffers, à Orgrimmar.' WHERE l.`ID` = 81 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La livraison de Houle' WHERE l.`ID` = 81 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'J\'ai pris la peine de mettre à l\'abri dans le tonneau, en plus de la houle emballée de Dran, les bouteilles supplémentaires qu\'il veut faucher pour son propre compte. Je n\'aime pas beaucoup Dran, mais il n\'y a rien de pire que de la houle éventée. Ne vous donnez pas la peine de me remercier.$B$BAllez maintenant livrer le baril à Dran Droffers, à sa boutique d\'Orgrimmar. Et passez le bonjour à Malton ! Dites-lui que s\'il cherche d\'excellentes boissons et de sympathiques compagnons de beuverie, nous serions honorés de recevoir sa visite.' WHERE l.`ID` = 81 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez l\'Éclat d\'eau à Islen Oeil-des-rivières à l\'Escalier des marées, dans les Tarides.' WHERE l.`ID` = 96 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'appel de l\'eau' WHERE l.`ID` = 96 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Prendre l\'éclat. Prendre l\'éclat et donner la vie.$B$BDonner la vie et comprendre. Comprendre que l\'eau, c\'est la vie... La corruption détruit la vie.$B$BLe pouvoir de l\'eau protège et donne la vie.' WHERE l.`ID` = 96 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Prévenez le commandant Bouclenoire.' WHERE l.`ID` = 97 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
