UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'À la fin de votre incantation, une explosion lumineuse se produit. Le grésillement des gouttes dans les flammes s\'est arrêté, et vos sens reviennent à mesure que les esprits corrompus autour de vous sont détruits.' WHERE l.`ID` = 100 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
