UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Analyse des morceaux d\'insectes' WHERE l.`ID` = 110 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Je vais passer un peu de temps à examiner l\'équipement d\'analyse de Scrimshank... et remettre de l\'ordre dans ses effets personnels. J\'ai le sentiment que ces insectes vont nous faire subir bien d\'autres pertes.$B$BPourriez-vous aller voir si l\'alchimiste Pilonzugg a analysé les morceaux d\'insectes que nous lui avons envoyés ? S\'ils sont prêts, rapportez-les-moi.' WHERE l.`ID` = 110 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez le rapport au Grand géomètre Radiésthéflop à Gadgetzan. Obtenez une copie de ce rapport, comme l\'alchimiste Pilonzugg vous l\'a demandé.' WHERE l.`ID` = 113 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Analyse des morceaux d\'insectes' WHERE l.`ID` = 113 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Le grand géomètre Radiésthéflop doit être informé immédiatement. En fait... toute personne sachant lire doit voir ce rapport. Nous sommes confrontés à une menace très sérieuse et très grave non seulement pour Tanaris et Gadgetzan, mais si on ne s\'en occupe pas, pour tout le Sud de Kalimdor. Oups, et même pour tout Azeroth ; cette menace n\'a donné aucun signe de déclin.$B$BDemandez à Radiésthéflop de faire des copies du rapport pour que vous le distribuiez le plus largement possible. Tout le monde doit être informé de cette menace !' WHERE l.`ID` = 113 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
