UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'NON !$B$BPrenez-le, reprenez ce peigne, éloignez-le de moi !$B$BJe suis un monstre et personne ne peut me trouver le moindre charme !' WHERE l.`ID` = 154 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
