UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Apportez cette lettre à Ello Bouclenoire, le maire de Sombre-Comté.$B$BNous sommes de vieux amis… Et quand il lira ça et comprendra ce que vous avez fait pour moi, je suis sûr qu\'il sera tout aussi heureux que moi ! Ha ha !' WHERE l.`ID` = 160 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
