UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'appel de l\'eau' WHERE l.`ID` = 220 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Islen aura une nouvelle tâche à vous confier avant de vous récompenser d\'un totem. La fiole d\'eau que je vous ai donnée est nécessaire à l\'accomplissement de cette tâche.$B$BPartez à présent et trouvez-la. Nous nous reverrons un jour.' WHERE l.`ID` = 220 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
