UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Worgens dans les bois' WHERE l.`ID` = 223 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Voilà, $n. Portez ce message à maître Carevin.$b$b<Il sort promptement un morceau de parchemin décoloré et vous le tend.>$b$bEncore d’autres comme vous, et nous pourrons vaincre les Veilleurs ! Peut-être alors serions-nous en mesure d’achever l\'œuvre à laquelle si peu d\'entre nous se sont attelés.' WHERE l.`ID` = 223 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
