UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '<Il cherche quelques instants sur les étagères puis en sort un livre relié en cuir.>$b$bSi vous voulez en savoir plus, vous devriez parler à Althea, c\'est elle qui s\'est occupée du… problème… avec lui ces derniers temps.' WHERE l.`ID` = 227 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
