UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La fille qui survécut' WHERE l.`ID` = 229 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'J\'aurais dû vous le dire plus tôt…$b$bComment puis-je m\'exprimer…$b$bIl se peut que Morgan ait cru que sa famille tout entière était morte, mais en fait sa fille Sarah est Gardien à présent. Elle a toujours été troublée par les… circonstances... entourant la mort de son père. Peut-être pourriez-vous lui donner des nouvelles.' WHERE l.`ID` = 229 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez une Trousse d\'analyse de terrain à l\'Apothicaire Zinge à Fossoyeuse.' WHERE l.`ID` = 238 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Course pour l\'apothicaire Zinge' WHERE l.`ID` = 238 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'La trousse est prête, $n. L\'apothicaire Zinge souhaite sûrement l\'avoir le plus vite possible. Apportez-la-lui sans tarder et dites-lui que j\'ai mis cela sur le compte de la Société. Passez-lui également mes plus sincères salutations.$B$BEh bien, ne restez pas là. C\'est pourtant simple d\'être coursier, non ?' WHERE l.`ID` = 238 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La chasse achevée' WHERE l.`ID` = 247 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Enquêtez près de la rampe est du barrage et rapportez à l\'ingénieur en chef Hinderweir un indice qui permettrait de deviner les intentions des nains sombrefers.' WHERE l.`ID` = 250 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Une sombre menace se dessine' WHERE l.`ID` = 250 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Grâce au Ciel, quelqu\'un s\'inquiète pour le barrage ! D\'abord la destruction du viaduc de Thandol, ensuite le pillage de Dun Modr ! Je suis sûr que le barrage est la prochaine cible des Sombrefers. La plus grande partie de mon détachement de sécurité a été dépêché sur le front de l\'Alliance, y compris mon meilleur inspecteur.$b$bC\'est pourquoi j\'ai besoin de vous, $n. J\'ai aperçu quelques sapeurs sombrefers près de la rampe est du barrage. Enquêtez sur place, et rapportez un indice.' WHERE l.`ID` = 250 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez la Lettre à Ello à Sirra Von\'Indi.' WHERE l.`ID` = 251 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]La traduction de la lettre d\'Abercrombie' WHERE l.`ID` = 251 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Apportez la lettre que vous m\'avez donnée à Sirra Von\'Indi. C\'est un érudit en lettres anciennes. Si quelqu’un ici peut traduire ce message, c\'est lui !' WHERE l.`ID` = 251 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez la lettre traduite au seigneur Ello Bouclenoire.' WHERE l.`ID` = 252 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La traduction pour Ello' WHERE l.`ID` = 252 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Bon sang ! Si ce qui est écrit là est vrai, alors ce qu\'a fait Abercrombie est… incroyable.$B$BVous devez la transmettre à Ello.$B$BEt faites vite, car je crains qu\'un sort funeste n\'avance déjà vers notre ville...' WHERE l.`ID` = 252 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Tuez 8 Busards des montagnes et retournez auprès de Daryl le Jeune au Pavillon des Pérégrins.' WHERE l.`ID` = 257 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La fanfaronnade d\'un chasseur' WHERE l.`ID` = 257 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous voulez jouer $gau plus malin:à la plus maligne; avec Daryl l\'Intrépide, hein ? Vous avez perdu d’avance ! Bien sûr, vous êtes libre d\'essayer. Voilà un défi qui devrait être au-dessus de vos capacités, alors ne culpabilisez pas trop si vous n\'êtes pas à la hauteur.$b$bUn groupe de busards s\'est établi ici, au loch Modan. Pourquoi ne pas essayer d\'en désabuser quelques-uns ? Voilà le marché : si vous parvenez à remporter mon défi, je vous donne mon arc ou mon fusil.$b$b<Il vous jauge dédaigneusement.>$b$bVous n\'avez pas grand-chose à perdre, de toute façon...' WHERE l.`ID` = 257 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Tuez 10 Anciens sangliers des montagnes et retournez auprès de Daryl le Jeune au Pavillon des Pérégrins.' WHERE l.`ID` = 258 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le défi d\'un chasseur' WHERE l.`ID` = 258 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '$naf, c\'est ça ? Vous vous vantez d’avoir réussi le premier test, pas vrai ? Comme je vous l\'ai dit, ce n\'était pas grand-chose.$b$bVous devriez vous essayer à la chasse au sanglier. Croyez-moi, cela n\'a rien à voir avec la chasse au sanglier de la vallée des Frigères, alors prenez vos précautions.$b$bEt ne soyez pas $gdéçu:déçue; en cas d’échec. Je vous donnerai ma chemise si vous réussissez !$b$bÀ propos, je vous ai déjà raconté comment j\'ai reçu ma célèbre cicatrice ? Non ? C\'était il y a deux ans...' WHERE l.`ID` = 258 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à Kelt Thomasin.' WHERE l.`ID` = 259 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '<INUTILISÉ>' WHERE l.`ID` = 259 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Salut, $n. J\'ai entendu parler de vos exploits, et je dois admettre que c\'est un honneur pour moi de vous rencontrer. Je ne crois pas que vous connaissiez l\'histoire du vieux Kelt ? Eh bien, fut un temps où le vieux Kelt – Kelt Thomasin, tel est son nom – était considéré comme le meilleur chasseur du royaume. Peu de proies lui échappaient. Mais un jour, il devint totalement obnubilé par une histoire ancienne... un mythe. En fait, selon cette histoire, un énorme battrodon vivrait dans les eaux du lac. Balivernes, si vous voulez mon avis. Mais si cela vous intéresse, vous devriez parler à Kelt.' WHERE l.`ID` = 259 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Montrer le livre que vous avez trouvé à la ferme de Sven aux habitants de Sombre-Comté.' WHERE l.`ID` = 262 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La silhouette mystérieuse' WHERE l.`ID` = 262 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Je dois savoir qui était ce rôdeur que j\'ai vu dans les ombres, la nuit où ma famille a été tuée !$B$BJe vous en prie, $n, vous avez montré que vous êtes $gplein:pleine; de ressources, trouvez cet individu. Je dois apprendre les secrets qu\'il détient !$B$BJe n\'ai aucun autre indice que vous ne connaissiez déjà, mais tenez, prenez le livre que vous avez trouvé à la ferme. Peut-être quelqu\'un pourra-t-il faire un lien entre ce livre et son propriétaire.' WHERE l.`ID` = 262 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Voir si d\'autres habitants ont des indices concernant la Silhouette mystérieuse.' WHERE l.`ID` = 265 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La mystérieuse recherche se poursuit' WHERE l.`ID` = 265 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Je vous rends votre livre, $n, et vous souhaite bonne chance dans vos recherches. Si vous enquêtez auprès d\'autres personnes en ville, elles seront peut-être en mesure de vous fournir d’autres indices.$B$BEn attendant, en voici un : bien que l\'auteur de ce livre soit étranger à Sombre-Comté, le livre lui-même a été acheté ici.' WHERE l.`ID` = 265 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Chercher à l\'auberge des indices concernant la Silhouette mystérieuse.' WHERE l.`ID` = 266 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]Une enquête à l\'auberge' WHERE l.`ID` = 266 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Voici votre livre, et bonne chance dans votre quête.$B$BVous devriez aller jusqu\'à l\'auberge. Si celui que vous recherchez a passé quelque temps en ville, on l’a peut-être vu là-bas.' WHERE l.`ID` = 266 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Retourner voir Sven avec le journal complété de la Tremblote.' WHERE l.`ID` = 268 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Retourner voir Sven' WHERE l.`ID` = 268 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Le livre que vous avez trouvé n\'était écrit qu\'à moitié. J\'ai dû le laisser à l\'exploitation de Sven lorsque je me suis enfui jusqu\'ici…$B$BTenez, prenez la version complète de mon journal et donnez-la à Sven. Il décrit de manière plus exhaustive ce qu\'il s\'y est déroulé.$B$BCe journal a été ma seule compagnie durant ces dernières semaines, mais je vous le donne volontiers si cela m\'épargne d’affronter Sven et sa colère.' WHERE l.`ID` = 268 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'L\'Ingénieur en chef Hinderweir vous demande de nager jusqu\'à la base du barrage pour localiser le tonnelet de poudre et d\'y verser la mixture de désamorçage pour empêcher une explosion.' WHERE l.`ID` = 280 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Une sombre menace se dessine' WHERE l.`ID` = 280 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Tout à l\'heure, j\'ai découvert quelques insurgés sombrefers qui nageaient vers le barrage avec un tonnelet. Aucun Montagnard n\'était présent pour les arrêter ! J\'ai bien peur qu\'ils n\'aient placé de l\'hydroglycérine à la base du barrage et ça pourrait exploser à tout moment !$b$bMaintenant, j\'ai besoin de vous pour prendre ce produit et le mélanger au contenu du tonnelet avant qu\'il ne soit trop tard ! Vite !' WHERE l.`ID` = 280 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Continuez à fouiller les taudis des murlocs pour retrouver la Statuette de Menethil.' WHERE l.`ID` = 285 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
