UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'L\'inspection minutieuse de ces quelques taudis murlocs n\'a rien donné, mais vous sentez que vous touchez au but.$B$BLa statuette de Menethil doit forcément se trouver dans l’un des taudis situés au nord !' WHERE l.`ID` = 285 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez l\'Oeil maudit de Paleth à Glorin Front-d\'acier au Port de Menethil, dans les Paluns.' WHERE l.`ID` = 292 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'Œil de Paleth' WHERE l.`ID` = 292 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'En ouvrant le coffre, on trouve une sphère noircie, qui irradie une lumière à faire frémir. C\'est le trésor dont Fitzsimmons a parlé : un Oeil maudit de Paleth.$B$BApportez l\'Oeil maudit de Paleth au prêtre Glorin Front-d\'acier, un nain qui se trouve au port de Menethil. Demandez-lui comment lever la malédiction de l\'Oeil.' WHERE l.`ID` = 292 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Ormer Tressefer, de l\'Excavation de Whelgar, vous demande de tuer Grondecroc et de revenir avec l\'une de ses serres une fois la tâche accomplie.' WHERE l.`ID` = 296 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La vengeance d\'Ormer' WHERE l.`ID` = 296 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Lorsque vous étiez là-bas, j\'ai remarqué qu\'un de ces monstres se tenait à l\'écart des autres. Il était plus grand et plus menaçant. Je parie que c\'est lui qui a incité les autres à venir ici interrompre les fouilles.$b$bJ\'ai une dernière chose à vous demander, $n. Faites en sorte que Grondecroc réponde de ses crimes à la justice. Et compte tenu de la gravité de ses crimes, la justice dans ce cas, c\'est la mort ! Apportez-moi une de ses serres pour preuve de sa mort.' WHERE l.`ID` = 296 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
