UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Prouver votre valeur' WHERE l.`ID` = 421 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Dame Sylvanas a chargé Varimathras de la conquête des terres humaines et naines se trouvant vers le sud.$b$bMais Arugal, ci-devant charlatan de Dalaran et aujourd\'hui bête maudite du donjon d\'Ombrecroc, a tristement utilisé sa magie. Il a créé le chaos dans la forêt des Pins-Argentés qui est d\'une grande importance stratégique.$b$bJ\'ai besoin de quelqu\'un de doué dans les arts du combat pour rétablir l\'ordre. Prouvez-moi votre valeur en tuant 5 poils-blancs Ragelune. Ces bêtes dégénérées se trouvent généralement près de la route, en bas de la colline.' WHERE l.`ID` = 421 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
