UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Avant que vous n\'attaquiez l\'île de Fenris, faites un rapport au grand exécuteur Hadrec. Il aura sans doute les informations et l\'équipement complémentaires dont vous aurez besoin.' WHERE l.`ID` = 448 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
