UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Le montagnard Rochegar cherche des volontaires pour une mission dans Dun Algaz et les Paluns.$B$BSi vous voulez mouiller vos bottes dans cette terre détrempée au nord, allez parler à Rochegar à Dun Algaz. Dun Algaz est plus au nord sur la route, après la Tour de garde.' WHERE l.`ID` = 468 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
