UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '$n. Le clan des orcs Gueules-de-dragon montre sa puissance bien au-delà d\'Algaz. Le capitaine Rudepoing a demandé à parler à tous ceux qui sont prêts à s\'engager contre ces orcs. Il est à l\'intérieur du donjon, dans la salle de guerre.' WHERE l.`ID` = 473 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
