UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Les intentions de Dalaran' WHERE l.`ID` = 482 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Bien sûr ! Comment ai-je pu oublier ?$b$bMoulin-de-l’Ambre était l’un des sites sélectionnés par le Kirin Tor en raison des nœuds dormants d’énergie tellurique qu’il abrite. Les sorciers projettent sûrement de réactiver les nœuds et d’utiliser cette énergie pour un projet de grande envergure.$b$bNous ne pouvons les laisser faire…$b$bIl leur faudra beaucoup de puissance pour activer les zones d’énergie tellurique. Nous pouvons enrayer le processus en volant leurs pendentifs aux sorciers.$b$bRapportez cette information à Allister, il décidera de la suite.' WHERE l.`ID` = 482 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Rapporter 20 Crocs de Pins-tordus à Shayla Noctebrise, à l\'extérieur de Darnassus.' WHERE l.`ID` = 490 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '<INUTILISÉ>' WHERE l.`ID` = 490 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir la Sentinelle Shayla Noctebrise sur Teldrassil.' WHERE l.`ID` = 490 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Selon les ordres stricts du Conseil de Darnassus, j\'ai mis une prime sur la tête des Pins-tordus. Ce ne sont plus des amis de la forêt, mais des êtres corrompus et stupides qui représentent une menace pour toutes les créatures de la clairière.$b$bComme le conseil l\'a ordonné, vous serez récompensé si vous arrivez à éradiquer la menace furbolg de Kalidar. Apportez-moi leurs crocs comme preuve de leur destruction.' WHERE l.`ID` = 490 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter la Boisson spéciale de Johaan au Montagnard captif.' WHERE l.`ID` = 492 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Une peste nouvelle' WHERE l.`ID` = 492 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Selon le nécrogarde, un autre de ces montagnards nains insensés vient juste d\'être capturé. Le nécrogarde aime utiliser la cave de la taverne des Pendus comme cellule, jusqu\'à ce qu\'on puisse « correctement » s\'occuper des prisonniers.$b$bPourquoi n\'iriez-vous pas voir si le captif apprécie la boisson spéciale que j\'ai concoctée pour lui ? Elle contient un soupçon du traitement que la Dame noire réserve au reste d\'Azeroth.' WHERE l.`ID` = 492 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Rendez-vous à Moulin-de-Tarren et délivrez le message du nécrotraqueur Lesh à la Grande exécutrice Darthalia.' WHERE l.`ID` = 494 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]Prêts à frapper' WHERE l.`ID` = 494 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Taisez-vous et écoutez, $c.$b$bJ\'ai été envoyée ici pour surveiller la ville de Hautebrande. C\'est une mission de reconnaissance. Il est impératif que vous envoyiez immédiatement des nouvelles à la grande exécutrice Darthalia à Moulin-de-Tarren. Dites-lui que moi, le nécrotraqueur Lesh, je lui transmets le message suivant :$b$b« Le cri du corbeau retentit à l\'ouest. »$b$bSuivez la route vers l\'est et faites bien attention aux panneaux. Allons, vite, partez pour Moulin-de-Tarren, et en toute hâte !' WHERE l.`ID` = 494 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Aller à Moulin-de-Tarren et chercher l\'escouade dépêchée par Thrall.' WHERE l.`ID` = 497 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '<INUTILISÉ>' WHERE l.`ID` = 497 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Jeune, j\'étais entraîné au métier de gladiateur au donjon de Fort-de-Durn. J\'étais alors ami avec Taretha, la fille de ma nourrice, et maîtresse à l’époque du maudit bâtard Landenoire.$b$bLe passé est le passé, $n, mais les rumeurs de l\'activité humaine à Hautebrande m\'ont rappelé cette époque. J\'ai dépêché une petite escouade sur place pour enquêter et retrouver, si possible, un...objet...qui me fut donné par Taretha.$b$bEn vain, je le crains, mais peut-être...$b$bMes hommes devraient être déjà rentrés maintenant ; je veux que vous vous rendiez à Moulin-de-Tarren pour juger de la situation.' WHERE l.`ID` = 497 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Donner l\'Elixir de souffrance à Umpi.' WHERE l.`ID` = 499 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]L\'élixir de souffrance' WHERE l.`ID` = 499 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Cela va prendre un petit moment d\'associer ces ingrédients pour mettre au point ce qui s\'appellera l\'élixir de souffrance.$b$bNous y voilà ! Ah ! Rien de tel pour égayer une triste journée dans ces mornes contrées que d\'insuffler un peu de souffrance dans le monde.$b$bVoyons voir si notre petite potion produit l\'effet désiré.$b$bDonnez à mon assistant Umpi un avant-goût de ce que la Dame noire a prévu pour les humains et ceux du Fléau.' WHERE l.`ID` = 499 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Transmettre l\'information recueillie par Gol\'dir à Krusk à Moulin-de-Tarren.' WHERE l.`ID` = 506 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]L\'héritage de Landenoire' WHERE l.`ID` = 506 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Il y a quelques jours, j\'ai reçu la visite du leader de ce Syndicat. Son nom est Aliden Perenolde et il se prend pour le seigneur de ce pays. Il m\'a confié qu\'il voulait utiliser les orcs qui s\'insurgent contre lui comme esclaves, exactement comme le voulait son père et mentor, le méprisable Landenoire.$b$bPlus important : il est venu en compagnie de sa maîtresse, une petite femme nommée Elysa, qui portait autour du cou le pendentif que le Chef de guerre désire tant.$b$bPartez maintenant, je me débrouillerai pour régler mes affaires.' WHERE l.`ID` = 506 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez les Documents d\'annonce d\'attaque au Magistrat Maleb à Austrivage.' WHERE l.`ID` = 510 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]Documents d\'annonce d\'attaque' WHERE l.`ID` = 510 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Parmi ces documents se trouve une liste des marchandises commandées. Elle contient des requêtes ordinaires (nourriture, armes, vêtements), mais aussi des demandes moins conventionnelles (masques, huile, poison).$B$BMais ce qu\'il y a de plus remarquable est le caractère urgent de la commande. Ces marchandises étaient nécessaires à l\'exécution de ce qui est décrit dans le document comme une « mission importante contre Austrivage », et l\'on en avait besoin rapidement.' WHERE l.`ID` = 510 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter un Tonneau de Croquejarret brune à l\'Apothicaire Lydon à Moulin-de-Tarren.' WHERE l.`ID` = 517 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]L\'élixir d\'agonie' WHERE l.`ID` = 517 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Ce nouvel élixir est enfin prêt à être testé. Mais pourquoi gâcher une si bonne et si contagieuse peste sur une pauvre grenouille ou un chien famélique ? Amusons-nous un peu, au nom de dame Sylvanas.$B$BDescendez à Dun Garok. Vous connaissez les casernes où ces sales petits nains s’agitent partout ? Volez un tonneau de leur Croquejarret brune pour moi. Une fois que j\'aurai ce baril, nous pourrons commencer la fête, vous et moi, $n.' WHERE l.`ID` = 517 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Placer le Baril infecté sur le tapis pour les fermiers détenus comme otages.' WHERE l.`ID` = 524 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]L\'élixir d\'agonie' WHERE l.`ID` = 524 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'À côté, les nécrogardes détiennent quelques fermiers pris en otage. La grande exécutrice Darthalia suspectait qu\'un des stratèges de Hurlevent se cachait parmi eux. Apparemment, le pauvre militaire a été retrouvé mort dans les Maleterres la nuit dernière. Darthalia, toujours aux petits soins pour moi, a décidé de me laisser faire ce que je voulais avec les fermiers.$b$bJe pense qu\'il est temps de leur préparer une petite fête. Comme au bon vieux temps !$b$bPlacez ce baril infecté sur le tapis, dans leur pièce. Tournée générale de bière pestilentielle !' WHERE l.`ID` = 524 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez la Lettre décodée au Magistrat Maleb, à Austrivage.' WHERE l.`ID` = 525 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'D\'autres mystères' WHERE l.`ID` = 525 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'J\'ai déchiffré la lettre, mais je ne sais pas quoi en faire. Vous l\'avez trouvée chez des voleurs dans les collines d\'Alterac ? C\'est étrange…$b$bVous devriez la montrer au Magistrat d’Austrivage. Bien que cette lettre soit sibylline, Austrivage est la ville la plus proche d\'Alterac. Si un danger menace, alors il doit savoir.' WHERE l.`ID` = 525 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Amener la tête du vieux Noiraud à Vyrin Vent-vif au pavillon des pérégrins.' WHERE l.`ID` = 531 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La vengeance de Vyrin' WHERE l.`ID` = 531 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Par la Lumière ! N\'apportez pas de choses comme ça dans le pavillon… c\'est insalubre, insupportable, in… in… insalubre !$b$bSortez-moi ça de là, voulez-vous ? Personne ne veut voir votre fichu petit trophée, vraiment !' WHERE l.`ID` = 531 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter une Chope de bière brune d’Austrivage à Valik, au Camp du Syndicat.' WHERE l.`ID` = 535 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Eurrgh… Blessé et mourant, me voilà en face de l\'ennemi.$b$bVous me tuerez sans doute de toute façon, mais si vous m\'apportez de la bière brune d’Austrivage... Les gens de votre race ne boivent pas, non ? Je vous dirai ce que vous voulez savoir.' WHERE l.`ID` = 535 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter le Parchemin ensorcelé au Prospecteur Foudrepique à Forgefer.' WHERE l.`ID` = 554 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]Les Runes gravées' WHERE l.`ID` = 554 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Le prospecteur Foudrepique est un maître du décodage. Si vous lui apportez le parchemin que vous avez trouvé, alors, avec un peu de chance, il pourra en comprendre la signification. Foudrepique étudie en ce moment aux quartiers généraux des Prospecteurs, à Forgefer.$b$bEt quand vous le verrez, dites-lui que vous m\'avez parlé. Je lui ai envoyé beaucoup de choses dernièrement.' WHERE l.`ID` = 554 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Livrer le Sac de têtes de murlocs au maréchal Senterouge à Austrivage.' WHERE l.`ID` = 560 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]La preuve de Farren' WHERE l.`ID` = 560 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous savez, $n, je préférerais ne pas toucher à ces têtes… Puisque vous avez déjà les mains qui sentent le poisson, cela vous dérangerait-il de les livrer à Senterouge pour moi ?' WHERE l.`ID` = 560 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler au Lieutenant Farren Orinelle à Austrivage.' WHERE l.`ID` = 561 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]La preuve de Farren' WHERE l.`ID` = 561 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Veuillez informer le lieutenant Orinelle que j\'aimerais qu\'il concentre ses efforts sur les nagas qui infestent le Rivage oriental. Quand il aura obtenu des résultats, dites-lui qu\'il vienne en personne m\'en rendre compte.' WHERE l.`ID` = 561 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La Bibliothèque de Hurlevent' WHERE l.`ID` = 579 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
