UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'La carte montre Baie-du-Butin avec un « X » rouge dessiné précisément à l\'endroit où vous vous trouvez.$B$BLe texte gribouillé dit :$B$B« Vous devez préparer un camp à cet endroit et rester tranquilles. Attendez le signal du poste de commandement du sud avant d\'attaquer. Si quiconque approche, tuez-le. »' WHERE l.`ID` = 597 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
