UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La récupération de Houle' WHERE l.`ID` = 649 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'J\'ai un travail de récupération pour vous, et si vous êtes un amateur de Houle comme moi, vous l\'apprécierez sûrement. La Houle !$B$BMais c\'est une boisson, imbécile.$B$BIl reste une réserve de Houle au miel des Hinterlands dans un avant-poste abandonné de la Horde, qui date de l\'époque où il fonctionnait encore. On ne peut plus trouver d’aussi bonne Houle, aujourd\'hui. L\'un des hommes de paille de Malton est au courant et connaît la musique. Alors, vous allez vous rendre là-bas et m\'apporter une caisse de Houle emballée, et deux bouteilles pour ma collection. Parlez à Malton, il vous donnera tous les détails nécessaires.' WHERE l.`ID` = 649 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Acquérir des Echantillons non testés de 8 basilics, 8 hyènes et 8 scorpions. Rapporter la Trousse d\'analyse de terrain à l\'Ingénieur en chef Vizisanie à Gadgetzan avant que la source d\'énergie ne s\'épuise.' WHERE l.`ID` = 654 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Les échantillons du désert de Tanaris' WHERE l.`ID` = 654 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'L\'activation de la source d\'énergie fait briller et vibrer la trousse d\'analyse de terrain. Tout semble fonctionner comme prévu.$B$BJe vais l\'envoyer immédiatement.$B$BD\'après l\'ingénieur en chef Vizisanie, vous disposez à présent d\'un peu de temps pour récupérer les données dont vous avez besoin dans le désert de Tanaris.$B$BAllez le voir une fois votre tâche accomplie.' WHERE l.`ID` = 654 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Le lieutenant Nilzlix veut que vous récupériez les Cartes et les Journaux de bord de la « Folie de la vierge » et de « L\'Esprit des Pins-Argentés ».' WHERE l.`ID` = 662 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Sauvetage en haute mer' WHERE l.`ID` = 662 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'O\'Breen a conduit les bateaux dans la crique. Nous étions certains d\'y trouver le trésor. Le « Noir messager » a accosté sans encombre, mais à mesure que la « Folie de la vierge » et « L\'Esprit des Pins-Argentés » approchaient, le niveau de la mer a commencé à baisser. C\'est la chose la plus étrange que j\'aie jamais vue !$b$bLes deux bateaux se sont échoués sur quelque chose... Une sorte de temple dans les récifs. Puis ils ont coulé à pic ; une vraie tragédie.$b$bNous voulons récupérer leurs cartes maritimes et leurs journaux de bord avant de partir. Nous ne voulons pas que les autres puissent les récupérer !' WHERE l.`ID` = 662 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler au capitaine O\'Breen dans la Crique de Faldir, dans les Hautes-terres Arathies.' WHERE l.`ID` = 663 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Terre !' WHERE l.`ID` = 663 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Lolo voit $gun:une:r; minuscule $r ! Lolo fait toujours le guet !$b$bBienvenue dans la crique de Faldir. Le capitaine O\'Breen a dit qu\'on resterait que quelques heures. Juste le temps de récupérer le trésor et de rentrer à Baie-du-Butin.$b$bMais Lolo pense que ça va durer plus longtemps. Notre groupe a perdu deux navires. Pauvres « Esprit des Pins-Argentés » et « Folie de la vierge ». Au fond de la mer qu\'ils sont maintenant !$b$bLolo vous conseille de parler au capitaine O\'Breen si vous voulez rester ici.' WHERE l.`ID` = 663 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Le capitaine Tripacier de la crique de Faldir veut que vous tuiez 10 Écumeurs daguéchines et 3 Sorcières daguéchines.' WHERE l.`ID` = 664 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Chagrin noyé' WHERE l.`ID` = 664 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Argh, quelle horrible vie ! Je devrais être mort sous l\'eau, et pas assis ici près d\'un feu, respirant de l\'air frais.$b$bL\'équipage a tout fait pour sauver mon merveilleux « Folie de la Vierge ». Loué soit-il !$b$bO\'Breen a réussi à atteindre la rive, nous on n\'a pas été aussi chanceux. La mer s\'est carrément défilée sous nous, je le jure.$b$bÀ un instant on naviguait, l\'instant d\'après on était échoué sur un récif. Et ces créatures ! Elles ont tué tous les survivants. Saleté de nagas ! Je me suis évanoui, puis je me suis réveillé ici.$b$bJe veux que ces créatures meurent !' WHERE l.`ID` = 664 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`AreaDescription` = 'Défendre le professeur Phloppenthrope' WHERE l.`ID` = 665 AND l.`locale` = 'frFR' AND (l.`AreaDescription` IS NULL OR l.`AreaDescription` = '' OR BINARY l.`AreaDescription` = BINARY q.`AreaDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Escorter le professeur Phloppenthrope à la grotte et revenir.' WHERE l.`ID` = 665 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le trésor englouti' WHERE l.`ID` = 665 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir le Docteur Draunessieu dans la Crique de Faldir, dans les Hautes-terres Arathies.' WHERE l.`ID` = 665 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Maintenant que nous sommes des Écumeurs des Flots noirs accomplis, il est de notre devoir d\'aider M. O\'Breen à localiser le trésor perdu des elfes.$b$bDans ces eaux sombres, il est presque impossible de trouver les gemmes sans aide. Le docteur a conçu des lunettes spéciales qui pourraient nous être utiles. Il a besoin de les charger avec l’énergie magique de la pierre enchantée qui se trouve dans la grotte en haut de la colline.$b$bMais cette grotte est maudite ! Quand on s\'en approche, on se fait attaquer. Venez et protégez-moi, alors je pourrai transférer l\'énergie des pierres vers les lunettes.' WHERE l.`ID` = 665 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Le docteur Draunessieu, à la crique de Faldir, veut que vous rapportiez 10 Gemmes elfiques et que vous rapportiez ensuite les Lunettes de chasse aux gemmes.' WHERE l.`ID` = 666 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le trésor englouti' WHERE l.`ID` = 666 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Le trésor repose au fond de la mer depuis si longtemps que les gemmes se sont calcifiées en pierres. Mais le pouvoir contenu dans ces lunettes vous permettra de les localiser facilement.$B$BL\'ingéniosité gnome permet beaucoup !$B$BAussi, empruntez les lunettes de chasse aux gemmes, $n, et voyez si vous pouvez récupérer une partie du trésor perdu pour le capitaine O\'Breen.$B$BJ\'y plongerais bien moi-même mais... euh... des affaires scientifiques importantes nécessitent ma présence sur un sol dur et sec... euh... voilà, c\'est ça.' WHERE l.`ID` = 666 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`AreaDescription` = 'Défendre Shakes O\'Breen' WHERE l.`ID` = 667 AND l.`locale` = 'frFR' AND (l.`AreaDescription` IS NULL OR l.`AreaDescription` = '' OR BINARY l.`AreaDescription` = BINARY q.`AreaDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Protéger Shakes O\'Breen lors de l\'attaque.' WHERE l.`ID` = 667 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La mort venue d\'en bas' WHERE l.`ID` = 667 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir Shakes O\'Breen dans la Crique de Faldir, dans les Hautes-terres Arathies.' WHERE l.`ID` = 667 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Ça ne se présente pas bien. Il semble que les Daguéchines se regroupent pour une attaque.$B$BLes nagas ont la réputation d\'être impitoyables dans la bataille et ne cesseront d\'attaquer tant que je n\'aurai pas rencontré la mort.$B$BJe ne considère pas ma vie plus précieuse que celles des membres de mon équipage, mais vous devez aider à ma sauvegarde. L\'équipage ne pourra pas revenir à Baie-du-Butin seul et sans la connaissance que je possède des mers.$B$BLes nagas viendront de la mer. Je veux que vous restiez près de moi ici en haut pour parer leur attaque. Servez-vous du canon et repoussez-les.$B$BÊtes-vous $gprêt:prête;, $n ?' WHERE l.`ID` = 667 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter les Gemmes elfiques au Capitaine O\'Breen à la Crique de Faldir, dans les Hautes-terres Arathies.' WHERE l.`ID` = 668 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le trésor englouti' WHERE l.`ID` = 668 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Ne faites pas attendre le capitaine O\'Breen. Il veut voir les gemmes. Après tout, c\'est quand même pour ça qu\'on est là !$b$bAprès ces quelques semaines passées avec les pirates, le professeur et moi-même pensons que la plus mauvaise chose qui pourrait nous arriver serait d\'être surpris à accaparer leur trésor.$b$bVoilà, $n, portez ceci à O\'Breen.' WHERE l.`ID` = 668 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Prenez l\'Échantillon de gemme elfique et apportez-le à l’Amiral Corne-de-Mer à Baie-du-Butin, dans la Vallée de Strangleronce.' WHERE l.`ID` = 669 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le trésor englouti' WHERE l.`ID` = 669 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'L\'amiral Corne-de-Mer voudrait voir le plus rapidement possible ce que vous avez trouvé.$b$bMais comme vous pouvez le constater, nous sommes un peu coincés ici. Primo la marée est trop basse, deuzio ces fichues créatures ne nous quittent pas des yeux.$b$bVous rendriez un immense service aux Écumeurs des Flots noirs si vous pouviez prévenir l\'amiral Corne-de-Mer à Baie-du-Butin que nous avons découvert le trésor, et que nous sommes en train de le remonter. Prenez cet échantillon en guise de preuve.' WHERE l.`ID` = 669 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Remettre la Lettre de Corne-de-Mer à Shakes O\'Breen à la Crique de Faldir, dans les Hautes-terres Arathies.' WHERE l.`ID` = 670 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le trésor englouti' WHERE l.`ID` = 670 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Dites, $n, vous semblez aimer l\'aventure. Ma flotte est bloquée à Baie-du-Butin pour cause de ravitaillement.$b$bIl y a des choses qui se trament dans le coin, et j\'ai besoin d\'envoyer une correspondance secrète à Shakes O\'Breen, qui a jeté l’ancre près des côtes arathies.$b$bPuis-je vous faire confiance pour remettre en toute confidentialité cette missive ?' WHERE l.`ID` = 670 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Donner l\'Amulette de griffe de raptor à Gor\'mul à Trépas-d\'Orgrim, dans les Hautes-terres Arathies.' WHERE l.`ID` = 674 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'éveil de l\'esprit' WHERE l.`ID` = 674 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Tenez, donnez cette amulette à Gor\'mul, et regardez si la force des raptors peut ranimer la flamme guerrière qui sommeille en lui.' WHERE l.`ID` = 674 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à Tor\'gan au Trépas-d\'Orgrim, dans les Hautes-terres Arathies.' WHERE l.`ID` = 675 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'éveil de l\'esprit' WHERE l.`ID` = 675 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '<Gor\'mul jette l\'amulette au sol.>$b$bTor\'gan vous envoie, c\'est ça ? Peuh ! Pourquoi est-il si miséricordieux avec moi. Ma propre miséricorde m\'a été enlevée le jour où je n\'ai pas pu mourir avec mon Chef de guerre au combat. Un mauvais coup du sort...' WHERE l.`ID` = 675 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à Zaruk au Trépas-d\'Orgrim, dans les Hautes-terres Arathies.' WHERE l.`ID` = 688 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Les alliés de Myzrael' WHERE l.`ID` = 688 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '<Myzrael parle.>$B$BLibre ! JE SUIS LIBRE ! Je suis libre de rassembler mes forces, hors de portée de mes ravisseurs. Si je les rencontrais maintenant, ils seraient sûrement plus forts que moi et me captureraient à nouveau.$B$BEn temps voulu, j\'affronterai les géants, et ils regretteront de m\'avoir bannie !$B$BVous êtes d’une aide précieuse, $n. J\'aurai encore besoin de vous. Quand je serai prête, j\'aurai besoin de vous pour m\'invoquer à la surface.$B$BParlez avec Zaruk au Trépas-d\'Orgrim. Il sait comment m\'invoquer.' WHERE l.`ID` = 688 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parlez à Skuerto au Refuge de l\'Ornière, dans les Hautes-terres Arathies.' WHERE l.`ID` = 695 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Enchantement d\'Apprenti' WHERE l.`ID` = 695 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Et voilà, $n. Il suffit d\'appuyer la gemme sur un des piédestaux près de la base de la tour, et ses défenses s\'activeront. Utilisez-la pour rentrer dans la tour quand vous serez $gprêt:prête; et allez chercher les autres objets de Trelane.$B$BBonne chance à vous ! Je vous attendrai au camp. Oh ! Parlez à Skuerto avant de partir. Il vous donnera tous les détails nécessaires.' WHERE l.`ID` = 695 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Porter la Lettre scellée à l\'archimage Malin dans le Quartier des Mages de Hurlevent.' WHERE l.`ID` = 697 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La demande de Malin' WHERE l.`ID` = 697 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Apportez cette lettre à Hurlevent et informez Malin que Kryten sera bientôt de retour. Il vous récompensera pour nous avoir aidés, $n, sans aucun doute.$B$BBon voyage.' WHERE l.`ID` = 697 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter 6 Griffes de Mordeurs Dents-de-scie à Tok\'Kar dans le marais des Chagrins.' WHERE l.`ID` = 699 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]Petit bonus du soir' WHERE l.`ID` = 699 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'En raison de la menace des murlocs le long des côtes, nous sommes stationnés ici pour repousser, ou au pire alerter s\'ils sont trop nombreux, toutes les menaces sur Pierrêche. Nous n\'avons pas vraiment le temps de respirer, donc si vous le souhaitez, vous pouvez rejoindre nos rangs pour nous aider.$B$BLes Griffes de Mordeurs Dents-de-scie sont un excellent matériau pour fabriquer des armes. Rapportez-m\'en quelques-unes et nous vous donnerons une de nos armes, de la viande fraîche et une bonne compagnie.' WHERE l.`ID` = 699 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Donner l\'Orbe de Tor\'gan à Gor\'mul au Trépas-d\'Orgrim, dans les Hautes-terres Arathies.' WHERE l.`ID` = 702 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La ruse du raptor' WHERE l.`ID` = 702 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Prenez cet orbe et utilisez sa magie pour insuffler à Gor\'mul l\'essence des raptors. Cela va revigorer son esprit et lui redonner goût à la vie. Lorsqu\'il sera comme avant, nous lui ferons un résumé de l\'activité de la Horde, et il comprendra que pour nos incessantes batailles nous avons besoin d\'un grand guerrier.' WHERE l.`ID` = 702 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter 3 Grands blocs de pierre à Lotwil Veriatus dans les Terres ingrates.' WHERE l.`ID` = 711 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Étude des éléments : la roche' WHERE l.`ID` = 711 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '$n, vous vous êtes déjà $gmontré:montrée; plus capable que tous mes apprentis réunis.$B$BLes prochains éléments dont j\'ai besoin nécessitent un peu plus de force. On trouve de grands blocs de pierre sur des élémentaires de roche, en étant prudent. Leurs corps sont plus forts et plus grands, et ainsi plus enclins à posséder des morceaux de taille suffisante pour mes tests. Ils se trouvent encore un peu plus à l\'ouest d\'ici, ou bien au sud-est le long des bords des montagnes.$B$BPrenez votre temps, je vais d\'abord effectuer des tests avec les plus petits morceaux que vous m\'avez apportés.' WHERE l.`ID` = 711 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter un Gyrochronatome à Lotwil Veriatus dans les Terres ingrates.' WHERE l.`ID` = 714 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Un gyro... quoi ?' WHERE l.`ID` = 714 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '$n, vous avez brillamment accompli votre travail.$B$B<Lotwil est visiblement obnubilé par son travail.>$B$BSi vous venez à Kharanos, n\'hésitez pas à venir me demander du travail.$B$BOups ! Vite ! Rattrapez-le... oui, ça là. Merci.$B$BMaintenant, j\'ai juste besoin d\'une dernière petite chose. C\'est un petit truc, mais c\'est indispensable, j\'en ai peur : un gyrochronatome.$B$BSi vous pouviez en récupérer un et me l\'apporter, alors je pourrais finir ceci.' WHERE l.`ID` = 714 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Trouver le Piolet porte-bonheur de Ryedol et le rapporter au Prospecteur Ryedol au sud du site de fouilles de Martèlorteil.' WHERE l.`ID` = 719 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Un nain et ses outils' WHERE l.`ID` = 719 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Bonjour, $n. Faites attention par ici. Y\'a des nains sombrefers partout : on aurait dit le clan Ombreforge.$B$BIls viennent d\'attaquer le site de fouilles où j\'travaillais... Ils ont tué presque tout le monde, y compris mon chef, Martèlorteil. J\'leur ai échappé de justesse.$B$BLe site se trouve juste au nord d\'ici, et j\'essaie de trouver un moyen d\'récupérer une partie de nos fournitures, mon piolet porte-bonheur surtout.$B$BVous croyez qu\'vous pourriez m\'aider ? L\'un d\'ces maudits Sombrefers a sûrement mon piolet ! Ça peut être n\'importe lequel.' WHERE l.`ID` = 719 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Trouver le Prospecteur Ryedol et lui dire que Martèlorteil Grez est en vie.' WHERE l.`ID` = 720 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Un signe d\'espoir' WHERE l.`ID` = 720 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Parlez au Prospecteur Ryedol dans les Terres ingrates.' WHERE l.`ID` = 720 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '<Des mots sont grossièrement écrits à la craie sur la carte.>$B$B« Ryedol, $BIls m\'emmènent à Uldaman. Envoie de l\'aide.$B-Martèlorteil »' WHERE l.`ID` = 720 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Porter l\'Amulette de Martèlorteil au Prospecteur Ryedol dans les Terres ingrates.' WHERE l.`ID` = 723 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Espérance en la foi' WHERE l.`ID` = 723 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '<Martèlorteil tient sa blessure et attend un moment pour reprendre son souffle avant de continuer.>$B$BTrouvez Ryedol, $n. Portez-lui l\'amulette. <toux toux> Il... <toux> saura quoi en faire. Il sait que je recherchais l\'origine de notre peuple, et il... <toux>... sait que c\'était ma mission que d\'arrêter le clan Ombreforge. Ils ne doivent pas s\'emparer de ces parchemins... <toux>' WHERE l.`ID` = 723 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter l\'Amulette de Martèlorteil à l\'Historien Karnik à Forgefer.' WHERE l.`ID` = 724 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Espérance en la foi' WHERE l.`ID` = 724 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Bon, alors... Qui pourrait savoir quoi en faire ?$B$BL\'historien Karnik ! Bien sûr !$B$BIl est à Forgefer. Lui pourra nous aider. Lui et Martèlorteil travaillaient ensemble pour retrouver des artéfacts perdus à Uldaman.$B$BJ\'imagine que le clan Ombreforge a découvert qu\'ils en savaient plus qu\'ils n\'le laissaient croire.$B$BRacontez à Karnik ce qui est arrivé à Martèlorteil et donnez-lui l\'amulette. Il vous dira quoi faire ensuite.' WHERE l.`ID` = 724 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Trouvez le Conseiller Belgrum et donnez-lui la Note.' WHERE l.`ID` = 725 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Avertir de la menace' WHERE l.`ID` = 725 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '$n, courez trouver le conseiller Belgrum aussi vite que vous le pourrez. Dites-lui ce que vous savez et demandez-lui ce que nous devons faire. Cette note lui donnera plus d’explications.$B$BPendant ce temps, je vais essayer d\'entrer en contact avec l\'esprit de Martèlorteil. Peut-être qu\'il sait quelque chose qui pourrait nous aider à mettre un terme aux activités de ces crétins d\'Ombreforge dans les Terres ingrates. Espérons-le.' WHERE l.`ID` = 725 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à l\'Historien Karnik.' WHERE l.`ID` = 726 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Avertir de la menace' WHERE l.`ID` = 726 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Parlez à l\'Historien Karnik à Forgefer.' WHERE l.`ID` = 726 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '<Le conseiller Belgrum achève de lire la note, et ses yeux s\'élargissent un moment.>$B$BHoula, très mauvaises nouvelles !$B$B$n, retournez voir l\'historien Karnik et dites-lui qu\'il agit sous l\'autorité du roi pour s\'occuper de cette affaire rapidement et avec fermeté. Il doit mettre un terme aux activités des Ombreforge dans les Terres ingrates.' WHERE l.`ID` = 726 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Aller à Auberdine et chercher des indices sur les nains de l\'équipe de fouilles.' WHERE l.`ID` = 730 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Des problèmes à Sombrivage ?' WHERE l.`ID` = 730 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Il est plaisant de voir qu\'$gun:une:c; $c s\'intéresse à l\'archéologie et aux grandes merveilles de notre monde.$b$bBien souvent, notre métier est considéré comme un simple passe-temps par nos amis de l\'Alliance. Mais ce que la plupart d\'entre eux ne comprennent pas, c\'est que les récentes découvertes dans Khaz Modan ont prouvé que de grandes et mortelles puissances menacent tout Azeroth, de Lordaeron en Kalimdor.$b$bJe suis vraiment inquiet pour le groupe que j\'ai envoyé à Sombrivage. Je suis sans nouvelles de lui depuis des semaines.$b$bAllez à Auberdine et cherchez des indices sur ce qu\'il lui arrive.' WHERE l.`ID` = 730 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à Lucien Torsaclef dans les Terres ingrates.' WHERE l.`ID` = 734 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Grandes difficultés' WHERE l.`ID` = 734 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Merveilleux, merveilleux.$B$B<Lotwil lève les yeux vers vous un instant avant de reprendre son travail.>$B$BAllez parler à Lucien, $n. J\'ai besoin d\'un rouage n° 5. Voulez-vous bien me l\'apporter ?' WHERE l.`ID` = 734 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez l\'Abrégé de Yagyin à Theldurin.' WHERE l.`ID` = 737 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le savoir perdu' WHERE l.`ID` = 737 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'J\'ai le livre pour vous, $n. Je n\'ai pas besoin de vous demander d\'en prendre le plus grand soin. Et de le garder hors de portée de nos ennemis.$B$BCe livre contient de nombreuses vérités...$B$B... Et la vérité peut vous consumer.' WHERE l.`ID` = 737 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
