UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le rite de vision' WHERE l.`ID` = 767 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Réussir le Rite de vision, un des rites de la Terre-mère, vous attirera le respect des aînés des Pitons-du-Tonnerre.$b$bNotre peuple a compris que la terre était pourvoyeuse de ressources. Pour faire l\'expérience de la vision rituelle, vous devez parler au chef spirituel du village, Zarlman Deux-Lunes.' WHERE l.`ID` = 767 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
