UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Bon.$B$BJe serai là-bas... à l\'abri.$B$BRejoignez-moi, si vous le souhaitez.' WHERE l.`ID` = 777 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Vaincre le Gardien Fam\'retor et rapporter les Entraves de lien élémentaire de Lotwil à Lotwil Veriatus.' WHERE l.`ID` = 778 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Ça promet d\'être dur' WHERE l.`ID` = 778 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Haha ! C\'est fait ! Les entraves sont finies !$B$BC\'est le moment, Lucien. C\'est le moment, Servo !$B$BÊtes-vous $gprêt:prête; à assister à la fusion parfaite de la science alchimique et des arcanes, $n ?$B$BJe vais maintenant invoquer un puissant élémentaire. C\'est un grand jour pour nous !' WHERE l.`ID` = 778 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
