UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La nouvelle Horde' WHERE l.`ID` = 787 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Throm\'ka, $c. Je suis Eitrigg, chargé par Thrall de superviser l\'entraînement des recrues.$b$bLa Horde n\'est plus ce qu\'elle était. Jadis, je la quittai, écœuré par l\'influence toujours croissante des sbires avides de la Légion ardente. Durant mon exil, je fus pris par un groupe d\'humains, mais secouru ensuite par le Chef de guerre. Lorsqu\'il me fit part de sa vision de la Horde, libre de toute influence démoniaque et guidée par les chamans, je réintégrai ses rangs.$b$bGornek aura d\'autres instructions pour vous.' WHERE l.`ID` = 787 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
