UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '<INUTILISÉ>' WHERE l.`ID` = 803 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Informer Gornek, à l\'Antre, de la situation critique dans laquelle se trouve Hana\'zua.' WHERE l.`ID` = 804 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Ce que vous avez fait pour moi remplit mon cœur de courage. Je ne peux pas me laisser mourir comme ça, je dois me battre !$b$bJe ne puis, cependant, regagner l\'Antre sans assistance. S\'il vous plaît, $n, retournez à l\'Antre et informez Gornek de ma situation. Peut-être saura-t-il m\'aider.' WHERE l.`ID` = 804 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Trouver Kor\'ghan à Orgrimmar et obtenir l\'Antidote du Queue-venin. L\'apporter ensuite à Rhinag près de la frontière nord-ouest de Durotar.' WHERE l.`ID` = 812 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Besoin d\'un remède' WHERE l.`ID` = 812 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '$n... votre minutage est parfait. J\'espère que je pourrai en dire autant de votre célérité.$B$BJ’ai manqué d\'attention en combattant des Queues-venin aux alentours, et j\'ai été piqué par l\'un d\'entre eux. Le poison m\'affaiblit au moment même où je parle. A ce rythme, il me reste peut-être une heure à vivre. Mais je vais avoir besoin de vous...$B$BKor\'ghan, à Orgrimmar, sait comment confectionner l\'antidote. Trouvez-le... et faites vite, $n. Je ne vais pas pouvoir tenir beaucoup plus longtemps. Il devrait se trouver dans la Faille de l\'Ombre.' WHERE l.`ID` = 812 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter 4 Glandes à venin de Queue-venin à Kor\'ghan à Orgrimmar.' WHERE l.`ID` = 813 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La recherche de l\'antidote' WHERE l.`ID` = 813 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Les scorpides Queue-venin sont parmi les plus dangereux en Durotar. Rhinag a manqué de sagesse lorsqu\'il a les a chassés sans emporter d\'antidote, mais à présent, une remontrance est vraiment la dernière chose dont il a besoin.$B$BApportez-moi des Glandes à venin de n\'importe quel Queue-venin, et je lui préparerai un antidote. Vous en trouverez près de l\'entrée d\'Orgrimmar.$B$BDépêchez-vous, $n. L\'un d\'entre nous a besoin de votre aide.' WHERE l.`ID` = 813 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à Orgnil Marque-l\'âme à Tranchecolline.' WHERE l.`ID` = 823 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Un rapport à Orgnil' WHERE l.`ID` = 823 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Nous autres au village de Sen\'jin avons nos problèmes, et nous vous remercions pour votre aide. Mais les nouvelles que vous apportez à propos de la Lame-Ardente pourraient annoncer des ennuis pour tout le monde.$B$BUn orc nommé Orgnil Marque-l\'âme est posté à Tranchecolline. Il protège Durotar de maux tels que la Lame-Ardente. Allez lui parler et informez-le de notre demande. Donnez-lui également des nouvelles de la vallée des Épreuves. Il voudra savoir ces choses.$B$BTranchecolline est au nord.' WHERE l.`ID` = 823 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à l\'Apothicaire Dithers à la Barricade, dans les Maleterres de l\'Ouest.' WHERE l.`ID` = 838 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Sur l\'île de Caer Darrow se trouve la Scholomance - une école servant de forteresse au Fléau. Nos ennemis y résident, à l\'abri, et libres de poursuivre des recherches qui ne font qu\'accroître leur pouvoir. Une porte se dresse sur le chemin, et malgré tous nos efforts, elle ne peut être franchie sans que la bonne clé ne lui soit présentée.$B$BL\'apothicaire Dithers sait beaucoup de choses au sujet de la Scholomance, et a une idée quant à la façon d\'obtenir cette clé. Vous m\'avez prouvé que vous êtes capable d\'atteindre des objectifs, aussi je vous confie cette tâche. Allez lui parler et entretenez-le à ce propos.' WHERE l.`ID` = 838 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '<INUTILISÉ>' WHERE l.`ID` = 839 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à Tor\'gan au Trépas-d\'Orgrim, dans les Hautes-terres Arathies.' WHERE l.`ID` = 847 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La ruse du raptor' WHERE l.`ID` = 847 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Ce… Ce pouvoir… Est-ce le pouvoir des chamans que Tor\'gan a essayé de me montrer ? Je dois admettre que c\'est intéressant. Dites à Tor\'gan qu\'il a réussi à me convaincre… pour l\'instant. Je vais écouter ce qu\'il a à dire.' WHERE l.`ID` = 847 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez les Spores fondues à l\'Apothicaire Zamah aux Pitons-du-Tonnerre, avant que la limite de temps ne soit dépassée.' WHERE l.`ID` = 853 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]L\'apothicaire Zamah' WHERE l.`ID` = 853 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'J\'ai fait une émulsion avec les spores que vous m\'avez apportées. Je dois à présent l\'envoyer à mon associée, l\'Apothicaire Zamah. Si vous pouviez la lui apporter, elle pourra vous offrir quelque chose de nos magasins d\'alchimie.$b$bElle est aux Bassins de la vision, une caverne qui se trouve sous les chamans des Pitons-du-Tonnerre. Le chemin menant à cette caverne est bien caché, mais vous pourrez le trouver sur la cime des Esprits.$b$bDépêchez-vous ! Cette émulsion ne restera pas puissante longtemps. Elle doit être livrée et utilisée au plus vite.' WHERE l.`ID` = 853 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez la Trousse d\'analyse de terrain verrouillée à l\'apothicaire Zinge à Fossoyeuse.' WHERE l.`ID` = 864 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'De retour vers l\'apothicaire Zinge' WHERE l.`ID` = 864 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '« Et voilà, la source d\'énergie est enlevée et les données sont préservées. Bien, faites attention sur la route et tout ça. J\'espère que cette horrible expérience s\'est bien déroulée pour vous, et tous les autres… »$B$BLe gobelin se détourne pour s\'occuper des demandes de la Compagnie des eaux de Gadgetzan. « Vous mettez la trousse d\'analyse verrouillée à l\'abri en vue du voyage de retour vers Fossoyeuse. Là-bas, l\'apothicaire Zinge vous attend, vous et la trousse d\'analyse de terrain verrouillée. »' WHERE l.`ID` = 864 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez le Noyau de la Brasse à Je’neu Sancrea, à l’Avant-poste de Zoram’gar, en Orneval.' WHERE l.`ID` = 908 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Parmi les ruines' WHERE l.`ID` = 908 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir Je’neu Sancrea en Orneval.' WHERE l.`ID` = 908 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Le Marteau du crépuscule s’est déplacé dans les ruines d’Écrin-de-Lune, dans les profondeurs de Brassenoire. Leur présence forcera les élémentaires à travailler contre nous. Si nous ne nous occupons pas de cette région, ils en prendront complètement le contrôle.$B$B$n, allez à Brassenoire et trouvez la pierre de la Brasse. Elle devrait se trouver quelque part, à proximité, dans l’eau. À l’intérieur, se trouve un noyau de la Brasse, un objet qui, s’il est utilisé correctement, offrira un historique de toute l’activité des élémentaires. Si je l’avais, je pourrais, avec l’aide du Cercle terrestre, faire quelque chose pour les arrêter !' WHERE l.`ID` = 908 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez le Globe d’eau étrange à Je’neu Sancrea, à l’Avant-poste de Zoram’gar, dans Orneval.' WHERE l.`ID` = 909 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Sur l’élémentaire d’eau vaincu, vous trouvez un étrange globe d’eau. Vous avez la nette impression que l’objet a absorbé l’énergie de la créature. À l’intérieur du globe, vous discernez une eau aux reflets malsains. Le globe lui-même semble insensible à toute forme d’action physique.$B$BS’il y a une personne qui puisse comprendre ce qu’est cet objet, cela ne peut être que Je’neu Sancrea du Cercle terrestre. Il se trouve dans l’avant-poste de Zoram’gar de la Horde, en Orneval.' WHERE l.`ID` = 909 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Remplir la Flasque d\'améthyste et la rapporter à Corithras Ragelune à Dolanaar.' WHERE l.`ID` = 934 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La couronne de la Terre' WHERE l.`ID` = 934 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Cependant, tout n\'était pas parfait sur Teldrassil. Les plans soigneusement conçus de Forteramure pour le nouvel Arbre-Monde s\'étaient déroulés comme il l\'avait espéré. Mais il y eut un petit problème, un problème sans doute à l\'origine des nombreuses difficultés rencontrées sur Teldrassil.$b$b. Mais je ne vais pas m\'étendre maintenant sur ce sujet. Vous devez vous rendre au dernier puits de lune, au nord-ouest, dans la clairière de l\'Oracle. Sous les branches de l\'arbre-oracle se trouve le premier et le plus puissant de nos puits. Remplissez une flasque de son eau et revenez me voir.' WHERE l.`ID` = 934 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez la Flûte de Xavaric et 5 échantillons de Lien maudit Jadefeu à Eridan Ventebleu, dans le sud de Gangrebois.' WHERE l.`ID` = 939 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]La flûte de Xavaric' WHERE l.`ID` = 939 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous étudiez la simple flûte de bois que vous avez récupérée après avoir vaincu Xavaric.$B$BLe bois noueux semble solide mais les spirales et les motifs à sa surface semblent se mouvoir quand vous tournez l’instrument entre vos mains. Soudain, vous êtes $gpris:prise; d’un sentiment d’appréhension…$B$BVous vous ébrouez, $gcertain:certaine; que votre esprit vous joue des tours.$B$BIl se pourrait que d’autres satyres détiennent des indices relatifs à ce que vous avez trouvé. Apportez vos découvertes au druide Eridan Ventebleu qui vit dans la partie sud de Gangrebois.' WHERE l.`ID` = 939 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '<INUTILISÉ>' WHERE l.`ID` = 946 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Étudier les tablettes qui parlent d\'Ameth\'Aran et de sa chute, puis retourner voir la Sentinelle Tysha Lamelune à Sombrivage.' WHERE l.`ID` = 953 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La chute d\'Ameth\'Aran' WHERE l.`ID` = 953 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous trouverez à l\'est les ruines d\'Ameth\'Aran. Elles sont habitées par les esprits sans repos des Bien-nés qui vivaient autrefois dans ces murs, quand les serviteurs d\'Azshara y pratiquaient librement leur puissante magie.$b$bOn m\'a envoyée pour explorer les ruines et trouver deux grandes tablettes, sur lesquels sont racontées les histoires d\'Ameth\'Aran et de sa chute. Alors que je lisais les runes, j\'ai été surprise par les esprits, et je me suis enfuie.$b$bS\'il vous plaît, si vous le pouvez, aventurez-vous dans les ruines et déchiffrez les tablettes pour moi.' WHERE l.`ID` = 953 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter 15 Fragments de squelette à l\'Apothicaire Dithers à la Barricade, dans les Maleterres de l\'Ouest.' WHERE l.`ID` = 964 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Fragments de squelette' WHERE l.`ID` = 964 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'La clé pour accéder à la Scholomance s\'appelle une Clé squelette. Elle doit être forgée à partir des restes d\'un squelette - de plusieurs en fait - et doit être renforcée des métaux les plus robustes dans un moule particulier. Enfin, un sceau de pouvoir provenant d\'une créature naturellement capable d\'ouvrir le portail de la Scholomance permettra à la clé d\'avoir la fonction désirée.$B$BMais commençons par le commencement, $n. Nous allons avoir besoin de fragments de squelette pour forger la clé. Les squelettes d\'Andorhal devraient nous les fournir, mais ceux en dehors des murs de la ville devraient pouvoir faire l\'affaire également.' WHERE l.`ID` = 964 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Attendre un instant, puis reparler à la Féticheuse Mau\'ari pour recevoir le Charme de chance.' WHERE l.`ID` = 975 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]Cache de Mau\'ari' WHERE l.`ID` = 975 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Avant de vous donner ce charme, je vous expliquerai comment l’utiliser.$B$BSi vous le portez sur vous, vous trouverez certains objets spéciaux sur les créatures que vous combattrez. Sans le charme, pas d’objets spéciaux, vous voyez ?$B$BCes objets s’appellent des E\'ko. Si vous trouvez n\'importe lequel de ces objets, apportez-le à la vieille Mau\'ari, qui saura vous aider.$B$BAttendez ici pendant que je prépare votre charme.' WHERE l.`ID` = 975 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Aller voir Delgren le Purificateur au Poste de Maestra.' WHERE l.`ID` = 981 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
