UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Ça va, $n. Sortons de là. Nous nous fraierons un passage jusqu\'à la route ; Griffe-sinistre devrait encore y être. Une fois là-bas, nous pourrons nous séparer.$B$BTerenthis va vouloir que vous lui racontiez immédiatement ce qui s\'est passé, vous irez donc à Auberdine dès que nous serons sortis vivants d\'ici.' WHERE l.`ID` = 994 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
