UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'D’accord... si vous le voulez, nous nous échapperons d’ici.$B$BRappelez vous, une fois que vous aurez quitté ce lieu, allez à Auberdine et rencontrez Terenthis. C’est là que je vais me rendre aussi, et j’y serai probablement avant vous.' WHERE l.`ID` = 995 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à l’Archidruide Hamuul Totem-Runique, sur la Cime des Anciens des Pitons-du-Tonnerre. Évoquer l’appel du Cercle cénarien concernant l’exploration des frontières de Kalimdor.' WHERE l.`ID` = 1000 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
