UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'La larme d\'Élune a un peu amélioré l\'état de ma fille. Ses cauchemars ont diminué et je remercie la déesse pour sa bénédiction. Mais... la fièvre n\'a pas baissé.$B$BOrendil m\'a parlé d\'une poussière dépolie que l\'on trouve dans les ruines de Chimétoile. Peut-être qu\'elle diminuerait la fièvre de Relara. Trouvez un peu de cette poussière, et rapportez-la-moi, je vous en prie.$B$BLes ruines de Chimétoile se trouvent au sud, $n. Puisse Élune vous faire revenir rapidement !' WHERE l.`ID` = 1034 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Aller voir le greffier Daltry à Sombre-Comté.' WHERE l.`ID` = 1041 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
