UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'S\'avère que j\'ai eu tort à propos de vous et que ça n\'arrive pas tous les jours.$b$bJe viens juste de me rappeler de cette Velinde que vous cherchez. Pas tous les jours qu\'une prêtresse des elfes de la nuit veut voyager dans une vieille et sale – mais parfaitement adaptée à vos transports de marchandises ! – caravane comme la mienne.$b$bNous avons pris ensemble le chemin vers le nord, elle se dirigeait vers Sombre-Comté. L\'employé là-bas tient à jour toutes sortes d\'informations. Pourrait savoir quelque chose d\'utile.$b$bFaites preuve de prudence dans la jungle, c\'est un endroit mortel même dans les bons jours.' WHERE l.`ID` = 1041 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Aller voir Jonathan Carevin à Sombre-Comté.' WHERE l.`ID` = 1042 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La famille Carevin' WHERE l.`ID` = 1042 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Non, je n\'ai reçu aucun rapport concernant une Velinde Chantétoile résidant à Sombre-Comté... Quoique, si vous voulez mon avis, j\'aie du mal à imaginer une prêtresse elfe de la nuit prenant une chambre à l\'auberge, si vous voyez ce que je veux dire.$b$bPour ce qui est des hommes-loups que vous mentionnez, j\'en ai entendu parler. Justement l\'autre jour, Calor est rentré en ville avec une guirlande de leurs têtes. Il travaille avec la famille Carevin. Des chasseurs de démons, de morts-vivants et autres monstres. Allez voir Jonathan, c\'est le chef de famille.' WHERE l.`ID` = 1042 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Cherchez les signes de la Faux d\'Élune puis retourner voir Jonathan Carevin à Sombre-Comté.' WHERE l.`ID` = 1043 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La faux d\'Élune' WHERE l.`ID` = 1043 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Votre histoire sonne juste... Je ne comprends pas bien vos motifs, mais si vous venez dans le bois de la Pénombre pour le débarrasser de quelques worgens, je ne vais plus chercher à comprendre.$b$bIl y a une mine au sud, que les worgens ont envahie... Ils sont apparus de nulle part, mais d\'après ce que nous savons, c\'est là qu\'on les a vus pour la première fois.$b$bFaites votre boulot, mais si vous découvrez quoi que ce soit d\'important, je vous demande de m\'en faire part. Nous acceptons l\'aide de tout le monde dans notre guerre contre le Mal.' WHERE l.`ID` = 1043 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
