UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Nous, les membres de la Croisade écarlate, nous revendiquons des forteresses d’Âtreval dans les Clairières de Tirisfal. Nous sommes assez fiers des bastions de nettoyage que nous avons installés partout dans Lordaeron.$b$bVous avez fait vos preuves contre les morts-vivants de Désolace. Mais la vraie menace de cette peste se trouve à Lordaeron.$b$bFaites route jusqu\'à la ville d’Austrivage, dans les royaumes de l\'Est. Cherchez-y un croisé nommé Raleigh le Dévot. Remettez-lui cette lettre de recommandation portant mon sceau et il vous donnera une place d\'honneur dans notre monastère.' WHERE l.`ID` = 1052 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Retourner voir Shael\'dryn au puits de lune.' WHERE l.`ID` = 1055 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
