UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Le village des Cognepierres a été envahi par la portée d\'Onyxia. Mais pourquoi la fille d\'Aile de mort, le seigneur du vol noir, est-elle descendue sur nos champs ?$b$bC\'est très troublant. Onyxia a sûrement un autre but que de faire le siège d\'un petit village ogre.$b$bRendez immédiatement compte à Mok\'Morokk ! Il faut agir !' WHERE l.`ID` = 1170 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
