UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Désolé, je ne vais pas être d\'un grand secours, $n ! Si vous voulez d’autres informations, je vous suggère d\'aller trouver le baron lui-même. S\'il y a quelqu\'un qui est en mesure de vous renseigner sur les affaires de Revilgaz, c\'est Revilgaz lui-même. $b$bVous le trouverez à l’étage de la Taverne, de l\'autre côté du port.' WHERE l.`ID` = 1181 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
