UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Retournez voir Belgrom à Orgrimmar pour lui dire que Moktar fait tout ce qu\'il peut aux Mille pointes. Dites-lui aussi que mes études progressent et que je pourrai lui donner des détails assez vite. Cela devrait le satisfaire pleinement.' WHERE l.`ID` = 1184 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
