UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Mais qu\'est-ce que c\'est que ça ? Shreev a laissé la sûreté enclenchée. Ça limite l\'énergie que je peux en tirer à chaque fois. Je lui avais dit de l\'enlever ! Ça ne va pas ! $b$bVous devez rapporter ça au Bidulium de Gadgetzan dans le désert de Tanaris, et faire enlever ce truc par Shreev.' WHERE l.`ID` = 1188 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Utiliser Zamek pour faire diversion, dérober les plans de Tropp et les apporter à Pozzik dans les Salines, aux Mille pointes.' WHERE l.`ID` = 1190 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
