UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Les frères Zéboulon ont utilisé un nouveau matériau de construction, c\'est la seule explication plausible. Leurs voitures avancent plus rapidement qu\'avant, mais leur aspect et toutes les données que nous avons recueillies sur leurs courses restent identiques.$b$bCe que nous savons, c\'est que Tropp Zéboulon est branché à temps plein sur les plans de sa nouvelle découverte.$b$bZamek peut créer une diversion pour vous, ainsi vous pourrez dérober ces plans.' WHERE l.`ID` = 1190 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez l\'Échantillon de minerai d\'indurium à Pozzik dans les Salines, aux Mille pointes.' WHERE l.`ID` = 1194 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
