UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Les schémas de Tropp montrent le processus de raffinage de l\'indurium. D\'après ses gribouillages, il apparaît que le minerai provient de la mine des nains d\'Uldaman dans les Terres ingrates.$b$bLa plupart des autres notes évoquent ses propriétés de résistance à la chaleur.$b$bCe qui sert de presse-papiers pour les plans est vraisemblablement un gros morceau d\'indurium non raffiné.' WHERE l.`ID` = 1194 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez le Rapport de l\'Espion au Lieutenant Aden de Theramore.' WHERE l.`ID` = 1219 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
