UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'En remuant la poussière, on trouve la main coupée d\'un orc. Une main qui agrippe encore un tube en os gravé. Le tube contient un parchemin taché.$B$BLe parchemin est écrit en orc... Et ça semble important.' WHERE l.`ID` = 1219 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
