UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Le capitaine Vimaire désire voir le rapport orc que vous avez trouvé, $n. C’est lui qui connaît le mieux la langue des orcs. Et il doit savoir qu\'il y a des espions de la Horde près de Theramore !$B$BLe capitaine est dans la Caserne, au nord-est de Theramore.' WHERE l.`ID` = 1220 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
