UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Ouais ! Cela semble bien trop compliqué pour quelque chose qui serait juste destiné à vous induire en erreur. Je ne devrais même pas être en train de regarder tout ça. Portez-le à Trias. Il sera capable de comprendre tout cela. Et ne laissez PERSONNE se mettre en travers de votre chemin. Ceci est trop gros pour moi. C\'est peut-être même trop gros pour lui, mais il verra.$B$BEt faites-moi une faveur, $n, ne dites à personne que je vous ai fourni de l\'aide. Si mes supérieurs apprennent que je savais quelque chose sur cette affaire et que je ne les ai pas prévenus, ils me pendront.' WHERE l.`ID` = 1245 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à Mikhail dans les Paluns.' WHERE l.`ID` = 1250 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Un diplomate a disparu' WHERE l.`ID` = 1250 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Les Défias ne me payent pas suffisamment pour que je meure pour leur cause. Ils ont pris le roi. Ouais, le roi de Hurlevent, pas un petit diplomate de rien du tout. Il était en route pour rencontrer Jaina Portvaillant. C\'était un gros coup apparemment et un grand secret. Mais il n\'y avait pas que les Défias qui y participaient. Ils travaillaient pour quelqu\'un. Je pense qu\'ils savaient que c\'était quelque chose de trop gros pour eux.$B$BMon travail consistait à introduire l\'un de leurs hommes sur le bateau du roi lorsqu\'il était à quai. Le nom de ce type est Hendel. C\'est tout ce que je sais. Je le jure !' WHERE l.`ID` = 1250 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Rapporter le badge de Reethe au capitaine Garran Vimaire à Theramore.' WHERE l.`ID` = 1252 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
