UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Un éclat de lumière attire votre attention sur les gravats. Écartant les débris et la poussière, vous trouvez un insigne émaillé représentant une ancre dorée sur fond blanc : le symbole de Theramore.$b$bSous l\'ancre est gravé : « Lieutenant Paval Reethe ».' WHERE l.`ID` = 1252 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Trouver plus de renseignements sur Paval Reethe auprès de l\'adjudant Tesoran à Theramore.' WHERE l.`ID` = 1259 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]Le lieutenant Paval Reethe' WHERE l.`ID` = 1259 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Le nom du lieutenant Paval Reethe ne me dit rien. Votre meilleure chance est de vérifier auprès de l\'adjudant Tesoran. Il conserve tous les dossiers de la garde de Theramore, du personnel jusqu\'à l\'équipement.$b$bIl devrait être capable de vous dire qui est ce Reethe après un rapide coup d\'œil dans ses registres.' WHERE l.`ID` = 1259 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez le Pendentif orné à Nazeer à Mur-de-Fougères.' WHERE l.`ID` = 1261 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Marg parle' WHERE l.`ID` = 1261 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Maudit Bourbecoque ! Tu ne peux pas tuer Marg ! Ah, mais je suis mort. Alors il doit m\'avoir tué...$B$BMais ma mission ! Ma mission ! Vous, $n, devez achever ma mission.$B$BAlors que j\'étais près de Theramore, j\'ai espionné un groupe de soldats de l\'Alliance qui campaient sur la plage. Un de ces soldats portait un pendentif... Un pendentif avec plus de pierres précieuses que dans les rêves d\'un soldat !$B$BCette nuit-là, je me suis glissé dans leur camp et j\'ai volé le pendentif, mais au retour à la base, un homme-crabe Bourbecoque m\'a tué !$B$B$n, vous devez le retrouver et récupérer le pendentif !' WHERE l.`ID` = 1261 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez le Pendentif orné à Zor Arbre-solitaire à Orgrimmar.' WHERE l.`ID` = 1262 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
