UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Des lignes d\'empreintes de sabots partent des ruines encore fumantes de l\'auberge du Repos ombragé. Il y a au moins quelques traces visibles avec d\'autres empreintes peu marquées dans la boue du marais.' WHERE l.`ID` = 1284 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
