UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Je suis désolé de ne pouvoir vous en dire plus, $n, mais je sais qui peut vous aider. Caz Bi-Douille, un de nos meilleurs forgerons. Portez-lui le bouclier et voyez ce qu\'il peut vous dire.' WHERE l.`ID` = 1319 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
