UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Ah ! J\'ai failli manquer ceci… La lanière de cuir au dos a dû brûler, mais on dirait qu\'elle avait été faite pour un grand gabarit. Je dirais même un tauren.$b$bC\'est tout ce que je peux dire. Dites au capitaine Vimaire que je suis désolé de n\'avoir pas pu l’aider davantage.' WHERE l.`ID` = 1320 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
