UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]Le Bouclier noir' WHERE l.`ID` = 1321 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Hmmm… Je ne vois rien qui sorte de l\'ordinaire à propos de ce bouclier. Demandons à Do\'gol, le forgeron, de l\'examiner, puis écoutons ce qu\'il peut nous dire, mais n\'espérons pas trop…' WHERE l.`ID` = 1321 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
