UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Oh ! Je crois que j\'ai mis trop d\'acide sur le bouclier. Frottons un peu pour voir…$b$bHmm, difficile à lire, mais je crois que c\'est un nom : Mosarn. Jamais entendu parler de lui. Peut-être Krog le saura. Krog connaît tellement de monde.' WHERE l.`ID` = 1323 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à l\'acolyte Dellis à Hurlevent.' WHERE l.`ID` = 1363 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Les ordres de Mazen' WHERE l.`ID` = 1363 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'En tant que conservateur de la bibliothèque de l\'Académie des arts et sciences des arcanes, il est de ma responsabilité de m\'assurer que tous les livres magiques et les parchemins sont bien présents. Qui sait quelle folie pourrait survenir si l\'un de ces textes enchantés tombait entre de mauvaises mains ?$b$bCela me fait penser : mon assistant, Dellis, a fait une terrible erreur la semaine dernière. Il est parfaitement à l\'aise dans la bibliothèque, mais parfaitement incompétent dès qu\'il franchit les portes de Hurlevent. Soyez un exemple de ce temps et allez aider le vieux Dellis, voulez-vous ?' WHERE l.`ID` = 1363 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter 15 Oreilles de centaure à Felgur Doublecoupe, en Désolace.' WHERE l.`ID` = 1366 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La prime aux centaures' WHERE l.`ID` = 1366 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Maintenant que vous avez terrifié les clans centaures, il est temps de les saigner. Lorsque vous voyagerez à travers Désolace, chassez-les. Je me moque de savoir à quel clan ils appartiennent. Vous devez juste collectionner les oreilles. Je veux un monceau d\'oreilles !$B$BEn diminuant leur nombre vous porterez un coup à leur résolution et sonnerez le glas de leurs envies d\'expansion.$B$BBonne chasse, $n.' WHERE l.`ID` = 1366 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Rapporter 6 Sacs de viande grossièrement séchée à Uthek la Sage au village des Gelkis.' WHERE l.`ID` = 1370 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Voleur de viande' WHERE l.`ID` = 1370 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Lorsque nous ne sommes pas en guerre, nous chassons pour trouver de la viande. La viande nous donne la force et des ventres remplis se battent mieux que des ventres vides.$B$BC\'est la même chose chez les Magram. Ils gardent la viande en trop afin de se battre plus longtemps entre leurs chasses. Si vous attaquez leur village à l\'est et prenez leurs réserves de viande, leur force va diminuer.' WHERE l.`ID` = 1370 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à l’Apothicaire Faustin, au Repaire des Mendiants.' WHERE l.`ID` = 1372 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La vérité, rien que la vérité' WHERE l.`ID` = 1372 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Notre force expéditionnaire a été envoyée sur les ordres de Varimathras pour surveiller le bas-Azeroth.$b$bPendant une reconnaissance, j\'ai remarqué un infiltrateur humain qui espionnait le repaire des Mendiants. Avant que je ne puisse l\'attraper, certains de nos... frères orcs l\'ont capturé et emmené à Pierrêche, leur forteresse dans le marais des Chagrins.$b$bJe veux… aider… nos alliés, les orcs. Ils n\'ont pas vu notre camp, mais malgré cela, je veux les aider.$b$bTravaillez avec Faustin pour développer… un sérum de vérité pour notre ami, à Pierrêche.' WHERE l.`ID` = 1372 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez la Tête du khan Jehn à Uthek la Sage au village des Gelkis, en Désolace.' WHERE l.`ID` = 1374 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'La terre me parle et me dit que les Magram sont de plus en plus faibles. Il est maintenant temps de tuer leur khan !$B$BRapportez-moi la tête de Jehn, le khan des Magram !' WHERE l.`ID` = 1374 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Maintenez votre réputation auprès des Magram, et apportez le Fragment de clé des Maraudine à Warug au village des Magram, en Désolace.' WHERE l.`ID` = 1381 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Le khan des Gelkis est mort, et à présent le clan Maraudine va tomber ! Tuez le khan des Maraudine, Hratha.$b$bPour le combattre, soufflez dans la Corne sur le grand promontoire de la Vallée des lances. Mais pour y souffler, vous aurez besoin d\'une embouchure. Pour l\'obtenir, tuez des centaures Maraudine. Tuez jusqu\'à ce que vous la trouviez. Puis soufflez dans la corne.$b$bAgissez ainsi et les centaures Maraudine viendront à la tour. Tuez-en jusqu\'à ce que le khan Hratha apparaisse. Il détient un fragment de clé. Apportez-moi ce fragment...' WHERE l.`ID` = 1381 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'L\'apothicaire Faustin, du Repaire des Mendiants, a besoin de 5 Cœurs de panthère des ombres, d\'un Champignon de Boueux et de Sang de dragonnet vert.' WHERE l.`ID` = 1383 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La vérité, rien que la vérité' WHERE l.`ID` = 1383 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Je pense avoir trouvé la composition du sérum qu\'il nous faut. Il s\'occupera de la vérité exactement comme il convient. Pour cette préparation, je vais avoir besoin de beaucoup de cœurs de panthères des ombres, en provenance du marais. J\'aurai également besoin d\'un champignon de boueux enchanté, de la réserve personnelle du seigneur du bourbier local. Il est certain que quelqu\'un d\'aussi talentueux que vous, $n, peut le persuader de s\'en séparer.$b$bLa dernière chose dont j’aurai besoin pour le sérum, c’est du sang d’un dragonnet rêveur, comme ceux qui vivent à côté de la caverne d’Itharius dans le marécage.$b$bAllez-y à présent !' WHERE l.`ID` = 1383 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Maintenir votre réputation auprès des Magram, tuer 12 Centaures kolkars, 12 Éclaireurs kolkars, 6 Marteleurs kolkars, puis retourner voir Warug, dans le village des Magram, en Désolace.' WHERE l.`ID` = 1386 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Assaut sur les Kolkars' WHERE l.`ID` = 1386 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Les centaures kolkars pensent qu\'ils sont forts, mais nous rions de leur force ! Nous rions d\'eux et nous les tuons ! Vous les tuez aussi. Montrez-moi que vous pouvez tuer des centaures kolkars comme nous les tuons. Allez vers le nord et massacrez-les tous !' WHERE l.`ID` = 1386 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Remettre le Sérum de vérité de Faustin au Nécrotraqueur Zraedus au Repaire des Mendiants.' WHERE l.`ID` = 1388 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La vérité, rien que la vérité' WHERE l.`ID` = 1388 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Tout se déroule selon le plan, $n. Je veux que vous remettiez ce sérum de vérité au nécrotraqueur Zraedus et il vous montrera comment l\'administrer… proprement.$b$bHa ! Ha !' WHERE l.`ID` = 1388 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter 6 Cristaux de draenéthyste à Magtoor au Havre boueux du marais des Chagrins.' WHERE l.`ID` = 1389 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]Les cristaux de draenéthyste' WHERE l.`ID` = 1389 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Les Perdus qui vivent dans le Sanctuaire des friches nous ressemblent physiquement, mais ce sont des monstres… rendus fous par les rigueurs de notre voyage vers Azeroth. Nos anciens frères attrapent et tuent quiconque s’approche du Sanctuaire des friches, à l\'est.$b$bEt ils nous ont volé quelque chose de sacré à nos yeux : des cristaux de draenéthyste.$b$bNous n\'avons pas la force suffisante pour pénétrer dans le Sanctuaire des friches et reprendre nos draenéthystes volées dans leurs huttes et près des feux de camp. Mais sans ces cristaux... nous pourrions également perdre la voie, tout comme eux.' WHERE l.`ID` = 1389 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter la Bière de Zraedus à l\'Infiltrateur Marksen à Pierrêche.' WHERE l.`ID` = 1391 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La vérité, rien que la vérité' WHERE l.`ID` = 1391 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Nous devons procéder avec une certaine discrétion. Après tout, ce n\'est pas comme si vous alliez danser la valse là-bas et convaincre un imbécile de boire la préparation de Faustin, pas vrai ?$b$bMais il y a une chose à laquelle les humains ne savent pas dire non, c\'est l\'alcool. Je prendrai le sérum de Faustin et le verserai dans de la bière. Je peux garantir que le pauvre type n’hésitera pas à la siffler d\'un trait.$b$bHâtez-vous vers Pierrêche, dans le marais des Chagrins, $n.$b$bEt faites en sorte que notre petite mission reste secrète et sans accroc...' WHERE l.`ID` = 1391 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Tuer 8 Jeunes crocilisques dents-de-scie, 10 Tisseuses des pleurs et 10 Jaguars du marécage, puis retourner voir le Gardien Biggs, dans le marais des Chagrins.' WHERE l.`ID` = 1396 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]Des créatures sauvages rôdent' WHERE l.`ID` = 1396 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Ma caravane avait pour destination la côte est. Mais nous ne l\'avons pas atteinte. Les Perdus nous ont attaqués, tuant les gardes et volant des marchandises.$B$BMoi seul ai survécu à l\'assaut. J\'ai juré de protéger les marchandises restantes, mais des créatures sauvages rôdent dans les alentours. Je vous en prie, aidez-moi à défendre mon campement contre ces bêtes !' WHERE l.`ID` = 1396 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter 8 Morceaux de Bois séché au soleil au Gardien Biggs dans le marais des Chagrins.' WHERE l.`ID` = 1398 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]Bois flotté' WHERE l.`ID` = 1398 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Je vous dois beaucoup, $n. Un cœur noble bat en vous. J\'ai à présent une autre tâche pour laquelle je demanderai humblement votre aide.$b$bSi je veux avoir la moindre chance d\'atteindre Rempart-du-Néant, alors je dois réparer mon chariot. Et pour cela, j\'ai besoin de bois. Du bois fort, du bois sec, pas de ce bois spongieux et noueux des arbres du marais.$b$b$n, partez à l\'est pour la côte et cherchez du bois qui a séché au soleil. Et apportez-le-moi.' WHERE l.`ID` = 1398 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Trouver le Coffre de la Caravane, dans le Sanctuaire des Friches, obtenir les Composants pour les sorciers, et les apporter au Gardien Biggs.' WHERE l.`ID` = 1421 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]Le chariot perdu' WHERE l.`ID` = 1421 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'J\'ai perdu connaissance durant l\'attaque des Perdus, mais avant que tout ne s\'obscurcisse, j\'ai vu l\'un de nos chariots en train d\'être traîné vers le sanctuaire des Friches, le village des Perdus, au nord.$B$BUn coffre plein d\'ingrédients de valeur se trouvait dans ce chariot. Ces ingrédients sont d\'un intérêt scientifique vital pour les sorciers de Rempart-du-Néant. Retrouvez ce coffre et mettez la main sur ces ingrédients, $n. Une fois que vous les aurez en votre possession, rapportez-les-moi.' WHERE l.`ID` = 1421 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à Maurin Craquossement en Désolace.' WHERE l.`ID` = 1433 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Les relations de l\'Alliance' WHERE l.`ID` = 1433 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Les sectateurs de la Lame-Ardente élaborent de nombreux plans, mais sachez qu\'ils sont foncièrement maléfiques, que leur esprit est corrompu, et que la destruction est le seul moyen de mettre un terme à leurs objectifs.$b$bKeldran a envoyé Maurin avec moi car il connaît la Lame et les méthodes des démonistes.$b$bIl supervise nos actions contre la Lame, tandis que je m\'occupe des autres dangers démoniaques ici en Désolace.$b$bParlez-lui, et il vous expliquera ses projets.' WHERE l.`ID` = 1433 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter une Gemme ardente et 15 Gemmes ardentes infusées à Maurin Craquossement en Désolace.' WHERE l.`ID` = 1435 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Esprits consumés' WHERE l.`ID` = 1435 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'La mort est très désirable pour ces dégoûtantes créatures qui quittent les ordres de leur seigneur pour des raisons si égoïstes. Mais la mort n\'est pas suffisante quand on a affaire à ceux qui se sont donnés aux ténèbres.$b$bPrenez cette gemme. Lorsqu\'un membre de la Lame-Ardente approchera de la mort, activez sa magie. Le sort attirera l\'esprit corrompu de sa victime, laissant une gemme ardente infusée.$b$bApportez-moi ces gemmes ardentes, que je m\'en occupe comme il convient.$b$bPartez à présent, et puissiez-vous échapper à la mort.' WHERE l.`ID` = 1435 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Trouver Tyranis Malem en Désolace.' WHERE l.`ID` = 1439 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'À la recherche de Tyranis' WHERE l.`ID` = 1439 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Nous avons été emmenés ici après le massacre de nos gardes et de nos serviteurs par les orcs. Oh ! Ils leur ont fait des choses si horribles ! J\'ai cru qu\'ils allaient également nous tuer, sur place, mais ils avaient visiblement d\'autres plans.$b$bTyranis a essayé de leur parler. Je pense qu\'il voulait les impressionner par sa connaissance des arcanes... Je ne suis pas sûre de savoir pourquoi.$b$bJe vous en prie, je ne peux pas quitter les lieux tant que j\'ignore ce qu\'il est advenu de mon frère. Retrouvez-le, et venez me dire quel a été son sort.' WHERE l.`ID` = 1439 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`AreaDescription` = 'Secourir Dalinda Malem' WHERE l.`ID` = 1440 AND l.`locale` = 'frFR' AND (l.`AreaDescription` IS NULL OR l.`AreaDescription` = '' OR BINARY l.`AreaDescription` = BINARY q.`AreaDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Escorter Dalinda Malem depuis la forteresse de Hache-Tonnerre et retourner voir Vahlarriel Tueur-de-démons, en Désolace.' WHERE l.`ID` = 1440 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le retour vers Vahlarriel' WHERE l.`ID` = 1440 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Ainsi, le temps est venu ? J\'apprécie vos efforts, et si la situation ne se résout pas, alors permettez-moi de vous remercier dès à présent pour tout ce que vous avez fait pour moi et ma famille. Si vous êtes $gprêt:prête;, rien ne me retient ici. Nous pouvons partir quand vous estimerez le bon moment arrivé.' WHERE l.`ID` = 1440 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Retourner voir Fel’Zerul à Pierrêche.' WHERE l.`ID` = 1444 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'De retour vers Fel’Zerul' WHERE l.`ID` = 1444 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Jammal\'an le Prophète m\'a condamné à être exilé du temple d\'Atal\'Hakkar. Je considérais autrefois que le grand prêtre était un chef digne.$b$bSa foi inflexible dans sa prophétie apportera la destruction aux Atal\'ai. Si ce n\'est pas déjà fait.$b$bLorsque j\'ai exprimé des réserves, j\'ai été traité d’infidèle et évincé du temple.$b$bLes artéfacts que vous avez apportés sont inoffensifs. Mais si Jammal\'an a découvert le bon fétiche d\'enchantement pour le rituel d\'invocation, alors le monde court un grand péril...' WHERE l.`ID` = 1444 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parlez au Maître des griffons Hachegriffe dans la Volière de Nid-de-l\'Aigle.' WHERE l.`ID` = 1450 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le maître des griffons Hachegriffe' WHERE l.`ID` = 1450 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Ainsi, vous êtes un des fameux coursiers au service des vieux schnocks de la Ligue des Explorateurs, hein ?$b$bBien, écoutez-moi, $c. Je ne sais pas avec qui votre vieux pote faisait des ronds dans le ciel d’Azeroth. Est-ce que j\'ai la tête du Maître des griffons Hachegriffe ? Hein ?$b$bSi vous êtes tellement $gintéressé:intéressée; par les aléas du trafic aérien pourquoi n\'allez-vous pas lui parler directement ? Si je vous prends à glandouiller dans le coin un peu plus longtemps, je vais vraiment vous faire transpirer.$b$bÀ présent, bougez de là !' WHERE l.`ID` = 1450 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter la Sacoche de Karnitol à Roetten Martel-de-pierre à Forgefer.' WHERE l.`ID` = 1457 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'épave de Karnitol' WHERE l.`ID` = 1457 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Rapportez les biens de Karnitol à Roetten à Forgefer, et il vous paiera pour ce travail bien accompli.$b$bHa ! Ha ! Si vous ne faites pas attention, il sera tellement satisfait de vous qu\'il vous demandera de nous rejoindre à plein temps.$b$bMais à nouveau, bon travail, $n.$b$bSoyez $gprudent:prudente; sur le chemin du retour, et ne prenez pas tout votre temps ; Karnitol n\'est pas le plus patient des hommes, mais il reste très généreux néanmoins.' WHERE l.`ID` = 1457 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter 10 Griffes de Fielfurie et 10 Cornes de Fielfurie à Kreldig Ungor en Désolace.' WHERE l.`ID` = 1458 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Des réactifs pour les Récupérateurs' WHERE l.`ID` = 1458 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'L\'une de mes tâches ici consiste à collecter des réactifs pour Leftwitch, un mage gnome de Kharanos. Roetten semble penser que c\'est de l\'argent facilement gagné puisque nous sommes déjà sur place. Il se soucie peu du fait que nous sommes si démunis.$b$bLes premiers objets de sa liste devraient être assez faciles à trouver, et ce sera de l\'argent gagné pour quiconque m\'aidera.$b$bJ\'ai besoin de cornes et de griffes des satyres Fielfurie qui vivent à l\'est d\'ici. Rapportez-m\'en et nous poursuivrons la liste.' WHERE l.`ID` = 1458 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Rapporter le Pendentif de Malem à Vahlarriel Tueur-de-démons en Désolace.' WHERE l.`ID` = 1465 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La recherche de Vahlarriel' WHERE l.`ID` = 1465 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Tandis que vous continuez à fouiller le chariot, vous découvrez non seulement un pendentif mais également des traces de pas qui se dirigent vers le sud. Au loin, vous distinguez de la fumée s\'élevant d\'une grande forteresse. La fumée provient d\'un feu entretenu, il ne s\'agit pas de bâtiments qui brûlent, et votre instinct vous dit que les Malem, si tant est qu\'ils soient toujours en vie, ont été emmenés dans cette direction.$B$BVous estimez que Vahlarriel, à la Combe de Nijel, devrait voir le pendentif et savoir qu\'il se trouve des signes de vie au sud.' WHERE l.`ID` = 1465 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez le Fragment de tablette atal\'ai à Brohann Ventrabière à Hurlevent.' WHERE l.`ID` = 1469 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'histoire de Rhapsody' WHERE l.`ID` = 1469 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Avant le vol, je me suis bu un plein tonneau de bière brune. Hic !$b$bEt ça a été un de ces vols ! Volé de-ci de-là avec Brohann qui me suivait. Mais pas vu de temple en tout cas. Hic !$b$bJe veux dire, j\'ai pas vu de temple, jusqu\'à ce que je sois trop parti et que je tombe de ma monture. J\'ai plongé directement dans la flotte et j’ai été aspiré. Me suis trouvé entouré par un tas de trolls à la mine patibulaire. Vous pensez bien que j\'ai nagé très vite pour partir ! J\'ai quand même ramassé un souvenir troll. Tenez, apportez ça à Brohann et dites-lui que son temple est là-bas, en bas, de fait. Hic !' WHERE l.`ID` = 1469 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez 3 Crânes de Cliquethorax à Venya Marthand.' WHERE l.`ID` = 1470 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Lever le voile' WHERE l.`ID` = 1470 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Salutations, enfant. Je peux voir que vous êtes encore novice dans les arts du démoniste, le pouvoir échappant toujours à votre contrôle. Je peux aussi sentir votre désir d\'apprendre.$b$bEt vous apprendrez.$b$bLa force ne réside pas dans l\'ignorance. La connaissance est notre pouvoir le plus puissant. Par l\'application du savoir, nous pouvons contrôler les magies et les êtres chaotiques du vide, et les soumettre à notre volonté.$b$bJe peux vous montrer comment soumettre un servant, mais d\'abord vous devez m\'apporter trois crânes pris sur les squelettes Cliquethorax qui rôdent près de la forge abandonnée.' WHERE l.`ID` = 1470 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Rassembler 10 Tablettes atal\'ai pour Brohann Ventrabière à Hurlevent.' WHERE l.`ID` = 1475 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Dans le temple d\'Atal\'Hakkar' WHERE l.`ID` = 1475 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'D\'après la légende, le temple d\'Atal\'Hakkar est un lieu saint dédié au dieu ancien, Hakkar l\'Écorcheur d\'âmes. Habité par une ignoble tribu de trolls, les Atal\'ai, on dit qu\'il est impossible d\'y entrer.$b$bCe temple est à présent sous les eaux du Bassin des larmes, et récupérer les artéfacts sera d\'autant plus difficile. Mais c\'est pourtant ce que j\'ai besoin que vous fassiez, $n.$b$bAidez-moi, en récupérant les Tablettes atal\'ai intactes. Apportez-les-moi, et je deviendrai un héros aux yeux de la Ligue des Explorateurs. Nous partagerons ensemble cette gloire.' WHERE l.`ID` = 1475 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`AreaDescription` = 'Aller à la banque de Darnassus, connue sous le nom du Rameau des Éternels.' WHERE l.`ID` = 1479 AND l.`locale` = 'frFR' AND (l.`AreaDescription` IS NULL OR l.`AreaDescription` = '' OR BINARY l.`AreaDescription` = BINARY q.`AreaDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Conduire l\'orphelin à la banque de Darnassus. La banque est creusée dans le tronc d\'un arbre connu sous le nom du Rameau des Éternels.' WHERE l.`ID` = 1479 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le Rameau des Éternels' WHERE l.`ID` = 1479 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Parlez à votre Orphelin humain.' WHERE l.`ID` = 1479 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'J\'ai entendu parler d\'histoire sur les elfes de la nuit, qui ont leur banque dans un arbre, mais qui ressemble à un ours ! C\'est génial ! C\'est chouette, il paraît que les elfes de la nuit aiment la nature et ce genre de choses. Et les ours, c\'est trop terrible !$B$BVous voulez bien m\'emmener voir l\'arbre-ours à Darnassus, s\'il vous plaît ? Y\'a un bateau qui peut nous amener juste à côté, ça ne devrait pas prendre trop de temps. S\'il vous plaaaaaaaaaaaît !' WHERE l.`ID` = 1479 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parlez à Takata Lamacier en Désolace.' WHERE l.`ID` = 1484 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le corrupteur' WHERE l.`ID` = 1484 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Cette créature est beaucoup plus dangereuse que je ne l\'avais cru. Il est certain que Takata doute de mes capacités à battre une telle créature, et ce serait insulter son honneur que de ne pas l\'informer de ce qui vient juste de se passer.$b$bParlez à l\'homme d\'épée, dites-lui que vous voulez tuer le démon s\'il l’autorise, mais n\'insistez pas trop. Ce serait mieux qu\'il croie que c\'est son idée.' WHERE l.`ID` = 1484 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à Zureetha Mireloin.' WHERE l.`ID` = 1499 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Les vils quasits' WHERE l.`ID` = 1499 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Zureetha envoie des novices comme vous réduire le nombre des créatures de la caverne près de laquelle vous avez combattu les vils quasits.$b$bJe pense qu\'il serait bon pour vous de l\'aider et ainsi de gagner de l\'expérience. Dites-lui également que vous avez participé à la résolution du problème posé par ces diablotins, elle aura probablement une récompense pour vous.' WHERE l.`ID` = 1499 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter le Breuvage de Ken\'zigla au grunt Logmar, au Camp Taurajo.' WHERE l.`ID` = 1511 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Breuvage de Ken\'zigla' WHERE l.`ID` = 1511 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Je pensais bien que quelqu\'un d\'autre viendrait prendre le breuvage, alors je l\'ai préparé à toutes fins utiles.$b$bTenez, prenez, $n. N’oubliez pas : ne lui donnez que la moitié ! Cela lui donnera suffisamment de force pour qu\'il puisse bouger sans perdre tout son sang. Laissez passer une nuit, puis donnez-lui l\'autre moitié.$b$bVoilà, vous feriez bien de l\'apporter à Logmar au Camp Taurajo. D\'après ce que m\'a dit l\'autre qui est passé avant, il devrait avoir une idée de l\'endroit où Dogran se trouve.' WHERE l.`ID` = 1511 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Utiliser le Pendentif de Dogran pour invoquer et soumettre une succube, puis rapporter le Pendentif de Dogran à Gan\'rul Oeil-sanglant, à Orgrimmar.' WHERE l.`ID` = 1513 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le lien' WHERE l.`ID` = 1513 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Apportez cela au cercle d\'invocation dans la tente de Neeru, $n. Invoquez une ignoble succube, et dominez-la. Comme toujours cependant, soyez $gprudent:prudente;, car la fierté et une trop grande confiance en soi ont terrassé de nombreux démonistes prometteurs.$b$bUne fois que vous l\'aurez vaincue, venez me rendre le pendentif, pour que je puisse donner des nouvelles à Zankaja.' WHERE l.`ID` = 1513 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Trouver le Rocher des kodos et boire le Sapta de terre.' WHERE l.`ID` = 1520 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'appel de la terre' WHERE l.`ID` = 1520 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Un sapta est une boisson qui lie notre esprit aux éléments. Imprégnée de magie, cette potion permet aux esprits ouverts de voir les éléments comme personne d’autre ne peut les voir. Votre esprit sera lié à jamais à l\'élément pour lequel le sapta a été créé, que seuls de rares chamans peuvent confectionner.$b$bIl faut toujours boire le sapta dans un endroit sacré, jamais ailleurs.$b$bCherchez l\'autel du chaman à l\'est d\'ici et buvez-y le sapta.' WHERE l.`ID` = 1520 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Vaincre la Manifestation de feu mineure, et placer sa Braise rougeoyante dans le brasero, en haut de l\'Autel de la flamme éternelle.' WHERE l.`ID` = 1526 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'appel du feu' WHERE l.`ID` = 1526 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Le sapta de feu est terminé. Il est temps pour vous de vous confronter à la flamme. Utilisez le sapta à l\'autel et rendez-vous au sommet de la montagne pour affronter la manifestation. Elle n\'attaquera pas tant que vous ne serez pas $gprêt:prête;, mais elle sait que vous pouvez la voir.$b$bFrappez bien, et frappez vite, $n, car sa puissance grandira si vous tardez à la tuer. Quand vous l\'aurez vaincue, placez ses braises dans le brasero et allumez la torche.' WHERE l.`ID` = 1526 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez la Torche de la flamme éternelle à Kranal Fiss dans les Tarides.' WHERE l.`ID` = 1527 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'appel du feu' WHERE l.`ID` = 1527 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Tenant fermement la torche, vous vous détournez du brasero et embrassez Durotar du regard. Vous sentez la fièvre battre dans votre esprit tandis que le vent avive les flammes qui dansent furieusement.$b$bVous prenez le chemin du retour vers les Tarides, pour trouver Kranal Fiss.' WHERE l.`ID` = 1527 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Trouver Islen Oeil-des-rivières dans les Tarides.' WHERE l.`ID` = 1528 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'appel de l\'eau' WHERE l.`ID` = 1528 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'L\'eau est dans votre avenir, $gmon pote:m\'dame;. Je vois qu\'vous vous en sortez déjà bien avec les arts du feu, et je pense que vous êtes $gprêt:prête; à parler à Islen.$b$bElle vit le long de la côte des Tarides. Si vous suivez le fleuve Furie-du-Sud en direction du sud, vous pouvez pas la rater – cherchez l\'grand requin ! Elle maîtrise les arts des éléments et peut vous apprendre ceux de l\'eau... si vous pensez être $gprêt:prête;.$b$bElle est facile à trouver, n’allez pas trop loin, c\'est tout. Elle se trouve juste après Cabestan.' WHERE l.`ID` = 1528 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Trouver Islen Oeil-des-rivières dans les Tarides.' WHERE l.`ID` = 1529 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'appel de l\'eau' WHERE l.`ID` = 1529 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Cela fait longtemps que vous n\'avez pas été $gmis à l\'épreuve:mise à l\'épreuve;, $n. Vous avez montré de la patience jusque-là dans vos études, mais le temps est à présent venu pour vous d\'apprendre la pureté de l\'eau.$b$bCherchez Islen Oeil-des-rivières dans les Tarides. Elle se trouve le long de la côte est, au sud du fleuve Furie-du-Sud et de Cabestan. Vous la trouverez dans une hutte de pêcheur. Bonne chance à vous, $n.' WHERE l.`ID` = 1529 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Trouver Prate Oeil-des-nuages aux Mille pointes.' WHERE l.`ID` = 1531 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'appel de l\'air' WHERE l.`ID` = 1531 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Y faut que vous y alliez, là. Préparez-vous à montrer qu\'vous êtes digne de r\'cevoir vot\' totem d\'air. Mais déjà, vous d\'vez trouver Prate Oeil-des-nuages aux Mille pointes. Elle vous dira comment obtenir vot\' totem d\'air.$b$bPassez au sud par les Tarides, puis aux Mille pointes, à l\'est. Vous la trouverez cachée dans un trou, avec son p\'tit copain. Haha, ne lui dites pas qu\'je la salue pas, elle aimerait pas trop.' WHERE l.`ID` = 1531 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Trouver Prate Oeil-des-nuages aux Mille pointes.' WHERE l.`ID` = 1532 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'appel de l\'air' WHERE l.`ID` = 1532 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Les vents de Kalimdor se hâtent pour vous rencontrer et vous serez bientôt $gcompté:comptée; parmi nos plus puissants frères et sœurs. La fierté m\'emplit de vous voir arriver à ce stade, et de savoir votre avenir si prometteur.$b$bL\'air est difficile à contrôler, mais j\'ai foi en vos capacités à surmonter tous les obstacles.$b$bPartez pour l\'extrême sud des Tarides et entrez aux Mille pointes. C\'est là, loin à l\'est, que vous trouverez Prate Œil-des-nuages. Elle vous enseignera.' WHERE l.`ID` = 1532 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Remplir l\'Outre bleue vide aux Ruines de Chimétoile en Orneval et la rapporter à Brine dans les Tarides.' WHERE l.`ID` = 1534 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'appel de l\'eau' WHERE l.`ID` = 1534 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Prenez cette outre et enfoncez-vous au cœur de la forêt luxuriante que les elfes de la nuit appellent Orneval. C\'est à l\'extrême nord des Tarides.$b$bUne fois dans la forêt, allez à l\'ouest. Le long des montagnes qui séparent les Serres-Rocheuses d\'Orneval, au-delà du lac Mystral, vous trouverez un lieu sacré : les ruines de Chimétoile. Une petite fontaine jaillit au centre du lac.$b$bApportez-moi un échantillon de l\'eau de cette fontaine. Ce sera le dernier ingrédient que vous devez obtenir avant que je ne vous renvoie à Islen.' WHERE l.`ID` = 1534 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Remplir l\'Outre marron vide au trou d’eau, derrière la hutte de Brine, puis rapportez-lui la, dans les Tarides.' WHERE l.`ID` = 1535 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'appel de l\'eau' WHERE l.`ID` = 1535 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Pour trouver la compréhension et obtenir le sapta, vous devez trouver les eaux les plus pures. Tandis que vous rassemblerez les échantillons pour moi, observez les lieux qui vous entourent. Soyez $gattentif:attentive; aux créatures qui ont besoin d\'eau, et qui la protègent. Voyez comment elle affecte les forêts et les déserts. Soyez témoin de la manière dont la substance même qui maintient la vie force les créatures à ôter la vie.$b$bNous commencerons par une tâche simple : en bas de ma hutte, vous trouverez un bassin de ce précieux liquide. Remplissez-en cette outre et revenez me voir.' WHERE l.`ID` = 1535 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`AreaDescription` = 'Aller au sommet du barrage de Formepierre au Loch Modan' WHERE l.`ID` = 1558 AND l.`locale` = 'frFR' AND (l.`AreaDescription` IS NULL OR l.`AreaDescription` = '' OR BINARY l.`AreaDescription` = BINARY q.`AreaDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Conduire l\'orphelin au barrage de Formepierre au Loch Modan. Vous devez le conduire au milieu du barrage pour qu\'il puisse voir par-dessus l\'immense chute d\'eau.' WHERE l.`ID` = 1558 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le barrage de Formepierre' WHERE l.`ID` = 1558 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Parlez à votre Orphelin humain.' WHERE l.`ID` = 1558 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Forgefer, c\'est là où vivent tous les nains et les gnomes. Pas loin, il y a un endroit qui s\'appelle le Loch Modan. Les nains y ont construit un ÉNORME barrage. Ils disent que c\'est l\'une des choses les plus grandes jamais construites. Ouah !$B$BVous pouvez m\'emmener au Loch Modan pour voir le barrage, s\'il vous plaît ? Je crois que c\'est le barrage de Forme... de Formepierre. Il est énorme, c\'est sûr. J\'aimerais bien regarder par-dessus la grande chute d\'eau. Je promets que je ne me pencherai pas trop au-dessus de la rambarde !' WHERE l.`ID` = 1558 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`AreaDescription` = 'Guider Tooga vers Torta' WHERE l.`ID` = 1560 AND l.`locale` = 'frFR' AND (l.`AreaDescription` IS NULL OR l.`AreaDescription` = '' OR BINARY l.`AreaDescription` = BINARY q.`AreaDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Montrer à Tooga le chemin du retour vers sa femme, Torta.' WHERE l.`ID` = 1560 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La quête de Tooga' WHERE l.`ID` = 1560 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir Torta au Port Gentepression, en Tanaris.' WHERE l.`ID` = 1560 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Je suis complètement perdu !$b$bMa femme, Torta, m\'a envoyé chercher le dîner et j\'ai dû prendre le mauvais chemin quelque part.$b$bAuriez-vous l\'amabilité de me guider vers Torta ? Elle m\'attend au sud de Port Gentepression.' WHERE l.`ID` = 1560 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Chercher Stephanie Turner dans le Quartier commerçant de Hurlevent.' WHERE l.`ID` = 1643 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le Tome de divinité' WHERE l.`ID` = 1643 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Votre tâche, à présent, $n, est de trouver quelqu\'un ici, à Hurlevent, qui a besoin de votre aide. Quelqu\'un ayant un cœur et des motivations purs. Peut-être une personne dévouée aux autres. Peut-être quelqu\'un ayant besoin d\'un guide. En tout cas, cette personne doit être pétrie de bonnes intentions et doit vouloir compter sur votre gentillesse.$b$bAgissez au mieux et revenez me voir après. Alors, nous discuterons de la voie du paladin et de la Lumière.' WHERE l.`ID` = 1643 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter 10 morceaux d\'étoffe de lin à Stephanie Turner à Hurlevent.' WHERE l.`ID` = 1644 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le Tome de divinité' WHERE l.`ID` = 1644 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Qu’ils soient bénis. La plupart ont perdu leur famille dans les attaques du Fléau, ces dernières années.$B$BMon mari, John, collecte des matériaux qui me servent à confectionner des chemises et des pantalons pour les enfants, ce que je n’ai malheureusement pas eu le temps de faire dernièrement.$B$BMais peut-être voudriez-vous m\'aider ? Oh, merci mille fois, $n.$B$BSi vous pouviez m’apporter de l’étoffe de lin pour que je puisse en faire des vêtements pour les enfants, je vous en serais reconnaissante.' WHERE l.`ID` = 1644 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à Duthorian Rall à Hurlevent.' WHERE l.`ID` = 1649 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le Tome de la bravoure' WHERE l.`ID` = 1649 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'La bravoure et toutes les vertus qui vont avec sont comme les minerais rares : pour leur valeur vous devez les chérir, mais vous devez aussi prendre le temps de les entretenir, de les polir. Quand vous les associez judicieusement, vous obtenez un alliage résistant, qui peut résister même aux coups les plus violents.$B$BCette force, votre foi, votre bravoure doivent être éprouvées. Vous devez apprendre à ne jamais perdre la foi et comprendre qu\'avec le pouvoir de la Lumière à vos côtés, vous pourrez surmonter plus d’obstacles que la plupart des gens.' WHERE l.`ID` = 1649 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`AreaDescription` = 'Protéger Daphne Morpuits' WHERE l.`ID` = 1651 AND l.`locale` = 'frFR' AND (l.`AreaDescription` IS NULL OR l.`AreaDescription` = '' OR BINARY l.`AreaDescription` = BINARY q.`AreaDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Défendez Daphne Morpuits contre les attaques des Défias.$B$BAucun de vous deux ne doit mourir, si vous voulez réussir la quête.$B$BQuand vous aurez réussi, reparlez à Daphne Morpuits.' WHERE l.`ID` = 1651 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le Tome de la bravoure' WHERE l.`ID` = 1651 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir Daphne Morpuits dans la Marche de l\'Ouest.' WHERE l.`ID` = 1651 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Je suis sûre qu\'ils seront là dans peu de temps maintenant, préparez-vous.$B$BJ\'ai une arme à la maison. Je vais la chercher et je reviens vous donner un coup de main, mais vous allez devoir faire le plus gros du travail j\'en ai peur.$B$BJe n\'ai aucune idée de leur nombre, mais pour sûr ils seront plus nombreux que la dernière fois.$B$BPriez la Lumière de vous accorder ses faveurs parce que... Vous avez entendu ça ? Je pense qu\'ils arrivent.$B$BNous allons nous replier près de la maison !' WHERE l.`ID` = 1651 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à Duthorian Rall à Hurlevent.' WHERE l.`ID` = 1652 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le Tome de la bravoure' WHERE l.`ID` = 1652 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'S\'il vous plaît, retournez voir Duthorian et dites-lui que je suis saine et sauve. Et c\'est grâce à vous et à l\'Église.$B$BJe vais envoyer un mot à Jordan à Forgefer pour lui dire de ne pas s\'inquiéter. Oh qu\'il me manque ! J\'ai hâte qu\'il revienne.' WHERE l.`ID` = 1652 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Lancer trois Boules puantes des Réprouvés au milieu d’Austrivage en Hautebrande, puis revenez voir la sombre imploratrice Yanka à la Fête de l’homme d’osier, dans les Clairières de Tirisfal.' WHERE l.`ID` = 1657 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Empuantir Austrivage' WHERE l.`ID` = 1657 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Nous allons célébrer la Sanssaint en grande pompe… en en faisant voir de toutes les couleurs à nos ennemis d’Austrivage !$B$BPrenez l’une de ces boules puantes conçues spécialement pour l’occasion. Elle est remplie d’une substance nauséabonde dont aucun humain - ou aucune bête à l’esprit simple, d’ailleurs - ne peut supporter l’odeur. Il faut la jeter au beau milieu d’Austrivage pour qu’elle agisse correctement, donc attendez-vous à combattre l’Alliance !$B$BQuand vous aurez accompli cette tâche… cet hommage à notre libération, revenez me voir !' WHERE l.`ID` = 1657 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à Duthorian Rall, à Hurlevent.' WHERE l.`ID` = 1661 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le Tome de noblesse' WHERE l.`ID` = 1661 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Encore bonjour, $n. Je suis encore plus fier de vous appeler $gfrère:sœur; qu’avant ; votre dévouement est une bénédiction pour nous tous.$B$BLe temps est venu de vous accorder une grande récompense. Sachez que je vous donne cela gratuitement, mais que plus tard, les défis qu’auront à accomplir les paladins qui voudront réaliser mes quêtes seront autrement plus exigeants.$B$BReparlez-moi plus tard et je vous accorderai une grande faveur.' WHERE l.`ID` = 1661 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter la Tasse de Bartleby à Burlguard.' WHERE l.`ID` = 1665 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Tasse de Bartleby' WHERE l.`ID` = 1665 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'OK, voilà ma tasse. Attendez ! Laissez-moi finir avant... OK, allez-y !' WHERE l.`ID` = 1665 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez la Tête de Vejrek à Muren Foudrepique à Forgefer.' WHERE l.`ID` = 1678 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Si vous voulez monter dans les rangs des guerriers, vous avez intérêt à être robuste. Je peux vous apprendre de nouvelles passes d\'armes, mais avant, prouvez-moi que vous pouvez vous débrouiller $gseul:seule; contre des adversaires réels.$B$BVejrek est le plus coriace des trolls du coin ; c\'est lui que vous devez affronter. Il a une hutte dans les contreforts au sud du repaire des Crins-de-givre.$B$BRapportez-moi sa tête et je saurai que vous avez du courage.' WHERE l.`ID` = 1678 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à Muren Foudrepique.' WHERE l.`ID` = 1679 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Muren Foudrepique' WHERE l.`ID` = 1679 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Bonjour guerrier ! Vous êtes $gvoué:vouée; à un grand avenir, mais il vous reste quelques petits trucs à apprendre et Muren Foudrepique est le nain qu\'il vous faut pour vous les enseigner.$B$BVous trouverez Muren dans la Salle d\'armes à la Garde militaire de Forgefer. Parlez-lui quand vous serez $gprêt:prête; à apprendre ce qu\'est un vrai guerrier.' WHERE l.`ID` = 1679 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à Tormus Forge-profonde.' WHERE l.`ID` = 1680 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Tormus Forge-profonde' WHERE l.`ID` = 1680 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Maintenant que vous avez appris de nouvelles passes, il est temps pour vous d\'avoir une arme digne de ce nom. Parlez à Tormus Forge-profonde. Il peut vous fabriquer une arme dont vous me donnerez des nouvelles.$B$BVous trouverez Tormus ici, à Forgefer, à la Grande Forge.' WHERE l.`ID` = 1680 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez la Corne de Vorlus Vilsabot à Elanaria, à Darnassus.' WHERE l.`ID` = 1683 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Vorlus Vilsabot' WHERE l.`ID` = 1683 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Avant de vous apprendre quoi que ce soit, vous devez me prouver votre résolution.$B$BLe satyre Vorlus Vilsabot a découvert un de nos lointains puits de lune, au sud-est du refuge des saisons de Ban\'ethil. Il est en train d’y barboter, souillant l\'eau pure avec sa crasse.$B$BTrouvez Vorlus au puits de lune et détruisez-le. Rapportez-moi sa corne comme preuve, et je vous entraînerai.$B$BLe chemin vers le puits de lune est bien caché, $n, restez $gconcentré:concentrée; et alerte, et vous le trouverez.' WHERE l.`ID` = 1683 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à Elanaria.' WHERE l.`ID` = 1684 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Bonjour, $gguerrier:guerrière; ! Vos compétences progressent, mais il y a plus à savoir sur votre métier que vous ne le pensez. Pour continuer à progresser il vous faudra bientôt trouver un Maître.$B$BLa guerrière Elanaria réside à Darnassus, à la Terrasse des guerriers. Elle peut vous former.' WHERE l.`ID` = 1684 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Aller voir Gakin le Tisse-noir dans le Quartier des Mages de Hurlevent.' WHERE l.`ID` = 1685 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Convocation de Gakin' WHERE l.`ID` = 1685 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'N\'est-ce pas toujours ainsi ? Je vous ai $gcherché:cherchée; partout aujourd\'hui et je n\'ai pas pu vous trouver, et maintenant que je n\'ai plus besoin de vous, vous venez me voir. !$b$bJ\'ai perdu assez de temps à vous chercher, je ne vais donc pas vous faire attendre plus longtemps. Maître Gakin vous convoque pour une autre leçon. Il me semble que vous devriez y aller immédiatement.$b$bVous le trouverez au sous-sol de « l\'Agneau assassiné ». Au fait, pas un mot : je préférerai que l’endroit reste tranquille.' WHERE l.`ID` = 1685 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`AreaDescription` = 'Aller au phare de la marche de l\'Ouest' WHERE l.`ID` = 1687 AND l.`locale` = 'frFR' AND (l.`AreaDescription` IS NULL OR l.`AreaDescription` = '' OR BINARY l.`AreaDescription` = BINARY q.`AreaDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Emmenez l\'orphelin voir le phare sur la côte de la marche de l\'Ouest.' WHERE l.`ID` = 1687 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le phare hanté' WHERE l.`ID` = 1687 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Parlez à votre Orphelin humain.' WHERE l.`ID` = 1687 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Des fois, tard le soir, les gouvernantes de l\'orphelinat nous racontent des histoires qui font peur. C\'est GÉNIAL ! Il y en a une à propos d\'un fantôme qui hante un phare dans la marche de l\'Ouest. C\'était un pirate à qui d\'autres pirates ont pris son bateau. Waou !$B$BVous pourriez m\'emmener au phare de la marche de l\'Ouest ? Je veux voir le fantôme du capitaine ! Je resterai près de vous, c\'est promis, je ne m\'enfuirai pas ni rien...' WHERE l.`ID` = 1687 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Utilisez l’Écharpe de pierre de sang pour invoquer et soumettre un marcheur du Vide, puis rapportez-la à Gakin le Tisse-noir, à Hurlevent.' WHERE l.`ID` = 1689 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le lien' WHERE l.`ID` = 1689 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'En retrouvant mon écharpe et en éliminant Surena, vous avez prouvé que vous étiez au moins aussi $gtalentueux:talentueuse; qu\'elle.$b$bCela dit, vous avez terriblement besoin d\'entraînement. Vous pouvez manier les flux magiques, bien sûr, mais être démoniste, c\'est bien plus que cela.$b$bJe vais vous montrer comment contrôler un marcheur du Vide, mais avant, vous devez en invoquer un dans le cercle d\'invocation et le maîtriser avec les armes – physiques et magiques – dont vous disposez. Utilisez la magie que contient l\'écharpe sur le cercle d\'invocation en bas.' WHERE l.`ID` = 1689 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez le Tonneau de Scalder à Furen Barbe-longue.' WHERE l.`ID` = 1702 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Fabricant de bouclier' WHERE l.`ID` = 1702 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous avez montré vos talents en relevant le défi de Rethban, $n. Et je respecterai ma parole. Je vais vous donner votre récompense...$B$BSauf qu\'elle est à Hurlevent.$B$BParlez à mon ami, Furen Barbe-longue, dans le quartier des Nains de Hurlevent. C\'est le meilleur fabricant de boucliers que vous rencontrerez, et il me doit une faveur.$B$BTenez, apportez-lui ce tonneau de Brasselorge Scalder et demandez-lui un bouclier. Il vous en donnera un bon.' WHERE l.`ID` = 1702 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez 20 Coquilles desséchées au soleil à Mathiel, à Darnassus.' WHERE l.`ID` = 1710 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Coquilles desséchées au soleil' WHERE l.`ID` = 1710 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Mon collègue, Furen Barbe-longue, a fait une découverte que je suis impatient d\'essayer. Je veux la tester sur une de mes nouvelles armures, car je pense que ses techniques me permettraient d’améliorer la qualité de mes produits.$B$BVoulez-vous m\'aider ? Si vous me rapportez de quoi fabriquer l\'armure, alors j\'en ferai une pour vous.$B$BJ\'ai besoin de coquilles d\'œuf desséchées au soleil des wyvernes ailes-fières qui résident à Haut-Perchoir, dans les Mille pointes. Cherchez les coquilles au pied de leurs nids, et revenez quand vous en aurez assez.' WHERE l.`ID` = 1710 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez le Cœur de tourbillon à Bath\'rah la Vigie des vents.' WHERE l.`ID` = 1713 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'invocation' WHERE l.`ID` = 1713 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Je suis prêt à faire mon rituel pour invoquer un Cyclonien. Quand il apparaîtra, vous devez l\'abattre et lui prendre son Cœur de tourbillon. Je l\'utiliserai pour faire une arme qui possédera les pouvoirs du Cyclonien.$B$B$n, êtes-vous $gprêt:prête; à affronter le Maître des vents ?' WHERE l.`ID` = 1713 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Aller voir Gakin le Tisse-noir dans le Quartier des Mages de Hurlevent.' WHERE l.`ID` = 1715 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'Agneau assassiné' WHERE l.`ID` = 1715 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Hum ! Dans le temps, tous les démonistes de Khaz Modan étaient entraînés par les maîtres de Gnomeregan, mais maintenant que nous avons été forcés de nous réfugier dans ce trou à rats qu\'est Forgefer, et que Magni a décidé de nous surveiller, nous sommes forcés d\'envoyer les novices étudier à Hurlevent.$b$bHeureusement, Gakin n\'est pas un empoté, vous pourrez donc continuer à recevoir un enseignement, mais cela m\'exaspère !$b$bEnfin, vous trouverez Gakin au sous-sol de « l\'Agneau assassiné » à Hurlevent.' WHERE l.`ID` = 1715 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à Duthorian Rall à Hurlevent.' WHERE l.`ID` = 1780 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le Tome de divinité' WHERE l.`ID` = 1780 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'J\'amènerai ça aux enfants dès aujourd\'hui. Merci beaucoup, $c. Il est rare de nos jours qu\'$gun homme:une femme; de votre trempe se montre dans cette ville, mais vous avez prouvé que les paladins à Hurlevent ne tourneront jamais le dos à ceux qui sont dans le besoin.$B$BAdieu.' WHERE l.`ID` = 1780 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Prendre le Symbole de vie et ressusciter Narm Faulk dans Dun Morogh.' WHERE l.`ID` = 1783 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le Tome de divinité' WHERE l.`ID` = 1783 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'J\'espionnais des nains sombrefers qui se terrent au sud du lac du Lit d\'Helm. Nous savions qu\'ils n\'étaient pas là pour rien, alors Narm et moi nous nous sommes rapprochés – assez près pour voir leur chef donner des ordres à ses hommes.$B$BNarm et moi nous avons tenté d\'en tuer quelques-uns, mais ils se sont révélés plus résistants que nous le pensions, et beaucoup plus nombreux. Narm m\'a dit de partir et de ramener du renfort, donc voilà pourquoi je suis là.$B$BNarm a besoin d\'aide, et je ne me reposerai pas tant qu\'il n\'en n\'aura pas trouvé.$B$BAllez-vous m\'aider, $n ?' WHERE l.`ID` = 1783 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Récupérez un Document sombrefer près du lac du Lit d\'Helm, et rapportez-le à Muiredon Forgeguerre, à Forgefer.' WHERE l.`ID` = 1784 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le Tome de divinité' WHERE l.`ID` = 1784 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Avant de tomber, Muiredon et moi avions presque vaincu un des espions sombrefers près de cette petite maison. Nous avons vu le capitaine leur passer des ordres, et nous avons cherché à le tuer pour récupérer ces ordres.$B$BCertaines personnes au conseil de Forgefer ne croient pas à la présence des Sombrefers en Dun Morogh. En récupérant un de ces scripts, nous aurions non seulement la preuve de leur présence ici, mais nous aurions aussi une idée de ce qu\'ils trament.$B$BRécupérez un de ces scripts et rapportez-le à Muiredon, $n.' WHERE l.`ID` = 1784 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
