UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Parler à Dillinger' WHERE l.`ID` = 1818 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'J\'ai entendu dire que le nécrogarde Dillinger avait un travail pour quelqu\'un comme vous. Si vous voulez prouver votre valeur aux forces de la Dame noire, alors présentez-vous devant Dillinger immédiatement.$B$BLe poste du nécrogarde Dillinger est à la frontière ouest de Brill, près du cimetière.' WHERE l.`ID` = 1818 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
