UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Parler à Coleman' WHERE l.`ID` = 1820 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous avez prouvé votre valeur à la Dame noire, à présent vous pourrez peut-être la prouver à l\'un de ses sujets.$B$BColeman Farthing cherche un guerrier pour être son bras vengeur contre les ennemis des Réprouvés.$B$BVous le trouverez à « la Taverne des Pendus » dans l\'est de Brill.' WHERE l.`ID` = 1820 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
