UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'On dit qu\'avant de mourir, Velora Nitely était l\'un des plus grands forgerons d\'armures de Lordaeron. La mort, semble-t-il, n\'a pas affecté ses talents. Allez voir Velora : elle fabriquera vos garde-jambes de brutalité.$B$BVelora officie à Fossoyeuse de Lordaeron, dans le quartier des Marchands.' WHERE l.`ID` = 1841 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Rapporter 7 Sabots fendus de satyre à Ula\'elek au village de Sen\'jin en Durotar.' WHERE l.`ID` = 1842 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
