UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '$n ! Bink, ma collègue de Forgefer, vous salue. Elle a une mission qu\'elle ne veut confier qu\'à un mage ! Avez-vous cette qualification, $n ?$B$BDans ce cas, adressez-vous à elle. Elle passe son temps dans le Hall des Mystères de la Garde mystique de Forgefer.' WHERE l.`ID` = 1879 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Détruire 4 Tas de Ju-Ju, puis retourner voir Un\'thuwa au village de Sen\'jin.' WHERE l.`ID` = 1884 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Les Tas de Ju-Ju' WHERE l.`ID` = 1884 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Le démoniste Zalazane des îles de l\'Écho a perturbé le flux magique en Durotar. Il l\'a fait par l’intermédiaire de fétiches infectés, des tas de Ju-ju, qu\'il a placés dans ses huttes sur l\'île principale d\'Écho.$B$BCes tas perturbent la faune et la flore et accroissent le pouvoir des sorciers et des créatures infernales qui se cachent dans les coins sombres du pays.$B$BVous devez détruire les tas de Ju-ju, $n, avant que le flux de magie ne soit altéré pour toujours.' WHERE l.`ID` = 1884 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Aller voir Mennet Carkad dans le Quartier des Voleurs de Fossoyeuse.' WHERE l.`ID` = 1885 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '$n ? Pas vraiment ce à quoi je m\'attendais, compte tenu de l\'intérêt que Carkad lui-même manifeste pour vous ! Comme quoi les apparences sont parfois trompeuses, non ?$b$bPeu importe, vous devez aller le voir dès que possible. Autant que vous ne sachiez pas ce qui est arrivé au dernier qui a ignoré ses sommations.' WHERE l.`ID` = 1885 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
