UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir Magus Tirth à la Piste des mirages, dans les Mille pointes.' WHERE l.`ID` = 1950 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Je peux vous aider pour le livre, mais d\'abord, vous devez m\'aider !$B$BL’ouvrage que vous cherchez est dans mon coffre-fort, fermé magiquement. Pour l\'ouvrir, il faut prononcer une incantation spéciale et je ne me souviens plus de l\'incantation ! D’habitude, mon assistant m\'aide à me rappeler de ces choses, mais je ne le trouve nulle part.$B$BSi vous voulez mon livre, trouvez d\'abord mon apprenti ! Demandez aux gens le long de la piste. Avec un peu de chance, quelqu\'un l\'aura vu. Ramenez-le ici, ou au moins qu\'il vous donne l\'incantation pour ouvrir le coffre !' WHERE l.`ID` = 1950 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter 10 morceaux d\'Etoffe de lin et 6 Gemmes de mana de Dalaran à Josef Gregorian.' WHERE l.`ID` = 1961 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
