UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Bouseux de terrien ! Tu dois me dégoter mon second.$B$BPrends c\'te clé, mets-y dans le bon trou, et ramèn\' le ici pour servir le cap\'taine.$B$BCes murlocs et leur chef vont pas beaucoup aimer quand mon second va leur mettre l\'grappin dessus !' WHERE l.`ID` = 2078 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez le Fardeau d\'Ukor à l\'aubergiste Grosk à Tranchecolline.' WHERE l.`ID` = 2161 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Un fardeau de péon' WHERE l.`ID` = 2161 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Excusez-moi... Pouvez-vous m\'aider ?$B$BVous voyez ce chargement ? J\'ai suivi la route, j\'ai bravé les scorpides, les araignées, que sais-je encore, tout ça pour apporter ces vivres dans la vallée des Épreuves. Je pensais qu\'ils en auraient besoin... Mais non, ils n\'en ont pas voulu ! Maintenant, il ne me reste plus qu\'à rapporter tout ça à Tranchecolline et ça me terrorise, à cause des bêtes...$B$BVous pourriez vous en charger pour moi ? Je ne suis qu\'un malheureux péon mais vous... Vous n\'avez peur de rien, vous avez l\'habitude d\'être héroïque ! $B$BRapportez ce paquet à l\'aubergiste Grosk à l\'auberge de Tranchecolline. Merci !' WHERE l.`ID` = 2161 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à Hulfdan Barbe-noire à Forgefer.' WHERE l.`ID` = 2218 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La voie du salut' WHERE l.`ID` = 2218 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Une autre âme perdue en quête de conseil, hein ? Je suppose que vous cherchez une voie, votre voie. J\'ai déjà vu ça mille fois, encore $gun héros désœuvré:une héroïne désœuvrée; qui cherche du travail.$B$BEh bien, c\'est aujourd\'hui votre jour de chance, mon $gami:amie;. Hogral connaît la solution à votre tourment.$B$BVoici ce qu\'il vous faut faire : prenez cette route jusqu\'à Forgefer et cherchez-y la caverne Lugubre. Une fois sur place, localisez la guilde des voleurs et demandez entretien à Hulfdan Barbe-noire. Il vous guidera vers votre salut.' WHERE l.`ID` = 2218 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Porter la Rose de Jannok à Syurna à Darnassus.' WHERE l.`ID` = 2241 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Pomme d\'amour' WHERE l.`ID` = 2241 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Ils disent que je suis fleur bleue... quoi que cela puisse vouloir dire.$B$BC\'est vrai qu\'à tout instant je pense à Syurna. C\'est vrai, ma maison est tapissée de peintures et de dessins de Syurna. C\'est vrai, je peux passer des jours sans manger, boire ou dormir en me languissant de l\'amour que nous aurions pu connaître. Mais est-ce mal ?$B$BEt maintenant elle refuse de me voir ! MOI ! J\'ai essayé de lui envoyer des messages, mais elle ne veut parler à personne à moins que ce ne soit un voleur.$B$BPourriez-vous lui porter cette fleur ? Et n\'oubliez pas de dire que c\'est de la part de Jannok.' WHERE l.`ID` = 2241 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Trouver Sethir l’Ancien et rapporter tout indice découvert à Syurna.' WHERE l.`ID` = 2242 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'appel du destin' WHERE l.`ID` = 2242 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Nous pensons qu\'il existe un être qui pourrait nous aider à comprendre ce qui arrive aux forêts de Teldrassil. Malheureusement, toutes les tentatives pour amener la créature à coopérer se sont soldées par un désastre.$B$BIl se cache sur une branche, sur le rebord de la clairière de l\'Oracle. À ce jour, tous ceux qui ont approché le satyre, par la force ou la diplomatie, ont été anéantis. Le camouflage est peut-être la solution, $n.$B$BTrouvez ce que Sethir l\'Ancien cache dans ses poches et faites-moi un rapport.' WHERE l.`ID` = 2242 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
