UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Le Service de Renseignement de Hurlevent a entendu parler de vos exploits, $n, et il veut vous recruter. $B$BLe voyage est coûteux et périlleux, mais on ne rejette pas l\'opportunité de s\'entraîner pour le SI:7 !$B$BUn nouveau monde s\'ouvre à vous, $n. Rendez-vous dans la Vieille ville de Hurlevent et adressez-vous à Renzik "le Kriss" " au QG du SI:7.' WHERE l.`ID` = 2260 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
