UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Votre seule détermination ne suffira pas pour affronter les obstacles qui nous attendent.$B$BAdressez-vous à Zando\'zan pour commencer votre entraînement comme opérationnel de la Main-Brisée.$B$BLorsque vous maîtriserez le noble art du vol et de la tricherie vous pourrez faire un pas de plus vers votre destinée.' WHERE l.`ID` = 2379 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
