UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'En tant que voleur de la Main-Brisée, il est impératif que vous appreniez le Salut brisé. C\'est la seule façon d\'identifier un autre membre de la Main.$B$BRegardez, apprenez, répétez.' WHERE l.`ID` = 2460 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
