UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'La prêtresse A\'moora vous demande de placer les Filières d\'argent de dame Sathrah dans la fontaine à l\'intérieur du temple, puis de retourner la voir.' WHERE l.`ID` = 2520 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
