UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Oh, $n ! Bienvenue. On dirait que vous avez apprécié l\'effet de ce mélange tiré des Raillecroc. Prenez garde, si l\'effet immédiat est un fantastique regain de force, à long terme les effets pourraient être dangereux pour votre esprit et votre intelligence.$B$BSachant cela, en voulez-vous encore ? Dans ce cas, apportez-moi trois autres joues de Raillecroc, deux poumons de sanglier éclatés et une pince de scorpok.' WHERE l.`ID` = 2582 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Marin Brouillecaboche vous demande d\'aller voir Saupoudr à Gadgetzan.' WHERE l.`ID` = 2606 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'De bon goût' WHERE l.`ID` = 2606 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Beurk ! Cette substance a un goût épouvantable ! Je peux oublier tout de suite mon idée...$B$BAttendez, qu\'est-ce que c\'est que ça ? Oh, je sais ! Vous pensez que je dois continuer de croire en cette substance. Très bien alors...$B$BOh, j\'ai une idée brillante ! Apportez cette rosée à mon amie Saupoudr, c\'est un excellent chef. Racontez-lui ce que nous avons fait, et dites-lui que nous voudrions que ça descende un peu plus facilement.$B$BSi déjà ça a mauvais goût, il faut au moins que ça ait quelque chose de spécial... Et bien moi, je ne le sens pas...' WHERE l.`ID` = 2606 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Aller voir le docteur Mixilpixil dans la Cave de la caserne.' WHERE l.`ID` = 2607 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
