UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'À la recherche de Galvan' WHERE l.`ID` = 2759 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Galvan a quitté Baie-du-Butin depuis longtemps, mais les membres de l\'ordre sont restés en ville, espérant trouver un jour une autre personne digne de la tutelle de Galvan.$B$BPortez cet insigne à McGavan à Baie-du-Butin.$B$BSi vous avez réussi à aller aussi loin, il saura que vous êtes digne de lui. J\'ai foi en vous, $n !' WHERE l.`ID` = 2759 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
