UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Au dernier championnat intervallée des forgerons, tous les spectateurs ont vu un de ces chiens de la mine de la KapitalRisk m\'attaquer la jambe. Mais ils ne savent pas ce qui m\'a permis de continuer et de gagner ce championnat. Eh oui ! Des bottes ornées en mithril !$B$BJe vais avoir besoin d\'apprendre à faire un pantalon orné en mithril cette année, car la KapitalRisk participe encore au championnat ! Apprenez-moi comment faire le pantalon et je vous apprendrai à faire les bottes !' WHERE l.`ID` = 2772 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez deux Cuirasses lourdes en mithril et une paire de Gants ornés en mithril à Trenton Martelume.' WHERE l.`ID` = 2773 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
