UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir Scooty à Baie-du-Butin, dans la Vallée de Strangleronce.' WHERE l.`ID` = 2843 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Aussi longtemps que vous êtes en possession du transpondeur gobelin, tout ce que vous avez à faire est de traverser le portail et vous vous retrouverez à Gnomeregan.$B$BIl y aura peut-être des effets secondaires bizarres, mais aucun ne devrait être permanent... plus maintenant.$B$BJ\'oubliais de parler du plus important : le retour. Lorsque vous serez $gprêt:prête; à revenir, allez au portail de multitéléportation de Gnomeregan !$B$BBon, il faut maintenant régler le transpondeur selon votre poids et votre taille.' WHERE l.`ID` = 2843 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Retrouver la jeune elfe de la nuit perdue.' WHERE l.`ID` = 2844 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le garde géant' WHERE l.`ID` = 2844 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Je suis vraiment bon à rien, $n. J\'étais supposé surveiller mon amie Shay, et je l’ai perdue. Je ne suis pas sûr de ce qui s\'est passé, mais la dernière fois que je l\'ai vue, nous étions en train de marcher dans les ruines au nord d\'ici.$B$BTout allait bien, mais lorsque je me suis retourné vers elle... elle avait disparu.$B$BMaintenant je ne sais plus quoi faire. Vous avez une idée, $n ? Je suis affreusement inquiet.$B$BEt si vous alliez la chercher ? Vos jambes vous permettent d\'aller plus vite que moi.' WHERE l.`ID` = 2844 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`AreaDescription` = 'Ramener Shay au Camp de Croque-roc' WHERE l.`ID` = 2845 AND l.`locale` = 'frFR' AND (l.`AreaDescription` IS NULL OR l.`AreaDescription` = '' OR BINARY l.`AreaDescription` = BINARY q.`AreaDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Prendre la Cloche de Shay dans le coffre.$B$BEscorter Shay Coursefeuille au Camp de Croque-roc.' WHERE l.`ID` = 2845 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Shay l\'égarée' WHERE l.`ID` = 2845 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir Croque-roc aux Colosses jumeaux, en Féralas.' WHERE l.`ID` = 2845 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Pouvez-vous m\'aider à retrouver mon chemin jusqu\'à mon ami, Croque-roc ? Il était supposé me surveiller… Mais j\'ai tendance à folâtrer de-ci de-là. Il y a tant de choses à voir et je me laisse facilement distraire.$B$BIl y a toutefois une chose qui me ramène toujours.$B$BDans ce coffre, vous trouverez une cloche qui m\'est précieuse. J\'adore sa sonorité. Si je m\'égare, vous n\'avez qu\'à la faire sonner, je reviendrai immédiatement.' WHERE l.`ID` = 2845 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Rapporter 10 Cuirs épais à Pratt McGrubben au bastion de Pennelune.' WHERE l.`ID` = 2847 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'armure en cuir fauve' WHERE l.`ID` = 2847 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '$n, vous avez acquis une bonne connaissance du travail du cuir ! Mais je sais des choses qui pourraient vous intéresser… L\'armure en cuir fauve ! L’intérêt du cuir fauve tient aux propriétés chaotiques des sauvageonnes et de quelques autres créatures d\'ici. L\'armure que vous réaliserez sera ce qu’un artisan de votre compétence peut fabriquer de mieux.$B$BJe vous apprendrai à la réaliser si vous acceptez de travailler pour moi pendant un moment. Le coût initial est juste de dix pièces de cuir épais. Après nous parlerons technique.' WHERE l.`ID` = 2847 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter 6 Renforts d\'armure épais et 1 Sauvageonne à Pratt McGrubben au bastion de Pennelune.' WHERE l.`ID` = 2848 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Les épaulières en cuir fauve' WHERE l.`ID` = 2848 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Les épaulières en cuir fauve protègent efficacement le haut des bras et les épaules. Comme l\'ensemble des pièces d\'armure en cuir fauve, elles bénéficient d\'une qualité supplémentaire, mais aléatoire, en raison de l\'utilisation des sauvageonnes.$B$BPour ce patron, j’ai besoin de six renforts d\'armure épais et d’une sauvageonne. Cela ne devrait pas vous poser de problèmes.' WHERE l.`ID` = 2848 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Rapporter 2 Cuirasses en écailles de tortue, 2 paires de Gants en écailles de tortue et 1 Sauvageonne à Pratt McGrubben au bastion de Pennelune.' WHERE l.`ID` = 2849 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le gilet en cuir fauve' WHERE l.`ID` = 2849 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Le gilet est la pièce maîtresse de toute armure en cuir fauve. Il procure une protection maximale du torse tout en permettant à la puissante magie des sauvageonnes de se diffuser dans l’armure.$B$BPour ce modèle, je demande deux paires de gants en écailles de tortue, deux cuirasses en écailles de tortue et une sauvageonne. C\'est une grosse commande, mais vous ne devriez pas avoir de problème à me la fournir.' WHERE l.`ID` = 2849 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Rapporter 2 Tuniques de la nuit, 2 Bandeaux de la nuit et 1 Sauvageonne à Pratt McGrubben au bastion de Pennelune.' WHERE l.`ID` = 2850 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le casque en cuir fauve' WHERE l.`ID` = 2850 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Un casque en cuir fauve offre une protection optimale sans sacrifier au confort. Comme pour l\'armure en cuir fauve, les sauvageonnes lui apportent une amélioration puissante, mais aléatoire. Les porteurs d\'armures de cuir raffolent de cet article !$B$BPour ce modèle, j\'ai besoin de deux tuniques de la nuit, deux bandeaux de la nuit et d\'une sauvageonne. Complétez cette commande et le patron est à vous !' WHERE l.`ID` = 2850 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Rapporter 2 Pantalons de la nuit, 2 paires de Bottes de la nuit et 2 Sauvageonnes à Pratt McGrubben au bastion de Pennelune.' WHERE l.`ID` = 2851 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Les bottes en cuir fauve' WHERE l.`ID` = 2851 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous avez déjà beaucoup appris, $n. Mais ce n’est pas fini. Après viennent les bottes en cuir fauve, la pierre angulaire de tout l\'équipement.$B$BCes bottes protègent bien les pieds tout en étant très confortables. Les semelles souples sont une bénédiction pour ceux qui se déplacent discrètement.$B$BPour ces bottes, j\'ai besoin de deux pantalons de la nuit, de deux paires de bottes de la nuit, ainsi que de deux sauvageonnes. Lorsque vous aurez tout cela, faites-le-moi savoir.' WHERE l.`ID` = 2851 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Rapporter 2 Casques en écailles de tortue, 2 Brassards en écailles de tortue et 2 Sauvageonnes à Pratt McGrubben au bastion de Pennelune.' WHERE l.`ID` = 2852 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Les jambières en cuir fauve' WHERE l.`ID` = 2852 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous pouvez maintenant apprendre des techniques plus complexes, $n. Les jambières en cuir fauve sont un des équipements en cuir les plus résistants et les plus puissants. La taille, les hanches et les parties vitales sont particulièrement bien protégées. Les aventuriers qui l\'utiliseront apprécieront grandement cette protection combinant l\'amélioration apportée par la sauvageonne.$B$BPour ce modèle, j\'ai besoin de deux casques en écailles de tortue, de deux brassards en écailles de tortue et de deux sauvageonnes.' WHERE l.`ID` = 2852 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Rapporter 10 Cuirs épais à Jangdor Rôdeur-agile au Camp Mojache.' WHERE l.`ID` = 2854 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'armure en cuir fauve' WHERE l.`ID` = 2854 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '$n, la renommée de vos talents vous précède. Je connais quelque chose qui pourrait vous intéresser... l\'armure en cuir fauve ! Le cuir fauve tire ses propriétés des sauvageonnes que l\'on trouve dans la végétation luxuriante et sur quelques créatures. Cela ne devrait pas être compliqué pour quelqu\'un de votre niveau.$B$BJe vous enseignerai, mais en échange vous travaillerez pour moi pendant un moment. La première chose consiste à me rapporter dix pièces de cuir épais. Après nous discuterons technique.' WHERE l.`ID` = 2854 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Rapporter 2 Pantalons de la nuit, 2 paires de Bottes de la nuit et 2 Sauvageonnes à Jangdor Rôdeur-agile au Camp Mojache.' WHERE l.`ID` = 2858 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Les bottes en cuir fauve' WHERE l.`ID` = 2858 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous avez déjà beaucoup appris, $n. Mais ce n’est pas tout. L\'étape suivante concerne les bottes en cuir fauve.$B$BElles protègent bien les pieds tout en restant confortables. Les semelles souples sont une bénédiction pour ceux qui aiment se déplacer discrètement.$B$BPour ces bottes, j\'ai besoin de deux pantalons de la nuit et deux paires de bottes de la nuit, ainsi que de deux sauvageonnes. Lorsque vous aurez tout cela, nous continuerons.' WHERE l.`ID` = 2858 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Rapporter 2 Casques en écailles de tortue, 2 Brassards en écailles de tortue et 2 Sauvageonnes à Jangdor Rôdeur-agile au Camp Mojache.' WHERE l.`ID` = 2859 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Les jambières en cuir fauve' WHERE l.`ID` = 2859 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous pouvez maintenant apprendre des techniques plus complexes, $n. Les jambières en cuir fauve sont un des équipements en cuir les plus résistants et les plus puissants. La taille, les hanches et les parties vitales sont particulièrement bien protégées. Les aventuriers qui l\'utiliseront apprécieront grandement cette protection combinant l\'amélioration apportée par la sauvageonne.$B$BPour ce modèle, j\'ai besoin de deux casques en écailles de tortue, de deux brassards en écailles de tortue et de deux sauvageonnes.' WHERE l.`ID` = 2859 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Tuez 5 Alphas griffebois et retournez voir Hadoken Rôdeur-agile en moins d\'une heure.' WHERE l.`ID` = 2863 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Frappe sur les Alphas' WHERE l.`ID` = 2863 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Le plan concerne divers chefs gnolls - les Alphas pour reprendre leur propre appellation - et leur élimination successive en un minimum de temps. Si nous pouvions exécuter ce genre d\'éradication rapide et précise contre eux, cela amènerait le chaos dans leurs rangs. Et peut-être que le message passerait même à l\'intérieur de leurs têtes épaisses et infestées de puces que nous pouvons et allons les détruire !$B$BJe veux que vous soyez $gle messager:la messagère; de ma volonté. Éliminez cinq de leurs Alphas en une heure pour cette mission, $n, ou nous resterons dans l\'impasse.' WHERE l.`ID` = 2863 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Retourner voir Shandris Pennelune au bastion de Pennelune et lui rendre compte de vos découvertes.' WHERE l.`ID` = 2867 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Retourner au bastion de Pennelune' WHERE l.`ID` = 2867 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Après la découverte du belvédère étrange au cœur des ruines de Solarsal, il est temps de retourner au bastion de Pennelune et faire votre rapport au général Shandris Pennelune.' WHERE l.`ID` = 2867 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
