UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Contre les Hainecrêtes' WHERE l.`ID` = 2869 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'La meilleure approche est de penser, indépendamment du projet réel des nagas, qu\'ils tentent de prendre possession de l\'île. Nous devons réagir énergiquement avant qu\'il ne soit trop tard.$B$BRapportez-moi dix écailles de Hainecrête en bon état ; pas besoin de vous expliquer comment vous les procurer. Vous diminuerez leur puissance et affaiblirez leur présence sur l\'île de Sardor, ce qui joue en notre faveur.' WHERE l.`ID` = 2869 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Porter la Relique mystérieuse à Vestia Lancelune au bastion de Pennelune.' WHERE l.`ID` = 2871 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Livraison de la relique' WHERE l.`ID` = 2871 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Si vous aviez l\'amabilité de porter la relique à ma femme Vestia, je vous en serais très reconnaissant. Elle n\'est pas seulement une excellente prêtresse, elle fait également partie des meilleurs érudits que vous puissiez trouver. Je n\'arrive pas à comprendre l’usage de cet objet. Si quelqu\'un peut le savoir, c\'est ma femme... et nous avons besoin de savoir de quoi il s\'agit !$B$BElle est juste derrière le virage, sûrement en train d\'étudier. Merci, $n.' WHERE l.`ID` = 2871 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Présenter les Horaires des bateaux aux autorités de Port Gentepression.' WHERE l.`ID` = 2876 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Horaires des bateaux' WHERE l.`ID` = 2876 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Ce parchemin détaille le calendrier des livraisons entre Port Gentepression et Baie-du-Butin. La liste contient le nom des navires et des dates, passées ou à venir. Certaines lignes sont cochées d’un grand X. D\'autres sont annotées avec "Bon butin" ou "Dur combat".$B$BQuelqu\'un à Port Gentepression apprécierait certainement de voir ce document.' WHERE l.`ID` = 2876 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Dynamiser le Bâton de Troyas et trouver le Monolithe d\'Equinex.' WHERE l.`ID` = 2879 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le Bâton d\'Equinex' WHERE l.`ID` = 2879 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Il semble que ce bâton soit le Bâton d\'Equinex. C\'est en fait une clé qui permet d\'ouvrir le Monolithe d\'Equinex érigé dans les ruines de Vent-du-Corbeau, sur le continent, à l\'ouest du Bosquet du rêve.$B$BLocalisez les quatre flammes qui brûlent toujours dans les ruines: Samha, Imbel, Byltan et Lahassa. Là, retrouvez leur essence, et tout en vous tenant près du Monolithe, utilisez les essences pour dynamiser le bâton. S\'il s\'agit bien du Bâton d\'Equinex, vous pourrez alors ouvrir le Monolithe et prendre l\'artéfact sacré qui s\'y trouve.' WHERE l.`ID` = 2879 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
