UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Les plans de bataille' WHERE l.`ID` = 2903 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Une fois trouvés les plans des gnolls, il reste à les porter à Hadoken Rôdeur-agile au Camp Mojache. Peut-être comprendra-t-il les projets des gnolls…' WHERE l.`ID` = 2903 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler au Maître mécanicien Fontuyau, à Forgefer.' WHERE l.`ID` = 2931 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Du travail pour Fontuyau' WHERE l.`ID` = 2931 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Le maître-mécanicien Fontuyau à Forgefer a besoin d\'aventuriers ! Il organise des groupes pour pénétrer à nouveau dans Gnomeregan afin d\'effectuer une mission de récupération de première importance.$B$BIl se peut que Fontuyau ne soit pas membre des grandes Assemblées d\'arcanologie, d\'alchimie ou de sciences d\'ingénieries comme je le suis, mais il reste un gnome intelligent. S\'il considère que c\'est important, alors mes calculs indiquent qu\'il y a quatre-vingts pour cent de chances que ce soit véritablement important !$B$BIl s\'agit là des probabilités les plus optimistes en ce qui nous concerne !' WHERE l.`ID` = 2931 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
