UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Ces bouteilles contiennent un terrible venin.$B$BVu le nombre de bouteilles dans ce village, les Fanécorces doivent projeter quelque chose d\'important avec elles ; peut-être qu\'un apothicaire de la ville toute proche de Moulin-de-Tarren serait intéressé par l\'étude d\'un échantillon.' WHERE l.`ID` = 2933 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
