UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Ce livre a l\'air de ne pas avoir été ouvert depuis des années. Sa couverture est passée et ses pages jaunies ; mais en l\'examinant de plus près, vous remarquez que c\'est exactement ce que Troyas devait rechercher.$B$BVous le prenez, puis réalisez que vous devriez d\'abord demander la permission avant de l\'emprunter.' WHERE l.`ID` = 2940 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Rapporter la Pierre étincelante et le Bâton d\'Equinex à Troyas Lunebise, dans le bastion de Pennelune.' WHERE l.`ID` = 2942 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La Pierre du matin' WHERE l.`ID` = 2942 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
