UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Voilà, $n. Je vous en prie, prenez soin de mon livre.$B$BPartez, à présent. Je suis sûre que Troyas attend votre retour avec impatience.' WHERE l.`ID` = 2943 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
