UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apprendre le but du Gardien des pierres de Norgannon, puis interagir avec le Piédestal d\'Uldum, dans le désert de Tanaris.' WHERE l.`ID` = 2954 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
