UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '« Bonjour, je garde l’entrée. Si vous n’avez pas les Plaques d\'Uldum intégrées à votre jeu de disques je ne vous laisserai pas entrer dans le complexe d’Uldum. »$B$BL’apparition du Gardien des pierres de Norgannon est la réaction qui était espérée en vous envoyant dans le Désert de Tanaris avec les disques de platine. Vous devez maintenant découvrir l’histoire du Gardien des pierres avant de continuer.' WHERE l.`ID` = 2954 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler au Grand Explorateur Magellas, à Forgefer.' WHERE l.`ID` = 2964 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Travail imminent' WHERE l.`ID` = 2964 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Bien, $n... Il semblerait que nous soyons dans l\'impasse. Nous avons besoin des Plaques d\'Uldum, mais nous ne savons pas où elles se trouvent. Nous devons réfléchir avant d\'avoir un plan pertinent. J\'ai bien quelques petites idées et j\'espère que nous vous enverrons bientôt pour les récupérer.$B$BLe Grand Explorateur doit être informé de tout cela, $n ; il est à parier qu\'il veut aussi vous remercier pour l\'aide que vous avez apportée à la Ligue.' WHERE l.`ID` = 2964 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Aller à la Cime des Anciens, aux Pitons-du-Tonnerre et parler à Nara Crin-Sauvage.' WHERE l.`ID` = 2965 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Prodiges d\'Uldum' WHERE l.`ID` = 2965 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Ah, $n, vous voilà de nouveau. Vos révélations quant au site de fouilles d\'Uldaman ont motivé bien des discussions parmi nous. J\'en parlais justement avec mon ami, le druide Nara Crin-Sauvage et il m\'apparut que son expérience passée pouvait orienter la suite de notre action.$B$BAllez la voir et écoutez l\'histoire de ses voyages dans la vallée des Guetteurs du désert de Tanaris. Elle vous attend à la cime des Anciens.' WHERE l.`ID` = 2965 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez les Disques de platine miniatures aux Portes d\'Uldum, à Tanaris, et cherchez les indices de la connexion qui existe entre eux.' WHERE l.`ID` = 2966 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Questions sans réponses' WHERE l.`ID` = 2966 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Le Sage Recherche-la-Vérité et moi-même voulons que vous portiez les disques que vous avez découverts jusqu\'aux portes scellées d\'Uldum. Nous... ne sommes pas sûrs de ce qui va arriver quand vous serez là-bas.$B$BCela pourrait être risqué, aussi bien que parfaitement inefficace. Vous devrez utiliser les disques, d\'une manière ou d\'une autre... peut-être les portes s\'ouvriront-elles toutes seules à l\'approche des disques... allez savoir. Essayez ce qui vous semblera bon et attendez-vous à tout.$B$BApprenez ce que vous pourrez, puis revenez me voir ; nous aurons beaucoup à nous dire.' WHERE l.`ID` = 2966 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`AreaDescription` = 'Libérer au moins 6 Fées fléchetteuses' WHERE l.`ID` = 2969 AND l.`locale` = 'frFR' AND (l.`AreaDescription` IS NULL OR l.`AreaDescription` = '' OR BINARY l.`AreaDescription` = BINARY q.`AreaDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'À l’aide de la Clé de la cage en bambou, libérer les Fées fléchetteuses de l’enclos dans le Camp du Totem-sinistre. Au moins 6 Fées fléchetteuses et Kindal Tisselune doivent survivre.$B$BVous avez 6 minutes avant que Kindal décide qu’il est temps de battre en retraite et que vous échouiez dans votre quête.' WHERE l.`ID` = 2969 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Liberté pour toutes les créatures' WHERE l.`ID` = 2969 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir Kindal Tisselune en Féralas.' WHERE l.`ID` = 2969 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'L\'odieux clan du Totem-sinistre capture des dragons féeriques, $n. Jer\'kai et moi ne savons pas quels desseins ils poursuivent en faisant cela, mais ce n\'est certainement rien de bon.$B$BNous ne sommes pas assez puissantes pour combattre le Totem-sinistre dans son camp et libérer les dragons, mais peut-être qu\'avec votre aide...$B$BSi vous êtes d\'accord et avez quelques amis robustes qui voudraient se joindre à vous, allez libérer les créatures de leurs cages grâce à cette clé et assurez-vous qu\'elles restent en vie. Je serai à vos côtés tout le temps ; Jer\'kai, pour sa part, restera ici, au cas où...' WHERE l.`ID` = 2969 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Tuer 12 Naturalistes du Totem-sinistre, 10 Écumeurs du Totem-sinistre et 6 Chamans du Totem-sinistre avant de retourner voir Jer\'kai Tisselune, en Féralas.' WHERE l.`ID` = 2970 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Justice de châtiment' WHERE l.`ID` = 2970 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir Jer\'kai Tisselune en Féralas.' WHERE l.`ID` = 2970 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Comme vous l\'a déjà dit Kindal, nous allons désormais combattre le clan du Totem-sinistre. Ensemble, nous devrions pouvoir affronter quelques taurens, mais nous apprécierions votre aide, si vous êtes d\'accord.$B$BVous avez vu l\'un des camps, en aval ; il y en a encore d\'autres à l\'est. Faites selon vos compétences et techniques mais infligez autant de dégâts possibles aux taurens. Quand ils auront goûté à la piqûre des flèches de Kindal et à vos propres armes, nous nous retrouverons $gtous:toutes; ici, pour faire le point.' WHERE l.`ID` = 2970 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter la Chevalière de Jer\'kai à la Grande prêtresse Tyrande Murmevent, à Darnassus.' WHERE l.`ID` = 2972 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Justice de châtiment' WHERE l.`ID` = 2972 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Ici, dans les terres sauvages, Kindal et moi n’avons pas grand-chose à vous offrir, mais nous voulons récompenser votre aide. Prenez ma chevalière. Si un jour vous êtes dans les environs de Teldrassil, allez au temple de la Lune au cœur de Darnassus. Là, vous trouverez ma Grande prêtresse Tyrande Murmevent. L\'anneau lui dira que nous allons bien et que votre histoire est vraie.$B$BNous vous remercions toutes les deux, $n.' WHERE l.`ID` = 2972 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter 20 Cornes de Totem-sinistre à Krueg Casse-crâne au Camp Mojache.' WHERE l.`ID` = 2974 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Une découverte sinistre' WHERE l.`ID` = 2974 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Quoi ! Vous avez rencontré des taurens dans le secteur ? Vous plaisantez ! À quoi ressemblaient-ils !?$B$BLe clan du Totem-sinistre ! Vous en avez vus ? Belgrom, l\'un de nos maîtres, s\'intéresse à eux… Il offre même une prime sur leur tête.$B$BVous devez repartir, $c. Retournez-y et apportez-moi leurs cornes. Des montagnes si vous pouvez. Ils ne doivent pas être traités à la légère ou sous-estimés. Retournez-y et massacrez-les. Que les rivières de Féralas rougissent de leur sombre sang.' WHERE l.`ID` = 2974 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez la Caisse de Cornes de Totem-sinistre à Belgrom Cogneroche, Orgrimmar.' WHERE l.`ID` = 2976 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Une découverte sinistre' WHERE l.`ID` = 2976 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Comment ?$B$BAh, j\'ai parlé d\'une récompense, n\'est-ce pas ? Bon... ça m\'apprendra à ouvrir la bouche !$B$BVous avez fait le travail et je suppose que je vous dois ce que je vous avais promis. Prenez les cornes, je les ai mises dans une caisse pour vous. Portez-les à Belgrom Cogneroche, dans la Vallée de l\'Honneur. Il souhaite entendre votre rapport et vous récompenser.$B$BQue les vents vous portent, $c, et merci encore pour tout.' WHERE l.`ID` = 2976 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à l\'Historien Karnik, à Forgefer.' WHERE l.`ID` = 2977 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Retour à Forgefer' WHERE l.`ID` = 2977 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Comme vous accédez de nouveau au socle, les disques de platine apparaissent une fois de plus dans votre sac à dos.$B$BAvec ce que vous avez appris du Gardien des pierres et les disques de nouveau en votre possession, vous pouvez maintenant retourner à Forgefer et informer la Ligue des explorateurs de votre découverte.' WHERE l.`ID` = 2977 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Trouver Islen Oeil-des-rivières dans les Tarides.' WHERE l.`ID` = 2985 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'appel de l\'eau' WHERE l.`ID` = 2985 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous êtes capable d\'affronter la prochaine épreuve, $n. Vous avez su monter de la patience et avez progressé dans vos études, mais il est maintenant temps d\'apprendre plus encore et de connaître la pureté de l\'eau.$B$BCherchez Islen Oeil-des-rivières, dans les Tarides. Elle vit le long de la côte est, au sud du fleuve Furie-du-Sud et de Cabestan. Vous la trouverez dans sa cabane de pêcheur. Bonne chance, $n.' WHERE l.`ID` = 2985 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Trouver Islen Oeil-des-rivières dans les Tarides.' WHERE l.`ID` = 2986 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
