UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Pendant que vous m’aidiez, on m’a donné ce mémorandum pour vous. Prenez le temps de le lire. Je pense qu’il vient de Saripal, le maître des démonistes. Allez la retrouver dans Courbenclume quand vous en aurez le temps.$B$BEt faites attention à vous, $n, on n’apprécie pas trop les oiseaux dans votre genre, sur ces terres.' WHERE l.`ID` = 3115 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Porter la Tête réduite à Xerash Lamefeu, au Pavillon de Lariss, en Féralas.' WHERE l.`ID` = 3121 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Une Requête étrange' WHERE l.`ID` = 3121 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Xerash Lamefeu, au pavillon de Lariss, au nord du Camp Mojache, a ce qu\'il me faut pour travailler ici ! Il a préparé un mélange dont j\'ai besoin pour... enfin vous verrez.$B$BMettez-vous en chemin pour voir Xerash. Tenez, prenez ceci. C\'est une tête réduite que j\'ai promise à Xerash en échange des herbes. C\'est la tête d\'un pauvre nain qui a croisé ma route dans la forêt. Je suis certain qu\'il appréciera.' WHERE l.`ID` = 3121 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Tuez 8 Fées fléchetteuses ou Petits dragons féeriques. Utiliser le Récipient à muisek pour rétrécir et capturer les dragons féeriques vaincus.' WHERE l.`ID` = 3125 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Muisek de dragon féerique' WHERE l.`ID` = 3125 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'À présent, $n, je souhaite que vous capturiez une créature fragile en apparence, mais dont l\'esprit puissant nous intéresse. Je veux parler des dragons féeriques. Ils ont été les alliés des elfes de la nuit. Nous devons en capturer afin que la Horde puisse également bénéficier de cette force spirituelle.$B$BVoici le récipient, $n. Tuez 8 Fées fléchetteuses ou Petits dragons féeriques, et capturez leur muisek. On peut en trouver à l\'ouest d\'ici.' WHERE l.`ID` = 3125 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Tuez 3 Marcheurs des bois errants. Utilisez le Récipient à muisek pour miniaturiser et capturer les tréants vaincus.' WHERE l.`ID` = 3126 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Muisek de tréant' WHERE l.`ID` = 3126 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Les marcheurs des bois errants qu’on voit louvoyer dans la forêt sont notre prochaine cible, $n. Les elfes de la nuit ont gagné les tréants à leur cause dans leur combat contre la Horde. Leur vitesse de déplacement est faible, mais leur rôle en tant que protecteurs est indéniable.$B$BBientôt, nous pourrons utiliser leur pouvoir à notre propre compte.$B$BTrouvez trois marcheurs des bois errants, tuez-les et utilisez le récipient à muisek pour les miniaturiser et les capturer.' WHERE l.`ID` = 3126 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Tuer 7 Marcheurs des terres ou Géants des falaises. Utiliser le Récipient à muisek pour faire rétrécir et pour capturer les Géants des montagnes.' WHERE l.`ID` = 3127 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Muisek de géant des montagnes' WHERE l.`ID` = 3127 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'La dernière chose que je vous demande est de partir vers le nord-ouest pour trouver l\'ennemi final.$B$BLes géants des montagnes ont quitté leurs montagnes pour aider les elfes de la nuit quand la Légion ardente est apparue. Vous les reconnaîtrez à leur stature massive ainsi qu’aux vibrations du sol à mesure que vous avancerez dans leur contrée rocailleuse.$B$BJ\'ai à cœur de maîtriser une puissance d\'une telle taille. Tuez 7 géants des montagnes puis utilisez le Récipient pour capturer leur puissant muisek.' WHERE l.`ID` = 3127 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Le Féticheur Uzer\'i veut que vous patientez pendant qu\'il prépare les armes.' WHERE l.`ID` = 3129 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Armes de l\'Esprit' WHERE l.`ID` = 3129 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Imprégner les armes de muisek est un processus difficile. Maintenant que nous avons les matériaux nécessaires et le muisek des créatures que vous avez capturées, je peux commencer. Attendez s\'il vous plaît ; je reviens dans un moment.' WHERE l.`ID` = 3129 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Se présenter devant Latronicus Lancelune au bastion de Pennelune.' WHERE l.`ID` = 3130 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Contre les Hainecrêtes' WHERE l.`ID` = 3130 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'À présent, je vais vous diriger vers mon second, Latronicus. Il a gardé un œil attentif sur les forces des nagas jusqu\'alors. J\'estimerai la situation générale ici selon les nagas. Non pas que je veuille envoyer une force compacte les combattre, laissant ainsi la forteresse ouverte à une attaque directe de la Horde, ou pire...$B$BMais passons, Latronicus attend. Vous avez fait du bon travail jusque-là, $n. Continuez comme ça.$B$BVous pouvez disposer.' WHERE l.`ID` = 3130 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`AreaDescription` = 'Histoire de Loramus' WHERE l.`ID` = 3141 AND l.`locale` = 'frFR' AND (l.`AreaDescription` IS NULL OR l.`AreaDescription` = '' OR BINARY l.`AreaDescription` = BINARY q.`AreaDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Écoutez l\'histoire de Loramus Thalipedes.' WHERE l.`ID` = 3141 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir Loramus Thalipedes à la Baie des Tempêtes, à Azshara.' WHERE l.`ID` = 3141 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Donc vous souhaitez vous battre contre des démons ? Vous feriez bien d\'écouter mon histoire.' WHERE l.`ID` = 3141 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Porter la Corne gigantesque de Margol au conservateur en chef Thorius à Forgefer.' WHERE l.`ID` = 3182 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Titre de propriété' WHERE l.`ID` = 3182 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Et vous pensez que je vais avaler une histoire pareille ? Le fer de ma hache se serait brisé et serait coincé dans la véritable corne, s\'il s\'agissait bien d\'elle.$B$BÉcoutez, apportez ce faux grossier au conservateur en chef Thorius à Forgefer. S\'il est capable de valider vos dires, vous recevrez un certificat de haut fait. Rapportez-moi cette preuve et je vous remettrai la clé de la gorge des Vents brûlants.$B$BAllez-y !' WHERE l.`ID` = 3182 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter le document de preuve à la Montagnarde Minigravillon.' WHERE l.`ID` = 3201 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Enfin !' WHERE l.`ID` = 3201 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Je n\'arrive pas à croire que Minigravillon ait pu douter de l\'authenticité de la corne. Entre vous et moi, je pense qu\'elle est seulement jalouse. Je sais qu\'elle tenait vraiment à tuer elle-même cette bête, à cause de « l\'incident » et tout.$B$BDonc vous avez besoin d\'un document comme preuve ? Après la contribution que vous venez de faire au musée, ce ne sera pas un problème.$B$B<Le conservateur en chef Thorius commence à remplir un grand document>$B$BEt voilà ! Vous pouvez présenter ceci à Minigravillon.' WHERE l.`ID` = 3201 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à l\'apothicaire Renferrel au Sépulcre.' WHERE l.`ID` = 3221 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Parler à Renferrel' WHERE l.`ID` = 3221 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Tandis que vous étiez en train d\'aider nos nécrotraqueurs, l\'apothicaire Renferrel vous a fait appeler. Il n\'a rien précisé mais a dit qu\'il voulait vous parler à propos des cœurs de loup que vous lui aviez donnés.' WHERE l.`ID` = 3221 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter un Thé brûlant à Durnan Coupefourrure, dans Courbenclume, dans les cinq minutes imparties avant qu\'il ne refroidisse !' WHERE l.`ID` = 3364 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Une livraison de thé brûlant' WHERE l.`ID` = 3364 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Ah ! Je devais apporter un Thé brûlant à Durnan Coupefourrure, à Courbenclume, mais je dois d’abord en porter un à Grelin. Je n\'arriverai jamais à Courbenclume avant qu\'il ne refroidisse !$B$BVous m’avez l\'air rapide. Vous pouvez le faire. Cette boisson ne restera chaude que 5 minutes et Durnan n\'a pas commandé un Thé "glacé", alors partez tout de suite. Courbenclume est un village dans la montagne, au nord-est.$B$BMerci, $n, et n\'oubliez pas de me rapporter ma tasse !' WHERE l.`ID` = 3364 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`AreaDescription` = 'Parler à quelqu\'un de l\'Éclat de cauchemar' WHERE l.`ID` = 3366 AND l.`locale` = 'frFR' AND (l.`AreaDescription` IS NULL OR l.`AreaDescription` = '' OR BINARY l.`AreaDescription` = BINARY q.`AreaDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Aller à Cabestan pour trouver la raison d’être de l’Éclat de cauchemar.' WHERE l.`ID` = 3366 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'Éclat luminescent' WHERE l.`ID` = 3366 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'L\'éclat est d\'un vert brillant, et bien que compact, ce qui ressemble à de la fumée tourbillonne juste au-dessous de sa surface. Vous ne pouvez vous empêcher de contempler les profondeurs du cristal, bien qu\'en même temps, vous sentiez qu\'il y réside quelque chose de très inquiétant.$B$BPeut-être devriez-vous voir si quelqu\'un à Cabestan pourrait vous en apprendre plus à propos de cet étrange éclat...' WHERE l.`ID` = 3366 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter la Lettre roussie à Thorius à Forgefer. Il se trouve dans le Hall des Explorateurs.' WHERE l.`ID` = 3368 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Les pierres de Suntara' WHERE l.`ID` = 3368 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Mon frère,$B$BSi vous lisez cette lettre, c\'est que je n\'existe plus. Comment vous est-elle parvenue, je l\'ignore. Mais remerciez et récompensez ceux qui ont fait en sorte que vous l\'ayez reçue.$B$BÀ propos des pierres : elles existent, les Sombrefers les ont en leur possession. Leur chef, Lathoric le Noir, utilise le pouvoir de ces pierres pour asservir mon équipe d\'archéologues. Ils ont été emmenés au Chaudron. Leurs esprits sont à présent asservis et ils travaillent nuit et jour pour achever une chose qui répond au nom d\'Obsidion.$B$BSecourez-les. Il s\'agit là de la dernière volonté d\'un homme mort.$B$B-Dorius' WHERE l.`ID` = 3368 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez l\'Éclat de cauchemar à Hamuul Totem-runique à la Cime des Anciens.' WHERE l.`ID` = 3369 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Au cœur des cauchemars' WHERE l.`ID` = 3369 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Cet éclat détient de grands secrets. Il s\'agit de l\'essence pure du Rêve d\'émeraude. Ce que je vois dans cet éclat n\'a rien d\'un rêve cependant. On pourrait même appeler cela une vision de cauchemar.$B$BMon but n\'est pas de vous alarmer, $n, mais je crois qu\'il serait mieux pour vous de remettre cet éclat à un grand druide, et ce le plus tôt possible.$B$BLa personne que vous devriez rencontrer à la cime des Anciens se nomme Hamuul Totem-runique. Partez pour les Pitons-du-Tonnerre. Je ne peux pas vous en dire plus.' WHERE l.`ID` = 3369 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
