UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Mettre le feu aux Tours de garde nord, sud, est et ouest en utilisant la Torche de vindicte à l\'intérieur de chaque tour.' WHERE l.`ID` = 3463 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
