UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Retournez voir Belgrom à Orgrimmar. Il voudra voir sa tête de ses yeux ! Nous reviendrons bientôt.$B$BAh, c\'est en effet une bonne journée. Merci pour votre aide, $n.' WHERE l.`ID` = 3507 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
