UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Briser l\'Amulette' WHERE l.`ID` = 3508 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous êtes téméraire, $n. C\'est une qualité admirable de votre espèce, le fait de foncer aveuglément dans la bataille alors qu\'il n\'y a aucune chance de succès, ou si peu. Je vous aiderai, ne serait-ce que pour voir tomber un seul des sbires de Razelikh.$B$BBriser la tutelle de Razelikh sur ses subalternes va prendre du temps et nécessitera l’utilisation d\'artéfacts rares.$B$BNe bougez plus, je dois commencer le rituel de Lumière. L\'information que j\'en tirerai m\'aidera à façonner des armes de grand pouvoir.' WHERE l.`ID` = 3508 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Aller voir le seigneur Arkkoroc en Azshara. Commencer la recherche au bord de l\'eau pour trouver le temple d\'Arkkoran.' WHERE l.`ID` = 3509 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le nom de la bête' WHERE l.`ID` = 3509 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Il n\'y a qu\'une façon de nuire au seigneur démon et à ses sbires. Il faut forger une arme qui portera son véritable nom.$B$BSi nous parvenons à forger une telle arme, le démon et toute sa clique seront vulnérables.$B$BUn autre seigneur se trouve en Azshara, le seigneur Arkkoroc. Vous devez aller le trouver, mais attention, ses sbires n\'hésiteront pas à vous éliminer s\'ils vous découvrent.$B$BVous aurez certainement un prix à payer pour cette information.' WHERE l.`ID` = 3509 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Assassiner Hetaera et apporter la Tête ensanglantée d\'Hetaera, la Tête battue d\'Hetaera et la Tête meurtrie d\'Hetaera au seigneur Arkkoroc.' WHERE l.`ID` = 3510 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le nom de la bête' WHERE l.`ID` = 3510 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Elle tue mes enfants, $gmortel:mortelle;. Celle qui se proclame souveraine de ces océans. Une fausse déesse, rien de plus. Écrasez-la et apportez-moi chacune de ses têtes.$B$BEn échange, vous obtiendrez le nom que vous cherchez et autre chose, d\'importance égale.$B$BElle rôde sur la couvée... Elle se nomme Hetaera.$B$B<Le seigneur Arkkoroc désigne le sud-ouest.>$B$BAllez-y !' WHERE l.`ID` = 3510 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Rapporter le durcisseur à Loramus Thalipedes.' WHERE l.`ID` = 3511 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le nom de la bête' WHERE l.`ID` = 3511 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Comme promis, je vais vous révéler le nom du seigneur-démon : Razelikh le Souilleur. Mais tout d\'abord, je dois préparer quelque chose de la plus grande importance pour votre voyage.$B$BL\'arme que vous cherchez à confectionner nécessite une trempe particulière. Laissez-moi quelques instants pour vider le sang de ces têtes.$B$B<Le seigneur Arkkoroc presse les têtes entre ses gigantesques poings, exprimant ainsi tout le sang.>$B$BApportez la trempe à Loramus, ainsi que le nom de la bête : Rakh\'likh.' WHERE l.`ID` = 3511 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Allez Dirania Brillargent, au Sombrevallon.' WHERE l.`ID` = 3519 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Un ami dans le besoin' WHERE l.`ID` = 3519 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Ahhh... J\'ai été mordu par une araignée nommée Githyiss la Vile en explorant sa caverne, tout près d\'ici. Une grande quantité de poison m\'a été injectée ; vous devez m\'aider.$B$BPrévenez Dirania Brillargent. Elle sera capable de me secourir.$B$BVite... J\'ai des vertiges de plus en plus alarmants...' WHERE l.`ID` = 3519 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez la Tablette de Jin\'yael à Jes\'rimon à Orgrimmar.' WHERE l.`ID` = 3541 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Livraison pour Jes\'rimon' WHERE l.`ID` = 3541 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'J\'ai un copain à Orgrimmar. Il réside dans la rue principale. Il est difficile à trouver si vous ne savez pas où regarder, mais allez voir dans les bâtiments les plus hauts et vous devriez sans peine tomber sur lui.$B$BFaites-moi une faveur, n\'allez pas répéter à tout Kalimdor qu\'il est là : ce serait mauvais pour lui comme pour moi.$B$BIl nous donnera un prix plus qu\'honnête pour la Tablette de Jin\'yael. Je ne sais pas pourquoi, mais vous auriez dû voir comme il était excité quand je lui en ai parlé.' WHERE l.`ID` = 3541 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter la Note de Magatha à Jediga en Azshara.' WHERE l.`ID` = 3562 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]Le paiement de Magatha à Jediga' WHERE l.`ID` = 3562 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Portez cette note à Jediga. Dites-lui que son paiement l\'attendra à son retour. Et dites-lui que son travail est satisfaisant.$B$BFaites vite, $n. Dites à votre maîtresse que je l\'attendrai ici.' WHERE l.`ID` = 3562 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Trouvez 20 Azsharites cristallisées au sud d\'Azshara. Utilisez éventuellement le gangrechien pour « renifler » l\'emplacement où sont intelligemment cachés les dépôts.$B$BRetournez voir Loramus une fois votre tâche accomplie.' WHERE l.`ID` = 3602 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Les anciens géants des falaises de la région du sud d\'Azshara se nourrissent de la roche et des constructions locales. Leurs excréments forment un cristal très malléable et extrêmement solide appelé azsharite.$B$BOn le trouve dans le Cercle du sud, mais on en récupère peu en raison du tempérament extrêmement violent des géants.$B$BVous devez aller au sud et récupérer suffisamment d\'azsharite pour créer le corps de l\'arme. Mes gangrechiens vous aideront à trouver le cristal.' WHERE l.`ID` = 3602 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter la cargaison à Galvan l\'Ancien dans la vallée de Strangleronce.' WHERE l.`ID` = 3621 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La formation du gangreplaie' WHERE l.`ID` = 3621 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Les armes sont prêtes à être forgées. Vous devez apporter l\'azsharite trempée à quelqu\'un qui saura en exploiter l\'énergie.$B$BUn tel forgeron se trouve dans la vallée de Strangleronce. Galvan l\'Ancien, le chef de l\'ordre du Mithril, pourra fabriquer ces armes. Vous trouverez son campement entre Zul\'Gurub et le tertre des ogres mosh\'Ogg.$B$BPuissent votre détermination et votre foi vous porter dans cette épreuve. Si vous échouez, sachez que votre dieu vous regarde en souriant, $gmortel:mortelle;.' WHERE l.`ID` = 3621 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`AreaDescription` = 'Création d\'armes' WHERE l.`ID` = 3625 AND l.`locale` = 'frFR' AND (l.`AreaDescription` IS NULL OR l.`AreaDescription` = '' OR BINARY l.`AreaDescription` = BINARY q.`AreaDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Attendre que Galvan ait fini de forger les armes.' WHERE l.`ID` = 3625 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Armes gangrenées en azsharite enchantée' WHERE l.`ID` = 3625 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir Galvan l\'Ancien dans la Vallée de Strangleronce.' WHERE l.`ID` = 3625 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '$n, la création de chaque arme va prendre un peu de temps.$B$BDe plus, vous ne pourrez utiliser le pouvoir de la Malédiction gangreneuse qu\'une fois toutes les trois minutes. Ses propriétés d\'affaiblissement contre Razelikh le Souilleur et ses sbires peuvent varier dans la durée. C\'est pourquoi vous devez prendre garde d\'utiliser la Malédiction gangreneuse au bon moment !$B$BÀ présent, donnez-moi une minute pour terminer votre arme, $n.' WHERE l.`ID` = 3625 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Retourner voir le Héros de la Horde tombé au combat, au Croisement de Lance-brisée, au Marais des Chagrins.' WHERE l.`ID` = 3626 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Retour dans les terres Foudroyées' WHERE l.`ID` = 3626 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'L\'heure de la rédemption est proche, $n. Vous devez retourner dans les terres Foudroyées avec votre nouvel équipement et parler au Héros de la Horde tombé au combat pour recevoir votre objectif final.' WHERE l.`ID` = 3626 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Assassiner Grol le Destructeur, dame Sevine et l\'archimage Allistarj. Prendre sur leurs cadavres l\'Amulette de Grol, l\'Amulette de Sevine et l\'Amulette d\'Allistarj.$B$BN\'oubliez pas d\'UTILISER vos armes gangrenées en azsharite enchantée pour affaiblir la triade (ils ne peuvent pas être tués autrement), mais faites-le sagement...' WHERE l.`ID` = 3627 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Réunir les morceaux de l\'amulette brisée' WHERE l.`ID` = 3627 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Pour atteindre le Souilleur, vous devez d\'abord détruire la triade de pouvoir et récupérer les morceaux d\'amulette. Quand vous aurez récupéré les trois morceaux, revenez me voir et je vous donnerai de nouvelles instructions.$B$BAllez, $n ! Partez dans les terres Foudroyées ! Sevine, Allistarj et Grol doivent mourir !' WHERE l.`ID` = 3627 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Détruire Razelikh le Souilleur et apporter la Corne brisée du Souilleur au Héros de la Horde tombé au combat. Rendre aussi l\'Amulette du Souilleur au Héros pour qu\'il puisse la détruire, afin de l\'empêcher de tomber entre de mauvaises mains.' WHERE l.`ID` = 3628 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Son nom est Rakh’likh' WHERE l.`ID` = 3628 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Razelikh se terre sur la plus haute montagne des terres Foudroyées. Le seul moyen d\'y accéder est d\'utiliser les runes de téléportation près de la montagne. Tant que vous tenez l\'amulette, vous pouvez vous y transporter. Une fois là-bas, vous devez neutraliser la bête. L\'amulette est votre atout, $n. Utilisez-la sur l\'Autel du Souilleur.$B$BSi vous arrivez à le vaincre, prenez sa corne. Elle sera signe d\'espoir pour ceux qui la verront, la preuve que les héros existent dans ce monde déchiré par la guerre.' WHERE l.`ID` = 3628 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Pour en apprendre davantage sur l\'ingénierie gobeline, apporter le Manuel d\'Ingénierie à Nixx Elastirouage, à Gadgetzan, en Tanaris.' WHERE l.`ID` = 3633 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Ingénierie des gobelins' WHERE l.`ID` = 3633 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'La meilleure ingénierie est représentée par deux disciplines : celle des gnomes et celle des gobelins. L\'Ingénierie des gobelins est clairement le choix de tous les ingénieurs brillants. Apprendre à vaincre le monde par l\'utilisation judicieuse d\'explosifs et d\'incroyables mécanismes !$B$B$n, lisez ce manuel. Si vous voulez en apprendre plus, apportez-le à Nixx Elastirouage à Gadgetzan. Mais attention : l’adhésion à cette discipline est définitive et exclusive, alors soyez $gsûr:sûre; de faire le bon choix !' WHERE l.`ID` = 3633 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`AreaDescription` = 'Histoire de Thaurissan' WHERE l.`ID` = 3702 AND l.`locale` = 'frFR' AND (l.`AreaDescription` IS NULL OR l.`AreaDescription` = '' OR BINARY l.`AreaDescription` = BINARY q.`AreaDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Écouter l\'historienne royale Archesonus raconter l\'histoire de Thaurissan.' WHERE l.`ID` = 3702 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Les ruines fumantes de Thaurissan' WHERE l.`ID` = 3702 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Est-ce que vous aimeriez entendre une petite histoire sur les nains sombrefers ?' WHERE l.`ID` = 3702 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à l’Archidruide Hamuul Totem-Runique aux Pitons-du-Tonnerre.' WHERE l.`ID` = 3762 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'aide à l\'archidruide Totem-runique' WHERE l.`ID` = 3762 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Pardonnez-moi, $c, mais j\'aimerais prendre quelques instants de votre temps, si cela est possible.$B$BLe Cercle cénarien des Pitons-du-Tonnerre est très intéressé par des $gaventuriers aguerris tels:aventurières aguerries telles; que vous pour lui prêter main-forte dans un projet crucial. Bien que je n’en connaisse pas les détails, je peux vous dire que Hamuul Totem-runique lui-même mène ce projet.$B$BJe vous en prie, si cela vous intéresse, allez lui parler en personne à la cime des Anciens aux Pitons-du-Tonnerre.' WHERE l.`ID` = 3762 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à l’Archidruide Fandral Forteramure à Darnassus.' WHERE l.`ID` = 3763 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'aide à l\'archidruide Forteramure' WHERE l.`ID` = 3763 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Pardonnez-moi, $c, mais j\'aimerais prendre quelques instants de votre temps si la chose est possible.$B$BLe Cercle cénarien à Darnassus recherche des $gaventuriers aguerris tels:aventurières aguerries telles; que vous pour lui prêter main-forte dans des recherches capitales. Bien que je ne connaisse pas les détails, je peux vous dire que l\'archidruide Fandral Forteramure en personne mène ces recherches.$B$BSi cela vous intéresse, allez directement lui parler à l\'Enclave cénarienne à Darnassus.' WHERE l.`ID` = 3763 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter le Bon pour des graines de l\'archidruide à Mathrengyl Pasdelours dans l\'Enclave cénarienne à Darnassus.' WHERE l.`ID` = 3781 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Recherches sur la fibre d\'aurore' WHERE l.`ID` = 3781 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Nous avons planté des graines de Tharlendris dans de la terre du Cratère d\'Un\'Goro, avec ce que nous appelons une Sacoche de printemps. Ces graines ont germé et donné un grand nombre d\'herbes fortes et variées. Parmi elles, il y a la Fibre d\'aurore, une herbe dont on sait peu de chose. J\'ai l’intention de percer ses mystères.$B$BApportez ceci à Mathrengyl, en bas, et il vous remettra quelques graines afin que vous puissiez commencer. Si vous veniez à en manquer, vous devrez lui en acheter.' WHERE l.`ID` = 3781 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Utiliser une Sacoche de printemps avec une pochette de graines de Tharlendris et deux Échantillons d\'humus d\'Un\'Goro pour essayer de cultiver des Fibres d\'aurore.$B$BApporter 10 Fibres d\'aurore à Mathrengyl Pasdelours à Darnassus.' WHERE l.`ID` = 3785 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Recherches sur la fibre d\'aurore' WHERE l.`ID` = 3785 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Voici la Sacoche de printemps dont vous aurez besoin pour utiliser les graines de Tharlendris. Vous devrez avoir également des échantillons d\'humus d\'Un\'Goro sous la main comme fertiliseur pour les graines. Servez-vous juste de la sacoche lorsque vous serez en possession de tout ce qui est nécessaire. Elle s\'occupera du reste.$B$BLorsque vous aurez suffisamment de fibre d\'aurore, apportez-les-moi ici à l\'Enclave. Veuillez ne pas déranger l\'archidruide. C\'est un homme très occupé, et il ne s\'agit pas de le déranger à chaque fois que quelqu\'un arrive avec un nouveau sac de fibre d\'aurore !' WHERE l.`ID` = 3785 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à Quintis Gentecime dans le bastion de Pennelune.' WHERE l.`ID` = 3788 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La requête de Gentecime' WHERE l.`ID` = 3788 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Excusez-moi, mon $gami:amie;…$B$BL\'un de mes collègues voudrait vous entretenir à propos des recherches que vous effectuez conjointement avec le Cercle cénarien. Il est druide et se nomme Quintis Gentecime. Il demeure ici au bastion de Pennelune et voudrait vous parler de la Fibre d\'aurore. Il insiste pour que notre conversation n\'atteigne en aucun cas les oreilles de l\'archidruide.$B$BSi cela vous intéresse, allez lui parler. Il ne fait aucun doute que tout vous sera révélé si vous allez le voir.' WHERE l.`ID` = 3788 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter 10 Fibres d\'aurore à Quintis Gentecime au bastion de Pennelune.' WHERE l.`ID` = 3791 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le Mystère des Fibres d\'aurore' WHERE l.`ID` = 3791 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Je vais être franc avec vous, $n. Cela m\'intéresse – non, cela m\'inquiète ! – de savoir pourquoi l\'archidruide de Darnassus utilise le couvert du Cercle cénarien, tout autant que ses ressources, pour se procurer d’aussi grandes quantités de Fibre d\'aurore. Je suis chercheur et mon domaine concerne les malédictions. J\'ai entendu dire que la Fibre d\'aurore, placée dans certaines conditions, développe des propriétés similaires à celles d\'autres herbes utilisées dans des malédictions primitives.$B$BJe veux en savoir davantage, et je sollicite votre aide. Apportez-moi dix Fibres d\'aurore et je m’occuperai de vous.' WHERE l.`ID` = 3791 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Récupérez l’Anneau de nez de Sha\'ni sur Krom\'Grul, et rapportez-le à Thal\'trak, à Kargath. Fouillez les différentes grottes et mines du Rocher des Cognepeurs.' WHERE l.`ID` = 3822 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Tout mon régiment a été capturé, $n. Tous ont été tués, sauf moi.$B$BLeur chef, Krom\'Grul, voulait me réserver pour un genre de rituel.$B$BJ\'ai été enchaînée à cet autel et battue à mort par ce monstre. J’ai rendu l’âme après une heure de cette torture. Alors, il a arraché mon anneau de nez de mariage et l\'a passé à son doigt. Je n\'ai jamais vu une telle sauvagerie !$B$BTrouvez Krom\'Grul et tuez-le ! Rapportez mon anneau à Thal\'trak.$B$B$n, dites-lui que nous nous rencontrerons à nouveau... dans une autre vie.' WHERE l.`ID` = 3822 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Prendre la Tête coupée de Gor\'tesh et la placer au sommet du Rocher des Cognepeurs. Chercher un monticule de terre meuble pour planter la pique.' WHERE l.`ID` = 3825 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Une tête d\'ogre au bout d\'une pique = une fête' WHERE l.`ID` = 3825 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Il vous reste une dernière chose à faire, soldat.$B$BJ\'ai pris la liberté de planter la tête de Gor\'tesh sur une pique. À présent, tout ce que vous avez à faire, c\'est d\'apporter cette pique au sommet du rocher des Cognepeurs et de la ficher dans le sol. Après cela, vous pourrez admirer ces lâches d\'ogres courir pour sauver leur vie ! Après vous être $gamusé:amusée; un peu, revenez et je vous récompenserai pour votre dur labeur.$B$B<Oralius semble perdre contact avec la réalité.>' WHERE l.`ID` = 3825 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Rechercher dans l\'étang un indice sur l\'identité du propriétaire du radeau brisé.' WHERE l.`ID` = 3844 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'C\'est un secret pour tout le monde' WHERE l.`ID` = 3844 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Un radeau brisé repose le long du rivage. Vu qu\'il ne s\'agit que d\'un petit étang, on peut se demander comment ce radeau a échoué ici. Les traces sur les arbres aux alentours indiquent cependant que le niveau de l\'eau pourrait varier.$B$BExplorer ce secteur pourrait révéler des indices supplémentaires...' WHERE l.`ID` = 3844 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Partir pour les Profondeurs de Rochenoire et trouver 10 Essences des éléments. Commencer vos recherches par les golems et par les créateurs de golems. Vivian Lagrave a aussi marmonné quelque chose à propos d\'élémentaires.' WHERE l.`ID` = 3911 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le dernier élément' WHERE l.`ID` = 3911 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir l\'Ombremage Vivian Lagrave au Repos d\'Apocryphan, dans les Terres ingrates.' WHERE l.`ID` = 3911 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Il y a du travail pour ceux qui s\'aventurent dans les Profondeurs, $n.$B$BLes Sombrefers peuvent créer des golems extrêmement puissants.$B$BLes premiers rapports de nos espions indiquent que les nains se servent d\'une unique source de puissance pour donner à leurs créations une puissance de destruction incomparable.$B$BImaginez simplement ce que nous pourrions faire de nos abominations si nous mettions la main sur cette Essence des éléments ! Fouillez les moindres recoins de cette cité si cela est nécessaire, mais ne revenez pas tant que vous n\'avez pas découvert cette essence ! Votre récompense sera à la mesure du risque encouru.' WHERE l.`ID` = 3911 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Se rendre au cimetière au-dehors de Gadgetzan et boire l\'élixir de Videre. Suivre le reste des instructions de Donova pour trouver Gaeriyan.' WHERE l.`ID` = 3912 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Rendez-vous à la tombe' WHERE l.`ID` = 3912 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Cet élixir va vous permettre de vous entretenir avec quelqu\'un que vous ne pourriez même pas voir en temps normal…$B$BApportez l\'élixir de Videre et l\'épée de Linken jusqu\'au cimetière au-dehors de Gadgetzan, à Tanaris. Une fois $garrivé:arrivée;, buvez la potion. Les conséquences pourraient vous surprendre, mais en aucun cas n\'ayez crainte.$B$BUne fois que vous aurez votre "nouvelle" forme, dirigez-vous vers le nord jusqu\'à ce que vous atteigniez les montagnes. Vous trouverez la personne à qui vous devez parler dans l\'une des lézardes rocheuses. Il se nomme Gaeriyan.$B$BSouvenez-vous ! Il ne vous parlera que si vous avez adopté cette forme...' WHERE l.`ID` = 3912 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Ressusciter, puis rechercher la pierre tombale que Gaeriyan vous a demandé de trouver.' WHERE l.`ID` = 3913 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Une situation grave' WHERE l.`ID` = 3913 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Si vous retournez au cimetière dont vous venez, $n, vous y trouverez une pierre tombale particulière. Celle-ci se démarquera des autres. Elle renferme des secrets.$B$BPoussez la pierre, et vous les apprendrez…' WHERE l.`ID` = 3913 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Remettre l’Épée excellente de Linken à Linken dans le cratère d\'Un\'Goro.' WHERE l.`ID` = 3914 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'épée de Linken' WHERE l.`ID` = 3914 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Après un grand flash, vous pouvez à nouveau vous saisir de l\'épée. Elle s\'est transformée !' WHERE l.`ID` = 3914 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Trouver J.D. Collie dans la caverne du refuge des Marshal.' WHERE l.`ID` = 3941 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Un gnome dans le besoin' WHERE l.`ID` = 3941 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Réfléchir… réfléchir… je sais que je suis venu ici pour quelque chose d\'important…$B$BJ\'ai une idée, $n. Dans la caverne proche se trouve une gnome du nom de J.D. Elle a été très aimable envers moi lorsque je suis arrivé ici. Peut-être que désorienté comme je l\'étais, je lui ai dit quelque chose dont elle pourrait se souvenir ?$B$BPourquoi n\'iriez-vous pas la voir et lui demander ? Oh, mais attention ! Elle joue toujours avec ces cristaux brillants que j\'ai vus dans le cratère. Je ne sais pas vraiment ce qu\'elle prépare là-bas !' WHERE l.`ID` = 3941 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Trouver Eridan Ventebleu dans le sud de Gangrebois.' WHERE l.`ID` = 3942 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Les souvenirs de Linken' WHERE l.`ID` = 3942 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Oh… Linken ? Oui, c\'est un drôle de type. La première fois qu\'il est venu ici, il marmonnait des propos incohérents. Il a dû recevoir un sacré coup sur la tête, si vous voulez mon avis.$B$BMais je ne peux pas m\'empêcher de me souvenir de quelque chose qu\'il disait, tout de même. Comme quoi il construisait un genre de totem. Il disait qu\'il devait parler à quelqu\'un du nom d\'Eridan Ventebleu... dans un endroit appelé Gangrebois... je crois ?$B$BJe ne pense pas qu\'il puisse lui-même vous en dire plus. Si vous voulez en apprendre davantage, peut-être devriez-vous chercher en personne Eridan ?' WHERE l.`ID` = 3942 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter le Totem d\'argent d\'Aquementas à Linken au refuge des Marshal.' WHERE l.`ID` = 3961 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'aventure de Linken' WHERE l.`ID` = 3961 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Et dire que pendant tout ce temps la raison pour laquelle Linken est venu ici était de nous débarrasser de Coursembrase… Il semble être une personne ordinaire, mais j\'ai remarqué qu\'il ne s\'intéressait pas le moins du monde à mes expériences et à mes gadgets, qui passionnent d\'ordinaire les gnomes. Il doit être un grand guerrier.$B$BApportez-lui le totem. Voyez si cela l\'aide à se remémorer la raison pour laquelle il est venu ici.' WHERE l.`ID` = 3961 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter le Livre d\'Aquor, les Griffes argentées et le Cœur d\'Arbrefer à Tanaris.$B$BUtiliser le Livre d\'Aquor pour invoquer Aquementas.$B$BAprès avoir terminé le totem, l’apporter à J.D. Collie au refuge des Marshal.' WHERE l.`ID` = 4005 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Apportez le sac de fournitures à Tanaris. Rendez-vous à la crique des Gréements, et cherchez un cercle de pierres.$B$BLa péninsule la plus à l\'est, là est le secret…$B$BLisez le Livre d\'Aquor une fois que vous serez dans ce cercle. Invoquez la seule créature qui soit capable de transformer vos objets en un Totem pour combattre Coursembrase.$B$BAquementas n\'aimera pas être ainsi éveillé, mais souvenez-vous que vous devez rester dans le cercle pour qu\'il transforme les objets.' WHERE l.`ID` = 4005 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`AreaDescription` = 'Preuve présentée' WHERE l.`ID` = 4022 AND l.`locale` = 'frFR' AND (l.`AreaDescription` IS NULL OR l.`AreaDescription` = '' OR BINARY l.`AreaDescription` = BINARY q.`AreaDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Montrer à Cyrus Lerepenti l\'Ecaille des dragons noirs que vous avez reçue de Kalaran Lamevent.' WHERE l.`ID` = 4022 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
