UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Les dragons sont au courant de vos œuvres dans la gorge des Vents brûlants.$B$BMontrez-la-moi, $r. L\'écaille, imbécile.' WHERE l.`ID` = 4022 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Trouver 11 Griffes d\'argent et 1 Cœur d\'Arbrefer pour Eridan Ventebleu à Gangrebois.' WHERE l.`ID` = 4084 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Cœur d\'argent' WHERE l.`ID` = 4084 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Je ne connais pas la personne dont vous parlez, $n.$B$BMais ne vous inquiétez pas ; si votre ami était en voyage pour venir me trouver, je sais ce qu\'il recherchait.$B$BAu cœur du cratère d\'Un\'Goro demeure un mal sous sa forme la plus pure. Ce mal prend la forme d\'un élémentaire du nom de Coursembrase... Il est protégé par une aura que personne ne peut dissiper.$B$BPersonne... à part ceux qui ont suffisamment de pouvoir pour y parvenir. Je peux vous apprendre ce pouvoir, $n.$B$BD\'abord, faites ce que je vous demande. Trouvez 11 Griffes d\'argent et 1 Cœur d\'Arbrefer sur les créatures de Gangrebois, puis revenez.' WHERE l.`ID` = 4084 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Du baume en chassant' WHERE l.`ID` = 4108 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à Ginro Attisâtre dans le bastion de Pennelune.' WHERE l.`ID` = 4124 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le messager disparu' WHERE l.`ID` = 4124 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'L\'un de mes associés, Ginro Attisâtre, cherche à ce qu\'on l\'assiste dans ses recherches pour retrouver un messager et les paquets qu\'il transportait. Cela fait à peu près une semaine que le messager a disparu. Nos propres recherches n\'ont abouti à rien et nous sommes à présent dans l\'impasse. J\'ai malheureusement dû déclarer le messager disparu.$B$BSi vous avez et du temps et des ressources à nous consacrer, veuillez aller parler à Ginro. Il devrait être ici dans la Forteresse. Probablement dans ses quartiers.' WHERE l.`ID` = 4124 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Retourner au bastion de Pennelune et montrer à Ginro Attisâtre le Couteau perdu que vous avez découvert.' WHERE l.`ID` = 4127 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Débris de bateau' WHERE l.`ID` = 4127 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Tandis que vous fouillez la vase, vos doigts butent sur le manche d\'un couteau. Il semble qu\'on en ait pris soin, et il est logique de croire que celui qui était sur le canot l\'a perdu. Peut-être que le gros morceau de canot qui manque a quelque chose à voir avec cette perte.$B$BVous récupérez le couteau, vous souvenant que Ginro Attisâtre vous a demandé de lui ramener au bastion de Pennelune tous les indices que vous trouveriez. Vous avez l\'étrange sentiment cependant que vous n\'êtes pas $gseul:seule; dans l\'eau...' WHERE l.`ID` = 4127 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter le Couteau perdu à Quintis Gentecime au bastion de Pennelune.' WHERE l.`ID` = 4129 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le couteau révélé' WHERE l.`ID` = 4129 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Le druide du Bastion, Quintis Gentecime, possède des pouvoirs… particuliers. L\'un de ces pouvoirs est la psychométrie. C\'est-à-dire qu\'il peut révéler l\'histoire d\'un objet en le touchant. Ne me demandez pas comment il s\'y prend. Je le mets sur le compte de magies que je ne connais pas et que je ne veux pas connaître. Il y a deux choses que je sais, par contre. Premièrement, je l\'ai vu à l\'œuvre et ça marche. Deuxièmement, ce clochard me doit de l\'argent.$B$BApportez ce couteau à Quintis là-haut dans sa charmante petite maison, et dites-lui que sa dette de « L\'arnaque » en Kalimdor sera remboursée s\'il parvient à tirer quelque chose de ce couteau.' WHERE l.`ID` = 4129 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à Ginro Attisâtre dans le bastion de Pennelune.' WHERE l.`ID` = 4130 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La lecture psychométrique' WHERE l.`ID` = 4130 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Je me sens encore un peu flageolant, excusez-moi. Mais j\'ai reçu quelques visions utilisables.$B$BRaschal sort de son canot deux grands sacs à dos en cuir et pénètre dans les terres ; mais il retourne bientôt au canot cependant. Je vois des cuirs chevelus de gnolls... il a rencontré des gnolls. Je crois que ce sont ceux que l\'on appelle Griffebois. Quelque chose l\'inquiète, le terrifie presque ! C\'est à un point tel qu\'il ne remarque pas les élémentaires d\'eau qui se forment derrière lui... Les images... s\'arrêtent ici.$B$BJ\'ai besoin de repos, $n. Désolé. Dites à Gin ce que j\'ai vu. Il doit savoir.' WHERE l.`ID` = 4130 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à la maîtresse des ombres Vivian Lagrave à Kargath.' WHERE l.`ID` = 4133 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'La maîtresse des ombres Vivian Lagrave a besoin de vos services. Elle se trouve dans les Terres ingrates, à l\'avant-poste orc de Kargath, et collecte les rumeurs courant sur une bière faite par les nains Sombrefer des Profondeurs de Rochenoire.$B$BAllez lui parler. Elle vous attend.' WHERE l.`ID` = 4133 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'À présent que la dernière destination connue de Raschal est découverte, continuez à le rechercher, lui ou ses restes, dans le gouffre Grouillant. D\'après le message, il se trouve au sud des camps des gnolls griffebois.' WHERE l.`ID` = 4135 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le gouffre Grouillant' WHERE l.`ID` = 4135 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'À l\'intérieur des sacs à dos se trouvent deux objets : le premier est un paquet qui était destiné à Thalanaar, et le second est un message écrit à la hâte et dont le destinataire reste inconnu.$B$BLe message raconte la découverte de créatures insidieuses et ressemblant à des insectes au sud des camps des gnolls griffebois, dans un endroit appelé le gouffre Grouillant. L\'auteur a jugé bon d\'y aller en personne, comme s\'il s\'agissait d\'un réel danger pour tout Féralas. Le message est signé "Raschal de Pennelune".$B$BIl semblerait que vous ayez découvert la dernière destination de Raschal.' WHERE l.`ID` = 4135 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Les pousses de Pétales-de-sang' WHERE l.`ID` = 4144 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir Muigin dans le Cratère d\'Un\'Goro.' WHERE l.`ID` = 4144 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Collectez 7 Petites pattes d\'araignée.' WHERE l.`ID` = 4161 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Une recette kaldorei' WHERE l.`ID` = 4161 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Autrefois, les elfes de la nuit s’appelaient les Kaldorei, ce qui veut dire "les enfants des étoiles". La connaissance du passé est une étape importante de votre cheminement de $c, $n, aussi écoutez attentivement ce que je vais vous dire.$B$BLes Kaldorei ont toujours été très fiers de la relation harmonieuse qu\'ils entretiennent avec la nature. Cela implique que nous ne prélevons chez elle que le nécessaire et que nous le restituons toujours. Cet équilibre nous est très bénéfique, $n.$B$BPartez à présent et prélevez sept petites pattes d\'araignées – pas plus – puis revenez me voir.' WHERE l.`ID` = 4161 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Voyager jusqu\'à Comté-du-Lac, dans les Carmines et remettre la Lettre d\'Helendis Ruissecorne au Magistrat Salomon.' WHERE l.`ID` = 4183 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Les véritables maîtres' WHERE l.`ID` = 4183 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Nous avons toujours cru que le caractère des orcs rochenoires était la conséquence de leur éducation brutale. Mais ce que nous avons découvert dans leur terre natale raconte une tout autre histoire.$B$BEffectivement, la soif du sang et des conflits les domine, mais ce sont les dragons noirs qui contrôlent les orcs rochenoires. Nous soupçonnons que ce sont eux qui les abreuvent de colère et d\'agressivité.$B$BApportez cette lettre au magistrat Salomon. Il saura quoi faire.$B$B<Helendis vous remet une lettre scellée.>' WHERE l.`ID` = 4183 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Voyager jusqu\'à Hurlevent et remettre la Demande d\'aide de Salomon au roi Varian Wrynn.$B$BLe roi demeure au Donjon de Hurlevent.' WHERE l.`ID` = 4184 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Les véritables maîtres' WHERE l.`ID` = 4184 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Voilà de bien sombres nouvelles, $n. Découvrir que nos ennemis mortels ne sont que des pions entre les mains d\'une menace plus importante encore est décourageant. Je ne vois pas comment Comté-du-Lac pourrait survivre à une attaque menée à la fois par les orcs rochenoires et par les dragons noirs. Si Comté-du-Lac devait succomber à ce danger, Sombre-Comté le suivrait de près. Et ensuite ? Comté-de-l’Or ? Hurlevent elle-même ?$B$BVous devez immédiatement mettre au courant de la situation le roi Varian Wrynn, à Hurlevent ! Si cela ne mérite pas l\'intervention de Hurlevent, rien ne le fera et tout sera perdu.' WHERE l.`ID` = 4184 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`AreaDescription` = 'L\'avis de dame Prestor' WHERE l.`ID` = 4185 AND l.`locale` = 'frFR' AND (l.`AreaDescription` IS NULL OR l.`AreaDescription` = '' OR BINARY l.`AreaDescription` = BINARY q.`AreaDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler au généralissime Bolvar Fordragon après avoir parlé à dame Katrana Prestor.' WHERE l.`ID` = 4185 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Les véritables maîtres' WHERE l.`ID` = 4185 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Salomon dépeint une situation bien lugubre. Cependant nous ne pouvons pas nous permettre d\'envoyer nos maigres troupes aider Comté-du-Lac sur la base d\'une simple spéculation. J\'ai besoin de preuves avant de pouvoir agir.$B$BParlez à dame Prestor, $n. C\'est une érudite qui en connaît beaucoup sur les dragons et les draconiens. Il est possible qu\'elle soit en mesure d\'apporter quelque lumière sur cette situation.' WHERE l.`ID` = 4185 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter le Décret de Wrynn au Magistrat Salomon à Comté-du-Lac.' WHERE l.`ID` = 4186 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Les véritables maîtres' WHERE l.`ID` = 4186 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '$n, je vais vous nommer $gAdjoint suppléant:Adjointe suppléante; de Hurlevent.$B$BRetournez voir le magistrat Salomon à Comté-du-Lac et remettez-lui ce décret.' WHERE l.`ID` = 4186 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
