UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '<Le magistrat Salomon soupire.>$B$BVous devez retourner dans les steppes Ardentes, $n. En tant qu’adjoint de Hurlevent, votre présence est exigée pour faire votre rapport au maréchal Maxwell. Bonne chance !' WHERE l.`ID` = 4223 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
