UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir Karna Songerrance aux Fosses de goudron de Lakkari, dans le Cratère d\'Un\'Goro.' WHERE l.`ID` = 4245 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Tout en vérifiant que vous pourrez bien ramener A-Mi à Karna Songerrance, vous placez l\'interrupteur en position Off. Tandis que vous scrutez les alentours pour vous assurer qu\'aucun gorille ne survient, vous vous préparez à voir le résultat du passage de l\'interrupteur sur la position On.$B$BC\'est votre dernière chance… Êtes-vous $gsûr:sûre; que c\'est bien ce que vous voulez faire ?' WHERE l.`ID` = 4245 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`AreaDescription` = 'Aider Arei à se rendre en lieu sûr' WHERE l.`ID` = 4261 AND l.`locale` = 'frFR' AND (l.`AreaDescription` IS NULL OR l.`AreaDescription` = '' OR BINARY l.`AreaDescription` = BINARY q.`AreaDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Escortez Arei en lieu sûr, puis parlez à Kayneth Mortebrise au Chant des forêts, dans l’est d’Orneval.' WHERE l.`ID` = 4261 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]L\'esprit d\'un ancien' WHERE l.`ID` = 4261 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir Kayneth Mortebrise au Chant des forêts, en Orneval.' WHERE l.`ID` = 4261 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Gangrebois était autrefois une terre paisible et sereine… jusqu’à l’arrivée de la Légion. Les infernaux, la destruction, le chaos…$B$BLe crâne de Gul’dan s’est assuré que personne ici ne soit épargné. Tous ont succombé à la corruption.$B$BMême à présent, bien que je sois un esprit, je me sens emprisonné, et j’ai le sentiment de porter toute la souffrance de cette terre. Aidez-moi à rentrer chez moi. Je vous en prie, $n, dites-moi que vous mènerez un esprit ancien hors de cet endroit, pour que je puisse enfin trouver le repos.$B$BQuand je serai libre, cherchez un druide du nom de Kayneth Mortebrise, qui réside au Chant des forêts, à l’est.' WHERE l.`ID` = 4261 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Il se peut que vous ayez simplement buté sur quelque chose qui pourrait intéresser le maréchal Windsor au plus haut point. Il reste peut-être encore un peu d\'espoir, après tout…' WHERE l.`ID` = 4264 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Une note chiffonnée' WHERE l.`ID` = 4264 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'La note est couverte de taches. Le texte est difficile à lire, mais vous parvenez à en déchiffrer certaines parties :$B$B… douce ironie…$B$B… la chute de l\'Alliance brisée…$B$B… sans l\'aide assidue du général Forgehargne, nous n’aurions peut-être jamais découvert la structure du code…$B$B… Argelmach en a presque terminé avec le décodage des notes de Windsor.$B$BNotre Seigneur s\'élèvera des profondeurs et écrasera quiconque subsistera…$B$BEmpereur Dagran Thaurissan.' WHERE l.`ID` = 4264 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`AreaDescription` = 'Libérer Raschal' WHERE l.`ID` = 4265 AND l.`locale` = 'frFR' AND (l.`AreaDescription` IS NULL OR l.`AreaDescription` = '' OR BINARY l.`AreaDescription` = BINARY q.`AreaDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Libérer Raschal de la ruche de Zukk\'ash.$B$BRevenir voir Ginro Attisâtre au bastion de Pennelune et lui dire que Raschal est sain et sauf.' WHERE l.`ID` = 4265 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'évasion de la ruche' WHERE l.`ID` = 4265 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir Ginro Attisâtre au Bastion de Pennelune, en Féralas.' WHERE l.`ID` = 4265 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Alors que vous la touchez, l\'alvéole s\'entrouvre et révèle un elfe de la nuit - en vie, ce qui est étonnant. Il semble en bonne santé, bien qu\'il soit inconscient. Tandis que vous essayez de le dégager de l\'alvéole, il revient à lui.$B$B« Qu\'Élune soit louée, vous m\'avez sauvé, mon $gami:amie; ! Je… je suis Raschal, et je me suis réveillé dans cette alvéole après avoir été capturé par ces insectes. Ce sont les gens du bastion qui vous envoient ? »$B$BOn dirait que vous avez retrouvé le messager disparu !' WHERE l.`ID` = 4265 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à Shandris Pennelune dans le bastion de Pennelune.' WHERE l.`ID` = 4266 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Accueil d\'un héros' WHERE l.`ID` = 4266 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '$n, le général Shandris Pennelune voudrait vous parler en personne. Elle veut vous remercier pour les services rendus au bastion, mais je crois savoir qu\'elle souhaite également vous entretenir des créatures insectoïdes que vous et Raschal avez combattues dans le sud de Féralas. Ce que nous avons entendu de ces insectes zukk\'ash est… effrayant, c\'est le moins que l\'on puisse dire.$B$BLe général Pennelune vous attend dans la base principale.' WHERE l.`ID` = 4266 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter le Rapport de Raschal à Gracina Forcesprit à Darnassus.' WHERE l.`ID` = 4267 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'ascension des silithides' WHERE l.`ID` = 4267 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Je vous confie une copie du rapport de Raschal concernant l\'infestation du sud-est de Féralas. Bien que le rapport original soit envoyé à Darnassus, je veux que vous remettiez cette copie à une associée du Protectorat. Elle se nomme Gracina Forcesprit. C\'est une prêtresse qui réside au temple de la Lune à Darnassus. Elle possède une vaste connaissance de ce genre de créatures, et lui confier ce rapport profitera à tous.$B$BVous pouvez partir. Bonne chance, $n. Puisse Élune veiller sur nous tous.' WHERE l.`ID` = 4267 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez le Vieux colis à Falfindel Gardevoie, à Thalanaar.' WHERE l.`ID` = 4281 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La livraison à Thalanaar' WHERE l.`ID` = 4281 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Le colis que vous avez trouvé au camp des gnolls griffebois devait être livré au petit poste de Thalanaar, dans la région sud-est de Féralas. Malgré la disparition du messager, le colis doit être livré.$B$BEn l’examinant de près, on peut lire sur le côté, écrit à la main : "Falfindel Gardevoie". Peut-être s\'agit-il du destinataire ?' WHERE l.`ID` = 4281 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
