UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Ceci explique cela' WHERE l.`ID` = 4321 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'L’information que vous m’avez transmise à propos des pylônes est très intéressante...$B$BLaissez-moi réfléchir à certaines choses, $n. Revenez me voir dans un moment, je devrais pouvoir vous donner les réponses que vous cherchez.' WHERE l.`ID` = 4321 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
