UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Nous devons sortir d\'ici, $n. Aidez-moi à récupérer mon équipement dans la zone d\'approvisionnement et à libérer mes amis. Si nous nous en sortons, vous devrez vous rendre à la Veille de Morgan et parler au maréchal Maxwell. Il vous donnera d\'autres instructions.' WHERE l.`ID` = 4322 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Allez dans les Profondeurs de Rochenoire et trouvez Kharan Force-martel.$B$BLe roi a mentionné que Kharan était retenu prisonnier là-bas ; cherchez une prison.' WHERE l.`ID` = 4341 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Kharan Force-martel' WHERE l.`ID` = 4341 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Avez-vous été dans les ruines fumantes de Thaurissan ? Avez-vous rencontré un pitoyable voyou nommé Kharan Force-martel ? Ce nain qui était censé veiller sur ma petite fille !$B$B<Le roi sanglote.>$B$BEt maintenant elle est partie, $n !$B$BMes hommes ont fouillé les Steppes buisson par buisson. Le seul indice qu’ils ont trouvé semble révéler que ma fille se trouve quelque part dans les Profondeurs. Elle pourrait tout aussi bien être morte !$B$BKharan serait prisonnier là-bas... Trouvez-le, je veux des réponses !' WHERE l.`ID` = 4341 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`AreaDescription` = 'Histoire de Kharan' WHERE l.`ID` = 4342 AND l.`locale` = 'frFR' AND (l.`AreaDescription` IS NULL OR l.`AreaDescription` = '' OR BINARY l.`AreaDescription` = BINARY q.`AreaDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Écouter Kharan Force-martel raconter son histoire.' WHERE l.`ID` = 4342 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
