UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous devez délivrer cette information au roi Magni, $n. Il saura quoi faire !' WHERE l.`ID` = 4361 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Retourner à Forgefer et parler au roi Magni Barbe-de-bronze.' WHERE l.`ID` = 4363 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La surprise de la Princesse' WHERE l.`ID` = 4363 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Thaurissan était un nain valeureux et honorable. Vous avez détruit ma vie et celle de l’enfant que je porte !$B$B<Vous estimez que la princesse Barbe-de-bronze souffre toujours des effets résiduels du sort de l’empereur.>$B$BRetournez à Forgefer et dites à mon père que l’héritier du trône de Forgefer sera un nain Sombrefer.$B$BQue cela lui plaise ou pas, il en sera ainsi.' WHERE l.`ID` = 4363 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Tuer 8 Géologues Sombrefer et rapporter 15 morceaux d’Etoffe de soie à la personne enfermée dans les toilettes de la gorge des Vents brûlants.' WHERE l.`ID` = 4449 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Piégé !' WHERE l.`ID` = 4449 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Hé vous ! Oui, vous ! Venez donc ici !$B$BVous allez m’aider. J’étais poursuivi par les nains Sombrefer, et je me suis planqué ici, hors de vue. Ces maudits géologues et leur magie ! Ils ont dû me repérer quand même, parce qu’ils ont verrouillé la porte avant que je ne puisse réagir. Je suis coincé à l’intérieur.$B$BDonnez-leur une bonne leçon ! Oh… et puis si vous pouviez récupérer de l’étoffe de soie pour... euh… pour rien, ce serait parfait.' WHERE l.`ID` = 4449 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`AreaDescription` = 'Escorter Ringo jusqu\'à Spraggle Frock au refuge des Marshal' WHERE l.`ID` = 4491 AND l.`locale` = 'frFR' AND (l.`AreaDescription` IS NULL OR l.`AreaDescription` = '' OR BINARY l.`AreaDescription` = BINARY q.`AreaDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Conduire Ringo auprès de Spraggle Frock, au refuge des Marshal.$B$BSi Ringo s’évanouit, utiliser la Gourde de Spraggle pour le réanimer.' WHERE l.`ID` = 4491 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Un peu d\'aide de mes amis' WHERE l.`ID` = 4491 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir Spraggle Frock au Refuge des Marshal, dans le Cratère d\'Un\'Goro.' WHERE l.`ID` = 4491 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Wouf… Il fait tellement chaud…$B$BJ\'explorais le secteur lorsque soudain, la chaleur est devenue insupportable. Je dois souffrir d\'insolation.$B$BJe vous en prie, aidez-moi à retourner auprès de mon amie Spraggle au refuge des Marshal. Je pense que je vais encore suffisamment bien pour être capable de vous suivre jusque là-bas.$B$BJe ne me sens pas vraiment en grande forme, cependant, alors si je devais m\'évanouir à nouveau, renversez-moi de l\'eau de la gourde de Spraggle dessus. Ça devrait marcher, j\'espère...' WHERE l.`ID` = 4491 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Collecter un échantillon d’eau corrompue dans le puits de lune des satyres Jadefeu, puis le rapporter à Winna Hazzard, au Poste de la Vénéneuse.' WHERE l.`ID` = 4505 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]Puits de la corruption' WHERE l.`ID` = 4505 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Certains prétendent que je suis exceptionnellement cruelle... Mais voir la Horde prendre l’avantage sur l’Alliance, par tous les moyens possibles, n’est simplement qu’un souhait ardent.$B$BJe m’intéresse en ce moment à un puits de lune qui se trouve dans les ruines de Constellas, plus au sud, gardé par les satyres Jadefeu. Le puits de lune, jadis un symbole de renouveau pour ces insupportables elfes de la nuit, est maintenant corrompu et utilisé pour produire encore plus de satyres.$B$BJ’ai une idée, $n : j’aimerais un échantillon de cette eau... pour tous mes petits félins.' WHERE l.`ID` = 4505 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter le Rapport de Pilonzugg sur Un\'Goro à Gracina Forcesprit, à Darnassus.' WHERE l.`ID` = 4508 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le calme avant la tempête' WHERE l.`ID` = 4508 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Il faut faire parvenir mes recherches récentes et nos découvertes à ceux qui sauront en tirer bénéfice. Nous autres, ici à Gadgetzan, ne pouvons faire cela tout seuls.$B$BPortez mon dernier rapport à Gracina Forcesprit, à Darnassus ; elle est toujours au temple de la Lune, n’est-ce pas ? Elle a des amis qui sont des huiles de l’Alliance et si nous pouvions les impliquer dans cette affaire, $n, cela pourrait nous sauver la mise.' WHERE l.`ID` = 4508 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter un Échantillon de Limon mélangé au Chimiste Fuely à Fossoyeuse.' WHERE l.`ID` = 4642 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Trafic d\'influences' WHERE l.`ID` = 4642 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Voici un peu de Limon créé à partir des échantillons récupérés à Gangrebois. Portez cette caisse au Cratère d\'Un\'Goro et trouvez du Limon pur... la variété primitive fera parfaitement l’affaire. Quand vous serez assez près, libérez le Limon qui est dans la caisse, et voyez comment les deux variétés interagissent.$B$BQuand l’expérimentation sera terminée, rapportez-moi un échantillon de ce qui reste, quoi que cela soit. Je vous attendrai ici à l\'Apothicarium.' WHERE l.`ID` = 4642 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Trull Faillemort à Gangrebois veut que vous chassiez 10 Chouettards berserk au Berceau-de-l\'Hiver.' WHERE l.`ID` = 4721 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Les gardiens sauvages' WHERE l.`ID` = 4721 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Des messagers sont revenus du Berceau-de-l\'Hiver, reportant qu’il y a une série de petites grottes au sud de la région. Il semble qu’il y ait des Indomptables dans les environs de ces grottes. S’ils sont employés à garder une chose de valeur, je suppose que c’est là que nous trouverons ce que nous cherchons.$B$BCeux-là seront plus coriaces que les précédents, $n. Il semble que ces créatures aient été rendues folles par ce qu’elles sont justement censées garder.' WHERE l.`ID` = 4721 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter les Os de créature marine à Gwennyth Bly\'Leggonde à Auberdine.' WHERE l.`ID` = 4723 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La créature marine échouée' WHERE l.`ID` = 4723 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Les restes d’un batteur gigantesque, bien plus grand que ceux qu\'on s\'attendrait à trouver à Sombrivage, gisent, échoués sur la côte de la Lisière des brumes. La présence de cette créature à cet endroit est un mystère ; les murlocs qui festoient sur la carcasse semblent bien trop faibles pour avoir chassé et abattu la bête tout seuls.$B$BIl reste suffisamment à prélever sur la dépouille pour en rapporter un échantillon que Gwennyth Bly\'Leggonde, à Auberdine, pourrait étudier.' WHERE l.`ID` = 4723 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter la Boîte aux marques étranges à Gwennyth Bly\'Leggonde à Auberdine.' WHERE l.`ID` = 4725 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La tortue de mer échouée' WHERE l.`ID` = 4725 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'D’autres restes de tortue gisent, échoués le long de la côte. Cette dépouille a une espèce de chariot attaché à sa carapace. Il semble que la créature ait été conduite sur le littoral et qu’elle ne se soit pas échouée, à la différence des autres. Les murlocs grisebrumes habitent maintenant les restes de cette créature, se régalant sur la carcasse.$B$BDans le chariot, vous trouvez une boîte avec d’étranges inscriptions ; peut-être Gwennyth Bly\'Leggonde, à Auberdine, pourrait comprendre de quoi il s\'agit.' WHERE l.`ID` = 4725 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter les Restes de tortue de mer à Gwennyth Bly\'Leggonde à Auberdine.' WHERE l.`ID` = 4727 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La tortue de mer échouée' WHERE l.`ID` = 4727 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Les restes d’une tortue de mer gisent sur le sable des plages du nord de Sombrivage. Les murlocs grisebrumes n\'ont peut-être pas encore repéré cette carcasse ; ou alors, ils l\'ont rejetée pour quelque étrange raison. Il subsiste néanmoins de quoi prélever un échantillon et le rapporter à Gwennyth Bly\'Leggonde, à Auberdine, afin que ceux du temple de la Lune puissent l’étudier.' WHERE l.`ID` = 4727 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`AreaDescription` = 'Tester le prototype d\'Oeufilloscope' WHERE l.`ID` = 4734 AND l.`locale` = 'frFR' AND (l.`AreaDescription` IS NULL OR l.`AreaDescription` = '' OR BINARY l.`AreaDescription` = BINARY q.`AreaDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Utiliser le Prototype d’Œufilloscope sur un œuf dans la Colonie au Pic Rochenoire.' WHERE l.`ID` = 4734 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Un oeuf congelé' WHERE l.`ID` = 4734 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '$n, je travaille sur un nouvel appareil : l’Œufilloscope ! Il est destiné à projeter une salve d’énergie réfrigérante sur l’œuf d’un dragon noir... ce qui le congèle instantanément ! Pourriez-vous le tester pour moi ?$B$BJ\'ai entendu que très haut sur le pic Rochenoire, il y a une colonie de dragons où ils couvent leurs œufs. C’est là que vous devrez aller tester l’Oeufilloscope. Vous reviendrez ensuite me dire comment il a fonctionné !$B$BEt ne vous inquiétez pas, les œufs de dragons congelés sont tout à fait inoffensifs ; ce sont ceux qui ne seront pas congelés qui seront le véritable souci !' WHERE l.`ID` = 4734 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à Menara Taillevide dans les Tarides.' WHERE l.`ID` = 4736 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'À la recherche de Menara Taillevide' WHERE l.`ID` = 4736 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Bonjour, $n. Vos progrès sont rapides, si rapides que je pense que vous méritez une récompense ; de plus, vous avez su résister à la corruption des arcanes, pour l’instant.$B$BSi cela vous intéresse, allez voir Menara Taillevide, à Cabestan. Elle réside en ce moment dans la tour de Strahad Farsan, au-dessus de Cabestan.$B$BElle n’est pas très amicale, $n, n’en espérez ni accueil ni éloges. Mais si vous travaillez dur, elle saura s’occuper de vous.' WHERE l.`ID` = 4736 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à Menara Taillevide dans les Tarides.' WHERE l.`ID` = 4737 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'À la recherche de Menara Taillevide' WHERE l.`ID` = 4737 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Hum, vous vous efforcez encore d\'augmenter votre puissance. Mais ce n’est qu’une question de temps avant que la corruption ne vous soumette et que ne vous deveniez l’esclave de ce que vous combattez.$B$BPfah ! Quelle folie ! Le temps me donnera raison.$B$BIl semble pourtant que tous ne soient pas d’accord avec Zevrost et que Menara veuille créer des objets pour augmenter et exploiter votre force. Si cela vous intéresse, allez à Cabestan, dans les Tarides. Elle est là-bas, dans la tour qui domine la ville.' WHERE l.`ID` = 4737 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à Menara Taillevide dans les Tarides.' WHERE l.`ID` = 4739 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'À la recherche de Menara Taillevide' WHERE l.`ID` = 4739 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous ! Oui, vous, $gle:la:c; $c !$B$BVous n’avez pas l’équipement complet, mais il est évident que vous êtes au point ; en témoigne l’aplomb qui émane de votre présence.$B$BMenara Taillevide pourrait vous apprendre deux-trois choses, si vous le voulez. Elle passe son temps à enseigner à de jeunes apprentis l’art des arcanes. Elle fait même des cadeaux à ceux qui réussissent ses tests.$B$BAllez à Cabestan dans les Tarides, si cela vous intéresse. Elle réside dans la tour de Strahad, au-dessus de la ville.' WHERE l.`ID` = 4739 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Trull Faillemort à Gangrebois veut que vous chassiez 13 Chouettards lunaires.' WHERE l.`ID` = 4741 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Les gardiens sauvages' WHERE l.`ID` = 4741 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Dans la partie nord du Berceau-de-l\'Hiver, les Indomptables sont encore plus féroces. Nous devons continuer nos mesures là-bas.$B$BChassez les Chouettards lunaires du Berceau-de-l\'Hiver, et explorez la zone où ils vivent.$B$BC’est un terrain dangereux, mais je sais que vous êtes à la hauteur de la tâche. Revenez me voir après avoir tué 13 Indomptables.' WHERE l.`ID` = 4741 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à Thundris Tissevent, à Auberdine.' WHERE l.`ID` = 4761 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Thundris Tissevent' WHERE l.`ID` = 4761 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Thundris Tissevent doit être averti du résultat de votre reconnaissance au camp furbolg. C’est l\'un des anciens d’Auberdine qui aide à régler les affaires courantes du village. Allez lui faire part de vos découvertes sur la situation des furbolgs.$B$BIl sait certainement pourquoi ils ont été corrompus. Peut-être pourriez-vous travailler avec lui au rétablissement de l\'équilibre naturel à cet endroit !' WHERE l.`ID` = 4761 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Allez voir Mayara Luisaile à la Veille de Morgan, dans les Steppes Ardentes.' WHERE l.`ID` = 4766 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Mayara Luisaile' WHERE l.`ID` = 4766 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Un de mes agents, Mayara Luisaile, a été envoyée dans les steppes Ardentes pour une reconnaissance de la ville en ruine de Thaurissan. Cette cité détruite des nains sombrefers pourrait cacher des objets de grande valeur... qui auraient leur place dans notre musée familial.$B$BMayara a prévenu qu’elle avait trouvé quelque chose et qu’elle avait besoin d’aide pour le récupérer ; pourtant, cela ne se trouve pas à Thaurissan. Il faudra faire un raid sur le pic Rochenoire.$B$BJe ne connais pas les détails de cette affaire, mais si cela vous intéresse, parlez à Mayara, dans les steppes Ardentes.' WHERE l.`ID` = 4766 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à l\'ombremage Vivian Lagrave.' WHERE l.`ID` = 4769 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Vivian Lagrave et la tablette de Sombrepierre' WHERE l.`ID` = 4769 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vivian Lagrave de Kargath, dans les Terres ingrates, m\'a fait savoir qu\'il existait un ancien texte dans le pic Rochenoire qui nous serait très utile. Elle a besoin d’un volontaire pour aller récupérer ce texte. C\'est une mission difficile.$B$BSi cela vous intéresse, parlez à Vivian, dans Kargath.' WHERE l.`ID` = 4769 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter une Barre d\'or à Xizk Beaupiqué dans la vallée de Strangleronce.' WHERE l.`ID` = 4781 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Les composants de la robe sanglante dorée enchantée' WHERE l.`ID` = 4781 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Votre nouvelle tâche est aussi simple que la première, mais il vous faudra chercher de l\'aide.$B$BJ\'ai besoin de fil d\'or pour la broderie de la cape, mais il n\'est pas facile de s\'en procurer, et très peu sont ceux qui savent comment le fabriquer. Heureusement, un individu loyal à notre cause connaît le secret et est prêt à aider ceux qui montent dans nos rangs.$B$BApportez une barre d\'or à Xizk Beaupiqué à Baie-du-Butin. Il est maître tailleur et filera le fil pour vous de bon cœur. Ce sont les mineurs chevronnés qui fondent les barres d\'or. Demandez à un mineur de vous aider.' WHERE l.`ID` = 4781 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Retourner voir Menara Taillevide dans les Tarides.' WHERE l.`ID` = 4782 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Les composants de la robe sanglante dorée enchantée' WHERE l.`ID` = 4782 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Retournez voir Menara, dites-lui que cela prendra du temps mais que je le ferai, pour elle... et pour vous. Finissez de rassembler le reste des composants, j’aurai terminé le fil d’ici là. Revenez alors le chercher.$B$BBonne chance, $n. Oh, et saluez Strahad de ma part, pendant que vous y êtes. Ce vieux chnoque... avoir une tour tout près de Cabestan... quelle folie.' WHERE l.`ID` = 4782 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez du Fil d\'or fin, 2 Charbons ardents et un Fragment d\'âme à Menara Taillevide dans les Tarides.' WHERE l.`ID` = 4784 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Les composants de la robe sanglante dorée enchantée' WHERE l.`ID` = 4784 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Je n’ai plus besoin que de trois choses, $n, puis nous pourrons terminer votre robe.$B$BD\'abord, il nous faut le fil d’or délicat que Xizk fabrique pour vous. Retournez à Baie-du-Butin et allez le chercher.$B$BEnsuite, vous m\'apporterez deux charbons ardents que vous trouverez sur les élémentaires de feu dans les hautes-terres Arathies. Si mes souvenirs sont bons, ils sont à l’ouest, près du mur de Thoradin.$B$BFinalement, un fragment d\'âme créé par vous.$B$BUne fois que vous aurez tous ces éléments, revenez me voir et je terminerai la robe.' WHERE l.`ID` = 4784 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez le Paquet de Felnok à Brikolette Toutevapeur à la Corniche des Flammes, dans les Steppes Ardentes.' WHERE l.`ID` = 4810 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Retourner voir Brikolette' WHERE l.`ID` = 4810 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Bien, tout est prêt, empaqueté et paré au transport. Bonne chance dans votre voyage, et n\'oubliez pas de rappeler mon dévouement et ma loyauté à Brikolette !' WHERE l.`ID` = 4810 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Trouver le chariot saccagé de Jaron Sculptepierre.' WHERE l.`ID` = 4863 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Les Indomptables enragés' WHERE l.`ID` = 4863 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'En regardant autour de vous, vous vous demandez ce que Jaron pouvait bien vouloir ici. Vous remarquez cependant que la caisse que vous avez trouvée a été ouverte violemment, comme si c\'était cela que les indomptables cherchaient...$B$BEn regardant à l’est, vous discernez un chariot abandonné. Peut-être les effets de Jaron s’y trouvent-ils. Cela vaut certainement la peine d’aller jeter un coup d\'œil.' WHERE l.`ID` = 4863 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Ramasser les Fournitures de Jaron dans la neige, puis trouver l\'Indomptable qui a volé l\'amulette dont Jaron a parlé.$B$BRapporter les fournitures de Jaron et l\'Amulette de la plume bleue à Jaron Sculptepierre dans son pavillon au Berceau-de-l\'Hiver.' WHERE l.`ID` = 4864 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Les Indomptables enragés' WHERE l.`ID` = 4864 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Après avoir inspecté le contenu de la boîte, vous estimez que Jaron pourrait avoir usage des outils et des objets qu’elle renferme. Il n’y a cependant aucun signe de l’amulette.$B$BIl s’avère que les indomptables hantent les terres au nord et à l’est ; vous décidez par conséquent d’affronter les créatures et de leur arracher l’amulette.' WHERE l.`ID` = 4864 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter le Collier de plumes bleues à Trull Faillemort au Poste de la Vénéneuse.' WHERE l.`ID` = 4882 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Secrets gardés' WHERE l.`ID` = 4882 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous voudriez en savoir plus sur le collier qui est tombé du cou de l\'Indomptable que vous avez tué. Il brille fortement mais son éclat varie.$B$BTrull Faillemort devrait être capable de vous en dire plus, puisque c\'est un spécialiste des Indomptables. N\'hésitez pas à le consulter.' WHERE l.`ID` = 4882 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter le Collier de plumes bleues à Nara Crin-sauvage.' WHERE l.`ID` = 4883 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Secrets gardés' WHERE l.`ID` = 4883 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'J\'ai beau posséder de solides connaissances sur les Chouettards que vous avez vaincus au Berceau-de-l\'Hiver, je ne sais pas grand-chose de la magie qu\'ils utilisent. Mais je pense savoir qui pourra examiner ce collier et vous dire de quoi il s\'agit.$B$BNara Crin-sauvage aux Pitons-du-Tonnerre est experte en la matière. Allez la voir. Bonne chance, $n.' WHERE l.`ID` = 4883 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`AreaDescription` = 'Découvrir le secret de l\'Autel d\'Élune' WHERE l.`ID` = 4901 AND l.`locale` = 'frFR' AND (l.`AreaDescription` IS NULL OR l.`AreaDescription` = '' OR BINARY l.`AreaDescription` = BINARY q.`AreaDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Protéger Ranshalla pendant qu’elle s’efforce de réactiver l’Autel d’Élune. Faire un rapport de vos découvertes à Erelas Ambreciel, au village de Rut\'theran.' WHERE l.`ID` = 4901 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
