UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir Erelas Ambreciel à Rut\'theran, sur Teldrassil.' WHERE l.`ID` = 4901 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Au sommet de l\'arête se trouve ce que je crois être un autel de la déesse Élune. De ce que je peux dire, il faut allumer les cinq torches dans chaque caverne pour accéder à l\'autel.$B$BJ\'ai retranscrit quelques incantations taillées dans la pierre, dans les ruines antiques de Kel\'Theril ; je crois qu\'elles sont la clé pour ouvrir l\'autel. J\'aurai besoin de votre aide pour allumer les torches pendant que je réciterai le charme.$B$BSi notre entreprise est couronnée de succès, vous pourrez annoncer nos découvertes à Erelas !' WHERE l.`ID` = 4901 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à l’Archidruide Fandral Forteramure, à Darnassus.' WHERE l.`ID` = 4902 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Les indomptables d\'Élune' WHERE l.`ID` = 4902 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'C\'est fascinant !$B$BJ\'ai toujours voulu savoir la vérité... Bon, vous devez faire entendre cette vérité ! Allez tout de suite chez l\'archidruide Fandral Forteramure, vous le trouverez à Darnassus, au Cercle cénarien. Expliquez-lui ce qui est arrivé, comme vous me l\'avez expliqué. Je suis sûr qu\'il sera très intéressé !$B$BCette information est importante, $n !' WHERE l.`ID` = 4902 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
