UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Salut, $n. Vous vous rappelez de Brikolette Toutevapeur ? Elle, elle se souvient de vous ! Elle me fait vous dire qu’elle a encore besoin de votre aide. Je pense que c’est en rapport avec ses études sur les dragons.$B$BAllez lui parler dans les steppes Ardentes, à la corniche des Flammes.' WHERE l.`ID` = 4907 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Prendre l’Emeraude d\'Infus et l’utiliser sur l\'un des Infernaux qui se trouvent en Désolace. Quand vous aurez réussi, rapporter l’Emeraude d\'Infus et l’Esprit d\'Infernal emprisonné à Menara Taillevide, dans les Tarides.' WHERE l.`ID` = 4963 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
