UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Connaissance de l\'Orbe d\'Orahil' WHERE l.`ID` = 4967 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Alors, toujours dans les affaires des mortels ? Oui, je me suis adressé à vous avec arrogance. Je vous vois devant moi, et je ris : vous êtes pathétique !$B$BMais ce que je pense n’a pas d’importance, seul importe ce que pensent ceux qui veulent traiter avec vous de quelque façon que ce soit ! Ainsi, et contre mon avis personnel, ceux qui ont quelque pouvoir estiment que vous méritez plus encore.$B$BParlez avec Menara Taillevide, dans la tour qui domine Cabestan. Je crois savoir que vous l’avez déjà rencontrée il y a quelque temps.' WHERE l.`ID` = 4967 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parlez à Menara Taillevide, dans les Tarides.' WHERE l.`ID` = 4968 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Connaissance de l\'Orbe d\'Orahil' WHERE l.`ID` = 4968 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous avez réussi à arriver jusqu’ici, c’est vraiment étonnant. Je croyais que la corruption émise par la canalisation des arcanes infiltrerait votre âme et vous rendrait fou. Pourquoi ne pas aller plus loin, dans ce cas ?$B$BSi vous voulez mettre à l’épreuve vos compétences, allez voir Menara Taillevide dans la Tour de Strahad qui domine Cabestan. Elle vous guidera.' WHERE l.`ID` = 4968 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parlez à Menara Taillevide, dans les Tarides.' WHERE l.`ID` = 4969 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Connaissance de l\'Orbe d\'Orahil' WHERE l.`ID` = 4969 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Ha ha ! Vous êtes $gambitieux:ambitieuse;, jeune $c.$B$BEn temps voulu, les Infernaux et les Seigneurs de l\'effroi s’inclineront devant vous !$B$BMais pour l’instant, vous ne devrez compter que sur des armes forgées par les races mortelles.$B$BUne autre de ces créations est disponible pour vous. Si vous le voulez, Menara Taillevide pourrait vous parler ! Elle se trouve près de la Tour de Strahad qui domine la ville portuaire de Cabestan. Partez quand vous jugerez le moment venu.' WHERE l.`ID` = 4969 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Utiliser le Déplaceur temporel à côté de l’un des silos d’Andorhal pour révéler des Parasites temporels.$B$BTuer 10 Parasites temporels et rapporter le Déplaceur temporel à Chromie, à l’auberge d’Andorhal, dans les Maleterres de l’Ouest.' WHERE l.`ID` = 4971 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Une question de temps' WHERE l.`ID` = 4971 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Une altération du passage du temps par une force sinistre, la Horde très probablement, est survenue à Andorhal ! Je peux tenter de conserver le passage du temps intact ici et réparer ce qui a été endommagé, mais je vais avoir besoin de votre aide pour que je le fasse de manière ininterrompue.$B$BDes Parasites temporels infestent à présent les silos d\'Andorhal. Une pulsation bleue est le seul signe visible que nous ayons d\'eux. Ils ralentissent mes augures. S\'il vous plaît, $n, aidez-moi en vous servant de ce Déplaceur temporel afin de déloger ces parasites.' WHERE l.`ID` = 4971 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Trouver 5 Montres d\'Andorhal, dans des coffrets qui se trouvent parmi les décombres de la ville, et les rapporter à Chromie à l’Auberge d’Andorhal, dans les Maleterres de l’Ouest.' WHERE l.`ID` = 4972 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Arrêt du temps' WHERE l.`ID` = 4972 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'J’ai besoin que vous passiez dans le monde qui se trouve derrière cette pièce, $n. Je vais être plus claire.$B$BVous avez remarqué que cette pièce était différente des autres parties d’Andorhal. Mon vol de dragons agit dans différents plans et différents flux temporels. Pour réparer les dégâts d\'Andorhal, j’agis à partir d’autres flux temporels, évitant ainsi toute contamination de ce plan. Pour pouvoir continuer, j’ai besoin des bijoux temporels qui ont été pris dans le cours du temps lorsque le mal se déclara. Vous les trouverez dans des coffrets qui traînent parmi les ruines de cette ville, jadis majestueuse.' WHERE l.`ID` = 4972 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Trouver 5 Montres d\'Andorhal parmi les décombres de la ville et les rapporter à Chromie à l’Auberge d’Andorhal, dans les Maleterres de l’Ouest.' WHERE l.`ID` = 4973 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Arrêt du temps' WHERE l.`ID` = 4973 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Si vous êtes $gprêt:prête; à m\'aider une nouvelle fois, j\'aurais encore bien besoin de votre assistance. J\'accepterais volontiers les montres supplémentaires que vous pourriez trouver dans les ruines d\'Andorhal. Elles me serviraient pour maintenir l\'équilibre du flux temporel, malgré les forces hostiles qui sont en train de s\'y incorporer, ici.$B$BEn échange de ces montres, je vous remettrai un autre objet qui vous sera certainement utile dans le futur.' WHERE l.`ID` = 4973 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Aller au Pic Rochenoire et tuer le Chef de guerre, Rend Main-Noire. Prendre sa tête et retourner à Orgrimmar.' WHERE l.`ID` = 4974 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Pour la Horde !' WHERE l.`ID` = 4974 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Rend ose prononcer de telles revendications parce qu’il sait qu’il est sous la protection des dragons noirs.$B$BVous, $n, trouverez un moyen de traverser les Halls de l’Ascension. Après vous trouverez le « Chef de guerre » Rend Main-Noire et vous le détruirez - AU NOM DE LA HORDE !$B$B<Thrall abat son poing sur le trône.>$B$BLa prochaine fois que vous viendrez dans mon domaine, vous porterez sa tête, comme trophée, et la présenterez à votre Chef de guerre. Faites cela et soyez $ghonoré:honorée; comme $ghéros:héroïne; de la Horde.' WHERE l.`ID` = 4974 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Rapporter le Rapport de reconnaissance de Bijou au Grand-maître Lexlort, à Kargath.' WHERE l.`ID` = 4983 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Rapport de reconnaissance de Bijou' WHERE l.`ID` = 4983 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Portez ce rapport à Lexlort. Cela rachètera mes erreurs et donnera des informations stratégiques au C.E.K., lesquelles les avantageront dans leur lutte contre les orcs.$B$BVenir avec vous ? J’ai beaucoup trop de travail à faire. Partez, ils ont besoin de ce rapport aussi vite que possible !' WHERE l.`ID` = 4983 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'D\'après la magie contenue dans la Branche de chêne glyphée, le druide tauren voulait qu\'elle soit apportée au Cercle cénarien, à Darnassus. Aller solliciter l’assistance de l’un des druides, là-bas.' WHERE l.`ID` = 4986 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La branche de chêne glyphée' WHERE l.`ID` = 4986 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'La main sans vie du druide tauren est agrippée à une branche de chêne d’aspect étonnamment sain. En examinant la branche, vous découvrez des inscriptions de nature druidique gravées dans l’écorce.$B$BComme vous la prenez en main, vous remarquez qu’une curieuse tiédeur en émane. L’image de l’Arbre-Monde de Teldrassil s\'impose dans votre esprit, Darnassus, pour être plus précis, ainsi que les mots : « Cercle cénarien ». C’est comme si le lieu où emporter la branche était compris en elle.' WHERE l.`ID` = 4986 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Rendez-vous dans les Steppes Ardentes et confiez les Renseignements de Bijou au maréchal Maxwell.' WHERE l.`ID` = 5002 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Message à Maxwell' WHERE l.`ID` = 5002 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Je suis un gobelin de parole, $r. À présent, écoutez attentivement :$B$BCes orcs sont avant tout utilisés comme bêtes de somme et comme chair à canon par les dragons noirs !$B$BLeur véritable chef n\'est autre que Nefarian, rejeton de l\'Aile de mort. J\'ai également découvert la localisation des subordonnés de Nefarian dans cette partie de la citadelle.$B$BApportez cette carte au maréchal Maxwell dans les steppes Ardentes. J\'y ai marqué la localisation de ces monstres afin qu\'on puisse les trouver facilement.' WHERE l.`ID` = 5002 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Rendre visite aux Facteurs royaux de Hurlevent pour apprendre l’adresse d’une certaine Emma Gangrepierre. En général, il y a un officier du recensement à l’Hôtel de ville.' WHERE l.`ID` = 5022 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Mieux vaut tard que jamais' WHERE l.`ID` = 5022 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous ramassez le colis et époussetez la petite couche de poussière qui s\'y était déposée. Il est adressé, d\'une main hâtive, à une certaine Emma Gangrepierre, à Hurlevent. La remise du paquet date de plus de quatre ans.$B$BBien qu\'il ne soit même pas certain qu\'Emma Gangrepierre soit toujours en vie, il est de notoriété publique que l\'hôtel de ville de Hurlevent garde sur ses registres la population de la ville. Les responsables royaux du recensement de Hurlevent s\'en occupent.' WHERE l.`ID` = 5022 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La force d’Agammagan' WHERE l.`ID` = 5042 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir Mutiledent en Mulgore.' WHERE l.`ID` = 5042 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Trouver la vieille Emma à Hurlevent, et découvrir si elle est en fait Emma Gangrepierre. Si c’est le cas, elle appréciera peut-être le colis que Janice Gangrepierre lui a préparé.' WHERE l.`ID` = 5048 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Emma la bonne pâte' WHERE l.`ID` = 5048 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Elle est un peu revêche, et perd certainement la tête... mais les archives indiquent qu\'Emma correspond au signalement d\'Emma Gangrepierre.$B$BVous avez peut-être vu la vieille Emma errer dans la ville ? Elle parle toute seule, et la plupart du temps, c\'est du charabia. Elle ne fait de mal à personne, alors les gens la laissent tranquille.$B$BTout bien considéré, je dirais qu\'effectivement la vieille Emma doit être Emma Gangrepierre. Essayez de lui demander si son nom de famille est bien Gangrepierre.' WHERE l.`ID` = 5048 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Trouver Jeremiah Payson à Fossoyeuse et découvrir s’il est en fait Jeremiah Gangrepierre. Si c’est le cas, il appréciera peut-être le colis que Janice Gangrepierre lui a préparé.' WHERE l.`ID` = 5049 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le blues de Jeremiah' WHERE l.`ID` = 5049 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Au vu des preuves que j\'ai pu rassembler, la personne que vous cherchez, à savoir le bénéficiaire du terrain, est Jeremiah Payson, le Vendeur de cafards de Fossoyeuse.$B$BJ\'ai toujours pensé qu\'il fallait avoir une vocation pour vendre... des cafards. Nul doute que votre quête est des plus épiques, $gpuissant:puissante:c; $c. Je vais vous laisser à vos prouesses de sauveur du monde. Permettez-moi cependant, de jouer un rôle dans votre magnus opus en vous disant qu\'il est situé près de la rive, certainement en train de farfouiller sous les trottoirs.' WHERE l.`ID` = 5049 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez un Joyau de sang à Mutiledent, au Camp Taurajo, dans les Tarides.$B$BRécupérez plus de Joyaux de sang si vous souhaitez qu’il vous gratifie de la puissance d’Agamaggan.' WHERE l.`ID` = 5052 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Joyaux de sang d\'Agammagan' WHERE l.`ID` = 5052 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'À l’instar des ronces, le sang a modifié <grogne> certains aspects de la terre : les pierres rouge sang se sont mélangées à d\'autres minéraux. Les Dos-hirsutes déterrent ces pierres pointues et les portent comme des totems <grogne> représentant la force au combat et comme symbole de leurs pouvoirs. <grogne>$B$BJe connais les secrets de cette magie.$B$BRapportez à Mutiledent l\'une de ces pointes rouge sang et montrez ainsi que vous avez compris. Rapportez-en plusieurs et il vous offrira la magie des hurans, la magie d\'Agammagan ! <grogne>' WHERE l.`ID` = 5052 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Quête de test pour voir si le courrier est envoyé à votre boîte aux lettres électronique. Cliquer sur Terminer, puis consulter sa boîte aux lettres.$B$BBonne journée.' WHERE l.`ID` = 5053 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '<INUTILISÉ>' WHERE l.`ID` = 5053 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'À la fin de la quête vous recevrez un message dans votre messagerie. Faites en sorte d\'arriver au bout.' WHERE l.`ID` = 5053 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Orage Sabot-d\'ombre, à Long-Guet au Berceau-de-l\'Hiver, veut que vous triomphiez de Shy-Rotam.' WHERE l.`ID` = 5056 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Au nord du Berceau-de-l\'Hiver, de grands félins se rassemblent à un endroit appelé le roc des Sabres-de-Givre. Leur chef est connu sous le nom de Shy-Rotam. Vaincre la matriarche des sabres-de-givre vous apporterait le respect des autres membres de votre race, $r.$B$BRetournez dans les rudes terres sauvages et prenez de la viande sacrée sur les sabres-de-givre. Trouvez la pierre de Shy-Rotam et placez la viande dessus. En faisant cela, vous invoquez Shy-Rotam.$B$BPréparez-vous à affronter sa colère, et tuez-la.' WHERE l.`ID` = 5056 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez le Marqueur d\'Orage Sabot-d\'ombre à Melor Sabot-de-Pierre aux Pitons-du-Tonnerre.' WHERE l.`ID` = 5057 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Essais passés' WHERE l.`ID` = 5057 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Avant que vous ne me parliez, $n, j\'avais eu vent de vos prouesses…que vous aviez un désir inextinguible de faire vos preuves, que vous étiez admirable, et je sais maintenant que ces choses sont vraies, $c.$B$BCeux qui excellent comme vous valent d\'être reconnus. Apportez ce bon à l\'un de mes amis aux Pitons-du-Tonnerre nommé Melor Sabot-de-pierre. Je suis sûr qu\'il se souviendra de vous, et de ce que vous avez accompli il y a si longtemps. Parlez-lui de vos récentes victoires et n\'oubliez jamais ce que vous avez accompli aujourd\'hui.' WHERE l.`ID` = 5057 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Journal de Mme Dalson' WHERE l.`ID` = 5058 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Enfermé' WHERE l.`ID` = 5060 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir le Cabinet verrouillé dans les Maleterres de l\'Ouest.' WHERE l.`ID` = 5060 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez la Troisième et la Quatrième tablette Mosh\'aru au Prospecteur Botte-de-fer, à Tanaris.' WHERE l.`ID` = 5065 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Les tablettes perdues de Mosh\'aru' WHERE l.`ID` = 5065 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Le troll avec qui vous venez de parler vous a menti. Les deux tablettes que vous lui avez rapportées contiendraient l\'essence d\'Hakkar, une légende qui a plus d\'un tenant. J\'ai fait beaucoup de recherches et j\'ai découvert qu\'il y a six tablettes de Mosh\'aru et pas seulement deux ! Six !$B$BEt j\'ai peur que les secrets que contiennent les autres ne soient pas réjouissants.$B$BTrouvez les troisième et quatrième tablettes de Mosh\'aru. Elles sont dans les Maleterres de l\'Est, entre les mains des trolls écorchemousses. Trouvez-les et rapportez-les-moi.' WHERE l.`ID` = 5065 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Pour fabriquer la Cuirasse carnassière, il faut rapporter les éléments suivants à Malyfous Sombremartel : 1 Peau de la Bête en parfait état ; 10 Coutures d\'Abomination effilochées ; 5 Barres d\'arcanite ; 5 Peaux des ombres.$B$BIl faudra également payer 50 pièces d’or pour le travail de fabrication.' WHERE l.`ID` = 5068 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La cuirasse carnassière' WHERE l.`ID` = 5068 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Il paraît qu\'un seul exemplaire de la cuirasse carnassière a été créé et qu\'elle fut confectionnée pour le légendaire assassin Garona. Il est peu probable qu\'on en voit jamais une autre en ce monde.$B$BMais peu importe ! Nos maîtres fabricants peuvent reproduire l\'objet s\'ils disposent des composants requis :$B$B*La peau de la Bête en parfait état.$B$B*Couture d\'Abomination effilochée.$B$B*Barres d\'arcanite.$B$B*Peau des ombres.$B$B*Admirez !' WHERE l.`ID` = 5068 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Récolter 3 Gouttelettes d\'Horreur toxique pour Donova Antreneige au Berceau-de-l\'Hiver.' WHERE l.`ID` = 5086 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]Horreurs toxiques' WHERE l.`ID` = 5086 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'J\'ai étudié l\'échantillon que vous avez ramené, et je n\'en suis pas sûre mais je pense qu\'il y a des traces d\'éléments toxiques. Cependant, la seule façon d\'en être certain est d\'avoir des éléments de comparaison.$B$BJ\'ai l\'impression que les furbolgs Mort-bois sont en train de rassembler ces éléments à partir d\'autres créatures corrompues à Gangrebois. En particulier, je pense aux élémentaires vivant dans le bois d\'Arbrefer, appelés horreurs toxiques.$B$BPrélevez quelques échantillons pour moi, mais attention à vous, c\'est très dangereux !' WHERE l.`ID` = 5086 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Trouver les Messagers tombe-hiver et les empêcher de livrer leur cargaison au Village des Tombe-hiver.' WHERE l.`ID` = 5087 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]Les messagers des Tombe-hiver' WHERE l.`ID` = 5087 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Très intéressant, $n…$B$BLorsque cette substance toxique est mélangée à l\'eau des sources chaudes, elle perd sa toxicité, mais reste dangereuse temporairement pour ceux qui l\'ingèrent. Voilà donc pourquoi les Tombe-hiver protègent les sources chaudes aussi ardemment : ils en ont besoin pour purifier leur eau-de-feu.$B$BNous devons arrêter ça. Coupez le contact entre les Tombe-hiver et les Mort-bois. Un groupe de messagers fait le chemin entre leur village et Gangrebois. Trouvez-les et éliminez-les en vous appropriant ce qu\'ils transportaient.' WHERE l.`ID` = 5087 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Partez à la recherche du Grand exécuteur Derrington. Son camp de base se trouve à la Barricade, à l’est des Clairières de Tirisfal et de Fossoyeuse.' WHERE l.`ID` = 5094 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Un appel aux armes : les Maleterres' WHERE l.`ID` = 5094 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Héros du royaume, écoutez-moi ! La Horde vous somme d\'agir vite !$B$BLa mobilisation générale de tous les individus valides a été lancée pour prendre les armes contre le Fléau ! Des rumeurs annoncent de nouvelles menaces venant des ruines des royaumes de l\'Est. L\'ennemi serait à l\'est de Fossoyeuse, dans les marches septentrionales de la région aujourd\'hui appelée les Maleterres !$B$BHéros du royaume, présentez-vous au grand exécuteur Derrington, qui a installé son camp de base à la Barricade, à l\'est des clairières de Tirisfal !' WHERE l.`ID` = 5094 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La rétribution d\'Aurius' WHERE l.`ID` = 5125 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Rapporter le Journal mal écrit à Kelek Gardeciel dans le sud de Gangrebois.' WHERE l.`ID` = 5128 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]Paroles du Grand Chef' WHERE l.`ID` = 5128 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Les Tombe-hiver ne représentent plus le moindre danger pour moi, mais si vous désirez toujours découvrir ce qui a poussé les furbolgs à créer et à utiliser cette étrange eau-de-feu, je pense que vous devriez rechercher Kelek Gardeciel.$B$BIl fait partie d\'un groupe connu sous le nom du Cercle d\'émeraude. Il s\'agit de druides dévoués à leur travail dans Gangrebois et guérissant la terre de la corruption.$B$BKelek a beaucoup d\'expérience avec les furbolgs de Gangrebois, et il se peut qu\'il puisse vous en apprendre davantage à propos du journal.$B$BJe vous remercie encore, $n.' WHERE l.`ID` = 5128 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter 2 Cœurs de feu, 2 Globes d’eau, 2 Noyaux de terre, et 2 Souffles de vent à Sarah Tanner dans la Gorge des Vents brûlants.$B$BL’accomplissement de cette quête donne accès aux arts du Travail du cuir élémentaire.$B$BL’accomplissement de cette quête vous empêchera d’apprendre le Travail du cuir de dragon et le Travail du cuir tribal ; il faut être sûr du chemin que l’on veut suivre avant de faire ce choix.' WHERE l.`ID` = 5144 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Travail du cuir élémentaire' WHERE l.`ID` = 5144 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Le travail du cuir élémentaire est mon domaine, et si vous voulez ouvrir votre esprit aux plus grands pouvoirs de l\'art, je partagerai avec vous tout ce qu\'il y a à savoir.$B$BSachez ceci, $c : en prenant cette voie vous vous engagez à ne jamais apprendre le travail des écailles de dragon ou le travail du cuir tribal. Vous ne pouvez atteindre l\'excellence que dans un seul de ces trois domaines. De plus, j\'aurai besoin de la preuve que vous êtes en relation avec les éléments de la nature. Pour ce faire, apportez-moi les essences les plus pures de feu, d\'eau, de terre et de vent.' WHERE l.`ID` = 5144 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter 2 Cœurs de feu, 2 Globes d\'eau, 2 Noyaux de terre, et 2 Souffles de vent à Brumn Sabot-d\'hiver dans les montagnes d’Arathi.$B$BL’accomplissement de cette quête donne accès aux arts du travail du cuir élémentaire.$B$BL’accomplissement de cette quête vous empêchera d’apprendre le travail du cuir de dragon et le travail du cuir tribal ; il faut être sûr du chemin que l’on veut suivre avant de faire ce choix.' WHERE l.`ID` = 5146 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Travail du cuir élémentaire' WHERE l.`ID` = 5146 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Le travail du cuir élémentaire est mon domaine, et si vous voulez ouvrir votre esprit aux plus grands pouvoirs de l\'art, je partagerai avec vous tout ce qu\'il y a à savoir.$B$BSachez ceci, $c : en prenant cette voie vous vous engagez à ne jamais apprendre le travail des écailles de dragon ou le travail du cuir tribal. Vous ne pouvez atteindre l\'excellence que dans un seul de ces trois domaines. De plus, j\'aurai besoin de la preuve que vous êtes en relation avec les éléments de la nature. Pour ce faire, apportez-moi les essences les plus pures de feu, d\'eau, de terre et de vent.' WHERE l.`ID` = 5146 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Trouver la poupée de Pamela.' WHERE l.`ID` = 5149 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La poupée de Pamela' WHERE l.`ID` = 5149 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Ma tante Marlene m\'a dit de rester ici dans notre maison car mon père devait partir pour se battre. Mon père est l\'homme le plus courageux du monde !$B$BMais je suis là depuis longtemps, et il n\'est pas venu me chercher. Parfois des gens méchants viennent et chuchotent et je veux que mon père les chasse, mais il n\'est pas là !$B$BEt parfois quand il fait sombre je veux jouer avec ma poupée mais je ne peux pas parce que je l\'ai laissée en ville.$B$BVous voulez bien chercher ma poupée ?' WHERE l.`ID` = 5149 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez les Annales de Comté-de-Darrow à Chromie, à Andorhal.' WHERE l.`ID` = 5154 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Les annales de Comté-de-Darrow' WHERE l.`ID` = 5154 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Pour sauver Joseph Senterouge, nous devons d\'abord découvrir son passé. Nous pouvons l\'apprendre des annales de Comté-de-Darrow, un livre se trouvant à la mairie d\'Andorhal.$B$BApportez-moi ce livre. Nous pourrons alors découvrir le destin de Joseph, et avec un peu de chance... nous pourrons le changer !' WHERE l.`ID` = 5154 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter l’Eau de Puits de lune purifiée à Greta Sabot-de-mousse dans Gangrebois.' WHERE l.`ID` = 5159 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]L\'eau purifiée retourne à Gangrebois' WHERE l.`ID` = 5159 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Remerciez les esprits, $n. Ce sont eux qui vous ont apporté de l\'aide, pas moi.$B$BJe vous remets cette eau purifiée. Faites mes amitiés à Greta. Elle est sur la piste de quelque chose de plus important que nos petites personnes… et je pense qu\'elle arrivera bientôt à ses fins.$B$BLe Conseil des ombres n\'est pas une force que l\'on peut traiter à la légère, $n. Souvenez-vous-en.$B$BPartez maintenant. Prenez l\'eau et retournez voir Greta.' WHERE l.`ID` = 5159 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Si vous souhaitez continuer, parlez à Haleh.' WHERE l.`ID` = 5161 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La colère du vol bleu' WHERE l.`ID` = 5161 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Nous avons eu connaissance des plans de l\'engeance maudite de l\'Aile de mort, et nous ne pouvons pas les laisser faire.$B$BÀ cause de la protection que le mont Rochenoire offre à Nefarian, il est devenu très difficile pour nous d\'intervenir.$B$BCependant, nous pouvons vous donner des pouvoirs, si vous le désirez.$B$BLe chemin qui s\'ouvre devant vous est périlleux. Acceptez-vous notre aide ? Réfléchissez bien et revenez me voir quand vous aurez pris une décision.' WHERE l.`ID` = 5161 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Lire le Guide de l\'Indocile.' WHERE l.`ID` = 5164 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Guide de l\'Indocile' WHERE l.`ID` = 5164 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Haleh n\'aurait pas pu choisir un meilleur instrument de justice. Instruisez-vous en lisant le Guide de l\'Indocile et que votre esprit s\'illumine.$B$BPersistez...Faites ce qui vous est demandé...Si vous survivez…$gun héros:une héroïne; vous deviendrez.' WHERE l.`ID` = 5164 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Pour forger la Cuirasse du vol chromatique, il faut apporter les éléments suivants à Jeziba le « Sculpteur » :$B$B1 Carapace chromatique.$B$B10 Ecailles chromatiques brillantes.$B$B10 doses de Sang des héros.$B$B10 Coutures d\'Abomination effilochées.' WHERE l.`ID` = 5166 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La cuirasse du vol chromatique' WHERE l.`ID` = 5166 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'La fabrication d\'une puissante cuirasse qui formerait une protection contre les attaques incessantes des dragons chromatiques est une idée assez drôle.$B$BLes écailles des créatures que nous combattons doivent être cousues sur une carapace de drake ou de dragon chromatique en parfait état. Leur existence n\'est pas reconnue à ce jour et nous espérons qu\'elle ne le sera jamais.$B$BPour finir, peut-être le composant le plus improbable : du sang des héros.$B$BEnfin, le Sculpteur doit forger l\'objet.' WHERE l.`ID` = 5166 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Chercher dans Jaedenar à quoi sert la Clé rouge sang.' WHERE l.`ID` = 5202 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]Une étrange clé rouge' WHERE l.`ID` = 5202 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'La petite clé rouge semble faite d\'une espèce d\'os. Elle est lourde mais semble fragile. Pourquoi un membre du Conseil des ombres posséderait-il une telle chose ? Il doit y avoir quelque chose que cette étrange clé ouvre à Jaedenar.' WHERE l.`ID` = 5202 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Revenir à Jaedenar et tuer la succube Rakaiah avant de trouver le Cadavre de Trey Sancteforge.' WHERE l.`ID` = 5204 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]Le châtiment de la Lumière' WHERE l.`ID` = 5204 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Elle veut faire croire qu\'elle va bien. Elle aimerait que je la crois suffisamment forte pour faire face toute seule, mais je ne suis pas aveugle. La mort de Trey et la façon dont il a été torturé vont la hanter longtemps. Il n\'y a rien que l\'on peut faire pour soulager sa peine. Mais nous pouvons lui apporter un peu de paix !$B$B$n, retournez au Fort des ombres, tuez le tortionnaire de Trey et retrouvez ses restes. Pourquoi ne pas mettre fin à cela pendant qu\'Arko\'narin pleure en silence ?' WHERE l.`ID` = 5204 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez les Annales complètes de Comté-de-Darrow à Carlin Senterouge dans les Maleterres de l’Est.' WHERE l.`ID` = 5210 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Frère Carlin' WHERE l.`ID` = 5210 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Les annales de Comté-de-Darrow, grâce à ma magie, ont gagné des pages et vont maintenant au-delà de la bataille. L\'un des passages supplémentaires parle d\'un autre Senterouge, Carlin, qui a survécu à la trahison de Joseph. Carlin est maintenant dans les Maleterres de l\'Est, dans la chapelle de l\'Espoir de Lumière.$B$BPrenez le livre et parlez-lui.' WHERE l.`ID` = 5210 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
