UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Les chaudrons du Fléau' WHERE l.`ID` = 5215 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Sur les terres de l\'ancienne Lordaeron se trouvent huit chaudrons : quatre ici à l\'ouest et quatre plus à l\'est. Ces chaudrons diffusent du poison dans l\'air, propageant la peste sur tout le territoire, servant ainsi le Fléau.$B$BLa puissance nécromantique de Kel\'Thuzad est trop grande pour que l\'on puisse complètement fermer ces chaudrons. Nous pensons qu\'il y a peut-être moyen d\'en tirer parti. La grande prêtresse MacDonnell, qui me seconde, sera votre référent pour cette mission. C\'est elle qui vous donnera les instructions dorénavant.' WHERE l.`ID` = 5215 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
