UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous fermez avec précaution le robinet sur le panneau de contrôle tout en regardant le liquide putride du chaudron couler dans la bouteille vide.$B$BVous voilà en possession du poison et $gprêt:prête; à retourner auprès de la grande prêtresse MacDonnell au camp du Noroît.' WHERE l.`ID` = 5226 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
