UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Les chaudrons du Fléau' WHERE l.`ID` = 5228 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Dans les terres de l\'ancienne Lordaeron, il y a huit chaudrons : quatre à l\'ouest et quatre plus à l\'est. Ces chaudrons vomissent leur poison dans l\'air, propageant la peste au service du Fléau.$B$BLa puissance nécromantique de Kel\'Thuzad est trop importante pour que l\'on puisse sceller ces chaudrons, mais nous pensons qu\'il y a peut-être moyen d\'en tirer parti. La prêtresse des ombres Vandis, qui me seconde, sera votre référent pour cette mission. C\'est elle qui vous donnera les instructions dorénavant.' WHERE l.`ID` = 5228 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Se rendre au Champ de Gangrepierre, dans les Maleterres de l’Ouest, pour trouver et vaincre le Seigneur du Chaudron qui s’y trouve. Il aura peut-être une clé qui permet d’accéder au chaudron. Il faut se munir de la Bouteille du Champ de Gangrepierre vide pour pouvoir prélever un échantillon des poisons qui sont dans le chaudron.' WHERE l.`ID` = 5229 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Cible : le Champ de Gangrepierre' WHERE l.`ID` = 5229 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Des quatre chaudrons situés dans les Maleterres de l\'Ouest, celui du Champ de Gangrepierre est peut-être le plus facile d\'accès. Le Fléau a des troupes moins aguerries ici, à ne pas sous-estimer cependant.$B$BAllez au Champ de Gangrepierre, à l\'est d\'ici et au nord-ouest d\'Andorhal, et attaquez le seigneur du chaudron. Nous pensons qu\'il a une clé qui donnera accès au chaudron. Une fois déverrouillé, utilisez cette bouteille pour obtenir un échantillon des poisons contenus dans le chaudron ; nous en aurons besoin pour développer un antidote.' WHERE l.`ID` = 5229 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez la Bouteille du Champ de Gangrepierre remplie à la prêtresse des ombres Vandis à la Barricade, dans les Maleterres de l’Ouest.' WHERE l.`ID` = 5230 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Retour à la Barricade' WHERE l.`ID` = 5230 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous remplissez la bouteille avec suffisamment de décoction empoisonnée pour être étudiée.$B$BUne fois le poison en bouteille, retournez auprès de la prêtresse des ombres Vandis à la Barricade et votre mission sera terminée.' WHERE l.`ID` = 5230 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
