UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous remplissez avec précaution la bouteille d\'assez d\'essence du chaudron pour que vous considériez l\'échantillon suffisant.$B$BÀ présent que vous êtes en possession du poison, il est temps de retourner voir la prêtresse des ombres Vandis à la Barricade afin d\'achever la mission.' WHERE l.`ID` = 5232 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Se rendre au Repaire putride dans les Maleterres de l’Ouest pour trouver et vaincre le Seigneur du Chaudron qui s’y trouve, et utiliser sa clé pour accéder au chaudron. Il faut se munir de la Bouteille du Repaire putride vide pour pouvoir récupérer un échantillon des poisons à l’intérieur du chaudron.' WHERE l.`ID` = 5233 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
