UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous fermez avec précaution le robinet du panneau de contrôle, en regardant l\'essence putride goutter dans la bouteille vide.$B$BÀ présent que vous avez le poison, il est temps de retourner voir la prêtresse des ombres Vandis à la Barricade afin d\'achever la mission.' WHERE l.`ID` = 5236 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Mission accomplie !' WHERE l.`ID` = 5237 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Trouver Carlin Senterouge.' WHERE l.`ID` = 5241 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Oncle Carlin' WHERE l.`ID` = 5241 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Parfois, la nuit, j\'entends mon oncle Carlin pleurer. On dirait qu\'il est loin, à l\'est.$B$BJ\'espère ne pas être la cause de ses pleurs ! $n, pourriez-vous trouver mon oncle et lui dire que je vais bien ?$B$BSi vous le voyez, dites-lui que je l\'attends, et que j\'aimerais entendre à nouveau cette histoire qu\'il racontait... celle des lapins et de la confiture de baies ! Elle est si amusante !' WHERE l.`ID` = 5241 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à Jaron Sculptepierre au village de Pluie-d\'Étoiles.' WHERE l.`ID` = 5244 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]Les ruines de Kel\'Theril' WHERE l.`ID` = 5244 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'L\'histoire qui suit Kel\'Theril est celle d\'une race maudite, liée à l\'endroit où s\'est déroulé un malheureux rituel…$B$BLe Bien-né que vous trouverez là a jadis volé un artéfact sacré, croyant qu\'il pouvait absorber sa puissance, pour la transmettre aux siens. Lors du rituel, la relique fut détruite à la suite d\'une explosion qui éparpilla les morceaux sous la glace du lac...$B$BParlez avec Jaron Sculptepierre pour en savoir plus. Il a récemment parcouru la zone et connaît le coin.' WHERE l.`ID` = 5244 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Amener le Cristal de Zin-Malor au lac Kel\'Theril au Berceau-de-l\'Hiver et trouver un esprit Bien-né qui veuille bien vous parler.' WHERE l.`ID` = 5248 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Tourmentée par le passé' WHERE l.`ID` = 5248 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '$n, je pleure à cause du passé. Comme ce cristal, les elfes, en tant que race, ont été brisés. Je ne sais pas si les morceaux seront jamais recollés mais ma peine a été allégée grâce à l\'aide que j\'ai pu vous apporter dans cette tâche.$B$BNous ne devons pas oublier le passé, $n...$B$BS\'il vous plaît, allez remettre le cristal de Zin-Malor dans le lac Kel\'Theril. Vous devez trouver un esprit Bien-né qui ait réalisé l\'erreur commise il y a si longtemps. Montrez à l\'esprit que les choses sont rentrées dans l\'ordre.' WHERE l.`ID` = 5248 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Trouver le village de Pluie-d\'Étoiles au Berceau-de-l\'Hiver et parler à Wynd Pistenuit.' WHERE l.`ID` = 5250 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Pluie-d\'Étoiles' WHERE l.`ID` = 5250 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Le Berceau-de-l\'Hiver, au nord de Gangrebois, est jonché de ruines elfes. C\'est une terre hostile, mais elle détient beaucoup de secrets et d\'endroits à explorer.$B$BMes études ici m\'accaparent et je n\'ai pas eu l\'opportunité d\'aller jusqu\'au Berceau-de-l\'Hiver. Mais il n\'y a aucune raison pour que vous ne puissiez pas y aller et étudier les ruines.$B$BLorsque vous serez là-bas, cherchez Wynd Pistenuit. Il passe la plupart de son temps au village de Pluie-d\'Étoiles et il connaît bien la région.$B$BDites-lui que vous êtes $gl\'un de mes étudiants:l\'une de mes étudiantes;.' WHERE l.`ID` = 5250 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Pour devenir un Fabricant d\'armes, il faut fabriquer les éléments suivants et les rapporter à Ferronus : 4 Épées d\'acier lunaire, 4 Haches massives en fer, 2 Haches en mithril lourd, et 2 Grandes masses noires.' WHERE l.`ID` = 5284 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La voie du Forgeron d\'armes' WHERE l.`ID` = 5284 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'En tant que $gfabricant:fabricante; d\'armes, vous verrez à maintes reprises que les héros et les aventuriers viendront vous voir pour obtenir un bon équipement. Bien que la charge de travail puisse être parfois insoutenable, les richesses que l\'on en retire font oublier le mal de dos et les poumons pris.$B$BOh oui, $n, les fabricants d\'armes sont ceux qui ont tout l\'or !$B$BSi vous souhaitez rejoindre nos rangs, vous allez devoir me montrer que vous pouvez m\'apporter quelques pièces... je veux dire me faire quelques pièces et que vous serez $gl\'homme:la femme; de la situation lorsqu\'il s\'agira de forger des armes de qualité supérieure. Au travail !' WHERE l.`ID` = 5284 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Aller jusqu’au Pic Rochenoire et abattre la Chasseresse des ombres Vosh\'gajin. Récupérer la Pierre du serpent de Vosh\'gajin et la rapporter à Kilram.' WHERE l.`ID` = 5306 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Pierre du serpent de la chasseresse des ombres' WHERE l.`ID` = 5306 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Ne laissez pas sa beauté vous duper, $c. La chasseresse des ombres Vosh\'gajin est extrêmement dangereuse et son esprit est dérangé.$B$B<Kilram désigne la cicatrice qu\'il porte au visage.>$B$BOui, c\'est elle qui m\'en a fait cadeau. Une marque d\'amour, pour employer ses termes.$B$BVous pouvez trouver Vosh\'gajin au pic Rochenoire. Tuez-la et rapportez-moi sa pierre du serpent. Accomplissez cet exploit et je vous enseignerai l\'art de la fabrication du Tranchant de l\'aube !' WHERE l.`ID` = 5306 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Trouver le Fabricant d\'épées de la Garde noire à Stratholme et le tuer. Récupérer l’Insigne de la Garde noire et retourner auprès de Seril Plaie-du-Fléau.' WHERE l.`ID` = 5307 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Si je ne m\'étends pas avec vous, j\'ai une bonne raison. Les plans pour la création de la grande lame, Corruption, ont été volés par la Garde noire : des unités squelettes d\'élite du baron Vaillefendre.$B$BOui, le baron Vaillefendre de Stratholme.$B$BLe fabricant d\'épées de la Garde noire détient à présent ces plans, et il donnerait sa... non-vie pour les protéger.$B$BTuez-le et rapportez-moi la preuve de votre exploit. Je vous enseignerai alors l\'art de la fabrication de la rapière flamboyante !' WHERE l.`ID` = 5307 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Retournez à la Scholomance avec le Sang des innocents. Trouvez le porche et placez le Sang des innocents dans le brasero. Kirtonos viendra dévorer votre âme.$B$BCombattez vaillamment, sans perdre un pouce de terrain ! Détruisez Kirtonos et retournez auprès d’Eva Sarkhoff.' WHERE l.`ID` = 5384 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Kirtonos le héraut' WHERE l.`ID` = 5384 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Et voilà, $n.$B$B<Eva montre la fiole dans le sac.>$B$BLe sang d\'innocents. Le sang le plus pur, utilisé pour apaiser le maître de Krastinov.$B$BC\'est avec ce sang que Kirtonos peut être invoqué. C\'est donc avec ce sang que Kirtonos doit être détruit.$B$BAllez sous le porche et placez le sang sur le brasero. Kirtonos viendra ; il ne peut résister. Lorsqu\'il apparaîtra, déchaînez la furie et la colère de milliers d\'innocents, morts à cause de lui.$B$BSi vous réussissez, vous gagnerez plus que notre simple gratitude.' WHERE l.`ID` = 5384 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
