UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]Les restes de Trey Sancteforge' WHERE l.`ID` = 5385 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous ramassez le sac avec précaution et vous vous apprêtez à reprendre votre chemin pour rejoindre Jessir Arquelune, à la frontière de Gangrebois et d\'Orneval. Heureusement, le paladin recevra les honneurs qui lui sont dus une fois que vous aurez confié ses restes à ses amis.' WHERE l.`ID` = 5385 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
