UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Maître veut herbes. Nous avoir grosses mains et pas bons à ramasser. Vous aider et nous pas vous faire mal. Nous avoir besoin herbe des ténèbres. Beaucoup alentours et près de route.$B$BQuand vous avoir beaucoup, apporter à maître Holland dans cimetière de Brill.' WHERE l.`ID` = 5481 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
