UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parlez à l’Alchimiste Arbington à la Pointe du Noroît, dans les Maleterres de l’Ouest.' WHERE l.`ID` = 5533 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Sur l\'île de Caer Darrow, se trouve Scholomance, un centre de nécromancie maléfique du Fléau. Notre ennemi y est installé, perpétuant des actes infâmes sur des victimes innocentes… du moins, c\'est ce que nous croyons. Une porte barre le chemin, et malgré tous nos efforts, si nous n\'avons pas la bonne clé, nous ne pourrons pas entrer.$B$BArbington l\'alchimiste connaît bien Scholomance et il sait comment obtenir une clé. Puisque vous avez fait vos preuves, je vous confie cette mission. Parlez-lui de cette affaire.' WHERE l.`ID` = 5533 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Chercher les Larves putrides et les Dévoreurs de la région. Les tuer et récupérer leur viande. Retourner voir Tirion Fordring quand 15 pièces de Chair de Ver putride auront été récupérées.' WHERE l.`ID` = 5544 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Larve putride' WHERE l.`ID` = 5544 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Mes réserves de nourriture s\'amenuisent, $r. J\'ai honte d\'avouer que je pourrais ne pas avoir assez de nourriture pour partager avec vous.$B$BPourriez-vous m\'aider ? Dans les parages, les seules créatures non affectées par les ravages de la Peste sont les Vers putrides. Bien que fade, cette viande se garde pendant des mois. J\'en aurais besoin de quelques centaines de kilos afin de refaire mes stocks pour l\'hiver approchant !' WHERE l.`ID` = 5544 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Trouver la Sentinelle Shaya et la guérir de ses blessures en utilisant Soins inférieurs (Rang 2). Lui accorder ensuite le Mot de pouvoir : Robustesse, puis retourner voir Laurna Clairematin, à Dolanaar.' WHERE l.`ID` = 5621 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Vêtements de la lune' WHERE l.`ID` = 5621 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'J\'ai besoin de votre aide, $n. Je dois rester ici pour former les autres étudiants, mais vous, vous pouvez aller porter secours à l\'une de nos Sentinelles, juste au sud de Dolanaar. Elle a été blessée en patrouillant dans la ville et a besoin de notre aide. Son nom est Shaya.$B$BQuand vous l\'aurez trouvée, guérissez ses blessures et fortifiez-la avec vos sorts. Cela la protégera un peu si elle a d\'autres ennuis. Revenez me voir lorsque vous aurez accompli votre devoir pour Élune.' WHERE l.`ID` = 5621 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à Laurna Clairematin à Teldrassil.' WHERE l.`ID` = 5622 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Au service d\'Élune' WHERE l.`ID` = 5622 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '$n, vous devrez partir pour Dolanaar lorsque vous en aurez terminé ici à Sombrevallon. Vous y trouverez Laurna Clairematin. Elle vous en apprendra davantage sur les voies d\'Élune, et c\'est avec elle que vous obtiendrez votre premier vêtement dénotant votre nature de $gprêtre:prêtresse; d\'Élune.$B$BPrenez garde, et puissiez-vous être $gprotégé:protégée; durant vos voyages.' WHERE l.`ID` = 5622 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Trouver le Montagnard Dolf et guérir ses blessures en utilisant Soins inférieurs (Rang 2). Lui accorder ensuite le Mot de pouvoir : Robustesse, puis retourner voir Maxan Anvol, à Kharanos.' WHERE l.`ID` = 5625 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Vêtements de la Lumière' WHERE l.`ID` = 5625 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Il est de coutume de tester l\'un de vos pouvoirs pour savoir si vous êtes digne de porter les robes qui symbolisent votre place dans l\'Église. Mais il y a plus urgent. Le citoyen de Kharanos qui vient d\'entrer m\'a parlé d\'un montagnard blessé à l\'extérieur de la ville, au sud.$B$BGuérissez ce Dolf, restaurez sa fortitude et je considérerai que vous avez fait vos preuves. Cela vous convient-il ?' WHERE l.`ID` = 5625 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à la prêtresse Alathea à Darnassus.' WHERE l.`ID` = 5628 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Retour à la maison' WHERE l.`ID` = 5628 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Bonjour, $n. Quel bonheur que vous me parliez pendant quelques instants. Vous êtes bien loin de chez vous et vous êtes si jeune. J\'admire les ambitieux. Ah si j\'avais eu le courage de voyager lorsque j\'étais plus jeune...$B$BIl y avait une prêtresse de votre ordre ici, il n\'y a pas longtemps. Elle a dit qu\'il était important que vous reveniez au temple de la Lune à Darnassus et que vous parliez à la prêtresse Alathea. Cela concerne votre entraînement. Je ne traînerai pas trop si j\'étais vous.' WHERE l.`ID` = 5628 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à la prêtresse Alathea à Darnassus.' WHERE l.`ID` = 5631 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Retour à la maison' WHERE l.`ID` = 5631 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Une prêtresse est récemment venue nous voir et elle vous cherchait, jeune $r. Elle a dit qu\'elle avait pour mission de vous trouver et que vous deviez retourner au temple de la Lune à Darnassus dès que possible. Une fois sur place, cherchez la prêtresse Alathea. Elle vous en dira plus.$B$BQue la Lumière soit avec vous, $n.' WHERE l.`ID` = 5631 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à la grande prêtresse Laurena à Hurlevent.' WHERE l.`ID` = 5636 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Prière du désespoir' WHERE l.`ID` = 5636 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Qu’Élune vous bénisse, $n. J’espère que votre Lumière vous protègera bien aujourd’hui.$B$BL’un de vos prêtres était là il y a peu. Il vous cherchait. Il souhaitait que vous retourniez à la cathédrale de la Lumière dès que possible pour parler à la grande prêtresse Laurena. Il semble que vous avez fait bonne impression. Je ne resterais pas ici si j’étais vous. Votre peuple a besoin de vous.' WHERE l.`ID` = 5636 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à la grande prêtresse Laurena à Hurlevent.' WHERE l.`ID` = 5638 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Prière du désespoir' WHERE l.`ID` = 5638 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Il y a peu de temps, l’un de vos prêtres était ici et vous cherchait, $r. Il m’a dit que si je vous voyais je devais vous diriger vers la cathédrale de la Lumière. Il a dit que c’était très important, mais je ne m’inquiéterais pas si j’étais vous. Son attitude était positive... comme s’il avait de bonnes nouvelles à vous annoncer. Je ne traînerais pas si j’étais vous.$B$BQu’Élune vous accompagne, brave $r.' WHERE l.`ID` = 5638 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Trouver le grunt Kor\'ja et la guérir de ses blessures en utilisant Soins inférieurs (Rang 2). Lui accorder ensuite le Mot de pouvoir : Robustesse, puis retourner voir Tai\'jin, sur Tranchecolline.' WHERE l.`ID` = 5648 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Vêtements de la spiritualité' WHERE l.`ID` = 5648 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'V\'là votre premier test, $n. Au sud de Tranchecolline, juste à l\'extérieur de la ville, un d\'nos fantassins a été blessé en s\'battant contre les troupes de Portvaillant. Elle s\'trouve pas trop bien, et faudrait qu\'un d\'nous aille l\'aider. Trouvez-la – son nom c\'est Kor\'ja – soignez ses blessures et donnez-lui la bénédiction d\'nos ancêtres.$B$BQuand vous aurez fait ça, ce s\'ra la meilleure preuve que vous pouvez commencer à suivre notre trace.' WHERE l.`ID` = 5648 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler au sombre clerc Beryl dans les Clairières de Tirisfal.' WHERE l.`ID` = 5651 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Au service des ténèbres' WHERE l.`ID` = 5651 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Les Réprouvés ont appris beaucoup de choses au fil du temps, des choses que certaines races commencent seulement à entrevoir. Et bien que nos chemins restent dans les ténèbres, vous constaterez que beaucoup de choses s\'appuient sur la lumière et sur l\'obscurité. Vos leçons vous apprendront à utiliser les deux... et avec discrétion. Mais retenez bien ce que je vais vous dire : nous sommes nés dans la corruption et nous sommes faits de chair pourrissante. L\'obscurité est notre mère.$B$BLorsque vous voudrez en savoir plus, cherchez le sombre clerc Beryl à Brill.' WHERE l.`ID` = 5651 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à la prêtresse Alathea à Darnassus.' WHERE l.`ID` = 5673 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Grâce d\'Élune' WHERE l.`ID` = 5673 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous savez que vous avez accès à n\'importe lequel de nos Maîtres, $n mais il y a des choses que nous ne pourrons pas vous enseigner et que seule votre déesse Élune est en mesure de faire. Elle donne des compétences spéciales à ses croyants et je pense d\'ailleurs qu\'il est temps pour vous de retourner au temple de la Lune pour subir un test.$B$BRendez-vous là-bas dès que possible et parlez à la prêtresse Alathea.' WHERE l.`ID` = 5673 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à la prêtresse Alathea à Darnassus.' WHERE l.`ID` = 5675 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Grâce d\'Élune' WHERE l.`ID` = 5675 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Pas de temps à perdre, $gpetit:petite;. Il est temps que vous retourniez à Darnassus. La prêtresse Alathea a envoyé un message pour que vous alliez là-bas vous entraîner. Elle pense sûrement qu\'il est temps de vous mettre à l\'épreuve, comme tous ceux qui servent la Lumière. Mettez-vous en chemin dès que possible. Dans son message, Alathea dit qu\'elle vous attend dans le temple de la Lune. Bonne chance !' WHERE l.`ID` = 5675 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter la Sacoche du Totem-sinistre à Rahauro aux Pitons-du-Tonnerre.' WHERE l.`ID` = 5724 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Rapporter la sacoche perdue' WHERE l.`ID` = 5724 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous trouvez une sacoche sous le corps du tauren. Il la tient encore serrée entre ses bras comme s’il essayait de la protéger pendant l’attaque des troggs.$B$BVous libérez la sacoche qu’il étreint, vous la placez dans votre propre équipement et vous vous préparez à quitter les tunnels et à retourner auprès de Rahauro aux Pitons-du-Tonnerre.' WHERE l.`ID` = 5724 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à Neeru Lamefeu à Orgrimmar.' WHERE l.`ID` = 5729 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Ennemis cachés' WHERE l.`ID` = 5729 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Je pense que la prochaine étape devrait être de vous placer près de Neeru. S\'il est aussi agité que le suggèrent les rapports, nous pourrions accomplir deux choses. D\'abord, vous pourriez en apprendre davantage sur le Conseil ou au moins sur la Lame-Ardente. Ensuite, il se peut qu\'il vous fasse suffisamment confiance pour qu\'il vous demande de lui venir en aide. Il pourrait vous considérer comme quelqu\'un capable d\'occuper une place vacante à présent que sa direction connaît un grand bouleversement.$B$BRetournez à la Faille et parlez-lui à nouveau, mais dissimulez bien votre jeu.' WHERE l.`ID` = 5729 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`AreaDescription` = 'Le conte de Tirion' WHERE l.`ID` = 5742 AND l.`locale` = 'frFR' AND (l.`AreaDescription` IS NULL OR l.`AreaDescription` = '' OR BINARY l.`AreaDescription` = BINARY q.`AreaDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Écouter ce que Tirion Fordring a à dire.' WHERE l.`ID` = 5742 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Rédemption' WHERE l.`ID` = 5742 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir Tirion Fordring à la Thondroril, dans les Maleterres de l\'Est.' WHERE l.`ID` = 5742 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous avez travaillé dur, mon $gami:amie;. Reposez vos os fatigués et permettez-moi de me présenter correctement.' WHERE l.`ID` = 5742 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Vaincre Araj l\'Invocateur et apporter le Scarabée d\'Araj à l’alchimiste Arbington à la pointe du Noroît, dans les Maleterres de l’Ouest.' WHERE l.`ID` = 5803 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le Scarabée d\'Araj' WHERE l.`ID` = 5803 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Araj l’Invocateur règne sur Andorhal depuis le cœur de la cité en ruine. Nous savons qu’il était l’ancien chef de Scholomance avant de s\'approprier la cité. Pour finir la clé, nous avons besoin de sa chevalière – appelée Scarabée – pour en faire la tête de la clé.$B$BIntroduisez-vous au cœur d\'Andorhal, et brisez l’emprise d’Araj sur la cité, maintenant qu\'il a été amené à se découvrir. Quand vous l\'aurez détruit, emparez-vous de son scarabée contenu dans le petit sac qu’il aura laissé tomber !$B$BLa clé de la Scholomance vous attend, $n !' WHERE l.`ID` = 5803 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Vaincre Araj l\'Invocateur et apporter le Scarabée d\'Araj à l’apothicaire Dithers à la Barricade, dans les Maleterres de l’Ouest.' WHERE l.`ID` = 5804 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le Scarabée d\'Araj' WHERE l.`ID` = 5804 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
