UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Se rendre à Valnord, dans la région nord-est des Maleterres de l’Est, et récupérer le Symbole de l’honneur perdu. Revenir auprès de Tirion Fordring quand la tâche est accomplie.' WHERE l.`ID` = 5845 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'De l\'honneur perdu' WHERE l.`ID` = 5845 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'L’ordre de la Main d\'argent fut complètement décimé quand Uther fut tué.$B$BLe garçon tint bon aussi longtemps qu’il put. Repoussé jusqu’au hameau de Valnord ravagé par la guerre, il y livra son ultime combat.$B$BRestait-il encore des survivants de l’ordre, pensa-t-il, et cela avait-il encore de l\'importance ?$B$BC\'est en pensant cela que Taelan jeta à terre l’étendard de l’ordre et renia tout ce qu’il avait jamais connu. Son honneur abandonné sur le sol gorgé de sang de Valnord.$B$BIl faut vous rendre à Valnord pour récupérer ce symbole d’honneur perdu.' WHERE l.`ID` = 5845 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Voyager jusqu’à l’île de Caer Darrow, dans la région centre-sud des Maleterres, et chercher un indice de l’emplacement du tableau.' WHERE l.`ID` = 5846 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'amour et la famille' WHERE l.`ID` = 5846 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Quand Taelan était enfant, nous allions souvent à Caer Darrow pour une promenade en famille. Au cours de notre dernière visite, une artiste nommée Renfray peignit un portrait de nous sur la plage. C’est mon souvenir le plus cher de Taelan et Karandra. Car c’est à ce moment, avec ma femme et mon fils dans mes bras, que je sentis un lien d’amour et familial que je n’ai jamais plus connu depuis.$B$BSi ce tableau existe encore, il faut que vous le trouviez.$B$BRendez-vous jusqu’à l’île délabrée de Caer Darrow et voyez si le tableau ou l’artiste s’y trouvent encore.' WHERE l.`ID` = 5846 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Se rendre au tombeau d’Uther, au sud des Maleterres. Montrer à Myranda la Mégère le Don de Tirion.' WHERE l.`ID` = 5861 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Trouver Myranda' WHERE l.`ID` = 5861 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '$n, vous avez accompli tout ce que je vous ai demandé de faire jusqu\'à présent. Il n\'y a plus qu\'une dernière étape à franchir dans votre quête de rédemption.$B$BVous devez amener les éléments que vous avez récoltés à Taelan. Malheureusement, Taelan et ses croisés écarlates vous attaqueront en vous voyant.$B$BIl n\'y a qu\'une façon de remettre mon message, sous couvert d\'une supercherie.$B$BAu sud, vous trouverez le tombeau d\'Uther. Une vieille amie en qui j\'ai toute confiance, Myranda, vit là-bas. Allez la trouver, montrez-lui vos objets et elle vous aidera.' WHERE l.`ID` = 5861 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
