UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Utiliser le sort « Téléportation : Reflet-de-Lune » pour aller à Reflet-de-Lune. Une fois sur place, parler à Dendrite Brasétoile, au village de Havrenuit.' WHERE l.`ID` = 5922 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
