UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Le temps est venu pour nous de nous séparer. La mise en pratique des leçons que vous avez apprises vous ramènera vers la personne qui vous a demandé de venir me voir. Mathrengyl Pasdelours vit en complète harmonie avec l’équilibre naturel, bien que résidant à proximité de l’endroit où cet équilibre a vacillé. Écoutez attentivement ses instructions et vous aurez achevé vos premières leçons en tant que protecteur de l’équilibre naturel.$B$BPartez maintenant. Nous nous reverrons bientôt.' WHERE l.`ID` = 5931 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter l\'Ensemble de reliques à Chromie, à Andorhal.' WHERE l.`ID` = 5941 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Retourner voir Chromie' WHERE l.`ID` = 5941 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous avez collecté maintes reliques de la bataille de Comté-de-Darrow. À chaque fois que vous en avez rapporté davantage, mon cœur se languissait un peu plus de mon village, et je brûlais de le protéger de son destin.$B$BJe sais que cela ne se peut, mais Chromie, cette étrange gnome à Andorhal, m’a dit que c\'était possible. Elle dit que vous avez le pouvoir de sauver Comté-de-Darrow !$B$BElle m’a demandé de rassembler les reliques et de vous les donner pour que vous les lui apportiez. Elle a dit qu’elle vous attendait dans l’auberge en ruine d’Andorhal.' WHERE l.`ID` = 5941 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Aller à Pestebois, au nord-ouest de la chapelle de l\'Espoir de Lumière. Détruire 8 Bâtiments du Fléau en utilisant le Mélange spécial de Smokey sur les Marques de détonation que portent les bâtiments destinés à être détruits. Smokey a fait marquer les ziggourats et les abattoirs.$B$BUne fois la bombe placée, quitter le bâtiment et contempler le résultat de votre opération.$B$BGarder en tête que le Mélange spécial de Smokey est très... instable.' WHERE l.`ID` = 6041 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Quand Smokey chante, je deviens violent' WHERE l.`ID` = 6041 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Pendant que vous collectiez les provisions, quelques-uns de mes agents ont pu marquer les bâtiments du Fléau que nous devons démolir.$B$BVoici le plan : je m\'en vais vous donner dix bâtons de mon mélange spécial. Vous les porterez à Pestebois et les placerez dans les bâtiments du Fléau qui ont été marqués et sont destinés à sauter.$B$B<Smokey claque des doigts.>$B$BBing ! C\'est pas plus compliqué que ça.' WHERE l.`ID` = 6041 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
