UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Salut, jeune adepte de la chasse. Vous me semblez assez habile pour apprivoiser une bête et en faire votre compagnon.$B$BVous devez aller voir Thotar à Tranchecolline. Il vous guidera pour que vous trouviez votre animal de compagnie.' WHERE l.`ID` = 6068 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Adressez-vous à Ormak Trait-sinistre à Orgrimmar.' WHERE l.`ID` = 6081 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Entraîner la bête' WHERE l.`ID` = 6081 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous avez maintenant les compétences pour dompter un familier, mais vous devez aussi acquérir celles qui sont nécessaires à son apprivoisement.$B$BRendez-vous à Orgrimmar pour parler à l’un de nos chasseurs les plus respectés, Ormak Trait-sinistre. Il vous apprendra les techniques d’apprivoisement de votre nouveau familier. Vous le trouverez dans la vallée de l\'Honneur.$B$BBonne chance, $n.' WHERE l.`ID` = 6081 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`AreaDescription` = 'Dompter un scorpide blindé' WHERE l.`ID` = 6082 AND l.`locale` = 'frFR' AND (l.`AreaDescription` IS NULL OR l.`AreaDescription` = '' OR BINARY l.`AreaDescription` = BINARY q.`AreaDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Domptez un Scorpide blindé à l\'aide du Bâtonnet de domptage. Entraînez-vous puis retournez voir Thotar à Tranchecolline.' WHERE l.`ID` = 6082 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Dompter la bête' WHERE l.`ID` = 6082 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'La dernière créature qu’il vous faut dompter est l’une de celles que vous devriez vous efforcer d’imiter : le scorpide blindé. Il frappe rapidement et avec une grande assurance ; le contrôle d’une force telle que celle-ci fait partie de votre destin de chasseur.$B$BQuand vous reviendrez, je vous offrirai les compétences qui vous permettront de dompter l’animal de votre choix. Cette créature sera à vos côtés et sous votre commandement. Elle gagnera de l’expérience de concert avec vous. Je vous montrerai également comment l\'appeler et la renvoyer à volonté.' WHERE l.`ID` = 6082 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`AreaDescription` = 'Dompter un léopard des neiges' WHERE l.`ID` = 6084 AND l.`locale` = 'frFR' AND (l.`AreaDescription` IS NULL OR l.`AreaDescription` = '' OR BINARY l.`AreaDescription` = BINARY q.`AreaDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Domptez un Léopard des neiges à l\'aide du Bâtonnet de domptage. Entraînez-vous puis retournez voir Grif Cœur-sauvage à Kharanos.' WHERE l.`ID` = 6084 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Dompter la bête' WHERE l.`ID` = 6084 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Ces sangliers des rochers sont assez massifs ; peut-être préféreriez-vous quelque chose de plus raffiné ? Bon d’accord, je sais maintenant… Au sud et à l’ouest, vous verrez de grands félins blancs qu’on appelle des léopards des neiges. À l’instar d’une arme ouvragée, ils sont élégants et mortels. Vous les trouverez bien plus agiles que le sanglier que vous avez dompté.$B$BPrenez ce bâtonnet de domptage, et allez voir si vous ne préférez pas les félins.' WHERE l.`ID` = 6084 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Adressez-vous à Belia Tonnegranit à Forgefer.' WHERE l.`ID` = 6086 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
