UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`AreaDescription` = 'Dompter un traqueur des prairies' WHERE l.`ID` = 6087 AND l.`locale` = 'frFR' AND (l.`AreaDescription` IS NULL OR l.`AreaDescription` = '' OR BINARY l.`AreaDescription` = BINARY q.`AreaDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Utiliser le Bâtonnet de domptage pour dompter un Traqueur des prairies. S\'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Yaw Crin-Tranchant, à Sabot-de-Sang.' WHERE l.`ID` = 6087 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Dompter la bête' WHERE l.`ID` = 6087 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous avez un esprit fougueux, impatient de se confronter à la prochaine épreuve.$B$BVotre nouvelle mission est de dompter un loup connu sous le nom de Traqueur des prairies. Cette créature est rapide et ne craint personne ; si vous la prenez comme familier, vous devrez prouver que vous avez les mêmes qualités.$B$BPendant la bataille, vous apprendrez à former une équipe de combat avec votre familier. Au terme de votre entraînement, vous aurez appris à ne faire qu\'un avec lui ; un seul corps, utilisant les mêmes muscles, les mêmes idées.$B$BVoici un Bâtonnet de domptage, $n. Domptez un Traqueur des prairies et entraînez-vous à lutter en synergie avec lui.' WHERE l.`ID` = 6087 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`AreaDescription` = 'Dompter un rapace' WHERE l.`ID` = 6088 AND l.`locale` = 'frFR' AND (l.`AreaDescription` IS NULL OR l.`AreaDescription` = '' OR BINARY l.`AreaDescription` = BINARY q.`AreaDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Utiliser le Bâtonnet de domptage pour dompter un Rapace. S’entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Yaw Crin-Tranchant, à Sabot-de-Sang.' WHERE l.`ID` = 6088 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Dompter la bête' WHERE l.`ID` = 6088 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Votre tâche finale sera d\'apprivoiser une créature céleste. Le rapace est un adversaire difficile, mais comme allié, vous bénéficierez de ses attaques éclair et de sa présence menaçante.$B$BPar la volonté de mère Nature, quand vous reviendrez, je vous accorderai les compétences qui vous permettront d\'apprivoiser un animal de votre choix pour en faire votre compagnon. Cette créature fera face aux mêmes défis que vous et acquerra de l\'expérience à vos côtés. Je vous montrerai aussi comment l\'appeler et la renvoyer à votre guise.' WHERE l.`ID` = 6088 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`AreaDescription` = 'Dompter un rôdeur sabre-de-nuit' WHERE l.`ID` = 6101 AND l.`locale` = 'frFR' AND (l.`AreaDescription` IS NULL OR l.`AreaDescription` = '' OR BINARY l.`AreaDescription` = BINARY q.`AreaDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Utiliser le Bâtonnet de domptage pour dompter un Rôdeur sabre-de-nuit. S’entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Dazalar, à Dolanaar.' WHERE l.`ID` = 6101 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Dompter la bête' WHERE l.`ID` = 6101 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Il faut tenir compte des variations de la nature, $n. La seule chose qui est prévisible chez elle, c\'est qu\'elle n\'est jamais la même, elle change toujours.$B$BLes tâches que je vous donnerai à accomplir vous aideront à comprendre et à apprécier les différences qu\'il y a entre les créatures que vous pouvez choisir comme compagnes.$B$BPrenez ce bâtonnet de domptage et utilisez-le pour apprivoiser un rôdeur sabre-de-nuit, que vous trouverez dans le sud. Exercez-vous à chasser. Alors vous commencerez à comprendre les ressemblances et les différences qui forgent la nature.' WHERE l.`ID` = 6101 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`AreaDescription` = 'Dompter un hurleur Strigid' WHERE l.`ID` = 6102 AND l.`locale` = 'frFR' AND (l.`AreaDescription` IS NULL OR l.`AreaDescription` = '' OR BINARY l.`AreaDescription` = BINARY q.`AreaDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Utiliser le Bâtonnet de domptage pour dompter un Hurleur Strigid. S’entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Dazalar, à Dolanaar.' WHERE l.`ID` = 6102 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Dompter la bête' WHERE l.`ID` = 6102 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous avez dompté deux créatures qui vivent dans le pays, et maintenant vous devez en dompter une qui soit capable de filer dans les airs. Utilisez le bâtonnet de domptage pour dompter un hurleur Strigid que vous pourrez trouver plus à l’ouest. Entraînez-vous au combat avec ce grand hibou à vos côtés.$B$BQuand vous reviendrez, je vous laisserai dompter la créature de votre choix qui deviendra votre familier. Ce compagnon combattra à vos côtés, quels que soient les dangers et les adversaires que vous affronterez, et engrangera de l’expérience en même temps que vous. Je vous apprendrai comment l\'appeler et le renvoyer à volonté.' WHERE l.`ID` = 6102 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à Jocaste, à l\'Enclave cénarienne de Darnassus.' WHERE l.`ID` = 6103 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Entraîner la bête' WHERE l.`ID` = 6103 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous avez maintenant les compétences pour dompter un familier, mais vous devez également acquérir celles qui vous permettront de l\'apprivoiser.$B$BAllez à Darnassus. Quand vous serez là-bas, parlez à l\'un de nos meilleurs chasseurs, Jocaste. Elle vous apprendra à apprivoiser votre nouveau familier. Ne tardez pas.$B$BJocaste peut avoir l\'air sévère, mais elle est toujours contente de voir un nouveau chasseur se perfectionner. Traitez-la avec respect, elle vous le rendra. Bonne chance, $n.' WHERE l.`ID` = 6103 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Retourner voir Mathrengyl Pasdelours, dans l’Enclave cénarienne, à Darnassus.' WHERE l.`ID` = 6125 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Pouvoir contre le poison' WHERE l.`ID` = 6125 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous avez appris ce que signifie guérir un empoisonnement sans en appeler à des moyens spirituels. Rappelez-vous ce que les autres doivent endurer en combattant les afflictions de l\'empoisonnement, quand vous aurez définitivement acquis votre pouvoir de guérison du poison.$B$BVous devriez retourner voir Mathrengyl Pasdelours, à Darnassus, $n. Il a, à n’en pas douter, un sort de première importance à vous apprendre, maintenant que vous avez appréhendé les leçons qui vous ont été données.$B$BAdieu, jeune druide. Nous nous reparlerons un jour.' WHERE l.`ID` = 6125 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Utiliser le Remède pour animaux sur 10 Gazelles malades qui se trouvent dans la partie nord des Tarides ; ceci les soignera. Les Gazelles malades ont été vues au nord de la route orientée est-ouest qui traverse la Croisée.' WHERE l.`ID` = 6129 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Soigner la maladie' WHERE l.`ID` = 6129 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'J’ai pu faire dix doses de ce remède, $n. Pendant que je commence à travailler avec les autorités locales pour la fabrication de doses supplémentaires, je voudrais que vous nous aidiez à prendre les choses en main. Tout autour des Tarides du Nord vivent des gazelles malades ; utilisez le remède sur elles et guérissez-les de leur affection.$B$BDendrite Brasétoile, à Reflet-de-Lune, voudra vous parler une fois que cela sera fait. Vous n’oublierez pas de remercier ceux du Cercle cénarien... et j’en profite également pour vous adresser mes plus sincères remerciements pour ce que vous avez fait !' WHERE l.`ID` = 6129 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Retourner dans les Maleterres de l’Est et traquer le Messager cramoisi, le tuer et récupérer les Ordres du Grand croisé.$B$BApporter les Ordres à Nathanos le Flétrisseur pour obtenir des instructions supplémentaires.' WHERE l.`ID` = 6145 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le messager cramoisi' WHERE l.`ID` = 6145 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'De même que le corps ne peut pas survivre sans la tête, la tête ne peut pas survivre sans le corps. Les défenses du commandement de la Croisade écarlate, à Stratholme, sont presque impénétrables. Plutôt que d\'essayer de les enfoncer, nous allons séparer le corps de la tête.$B$BMes nécrotraqueurs ont rassemblé des données sur les activités de la Croisade à l\'extérieur de Stratholme. Chaque jour, un rapport est envoyé de leur commandement central à la Main de Tyr. Ce rapport est la clé, $r ! Trouvez le Messager cramoisi et récupérez ce rapport. Rapportez-le à Nathanos.' WHERE l.`ID` = 6145 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'La Croisade écarlate fait mouvement. Quelque part le long de la route, entre la Main de Tyr et Stratholme, vous trouverez l’Oracle Demetria et sa fratrie. La tuer et retourner voir Nathanos le Flétrisseur.' WHERE l.`ID` = 6148 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'Oracle écarlate, Demetria' WHERE l.`ID` = 6148 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Demetria est la conseillère en chef du Grand Croisé. On l\'appelle l\'Oracle en raison de ses sens un peu « irréels ». Elle a aidé efficacement la Croisade à remporter plusieurs victoires contre le Fléau.$B$BMême si la ruse qui consiste à l\'exposer est couronnée de succès, vu ses pouvoirs psychiques, elle s\'attendra sans doute à avoir des ennuis. C\'est vous qui allez provoquer ces ennuis.$B$BPoursuivez l\'Oracle et tuez-la. Ils doivent être en train de quitter la Main de Tyr pendant que nous parlons. Faites ma fierté, petit ver.' WHERE l.`ID` = 6148 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Trouver la Clé d\'argent de Rackmore. Trouver la Clé d\'or de Rackmore. Trouver et ouvrir le Coffre de Rackmore.' WHERE l.`ID` = 6161 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Revendiquer le trésor de Rackmore !' WHERE l.`ID` = 6161 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Le journal de Rackmore explique comment son bateau a été attaqué par des créatures marines alors qu\'il naviguait vers le bastion de Pennelune. Pour empêcher son trésor de tomber dans des mains ennemies, il a caché son coffre sur l\'île de Ranazjar.$B$BPour l\'ouvrir, il faut deux clés, une en argent et une en or. Elles ont été perdues, mais un trésor attend celui qui retrouvera les clés et le coffre !' WHERE l.`ID` = 6161 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Tuer le Seigneur Ror et apporter sa Griffe à Dreka\'Sur, au Poste de la Vénéneuse, en Gangrebois.' WHERE l.`ID` = 6162 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]La dernière bataille d\'un mari' WHERE l.`ID` = 6162 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Mon mari a traversé Gangrebois pour l\'honneur de notre clan, en se battant contre le Conseil des ombres et d\'autres atrocités corrompues !$B$BIl a échappé à la mort de nombreuses fois avant que je ne reçoive une lettre de lui disant qu\'un druide avait requis son aide pour lutter contre un puissant furbolg infecté, nommé le seigneur Ror. Depuis, je n\'ai plus de nouvelles ni de l\'un ni de l\'autre.$B$BJe veux la main griffue de ce Ror, $n. Je veux qu\'il paye pour avoir fait de moi une veuve ! Je crois que la créature est au sud... près de la frontière d\'Orneval.' WHERE l.`ID` = 6162 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez la Note de Lewis à Thor, le Maître des griffons.' WHERE l.`ID` = 6181 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Un message rapide' WHERE l.`ID` = 6181 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Bien que Hurlevent ne nous aide pas beaucoup directement, j\'ai quand même un contact dans la ville qui nous permet de nous procurer des armures. Son nom est Osric Strang. Son magasin, « Immunité limitée », est dans la Vieille ville de Hurlevent.$B$BNotre réserve d\'armures diminue et je dois entrer en contact avec Osric pour en obtenir. Pouvez-vous lui porter cette note ?$B$BLa façon la plus rapide d\'aller à Hurlevent est de demander à Thor, notre Maître des griffons. Il est juste en bas de la colline, apportez-lui ma note et prenez ensuite un griffon pour Hurlevent.' WHERE l.`ID` = 6181 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Reparlez à Mathias Shaw, quand vous aurez décidé d’accepter son travail.' WHERE l.`ID` = 6183 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Honorer la mort' WHERE l.`ID` = 6183 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Cinq de mes meilleurs agents sur le terrain ont été affectés au cas Marris. Un seul est revenu, pour mourir dans son sommeil trois jours plus tard.$B$BLe peu d\'information que nous avons réussi à obtenir de lui était du charabia. Nous n’avons compris que deux mots : "Nathanos" et "Flétrisseur".$B$BJe n\'ai personne de disponible pour continuer cette enquête et Ravenholdt ne nous aidera pas. Nous devons aller jusqu\'au bout, ne serait-ce que par respect pour les familles de ceux qui sont morts. M\'aiderez-vous ?' WHERE l.`ID` = 6183 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Retourner à Hurlevent et informer le roi Varian Wrynn du destin de Nathanos Marris.' WHERE l.`ID` = 6186 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La venue du Flétrisseur' WHERE l.`ID` = 6186 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '<Le visage de Flint est livide.>$B$BNa... Nathanos a fait cela ? Nathanos est le Flétrisseur ?$B$BPourquoi ? Il était... si noble, un seigneur forestier respecté de tous. Le seul humain jamais autorisé à recevoir la formation des hauts-elfes. Désormais il est un agent impitoyable des Réprouvés ?$B$BJe... Je suis désolé de vous demander cela, $n, mais le roi Varian doit être informé immédiatement de la tournure des événements. S\'il vous plaît, retournez à Hurlevent pour lui annoncer la nouvelle.' WHERE l.`ID` = 6186 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La Chasse d\'Orneval' WHERE l.`ID` = 6383 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Libérez les Termites des Maleterres dans la scierie de la Crête du nord, puis retournez voir Nathaniel Dumah, au camp du Noroît, dans les Maleterres de l\'Ouest, avec le Tonneau de Termites des Maleterres.' WHERE l.`ID` = 6389 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Une Plaie sur la Croisade' WHERE l.`ID` = 6389 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous cherchez autour de la scierie quelque chose qui vous permettrait d’ouvrir le tonneau. Vous apercevez un pied-de-biche qui semble pouvoir faire l’affaire.$B$BVous vous préparez, tout en priant pour que les termites vous laissent le temps de sortir de la scierie indemne.' WHERE l.`ID` = 6389 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Libérez les Termites des Maleterres dans la scierie de la Crête du nord, puis retournez voir Mickey Levine, à la Barricade, dans les Clairières de Tirisfal, avec le Tonneau de Termites des Maleterres.' WHERE l.`ID` = 6390 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
