UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous cherchez autour de la scierie quelque chose qui vous permettrait d’ouvrir le tonneau. Vous apercevez un pied-de-biche qui semble pouvoir faire l’affaire.$B$BVous vous préparez, tout en priant pour que les termites vous laissent le temps de sortir de la scierie indemne.' WHERE l.`ID` = 6390 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apprendre la bonne nouvelle à Tammra Champ-des-Vents à la Retraite de Roche-Soleil.' WHERE l.`ID` = 6401 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Kaya est en vie' WHERE l.`ID` = 6401 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Allez apporter cette bonne nouvelle à Tammra Champ-des-Vents, la tante de Kaya, qui se trouve à la Retraite de Roche-Soleil ! Kaya est vivante ! Nous la croyions perdue après l\'attaque de notre village. Suivez la route de l\'ouest pour arriver à la Retraite de Roche-Soleil.' WHERE l.`ID` = 6401 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`AreaDescription` = 'La marche de Reginald' WHERE l.`ID` = 6403 AND l.`locale` = 'frFR' AND (l.`AreaDescription` IS NULL OR l.`AreaDescription` = '' OR BINARY l.`AreaDescription` = BINARY q.`AreaDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Suivre Reginald Windsor dans Hurlevent. Le protéger contre toute menace !' WHERE l.`ID` = 6403 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La grande mascarade' WHERE l.`ID` = 6403 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Ce fut une sacrée aventure. J\'ai vraiment une dette envers vous. Peut-être, quand tout sera dit et accompli...$B$BComme vous l\'avez sans doute vérifié à ce jour, dame Prestor est Onyxia, rejeton de l\'Aile de mort et jumelle de Nefarian, le tyran du Pic.$B$BPendant trop longtemps elle a captivé notre royaume de son regard hypnotique. Même le généralissime est prisonnier de sa duperie – une véritable marionnette. Cela prendra fin aujourd\'hui... Le charme sera rompu.$B$BNe craignez rien, ensemble, nous serons victorieux !$B$BVous êtes d\'attaque ?' WHERE l.`ID` = 6403 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Vous devez écumer le monde pour pouvoir rétablir le pouvoir du Fragment de l\'Oeil de dragon. La seule information dont vous disposez à propos de cette chose, c’est qu’elle existe.' WHERE l.`ID` = 6501 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'Œil de dragon' WHERE l.`ID` = 6501 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Tout ce que je peux vous offrir, c\'est un fragment du médaillon brisé.$B$BVous devez encore trouver du sang de dragon pour fabriquer une nouvelle clé. Une fois que vous aurez sécurisé cette clé, vous devrez voyager vers la tourbière du Ver, dans le marécage d\'Âprefange. C\'est là que vous trouverez sa tanière, $n.$B$BOù trouver d\'autres vols qui accepteraient de vous aider ? Malheureusement, je ne sais pas... On dit qu\'il y en a. Certains peuvent même travailler et vivre parmi nous, déguisés pour faire croire qu\'ils font partie de l\'une des races humanoïdes. Je vous souhaite bonne chance.' WHERE l.`ID` = 6501 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Chercher Rokaro au village Proie-de-l\'Ombre en Désolace.' WHERE l.`ID` = 6567 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le Champion de la Horde' WHERE l.`ID` = 6567 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Rexxar, l\'un de mes champions les plus loyaux, a trouvé un chemin pour pénétrer dans la tanière du dragon. Il a cependant quitté Azeroth pour se joindre à notre expédition en Outreterre.$B$BIl a laissé l\'information à son compagnon, Rokaro, au village Proie-de-l\'ombre. Vous devez aller le trouver.' WHERE l.`ID` = 6567 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Aller au Pic Rochenoire et collecter 20 Yeux de draconide noir. Retourner voir Myranda la Mégère quand la tâche sera terminée.' WHERE l.`ID` = 6569 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Illusions d\'Oculus' WHERE l.`ID` = 6569 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Ainsi $gun:une:r; $r souhaite devenir membre du Vol noir, hein ?$B$BLa création de l\'illusion que vous exigez est insignifiante, mais les composants requis pour la divination sont très difficiles à obtenir. Le Chef de guerre vous a confié cette mission, Myranda doit donc penser que vous en êtes capable.$B$BAllez à la citadelle supérieure du Pic Rochenoire et tuez assez de draconides noirs pour remplir l\'un de vos sacs de leurs yeux.$B$BRetournez voir Myranda quand vous aurez ramassé suffisamment de réactifs.' WHERE l.`ID` = 6569 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Vous devez trouver Clairvoyant, le drake champion du Vol bleu, et le tuer. Arracher son crâne à son cadavre, et le rapporter à Brandeguerre.$B$BClairvoyant se trouve au Berceau-de-l\'Hiver.' WHERE l.`ID` = 6582 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'épreuve des crânes, Clairvoyant' WHERE l.`ID` = 6582 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Nous sommes les enfants de l\'Aile de mort. Notre domination sur les Aspects moindres doit être absolue.$B$BSi vous êtes vraiment digne de l\'Ascension, les dragons de moindre niveau fuiront votre présence.$B$BTrouvez leurs champions et causez leur perte au nom de notre Père !$B$BAllez au Berceau-de-l\'Hiver et traquez le puissant drake bleu, Clairvoyant. Écrasez-le, ainsi que tous ceux du Vol bleu qui se trouveront sur votre chemin. Arrachez son crâne et rapportez-le-moi.' WHERE l.`ID` = 6582 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Détruire le Champion drake du Vol vert, Somnus. Arracher son crâne à son cadavre, puis le rapporter à Brandeguerre.' WHERE l.`ID` = 6583 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'épreuve des crânes, Somnus' WHERE l.`ID` = 6583 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'De même que notre Père écrase les Aspects eux-mêmes, nous devons nous efforcer d\'apporter le chaos et la destruction à leurs enfants.$B$BVous devez tester votre talent au combat contre les rêveurs sans sommeil : les enfants du Vol vert.$B$BAllez au marais des Chagrins et traquez Somnus, le champion drake du Vol vert. Laissez agir votre haine ; dominez l\'insecte... Revenez me voir avec son crâne...' WHERE l.`ID` = 6583 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Chronalis, enfant de Nozdormu, garde les Grottes du temps, dans le Désert de Tanaris. Tuez-le et rapportez son crâne à Brandeguerre.' WHERE l.`ID` = 6584 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'épreuve des crânes, Chronalis' WHERE l.`ID` = 6584 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Les Gardiens du temps, les fils de Nozdormu le Seigneur des sssiècles...$B$BIl y en a trois qui gardent les Grottes du temps, mais sssseul l\'un d\'eux a retenu l\'attention du Vol noir : le Passeur du temps, Chronalissss, le favori de Nozdormu.$B$BTuez ce champion et vous aurez porté un coup qui tirera des larmes au plus sssstoïque des sssables du temps. Revenez me voir avec son crâne.' WHERE l.`ID` = 6584 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à Jaron Sculptepierre, au village de Pluie-d\'Étoiles.' WHERE l.`ID` = 6604 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Les Indomptables enragés' WHERE l.`ID` = 6604 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Avez-vous remarqué le camp abandonné au sud d\'ici ? Il semble que les Indomptables soient devenus fous et qu’ils aient tout détruit sur leur passage !$B$BIl paraît qu\'un des survivants de l\'attaque est resté au village de Pluie-d\'Étoiles, à l\'ouest. Je suis curieux de savoir ce qui s\'est passé... Pas vous ?' WHERE l.`ID` = 6604 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
