UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Réussir à répondre à la question de Parqual Fintallas, puis lui reparler. Il se trouve à Fossoyeuse.' WHERE l.`ID` = 6628 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
