UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Tous les préparatifs sont terminés. À présent, vous devez accomplir le rituel qui créera un Cercle de lien supérieur, puis utiliser le parchemin imprégné de poussière d\'étoile xorothienne... pour ouvrir un portail vers Xoroth.$B$BToutes les instructions figurent sur ce document. Étudiez-le attentivement, car vous ne devez en dévier sous aucun prétexte si vous voulez réussir.$B$BJe vous souhaite bonne fortune, $n. Et puisse l’âme de vos ennemis trouver le chemin de votre bourse !' WHERE l.`ID` = 7631 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Rendez-vous à Forgefer et procurez-vous l’Encensoir d’exorcisme du grand prêtre Rohan. Pour vous le procurer, il vous faudra verser une donation de 150 pièces d’or.' WHERE l.`ID` = 7637 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'accent sur le sacrifice' WHERE l.`ID` = 7637 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Pour vous préparer à cette tâche, vous devez vous faire preuve de jugeote et d\'esprit de sacrifice… en mettant l’accent sur ce dernier aspect.$B$BVous devez vous procurer l’Encensoir d’exorcisme du grand prêtre Rohan. Bien sûr, il ne vous servira que pour de bonnes et justes raisons, mais vous devrez néanmoins verser une compensation à son propriétaire.$B$BRendez-vous à Forgefer et parlez au grand prêtre. Le convaincre de le séparer de son encensoir vous coûtera une forte somme, mais cela montrera votre esprit de sacrifice.$B$BAllez maintenant, $n, le temps presse.' WHERE l.`ID` = 7637 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler au seigneur Grayson Brisombre dans le Quartier de la Cathédrale de Hurlevent.' WHERE l.`ID` = 7638 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le seigneur Grayson Brisombre' WHERE l.`ID` = 7638 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '$n, le temps est venu d’apprendre ce que vous devrez faire pour vous procurer quelque chose que vous attendez sans doute depuis un moment… votre destrier !$B$BAllez parler au seigneur Grayson Brisombre, ici même, dans le quartier de la Cathédrale, à Hurlevent. Il vous apprendra à maîtriser la monture favorite des paladins. Et auparavant, il vous chargera de toutes les tâches que vous devrez accomplir pour vous en procurer un.$B$BJ’espère que votre épreuve se passera bien. Pour la Lumière, noble $gfrère:sœur; !' WHERE l.`ID` = 7638 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Ramener l’Encensoir d’exorcisme au seigneur Grayson Brisombre, dans le Quartier de cathédrale de Hurlevent.' WHERE l.`ID` = 7639 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Des preuves de jugement' WHERE l.`ID` = 7639 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Prenez cet encensoir, avec ma bénédiction. Je l’ai utilisé lors de plusieurs exorcismes, et il vous rendra de grands services dans les tâches ardues qui vous attendent.$B$BRetournez voir le seigneur Grayson Brisombre à Hurlevent, $n. Votre quête continue avec lui.' WHERE l.`ID` = 7639 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Procurez-vous un aliment pour chevaux capable de nourrir un esprit équin. Il semble que Merideth Carlson, à Austrivage, sache en fabriquer.$B$BEnsuite, rendez-vous au donjon de Hache-Tripes en Féralas, et tuez Tendris Crochebois. Sa mort libérera l’Ancien esprit équin. Nourrissez-le avec l’aliment spécial afin de l’apaiser. Enfin, donnez-lui le Caparaçon d’arcanite pour qu’il le bénisse.' WHERE l.`ID` = 7643 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'ancien esprit équin' WHERE l.`ID` = 7643 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Votre caparaçon aura besoin d’une bénédiction particulière, prononcée par un esprit approprié. Hache-Tripes abrite une telle entité, un Ancien esprit équin. Malheureusement, il est entre les mains d’un tréant corrompu, Tendris Crochebois. Jugez cet être infâme, $n.$B$BEt sachez que la liberté ne suffira pas à l’esprit équin. Vous devrez l’apaiser, avant de recevoir sa bénédiction. Pour cela, vous aurez besoin d’une nourriture très particulière. Allez à Austrivage et parlez-en à Merideth Carlson… et préparez-vous à d’autres sacrifices.' WHERE l.`ID` = 7643 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Retourner dans le Quartier de la Cathédrale de Hurlevent avec le Caparaçon d’arcanite béni pour voir le seigneur Grayson Brisombre.' WHERE l.`ID` = 7644 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le caparaçon en arcanite béni' WHERE l.`ID` = 7644 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Une fois posé sur le dos de l’Ancien esprit équin, le caparaçon se met à luire faiblement. L’air se charge de puissance pendant un bref instant, puis le caparaçon se téléporte, en toute sécurité, dans votre sac.$B$BIl semble qu’il ait été béni. Il ne vous reste plus qu’à suivre les instructions du seigneur Brisombre : retourner le voir à Hurlevent.' WHERE l.`ID` = 7644 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Récupérer 20 Biscuits de manne enrichis, l’ingrédient vital qui permet de préparer du Fourrage enrichi en manne, pour le compte de Merideth Carlson d\'Austrivage dans les contreforts de Hautebrande. L’Aube d’argent est la seule à fabriquer ces biscuits.$B$BVous devrez également lui donner 50 pièces d’or pour apaiser sa susceptibilité.' WHERE l.`ID` = 7645 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Fourrage enrichi en manne' WHERE l.`ID` = 7645 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'À la Main d’argent, ils ont dit que j’étais FOLLE lorsque j’ai dit que je pouvais préparer un fourrage qui pourrait nourrir des esprits de chevaux. Ils ont TOUS pensé que j’avais perdu la tête !$B$BMais maintenant, je tiens ma revanche !$B$BJe ferai ce que vous me demandez, PALADIN… soi-disant CHAMPION… mais cela va vous coûter cher. J’ai besoin de biscuits spéciaux… Des biscuits de manne enrichis qui ne sont vendus que par l’Aube d’argent. Et pour cette fois, j’exige – parfaitement, j’EXIGE de l’or en compensation des souffrances que j’ai endurées !$B$BVous n’arrêtez pas de vous gargariser de votre sens du sacrifice, PALADIN ? Il est temps maintenant de le mettre en pratique !' WHERE l.`ID` = 7645 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez un Diamant d’Azeroth et un Diamant noir en parfait état au seigneur Grayson Brisombre dans le Quartier de la Cathédrale de Hurlevent.' WHERE l.`ID` = 7646 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le Clairvoyant' WHERE l.`ID` = 7646 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir le Seigneur Grayson Brisombre à Hurlevent.' WHERE l.`ID` = 7646 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'L’épreuve qui vous permettra de sauver le destrier déchu commence par l’assemblage d’un Clairvoyant. En fait, le vôtre est pratiquement prêt. L’Encensoir d’exorcisme que vous avez utilisé à Val-Terreur en sera le catalyseur, et je vais lui fabriquer un réceptacle.$B$BIl nous faut néanmoins nous procurer deux composants : deux diamants. Ils doivent tous deux être d’une eau bien précise – un diamant d’Azeroth et un diamant noir en parfait état. Tous deux formeront le phare grâce auquel le Clairvoyant percera les ombres !' WHERE l.`ID` = 7646 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Utilisez le Clairvoyant au cœur du sous-sol du Grand ossuaire, dans la Scholomance. Cela attirera des esprits que vous devrez juger. Lorsqu’ils seront vaincus, le Chevalier de la mort Ravassombre apparaîtra. Vainquez-le et purifiez l’âme du destrier déchu.$B$BEnsuite, donnez l’Ame rachetée du destrier et le Caparaçon enchanté et béni au Destrier déchu de Ravassombre.' WHERE l.`ID` = 7647 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Jugement et rédemption' WHERE l.`ID` = 7647 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Prenez ce paquet, il contient tous les objets dont vous aurez besoin.$B$BServez-vous du Clairvoyant au centre des fondations du Grand ossuaire, afin d’attirer les esprits maudits qui doivent être jugés. Utilisez vos jugements avec sagesse au cours de cette épreuve, car les esprits risquent d’être plus puissants que vous ne le croyez. Lorsque ce sera terminé, le chevalier de la mort apparaîtra. Tuez-le et récupérez l’âme de son destrier. Lorsque ce sera fait, vous pourrez la purifier et placer votre caparaçon sur votre nouveau destrier.$B$BBonne chance, $n !' WHERE l.`ID` = 7647 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Présentez le Caparaçon d’arcanite au seigneur Grayson Brisombre dans le Quartier de la Cathédrale de Hurlevent, pour inspection.' WHERE l.`ID` = 7648 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le chef-d\'œuvre de Grimand' WHERE l.`ID` = 7648 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '<Grimand s’essuie le front. Il irradie la satisfaction.>$B$BNous y voilà, $gmon ami:mon amie;. C’est une pièce particulièrement réussie, aussi bonne que le caparaçon que j’ai fait pour le seigneur Brisombre lorsqu’il est parti en quête de son destrier. Je vous remercie de m’avoir honoré de votre confiance.$B$BGrayson voudra certainement le voir par lui-même. Portez-lui ce caparaçon, et transmettez-lui mes remerciements pour la tâche honorable qu’il accomplit.' WHERE l.`ID` = 7648 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Rendez ce livre à ses légitimes propriétaires.' WHERE l.`ID` = 7650 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Les plates en thorium enchanté - Volume II' WHERE l.`ID` = 7650 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Ce livre porte la marque de l’Athenaeum.' WHERE l.`ID` = 7650 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Si vous voulez aider Sagorne Rôdeur-des-crêtes de la Vallée de la Sagesse d\'Orgrimmar, apportez-lui un Diamant d’Azeroth et un Diamant noir en parfait état.' WHERE l.`ID` = 7667 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Assistance matérielle' WHERE l.`ID` = 7667 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '$n, j’espère que vous pourrez m’aider dans une affaire urgente… à la fois matériellement et spirituellement. Laissez-moi vous expliquer.$B$BDans les profondeurs de la Scholomance, en Lordaeron, se trouve une chambre appelée le Grand ossuaire. Je suis en train de terminer un objet qui permettra de percer les ombres de cet horrible endroit. Pour le terminer, j’ai besoin de deux diamants : un diamant d’Azeroth et un diamant noir en parfait état. Je sais que cela ne se trouve pas facilement, et je n’ai pas les moyens de les acheter.$B$BPourriez-vous me les procurer ?' WHERE l.`ID` = 7667 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Utilisez l\'Ultra-réducteur de Zorbin sur des géants de n\'importe quel type en Féralas afin les rendre plus faciles à gérer. Apportez 10 Résidus de miniaturisation que vous trouverez sur les versions rétrécies des géants à Zorbin Poudrozieu aux docks de la Côte Oubliée, en Féralas.' WHERE l.`ID` = 7725 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le retour des géants rétrécis' WHERE l.`ID` = 7725 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Je sais que vous avez déjà ramassé des résidus pour moi... mais si vous aviez envie de recommencer cette activité fort amusante, j\'aurais toujours besoin de résidus.$B$BJe ne serai plus en mesure de vous offrir la même compensation, mais je serais plus qu\'heureux de parler de vous à tous mes amis gobelins dotés d\'oreilles.$B$BEt croyez-moi $gMonsieur:Madame; quand je vous dis que ces gobelins ont de grandes oreilles.' WHERE l.`ID` = 7725 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Récupérez 6 Noyaux élémentaires d\'eau sur les Elémentaires marins et les Embruns le long de la Côte Oubliée de Féralas, et rapportez-les à Zorbin Poudrozieu, près du quai.' WHERE l.`ID` = 7726 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Encore du carburant pour la zappette' WHERE l.`ID` = 7726 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Encore du travail, vous dites ? Cette héroïque mission que je vous avais confiée de ramasser des machins gluants dans des êtres élémentaires n\'a donc pas apaisé votre soif d\'aventure ? Peut-être qu\'il serait vain de tenter d\'assouvir votre désir insatiable de quêtes par davantage des mêmes tâches...$B$BD\'accord, assez de mélodrame, j\'ai en fait vraiment besoin de plus de noyaux d\'élémentaires d\'eau. J\'essaye désespérément de gérer ma boutique ici, la récompense ne sera donc plus aussi belle... mais je vous promets que je raconterai à tout le monde combien vous m\'avez aidé. Vous pouvez me faire confiance là-dessus. Je connais des membres du Cartel !' WHERE l.`ID` = 7726 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Rapportez 20 Carapaces de Zukk\'ash à Hadoken Rôdeur-agile au Camp Mojache en Féralas.' WHERE l.`ID` = 7730 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Infestation de Zukk\'ash' WHERE l.`ID` = 7730 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'D\'après les informations que nous avons pu réunir, l\'ennemi se trouvant au sud des gnolls est une race insectoïde. Franchement, cela nous est égal s\'il s\'agit de créatures sensibles ou non. Si elles excitent à ce point les gnolls contre nous, elles représentent une menace tout aussi grave qu\'eux, voire pire encore.$B$BPartez loin jusqu\'à la demeure de ces insectes zukk\'ash : on l\'appelle le gouffre Grouillant. Réduisez leur nombre et faites-moi un rapport sur la situation. Rapportez leurs carapaces pour prouver votre travail.' WHERE l.`ID` = 7730 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Battez Fouet-cuisant dans le Gouffre Grouillant et rapportez ses glandes à Hadoken Rôdeur-agile au Camp Mojache en Féralas.' WHERE l.`ID` = 7731 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Fouet-cuisant' WHERE l.`ID` = 7731 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Alors qu\'il surveillait le gouffre Grouillant, un de nos éclaireurs nous a signalé avoir vu un insecte géant, bien plus grand que les autres insectes, qui errait dans cet endroit tortueux. Il est non seulement plus grand, mais il semble aussi sécréter une sorte d\'aura que les autres insectes n\'ont pas. Nous lui avons donné un nom : Fouet-cuisant.$B$BIl nous serait très précieux de pouvoir étudier les entrailles de cette bête afin de déterminer le meilleur moyen de lutter contre cette nouvelle menace. Coupez ses glandes de sécrétion et rapportez-les-moi immédiatement !' WHERE l.`ID` = 7731 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez le rapport sur les Zukk\'ash du Camp Mojache à Zilzibin Kongadok. Il réside à la Herse d\'Orgrimmar.' WHERE l.`ID` = 7732 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le rapport sur les Zukk\'ash' WHERE l.`ID` = 7732 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous avez doublement bien fait de vous occuper de la menace que les insectes Zukk\'ash représentent pour le Camp Mojache. Cette menace est loin d\'avoir disparu, et j\'aimerais vous demander une dernière tâche pour la Horde.$B$BVoici un document contenant toutes les informations que nous avons obtenues au sujet de ces insectes zukk\'ash. Je veux que vous l\'apportiez à Zilzibin Kongadok à la Herse d\'Orgrimmar. C\'est un expert concernant ce genre de créatures. J\'espère qu\'il pourra faire quelque chose à l\'aide des connaissances que nous avons réunies.' WHERE l.`ID` = 7732 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Fournir 10 Peaux de yéti griffe féroce à Jangdor Rôdeur-agile au Camp Mojache, en Féralas.' WHERE l.`ID` = 7734 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Qualité améliorée' WHERE l.`ID` = 7734 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'J’ai une piste qui pourrait nous conduire à une source de peaux encore MEILLEURES. Incroyable, non ? Au nord de Féralas, loin dans le repaire des Griffes féroces, vit un autre groupe de yétis. Ils sont beaucoup plus coriaces que ceux que vous avez déjà combattus. Si vous aimez les défis, celui-là devrait être à la hauteur de vos attentes !$B$BJe vous récompenserai généreusement pour dix de leurs peaux. Amenez-les ici, et nous ferons affaire.' WHERE l.`ID` = 7734 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Entrez dans le goulet des Chanteguerres, triomphez de l\'Alliance et obtenez une Marque d\'honneur du goulet des Chanteguerres. Puis revenez voir le capitaine Fracasse-crâne au campement de Mor\'shan.' WHERE l.`ID` = 7789 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Écrasez les usurpateurs d\'Aile-argent' WHERE l.`ID` = 7789 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'La sauvagerie de la forêt d\'Orneval succombera devant la puissance de la Horde, $r. Aile-argent ne pourra rien dire ou faire pour arrêter nos obligations souveraines. Kalimdor appartient à la Horde. Comment osent-ils tenter de nous empêcher de récolter ce qui nous appartient de droit !$B$BQue la fierté gonfle votre poitrine lorsque vous repousserez leurs futiles efforts pour ralentir notre progression. Détruisez les Sentinelles d\'Aile-argent, et vous gagnerez une marque d\'honneur Chanteguerre. Revenez me voir avec l\'une de ces marques, $n, et je vous récompenserai.' WHERE l.`ID` = 7789 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
