UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La Main de Rastakhan' WHERE l.`ID` = 8182 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '$n, nos pires craintes se réalisent. Les légendes racontent que l’Écorcheur d’âmes régnait naguère sur les trolls par le mal et la terreur, et il exerçait un pouvoir sans partage. Si nous ne l’arrêtons pas maintenant, son royaume risque de s’étendre à tout Azeroth !$B$BLes envoyés des trolls zandalariens nous aideront peut-être à interrompre la montée des ténèbres. Ils se sont installés sur l\'île de Yojamba, sur la côte de Strangleronce, à l’ouest des ruines de Zul’Kunda. Parlez à leur chef, Molthor, et prions pour qu’il sache comment vaincre Hakkar.' WHERE l.`ID` = 8182 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Encore du sang de scorpide luminescent' WHERE l.`ID` = 8223 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter 6 Écailles de vandale des flots à Ogtinc en Azshara. Ogtinc demeure au sommet des falaises au nord-est des ruines d\'Eldarath.' WHERE l.`ID` = 8231 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Vandales des flots' WHERE l.`ID` = 8231 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Les vandales des flots sont des bêtes amphibies qui vivent seulement ici en Azshara. Ils s\'adaptent à tout et sont très résistants.$b$bLes écailles dures et réfléchissantes du vandale des flots évoquent la force du chasseur.$b$bTraquez et chassez des vandales le long de la côte d\'Azshara et apportez-moi leurs écailles.' WHERE l.`ID` = 8231 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Récupérez le Sac azur scellé auprès du chaman Grumegueule en Azshara. Puis apportez le sac à l\'archimage Xylem, également en Azshara.' WHERE l.`ID` = 8234 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Sac azur scellé' WHERE l.`ID` = 8234 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Commençons par le commencement. J\'ai perdu un petit sac bleu, dont le contenu ne regarde que moi.$b$bNe prenez pas la peine de chercher les voleurs, ils sont déjà morts. Nous savons cependant que ces écervelés n\'ont pas pu ouvrir le sac. Ils l\'ont alors vendu à un chaman Grumegueule en Azshara en le faisant passer pour une « relique sacrée ». Très malin.$b$bJe veux que vous alliez en Azshara pour le récupérer auprès du chaman, en employant des moyens subtils... ou bien la force. Je miserais sur la première méthode. Une fois que vous aurez le sac, apportez-le à l\'archimage Xylem.' WHERE l.`ID` = 8234 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter 10 Fragments codés à l\'archimage Xylem en Azshara.' WHERE l.`ID` = 8235 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Les fragments codés' WHERE l.`ID` = 8235 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Le seigneur Ravenholdt nous demande à tous deux une faveur. Il souhaite faire enlever l\'enchantement de ce sac.$b$bMalheureusement, certains de mes livres traitant du désenchantement m\'ont récemment été dérobés avant d\'être détruits par des sauvages. Leurs débris ont cependant encore de la valeur pour moi.$b$bSi vous m\'apportez assez de fragments codés, je pourrai les réassembler. Vous aurez le plus de chances d\'en trouver en tuant les bêtes d\'Azshara, elles ont tendance à ramasser n\'importe quoi.' WHERE l.`ID` = 8235 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Cherchez Ogtinc en Azshara.' WHERE l.`ID` = 8254 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Aider le Cercle' WHERE l.`ID` = 8254 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'La voie divine est d\'aider ceux qui sont dans le besoin. La manière importe peu, seule la raison compte.$b$bLe Cercle cénarien a un tel besoin. Parlez à Ogtinc pour prêter votre aide au Cercle en ces circonstances difficiles. Il réside au sommet des falaises, au nord-est des ruines d’Eldarath en Azshara.' WHERE l.`ID` = 8254 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Récupérez 4 Glandes de coursier en bonne santé et apportez-les à Ogtinc en Azshara. Ogtinc réside au sommet des falaises, au nord-est des ruines d’Eldarath.' WHERE l.`ID` = 8255 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Courser les coursiers' WHERE l.`ID` = 8255 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Les coursiers Sabot-de-mousse d’Azshara sont des animaux magnifiques qui vivaient autrefois à Gangrebois. Ils résistent bien aux maladies et aux poisons, et n’ont pas été affectés par la corruption de la région. Dans leur sagesse, ils ont simplement choisi de partir.$B$BJe dois vous demander de chasser ces bêtes puissantes, bien que cela m’attriste. Récupérez quatre glandes de coursier, elles seront le premier ingrédient d\'un baume purifiant, un baume que nous utiliserons pour guérir Gangrebois.' WHERE l.`ID` = 8255 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Paquetage de base d\'Arathor' WHERE l.`ID` = 8260 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Paquetage ordinaire d\'Arathor' WHERE l.`ID` = 8261 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le paquetage de base de Profanateur' WHERE l.`ID` = 8263 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le paquetage ordinaire de Profanateur' WHERE l.`ID` = 8264 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La gratitude d\'Oran' WHERE l.`ID` = 8273 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Récupérez 200 Fragments de carapaces de silithides et retournez voir Baristolth.' WHERE l.`ID` = 8301 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le Chemin des Justes' WHERE l.`ID` = 8301 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'La Progéniture de Nozdormu se méfie tout naturellement des peuples inférieurs. Vous m’avez effectivement prouvé que vous aviez le potentiel pour devenir un héros, mais vous devez encore en convaincre mon maître.$B$BLa Ruche’Ashi, la Ruche’Zora et la Ruche’Regal grouillent d’activité, et toutes trois sont une menace pour notre existence. Tuez les silithides de ces ruches et ramenez-moi un fragment de leur carapace. Lorsque vous serez si $gchargé:chargée; que vous ne pourrez plus en porter, revenez me voir et je fortifierai votre résolution.' WHERE l.`ID` = 8301 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Placez les Œufs pourris dans le tonneau de bière principal de l’auberge d’Austrivage.' WHERE l.`ID` = 8322 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Les œufs pourris' WHERE l.`ID` = 8322 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Les humains d’Austrivage adorent la bière, et tout particulièrement celle qui est servie à l’auberge d’Austrivage. Nous pouvons profiter du chaos provoqué par la Sanssaint pour gâter leur dernière cuvée de boissons pour des semaines… voire des mois !$B$BPrenez ces œufs pourris et allez les placer dans le tonneau de bière principal de l’auberge d’Austrivage. Votre simple présence déclenchera des combats, alors attendez-vous à vous battre !$B$BQuand vous aurez laissé à Austrivage un goût qu’ils ne risquent pas d’oublier, revenez me voir ici, à la fête !' WHERE l.`ID` = 8322 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parlez à Aurel Feuilledor au Fort cénarien.' WHERE l.`ID` = 8331 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Aurel Feuilledor' WHERE l.`ID` = 8331 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '$n, nous espérions que les opérations du Marteau du crépuscule en Silithus avaient ralenti… Mais malheureusement, nous nous sommes lourdement trompés. Grâce à nos incursions continuelles contre le culte, nous avons appris qu’il était contrôlé par un pouvoir encore plus sombre, le Conseil abyssal, au moyen de pierres des vents mystiques éparpillées dans leurs différents camps. Votre prochaine mission, $n, sera de vous attaquer au Conseil abyssal.$B$BAllez consulter l’artisan Aurel Feuilledor, dans le quartier est du Fort cénarien. Vous aurez besoin de ses compétences pour votre prochaine manœuvre.' WHERE l.`ID` = 8331 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parlez à Aurel Feuilledor au Fort cénarien.' WHERE l.`ID` = 8343 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La découverte de Feuilledor' WHERE l.`ID` = 8343 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '$n, Aurel Feuilledor pense qu’elle a trouvé un moyen pour invoquer et vaincre un dirigeant du Conseil abyssal. Une telle tâche est fort dangereuse, mais vous avez acquis un grand respect auprès du Cercle cénarien. Nous savons parfaitement que si une personne peut réussir, c’est bien vous.$B$BQue la fortune vous accompagne, $n. Parlez à Aurel quand vous serez $gprêt:prête;.' WHERE l.`ID` = 8343 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Remettez 4 Essences d’âmes en peine et 1 Essence d’âme en peine contaminée à l’invocateur Teli\'Larien, à la Flèche solaire de l’île de Haut-Soleil.' WHERE l.`ID` = 8344 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Des fenêtres vers la source' WHERE l.`ID` = 8344 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Écoutez-moi bien, $gmon jeune ami:ma jeune amie;. Il y a quelque chose de pourri dans cette île, quelque chose de bien plus puissant que les séquelles du Fléau.$B$BJe soupçonne l’île d’abriter une véritable présence démoniaque.$B$BUn peu plus à l’ouest, vous trouverez les flèches de l’académie de Falthrien. Les âmes en peines arcaniques qui l’infestent nous donnent une ouverture vers la source de ce pouvoir démoniaque. Vous allez me remettre les essences de ces âmes, corrompues ou non.$B$BEn échange, je vous apprendrai comment invoquer un diablotin qui sera le premier des nombreux compagnons de votre carrière de démoniste.' WHERE l.`ID` = 8344 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez la Chevalière abyssale à Bor Crin-sauvage, au Fort cénarien.' WHERE l.`ID` = 8348 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La chevalière des ducs' WHERE l.`ID` = 8348 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Huum m’a dit que vous avez trouvé comment invoquer les ducs abyssaux ? C’est un sacré succès !$B$BVous savez ce qui serait un succès encore plus grand ? En coincer un et lui botter les fesses très, très fort. Ça impressionnerait beaucoup ses subordonnés, si vous voyez ce que je veux dire. Ramenez-moi sa chevalière comme preuve de votre succès.' WHERE l.`ID` = 8348 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parlez à Bor Crin-sauvage au Fort cénarien.' WHERE l.`ID` = 8349 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Bor Crin-sauvage' WHERE l.`ID` = 8349 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Maintenant que vous avez un médaillon et que vous pouvez appeler un duc abyssal, allez voir Bor Crin-sauvage. Il vous confiera une mission contre le Conseil abyssal.$B$BBonne chance, $n. Et si jamais vous avez encore besoin de médaillons, revenez me voir.' WHERE l.`ID` = 8349 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`AreaDescription` = 'Nettoyer une boule puante qui a été lancée sur Austrivage !' WHERE l.`ID` = 8373 AND l.`locale` = 'frFR' AND (l.`AreaDescription` IS NULL OR l.`AreaDescription` = '' OR BINARY l.`AreaDescription` = BINARY q.`AreaDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Utilisez le Nettoyeur de boules puantes pour retirer les Boules puantes que les Réprouvés ont lancées sur Austrivage. Retournez voir le sergent Hartman à Austrivage quand vous aurez terminé.' WHERE l.`ID` = 8373 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La puissance du pin' WHERE l.`ID` = 8373 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir le Sergent Hartman à Austrivage, dans les Contreforts de Hautebrande.' WHERE l.`ID` = 8373 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'La chose que je déteste le plus dans la Sanssaint, ce sont les boules puantes que les Réprouvés lancent sur Austrivage. Qui aurait cru que fêter leur libération impliquerait une pagaille aussi nauséabonde ?$B$BPendant la Sanssaint, servez-vous de ce nettoyeur pour retirer toutes les boules puantes immondes que la Horde aura déposées dans le village. Il utilise la puissance du pin pour chasser les odeurs pestilentielles.$B$BSi vous aidez Austrivage à rester propre, je vous donnerai quelques bonbons de la Sanssaint. Je suis sûr que vous les aimerez. Marché conclu ?' WHERE l.`ID` = 8373 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
