UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez 3 Marques d\'honneur du Bassin Arathi à un général de brigade de l\'Alliance, devant les champs de bataille.' WHERE l.`ID` = 8395 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La revendication du bassin Arathi' WHERE l.`ID` = 8395 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Pour gagner une guerre, il ne suffit pas de battre l’adversaire, ou de déjouer ses ruses. Souvent, la victoire est remportée tout simplement en produisant plus de ressources que l’ennemi.$B$BLe bassin Arathi n’est ni plus ni moins qu’un océan de ressources potentielles pour le camp qui parviendra à s’en emparer le premier.$B$BSi l’Alliance l’emporte, cela signifie que nous aurons plus d’épées et de piques pour nos troupes. Si c’est la Horde qui gagne, ces épées et ces piques seront tout de même fabriquées, mais elles seront pointées sur nous ! Il est temps, maintenant, d’aider l’Alliance dans le bassin Arathi, $n.' WHERE l.`ID` = 8395 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez 3 Marques d\'honneur du goulet des Chanteguerres à un général de brigade de l\'Alliance, devant les champs de bataille.' WHERE l.`ID` = 8401 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La lutte pour le goulet des Chanteguerres' WHERE l.`ID` = 8401 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Les sentinelles d’Aile-argent sont en guerre contre les voltigeurs Chanteguerre, à cause des destructions perpétrées par les orcs. Cependant, nous avons d’autres raisons pour défendre tout particulièrement cette forêt. Il ne s’agit pas uniquement de promouvoir la philosophie de préservation des Ailes-argent.$B$BLa forêt constitue une barrière stratégique qui protège Orneval contre une attaque à grande échelle. Sans cela, Astranaar serait annexée aux Tarides en moins de deux jours. Faites votre part dans le combat contre les voltigeurs Chanteguerre ! Pour l’Alliance !' WHERE l.`ID` = 8401 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez les différents morceaux du Totem des esprits à Bath’rah la Vigie des vents.' WHERE l.`ID` = 8412 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]Le totem des esprits' WHERE l.`ID` = 8412 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Les esprits élémentaires de cet endroit ne m’aiment plus.$B$BVous savez ce qu’il en est des totems mieux qu\'aucun autre et j’ai besoin d’un totem des esprits pour me protéger. Nous avons déjà les éléments, il nous faut à présent des choses plus en rapport avec la nature. Plus primitives.$B$BDans les Maleterres de l’ouest, tuez des ours pour prendre leurs griffes et des araignées pour leurs yeux. Les charognards mangent de tout, ils pourraient avoir l\'un ou l\'autre.' WHERE l.`ID` = 8412 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez les Plumes vaudou à Bath\'rah la Vigie des vents.' WHERE l.`ID` = 8413 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Vaudou !' WHERE l.`ID` = 8413 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Le totem des esprits ne suffit pas. Nous allons avoir besoin de magie vaudou pour qu’il fonctionne correctement.$b$bLes trolls du temple englouti possèdent des plumes fortement imprégnées de magie vaudou. Allez là-bas et tuez Balafreur, Mijan, Zolo, Hukku, Zul\'lor et Loro. Nous aurons alors assez de magie pour un vrai totem des esprits.' WHERE l.`ID` = 8413 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Récupérez 20 Pierres du Fléau des serviteurs et apportez-les au grand prêtre Thel\'danis dans les Maleterres de l\'Ouest.' WHERE l.`ID` = 8414 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La dissipation du mal' WHERE l.`ID` = 8414 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Salutations, $c. Des croisés comme vous sont les bienvenus dans ces étendues désolées.$B$BVotre force sacrée est nécessaire pour nous aider à combattre les morts-vivants innombrables qui hantent cette région. Nous avons besoin de vous pour rassembler un grand nombre de pierres du Fléau et les apporter au grand prêtre Thel\'danis. Le grand prêtre garde la tombe d’Uther à la colline des Chagrins, non loin d’ici.$B$BSeule une personne détentrice d’un brevet de l’Aube d’argent peut espérer trouver des pierres du Fléau, il vaudrait donc mieux vous entretenir avec l’officier Purecarde, si vous ne l’avez pas déjà fait.' WHERE l.`ID` = 8414 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez la Pierre du Fléau inerte au commandant Ashlam Vaillepoing à la pointe du Noroît.' WHERE l.`ID` = 8416 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Pierres du Fléau inertes' WHERE l.`ID` = 8416 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Le mal a été purgé des pierres, $n.$b$bJe connais les plans du commandant Ashlam, et il n’a besoin que d’une seule pierre inerte. Apportez-la-lui pour que nous puissions plonger le Fléau dans le feu justicier.' WHERE l.`ID` = 8416 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter 10 morceaux de Bois pourri et 4 Essences de Vénéneuse à Démonet, en Gangrebois.' WHERE l.`ID` = 8421 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'anti-étoffe des héros' WHERE l.`ID` = 8421 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Maintenant que j’ai la gangrétoffe, je peux enfin commencer à fabriquer *mon* familier.$B$BMais… je crois que je vais avoir besoin d’yeux. Peut-être que vous pourriez arracher un peu de bois pourri aux gens d’Arbrefer, pour que je puisse lui sculpter des yeux adorables. Ils sont au nord, dans le bois d\'Arbrefer.$b$bJ’aurai aussi besoin d’essence de Vénéneuse pour lui donner cette nouvelle odeur démoniaque. Les limons corrompus en possèdent, et on en trouve juste à côté, près de Niby et moi.' WHERE l.`ID` = 8421 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez 3 Marques d’honneur du goulet des Chanteguerres à l’un des porteguerres de la Horde, devant les champs de bataille.' WHERE l.`ID` = 8427 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La bataille du goulet des Chanteguerres' WHERE l.`ID` = 8427 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'La bataille dans le goulet des Chanteguerres contre les Sentinelles d’Aile-argent est d’une grande importance. Sous le prétexte de protéger une forêt qui ne lui appartient pas, l’Alliance cherche à refuser à la Horde l’une de ses plus grandes ressources en bois.$B$BNe la laissez pas faire, $n ! Revenez me voir quand vous aurez la preuve que vous avez bien servi la Horde !' WHERE l.`ID` = 8427 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez 3 Marques d’honneur du goulet des Chanteguerres à l’un des porteguerres de la Horde, devant les champs de bataille.' WHERE l.`ID` = 8429 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La bataille du goulet des Chanteguerres' WHERE l.`ID` = 8429 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'La bataille dans le goulet des Chanteguerres contre les Sentinelles d’Aile-argent est d’une grande importance. Sous le prétexte de protéger une forêt qui ne lui appartient pas, l’Alliance cherche à refuser à la Horde l’une de ses plus grandes ressources en bois.$B$BNe la laissez pas faire, $n ! Revenez me voir quand vous aurez la preuve que vous avez bien servi la Horde !' WHERE l.`ID` = 8429 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '<TXT> Récompense mystère' WHERE l.`ID` = 8450 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter un Scalp de traqueur des ombres à Maurin Craquossement en Désolace.' WHERE l.`ID` = 8458 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '<INUTILISÉ>' WHERE l.`ID` = 8458 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir Maurin Craquossement au Poste de Rôdeur-fantôme, en Désolace.' WHERE l.`ID` = 8458 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Je pense pouvoir trouver ce démon si j\'ai les réactifs adéquats.$b$bS\'il est effectivement aussi puissant que je le suspecte, je vais avoir besoin de certains objets disponibles sur des créatures mortelles. Mais vous agissez au nom du Chef de guerre, aussi je suis certain que vous accepterez ma quête.$b$bD\'abord, je vais devoir briser toutes les protections qu\'il aurait contre les visions. Pour cela, j\'aurais besoin d\'un scalp de satyre. Mais pas de n\'importe quel satyre. Il doit provenir d\'un traqueur des ombres Fielfurie.$b$bCherchez cette tribu dans les ruines anciennes au nord-est de Désolace.' WHERE l.`ID` = 8458 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Objectif' WHERE l.`ID` = 8459 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '<INUTILISÉ>' WHERE l.`ID` = 8459 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez 20 Barres de thorium à Dame Doublenattes à l\'aérodrome de Dun Morogh.' WHERE l.`ID` = 8500 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'Alliance a besoin de plus de barres de thorium !' WHERE l.`ID` = 8500 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'C’est très agréable de vous revoir, $n. J’espère que vous allez bien. Il est vrai que nous avons encore besoin de barres de thorium. Si vous en avez quelques-unes en trop, j’en rassemble pour l’effort de guerre d’Ahn\'Qiraj.' WHERE l.`ID` = 8500 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Présentez-vous au poste de la brigade de Forgefer devant la Ruche’Zora. Préparez votre Ordre de mission et obtenez un Ordre de mission signé du capitaine Noirenclume. Ensuite, retournez voir l\'Implorateur céleste Kaldon au Fort cénarien, en Silithus.$B$BNote : lancer un sort de soin, ou tout autre sort bénéfique, sur un membre de la brigade de Forgefer vous infligera un marqueur JcJ.' WHERE l.`ID` = 8507 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Votre affectation' WHERE l.`ID` = 8507 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Salutations, $n. Avant que je vous assigne des tâches plus vitales pour la guerre, vous devrez faire votre part dans la mise en place de la campagne.$B$BVous trouverez les forces de la brigade de Forgefer commandée par le capitaine Noirenclume devant la Ruche’Zora.$B$BAllez vous présenter à lui ou à son lieutenant, Janela Rudemartel, et revenez me voir. Je vous aurai alors préparé des missions plus délicates.$B$BOh, et faites-nous une faveur. Ne restez pas à côté de la légion d’Orgrimmar. Nous avons été obligés de bien séparer les deux armées à cause de l’animosité mutuelle qu’elles se vouent…' WHERE l.`ID` = 8507 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez 10 Cuirs légers à Bonnie Ecorchepierre à l\'aérodrome de Dun Morogh.' WHERE l.`ID` = 8512 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'Alliance a besoin de plus de cuir léger !' WHERE l.`ID` = 8512 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Ramener 20 bandages en étoffe runique au gardien Lunombrage à l’aérodrome de Dun Morogh.' WHERE l.`ID` = 8523 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'Alliance a besoin de plus de bandages en étoffe runique !' WHERE l.`ID` = 8523 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Nous nous retrouvons une fois de plus pour discuter d’une affaire urgente, $c. Je vous remercie encore pour vos précédents efforts. Peu de gens se seraient montrés aussi généreux et altruistes. Mais il reste beaucoup à faire.$B$B$n, acceptez-vous de récolter de nouveaux bandages en étoffe runique et de me les ramener ?' WHERE l.`ID` = 8523 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Invoquez et tuez un Templier terrestre, puis allez faire votre rapport à Bor Crin-sauvage, au Fort cénarien. Pour terminer cette quête, vous devez aussi apporter le Briefing tactique III.' WHERE l.`ID` = 8536 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le templier terrestre' WHERE l.`ID` = 8536 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Les sectateurs du Marteau du crépuscule et les nobles élémentaires qu’ils adorent représentent une menace terrible pour nos opérations en Silithus. Nous affrontons de nouveaux ennemis à l’intérieur d’Ahn’Qiraj, mais nous ne pouvons pas nous permettre de baisser notre garde vis-à-vis des ennemis de l’extérieur.$B$BTrouvez un moyen d’invoquer et de détruire un templier terrestre, puis allez faire votre rapport à Bor Crin-sauvage.' WHERE l.`ID` = 8536 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Trouver un moyen d’invoquer et de tuer les duc des Cendres, le duc des Profondeurs, le duc des Zéphyrs et le duc des Éclats, puis revenir voir le commandant Mar\'alith au Fort cénarien. Pour terminer cette quête, vous devez aussi apporter le Briefing tactique V.' WHERE l.`ID` = 8538 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Les quatre ducs' WHERE l.`ID` = 8538 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Les liens entre le Marteau du crépuscule et le Conseil abyssal s’avèrent plus étroits que nous le pensions.$B$BNous soupçonnons des nobles élémentaires connus sous le nom de « ducs abyssaux » d’être l’une des forces qui organisent les sectateurs du Marteau du crépuscule. Trouvez un moyen de les attirer sur notre plan d’existence et détruisez-les.$B$BVotre détermination et vos exploits passés nous ont conduits à vous sélectionner pour cette mission. Nous sommes certains que vous réussirez.' WHERE l.`ID` = 8538 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Rendre l\'Echarpe à monogramme à son propriétaire.' WHERE l.`ID` = 8552 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'écharpe à monogramme' WHERE l.`ID` = 8552 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'On peut lire les lettres "HS" brodées le long de l\'ourlet de la belle écharpe.' WHERE l.`ID` = 8552 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à Bizutard.' WHERE l.`ID` = 8553 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le sabre du capitaine Smotts' WHERE l.`ID` = 8553 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Parlez à Bizutard à Baie-du-Butin, dans la Vallée de Strangleronce.' WHERE l.`ID` = 8553 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Après que mon premier navire a été détruit par ces géants, j\'en ai acheté un autre. Je l’ai baptisé le Revanche de Smotts, j’ai trouvé un nouvel équipage, j\'ai rempli les cales de marchandises, puis j’ai appareillé pour retrouver ces misérables géants. Je les ai trouvés, et de nouveau ils m’ont battu. Ils ont détruit le Revanche de Smotts, tué presque tout mon équipage et jeté les rescapés dans un canot.$b$bCette fois, un autre géant, Negolash, m’a volé mon sabre.$b$bCombattez Negolash et rapportez-moi mon sabre !$b$bParlez à Bizutard. C\'était mon cuistot sur le Revanche de Smotts et il a survécu à la dernière attaque. Il peut vous aider à trouver le géant.' WHERE l.`ID` = 8553 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter 10 Ailes de busard grillées et 5 bouteilles de Vin de Junglevigne dans le Canot de sauvetage du capitaine Smotts.$B$BTuer Negolash, et apporter le Sabre d\'abordage de Smotts au capitaine Smotts, à Strangleronce.' WHERE l.`ID` = 8554 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Face à Negolash' WHERE l.`ID` = 8554 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Negolash est un goinfre.$b$bQuand les géants ont détruit notre navire, il est venu directement dans ma cuisine. Il n\'avait pas faim d\'hommes d\'équipage comme les autres géants. Negolash voulait du vin et mes ailes de busard grillées au barbecue. C\'est ma spécialité, et j\'ai dû me rendre jusqu\'aux Terres ingrates pour avoir la recette !$b$bSi vous voulez tendre un piège au géant, trouvez du vin et un monceau d\'ailes de busard. Placez-les dans notre vieux canot, au sud-est, le long de la côte. Quand Negolash sentira cette bonne nourriture, il rappliquera, sans aucun doute !' WHERE l.`ID` = 8554 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Retrouver les Lunettes de divination de Narain et les rapporter à Narain Divinambolesque en Tanaris.' WHERE l.`ID` = 8578 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Des lunettes d\'observation ? Aucun problème !' WHERE l.`ID` = 8578 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '<Vous entendez un soupir de soulagement s’échapper de la caisse.>$B$BVous voulez juste ses lunettes de divination ? Génial ! Y’a pas de problème… Laissez-moi juste une minute pour… Hé ! Où le… Cornegidouille !$B$BBon, ben… J’ai une mauvaise nouvelle… et une très mauvaise nouvelle. La mauvaise nouvelle est que j’ai perdu les lunettes. La très mauvaise est que je les ai perdues quand je me suis promené dans le Cœur du Magma le mois dernier. Ouais, le Cœur du Magma… J’suppose qu’on a fini de faire affaire, maintenant ! Salut !' WHERE l.`ID` = 8578 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Récupérer la Carcasse de Lakmaeran et 20 Filets de chimaerok pour Dirge Hachillico, en Tanaris.' WHERE l.`ID` = 8585 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'île de l\'effroi !' WHERE l.`ID` = 8585 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'D’après les légendes, les chimaeroks de l’île de l’effroi, en Féralas, ont la chair la plus succulente qui soit au monde ! Or, il se trouve que leur papa, convenablement préparé, pourrait bien ressembler à un poulet de 500 livres – ou pas.$B$BAllez sur l’île de l’effroi, tuez le seigneur Lakmaeran et ramenez-moi sa carcasse. Ça, c’est pour le gnome. Quant à moi, je veux quelques filets de chimaeroks.$B$BQuand vous aurez fini, vous aurez un poulet de 500 livres et un petit extra.' WHERE l.`ID` = 8585 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Narain Divinambolesque, en Tanaris, veut que vous vous rendiez au Berceau-de-l’Hiver et que vous posiez le Sac d\'or à l’endroit indiqué par les voleurs de livres.' WHERE l.`ID` = 8606 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Un leurre !' WHERE l.`ID` = 8606 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Eurêka ! Je sais ce que nous allons faire. Je vais remplir un sac de pierres, et vous allez vous charger de le remettre. Je sais que je suis censé le faire moi-même… et bien c’est ce qui va se passer. En quelque sorte.$B$B<Narain vous examine des pieds à la tête.>$B$BBon bon bon, ça ira. Prenez cette robe, ce turban et ce sac de cailloux, et filez au lieu du rendez-vous, au Berceau-de-l’Hiver.$B$BJ’ai mis tout ce dont vous avez besoin dans cette panoplie spéciale. Lorsqu’ils se montreront pour récupérer l’argent… crac, vous leur tombez dessus ! Ça leur apprendra à s’en prendre à Narain !' WHERE l.`ID` = 8606 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Retrouver les 8 chapitres perdus du « Draconique pour les nuls » et les combiner avec la Reliure magique, puis ramener l’exemplaire réparé du « Draconique pour les nuls, volume II » à Narain Divinambolesque, en Tanaris.' WHERE l.`ID` = 8620 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le seul remède' WHERE l.`ID` = 8620 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'J’aurais dû m’en douter ! Mon ennemi juré, le docteur Dwenfer, a récidivé ! Et maintenant, à cause de votre échec au Berceau-de-l’Hiver, le docteur Dwenfer a détruit mon livre ! Comment allez-vous sauver le monde, maintenant ?$B$BD’après le message que j’ai reçu, l’unique exemplaire connu du "Draconique pour les nuls, volume II" a été divisé en huit morceaux et dispersé aux quatre vents ! Si par miracle vous parvenez à les récupérer, utilisez cette reliure magique pour les réunir et rapportez-les-moi.' WHERE l.`ID` = 8620 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Narain Divinambolesque, en Tanaris, veut que vous lui apportiez 20 Barres d’arcanite, 10 Minerais d’élémentium, 10 Diamants d’Azeroth et 10 Saphirs bleus.' WHERE l.`ID` = 8728 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La bonne nouvelle et la mauvaise nouvelle' WHERE l.`ID` = 8728 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Eh bien, cela a pris un peu plus de temps que je ne le croyais. Voyons voir maintenant ce que dit ce livre.$B$B<Narain lit silencieusement le grimoire, marmonnant de temps en temps dans sa barbe.>$B$BLa bonne nouvelle est que je suis certain à 99% d’être en mesure de créer une bouée d’arcanite qui fonctionnera selon vos spécifications. Cela dépend, bien sûr, complètement de la mauvaise nouvelle. La mauvaise nouvelle est que je vais avoir besoin de beaucoup de minerai d’arcanite et d’élémentium, et de pierres précieuses rares.$B$BApportez-moi tout ce dont j’ai besoin et je fabriquerai votre bouée.' WHERE l.`ID` = 8728 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Tuez Nefarian pour récupérer le Fragment de sceptre rouge. Rapportez le Fragment de sceptre rouge à Anachronos aux Grottes du temps en Tanaris. Vous avez 5 heures pour accomplir cette tâche.' WHERE l.`ID` = 8730 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La corruption de Nefarius' WHERE l.`ID` = 8730 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Champion, est-ce bien vous ? Un millier d’années se sont écoulées depuis que le fragment m’a été confié, et c’est à mon heure la plus sombre que quelqu’un se présente pour me le réclamer… Mais que serait une tragédie sans cruauté ?$B$B<Vaelastrasz tousse faiblement.>$B$BNe… Nefarius détient aujourd’hui le fragment du sceptre.$B$BLe temps presse. Nefarius a l’intention de détruire le fragment. Vous devez vous hâter !' WHERE l.`ID` = 8730 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Allez vous présenter à Krug Caskrâne, au poste de la légion d’Orgrimmar devant la Ruche’Regal. Préparez votre Ordre de mission, obtenez un Ordre de mission signé et apportez-le à l’Implorateur céleste Kaldon au Fort cénarien$B$BNote : lancer un sort de soin, ou tout autre sort bénéfique, sur un membre de la légion d’Orgrimmar vous infligera un marqueur JcJ.' WHERE l.`ID` = 8731 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Votre affectation' WHERE l.`ID` = 8731 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Salutations, $n. Avant que je vous assigne des tâches plus vitales pour la guerre, vous devrez faire votre part dans la mise en place de la campagne.$B$BVous trouverez la légion d’Orgrimmar, commandée par le capitaine Caskrâne, à l’extérieur de Ruche’Regal.$B$BAllez vous présenter à lui et revenez me voir avec une preuve de votre engagement. Je vous aurai alors préparé des missions plus délicates.$B$BOh, et ne restez pas à côté de la brigade de Forgefer. Les tensions entre les volontaires de l’Alliance et de la Horde sont fortes.' WHERE l.`ID` = 8731 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Rendez-vous sur Teldrassil et trouvez l’agent de Malfurion à l’extérieur des remparts de Darnassus.' WHERE l.`ID` = 8733 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Eranikus, le tyran du Rêve' WHERE l.`ID` = 8733 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'C’est un voyage de rédemption, $ghéros:héroïne;. Si seulement j’avais succombé aujourd’hui, j’aurais péri pour une cause juste et bonne. Vous devez retrouver le fragment de sceptre vert. Vous devez purifier Eranikus de la souillure que les Dieux très anciens ont placée sur lui.$B$BRendez-vous à Darnassus. Juste devant les remparts de la ville, vous rencontrerez l’un de mes agents. Cet agent lancera l’opération et informera Tyrande de nos plans sans alerter Forteramure.$B$B<Malfurion soupire.>$B$BUne déchéance qui a mis un millénaire à s’accomplir…' WHERE l.`ID` = 8733 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Rendez-vous aux quatre portails qui ouvrent sur le Rêve d’Emeraude et récupérez un Fragment de la corruption du Cauchemar auprès de chacun d’eux. Lorsque vous aurez terminé, retournez voir le Gardien Remulos à Reflet-de-Lune.' WHERE l.`ID` = 8735 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La corruption du Cauchemar' WHERE l.`ID` = 8735 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous devez vous rendre aux quatre portails du Rêve qui se trouvent sur Azeroth. Prélevez un morceau de la corruption du Cauchemar auprès de chacun d’eux. Les draconiens qui vivent aux alentours en détiendront. Revenez me voir lorsque vous aurez récupéré ces fragments.' WHERE l.`ID` = 8735 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Invoquez et tuez un Templier d\'azur, puis allez faire votre rapport à Bor Crin-sauvage, au Fort cénarien. Pour terminer cette quête, vous devez aussi apporter le Briefing tactique I.' WHERE l.`ID` = 8737 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le templier d\'azur' WHERE l.`ID` = 8737 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Les sectateurs du Marteau du crépuscule et les nobles élémentaires qu’ils adorent représentent une menace terrible pour nos opérations en Silithus. Nous affrontons de nouveaux ennemis à l’intérieur d’Ahn’Qiraj, mais nous ne pouvons pas nous permettre de baisser notre garde vis-à-vis des ennemis de l’extérieur.$B$BTrouvez un moyen d’invoquer et de détruire un templier d’azur, puis allez faire votre rapport à Bor Crin-sauvage.' WHERE l.`ID` = 8737 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez 2 Épées d’acier lunaire à Janela Rudemartel, à l’avant-poste de la brigade de Forgefer, près de la Ruche’Zora. Vous devez aussi apporter le Briefing logistique VI pour terminer cette quête.' WHERE l.`ID` = 8781 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Des armes pour le champ de bataille' WHERE l.`ID` = 8781 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'La brigade de Forgefer a joué un grand rôle dans nos combats en Silithus. Malheureusement, une bonne partie de son matériel s’est égarée au cours du transport. Procurez-vous des armes et livrez-les à Janela Rudemartel, à l’avant-poste de la brigade de Forgefer, près de la Ruche’Zora.' WHERE l.`ID` = 8781 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
