UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Lorsque vous aurez terminé les tâches qui vous sont assignées, allez voir Vargus, le forgeron. Montrez-lui les insignes que vous aurez reçus. Il vous fournira du matériel à la hauteur de votre dévotion à notre cause.' WHERE l.`ID` = 8800 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
