UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Le veneur Leopold, à la chapelle de l’Espoir de Lumière dans les Maleterres de l’Est, veut que vous lui apportiez 30 Morceaux de démon des cryptes.' WHERE l.`ID` = 9124 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'armure de traqueur des cryptes ne se fabrique pas toute seule' WHERE l.`ID` = 9124 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Ça vous dirait de gagner une de ces jolies pièces ?$B$B<Leopold vous montre un insigne de la Croisade.>$B$BJ’ai un petit souci et vous pourriez peut-être m’aider à le résoudre, $n. Je fabrique des armures de traqueur des cryptes pour ceux qui sont assez fous pour s’aventurer dans Naxxramas. Bien qu’ils me fournissent l’essentiel du matériau de base pour réaliser ces armures, je manque continuellement de morceaux de démon des cryptes. Apportez-moi un bon paquet de ces morceaux et je vous les paierai avec un insigne, utilisable auprès des intendants.' WHERE l.`ID` = 9124 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Livrer 9 Ceintures corrompues en cuir et la Commission d’artisan - Ceintures corrompues en cuir au maître-fourrier Navrepierre, à la chapelle de l’Espoir de Lumière dans les Maleterres de l’Est.' WHERE l.`ID` = 9186 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Commission d\'artisan - Ceintures corrompues en cuir' WHERE l.`ID` = 9186 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
