UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Mataus la Voix du courroux, à la chapelle de l’Espoir de Lumière dans les Maleterres de l’Est, veut 10 Insignes de la Croisade et 30 pièces d’or.' WHERE l.`ID` = 9211 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La Garde-glace' WHERE l.`ID` = 9211 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Ah, la Garde-glace. C’est une fine couche de magie protectrice qui recouvre certaines pièces d’équipement. Ceux qui se battent contre les créatures de glace ou de givre gagnent une protection améliorée contre leurs attaques en utilisant la Garde-glace.$B$BComme pour chaque chose que fabrique la Voix du courroux, il y a un prix à payer... Un prix qui ne baissera pas, même si vous passez la journée à geindre ! Alors, ça vous intéresse ?' WHERE l.`ID` = 9211 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Mataus la Voix du courroux, à la chapelle de l’Espoir de Lumière dans les Maleterres de l’Est, veut 10 Insignes de la Croisade et 30 pièces d’or.' WHERE l.`ID` = 9213 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'Ombregarde' WHERE l.`ID` = 9213 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Une idée de génie ! Suivant le même principe que la Garde-glace, l’Ombregarde se présente comme une fine couche de magie protectrice qui recouvre certaines pièces d’équipement. Et comme la Garde-glace, elle va vous coûter un gros paquet de fric.$B$B<Mataus tend la main et se frotte les doigts.>$B$BÇa vous intéresse ?' WHERE l.`ID` = 9213 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'En échange de 75 Insignes de l\'Aube et 75 Insignes de la Croisade, vous pouvez choisir un objet du trésor de guerre de l\'Aube d\'argent.' WHERE l.`ID` = 9224 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Armes de bataille épiques - Honoré auprès de l\'Aube' WHERE l.`ID` = 9224 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Salutations, $gami:amie;. Avez-vous des insignes de l\'Aube ou de la Croisade que vous aimeriez échanger contre des objets d\'une grande puissance ?$B$BIl faut que je vous prévienne : si vous faites un achat alors que votre niveau de réputation auprès de l\'Aube est Honoré, vous paierez un très gros supplément. Je vous conseille d\'améliorer votre réputation auprès de l\'Aube avant d\'aller plus avant dans vos projets.' WHERE l.`ID` = 9224 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Entrez dans Naxxramas et découvrez le Destin de Ramaladni.' WHERE l.`ID` = 9229 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le destin de Ramaladni' WHERE l.`ID` = 9229 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Ramaladni était un guerrier de la Confrérie, et un élève du généralissime Mograine avant même la création de l’Aube ! Quand il a appris la nouvelle de la mort de Mograine, il a été submergé par la colère et la haine.$B$BComprenez-moi bien, $n, quand on laisse la rage et la vengeance prendre les rênes, on cesse d’être un être humain. On devient la personnification des émotions qui nous contrôlent. Et c’est ainsi que Ramaladni, esprit du châtiment, est entré dans Naxxramas pour satisfaire sa vengeance... et n’est jamais revenu.$B$BAllez dans Naxxramas et découvrez ce qui est arrivé à Ramaladni.' WHERE l.`ID` = 9229 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Korfax, à la chapelle de l’Espoir de Lumière dans les Maleterres de l’Est, veut que vous lui rameniez 1 Rune de givre, 1 Saphir bleu et 1 Barre d’arcanite.' WHERE l.`ID` = 9230 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'étreinte de glace de Ramaladni' WHERE l.`ID` = 9230 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Réparer cet anneau pourrait bien être un vrai défi, $n. Il a été fabriqué à partir des runes que l’on trouve sur les bâtiments du Fléau, comme Naxxramas. D’autres objets sont nécessaires, mais votre premier souci doit être de récupérer ces runes de givre. Si vous me fournissez ce dont j’ai besoin, cet anneau retrouvera sa gloire première.' WHERE l.`ID` = 9230 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Echanger les bons iCoke' WHERE l.`ID` = 9273 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
