UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Remettez l’Amulette d’elfe de sang au redresseur de torts Aldar, au Point d’impact du val d’Ammen.' WHERE l.`ID` = 9308 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]Des restes d\'elfe de sang ?' WHERE l.`ID` = 9308 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous êtes $gsûr:sûre; que les restes mutilés qui gisent sur le sol sont ceux d’un sin’dorei : un elfe de sang. À en juger par ses blessures, il semble qu’il soit tombé sous les griffes des chouettides mutants qui vivent dans le fourré.$B$BEn fouillant le corps, vous découvrez qu’il porte une amulette autour du cou. Elle intéresserait peut-être le redresseur de torts Aldar.' WHERE l.`ID` = 9308 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
