UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Récupérez une Essence de marcheur du Vide puissante sur l’un des Marcheurs du vide vengeurs, puis retournez voir Taleris Mirelaube au Guet de l’épervier.' WHERE l.`ID` = 9377 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Assoiffés de puissance' WHERE l.`ID` = 9377 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Le Guet de l’épervier sert d’étape aux pèlerins lors de leur long voyage vers l’Outreterre. Nous sommes au début de la route, et pourtant, lorsqu’ils nous rejoignent, la plupart sont épuisés et rongés par leur dépendance à la magie.$B$BDans un monde comme celui-ci, nombre d’entre eux éprouvent le besoin de réapprendre à la contrôler. La nourriture et la boisson les aident, $c, mais l’énergie magique est leur principal besoin. Les restes de marcheurs du Vide de l’Outreterre fournissent une source d\'énergie efficace, mas ils se font rares et ne se trouvent que dans les champs de distorsion au sud-ouest.' WHERE l.`ID` = 9377 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parlez à l’éclaireur Kariel, le maître des voleurs, à l’intérieur de la Flèche solaire de l’île de Haut-Soleil.' WHERE l.`ID` = 9392 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La formation de voleur' WHERE l.`ID` = 9392 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Ne manquez pas de profiter de l’entraînement d’un maître si vous voulez progresser dans votre classe. Pour les jeunes voleurs sur l’île de Haut-Soleil, le maître est l’éclaireur Kariel. Parlez-lui et voyez ce qu’il peut vous apprendre. Tout ce qu’il enseigne a un coût, n’oubliez donc pas d’apporter un peu d’argent.$B$BComme tous les maîtres de l’île de Haut-Soleil, Kariel se trouve à l’intérieur de la Flèche solaire, au rez-de-chaussée.' WHERE l.`ID` = 9392 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
