UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Maintenant que vous avez récupéré la marque du Porteur de Lumière, il ne nous reste plus qu’à la rapporter à la tombe d’Uther.$B$BAccepteriez-vous de m’accompagner là-bas pour ce faire ? Ce n’est pas loin, et j’apprécierais beaucoup votre compagnie. Ensuite, vous pourrez revenir ici et raconter votre expérience à la grande prêtresse MacDonnell.$B$BQu’en dites-vous, $n ?' WHERE l.`ID` = 9446 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Tuez 3 Perdus maudits avant de retourner voir l’anachorète Avuun au Havre boueux, dans le marais des Chagrins.' WHERE l.`ID` = 9448 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]Pitié pour les maudits' WHERE l.`ID` = 9448 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Cette sorcière elfe de sang, Cersei Chantebrune, elle a maudit les Perdus, je le sais ! Je ne sais pas pourquoi ni comment, mais les résultats sont tragiques. Plusieurs des Perdus ont été corrompus, maudits par un surcroît d\'énergie gangrenée.$B$BEst-ce qu’$gun:une:c; $c ne devrait pas éprouver de la compassion pour ces pauvres créatures ? On ne peut les laisser vivre le reste de leurs jours dans un état si horrible.$B$BVous trouverez ces Perdus maudits au Sanctuaire des friches, sur le chemin vers l’est.' WHERE l.`ID` = 9448 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parlez à l’Esprit du val au Bosquet sacré du val d’Ammen.' WHERE l.`ID` = 9449 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'appel de la terre' WHERE l.`ID` = 9449 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Le temps est venu, $n. Vous avez atteint le point où vous êtes $gprêt:prête; à communier directement avec les esprits élémentaires de ce monde.$B$BMais prenez garde. Je sens que la manière dont nous sommes entrés dans ce monde, avec ses désolants effets secondaires, a mis les esprits de la terre en colère et a déséquilibré les éléments.$B$BSi vous voulez créer votre totem de terre, vous devez d’abord parler à l’Esprit du val. Vous le trouverez dans le Bosquet sacré, niché dans les collines au nord-ouest.' WHERE l.`ID` = 9449 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
