UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Keltus Sombrefeuille veut que vous fassiez les poches du Chef des Sentinelles, que vous y récupériez un Mouchoir en dentelle et que vous le lui remettiez.' WHERE l.`ID` = 9460 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
