UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Keltus Sombrefeuille, au rapport !$B$BHeu… qui êtes-vous, au fait ? Si vous voulez que je vous fasse un rapport, vous allez d’abord devoir m’aider.$B$BJ’ai l’intention d’attaquer ces Sentinelles espionnes, mais j’ai l’intention de laisser ma fidèle Murmure frapper la première. Elle a besoin d’une odeur pour repérer ses proies.$B$BQuelqu’un d’aussi doué que vous pourrait sûrement se faufiler là-bas et voler quelque chose au chef des Sentinelles ?' WHERE l.`ID` = 9460 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
