UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Je dois vous annoncer que le Prophète demande à vous voir. Il a entendu parler de votre succès lors de l\'épreuve que vous avez passée. La création de votre totem de feu devra attendre jusqu\'à ce que vous lui ayez parlé.$B$BC’est un honneur rare. Hâtez-vous de rejoindre l’Exodar pour le rencontrer !' WHERE l.`ID` = 9461 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Allez voir Tuluun au Guet d\'Azur, sur l’île de Brume-azur.' WHERE l.`ID` = 9462 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
