UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '$n ! Le temps est venu pour vous de progresser dans votre découverte des voies des esprits. Allez voir Tuluun, le chaman du Guet d\'azur. Il pourra commencer votre initiation à la compréhension et à la maîtrise de la puissance des flammes.' WHERE l.`ID` = 9462 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parlez à Hargne à la clairière des braises, sur l\'île de Brume-d\'azur.' WHERE l.`ID` = 9464 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'appel du feu' WHERE l.`ID` = 9464 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Une fois de plus vous allez être $gmis:mise; à l\'épreuve. Cette fois, c\'est le chaotique élément de feu que vous devrez comprendre afin de créer un totem pour maîtriser ses énergies.$B$BEn suivant la côte vers le nord-est, on trouve un endroit sacré appelé la clairière des braises. C\'est là, au milieu des arbres carbonisés, que réside Hargne, un élémentaire de feu d’une grande puissance, celui avec qui vous devez parler.$B$BAllez le voir dès maintenant, et puissent les esprits élémentaires d’Azeroth vous accompagner.' WHERE l.`ID` = 9464 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Récupérez les Cendres d\'Arrogance et rapportez-les avec la Torche rituelle à Hargne, à la clairière des braises sur l\'île de Brume-d\'azur. N\'oubliez pas que vous pouvez utiliser l\'Orbe de retour pour vous téléporter auprès de Hargne une fois que vous aurez les cendres.' WHERE l.`ID` = 9467 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'appel du feu' WHERE l.`ID` = 9467 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Les chouettards de la tanière Aile-de-lune, sur l\'île de Brume-argent loin au sud-ouest, ont été trompés et croient qu\'Arrogance est un dieu qu\'il faut vénérer. En réalité, c\'est un élémentaire déchu dont il faut abréger les souffrances. Cette torche sera la clé de sa chute.$B$BArrogance exige régulièrement que ces chouettards brûlent une effigie en son honneur. Quand vous l\'allumerez, il viendra. Tuez-le et apportez-moi ses cendres. Puis utilisez l\'orbe qui se trouve dans la sacoche que je vais vous donner pour revenir ici.' WHERE l.`ID` = 9467 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
