UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Les anciens prestes-pattes sont des chasseurs vifs et efficaces. Lorsque vous essayerez de vous lier à l’un d’eux, il vous percevra comme une proie. Ne renoncez pas.$B$BUtilisez le bâtonnet de domptage sur l’un de ces grands félins, et chassez à ses côtés. On en trouve dans tout le bois des Chants éternels, y compris aux alentours du pavillon. Lorsque vous en aurez appris assez, revenez me voir.' WHERE l.`ID` = 9486 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Lancez Prière de Robustesse sur 6 Forestiers des Chants éternels dans la Malebrèche.' WHERE l.`ID` = 9489 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Purifier la Malebrèche' WHERE l.`ID` = 9489 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Heureusement que vous êtes là, $n. Le Fléau attaque la ville sans trêve ni repos, et avec tant de haine que je redoute de voir le moral de notre garde fléchir.$B$BAllez aussi vite que possible à la Malebrèche. Jaela et ses forestiers s’y tiennent prêts. Bénissez-les et inondez-les de la puissance de la Lumière.' WHERE l.`ID` = 9489 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parlez à Aqueuse, à l’intérieur du Récif caché, près de l’île de Brume-sang.' WHERE l.`ID` = 9501 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'appel de l\'eau' WHERE l.`ID` = 9501 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Aqueuse, une puissante élémentaire de l’eau, désire vous voir. Il semble que l’élément de l’eau souffre d’un grave déséquilibre sur l’île de Brume-sang. Cela n’a rien d’étonnant, si l’on pense aux préférences des elfes de sang pour les choses non-naturelles.$B$BAqueuse se trouve à l’intérieur d’un récif caché sous les eaux, au large de la côte nord de l’île de Brume-sang.$B$BPrenez cette potion. Elle vous aidera à la rejoindre lorsque vous serez dans l’eau, près du récif.' WHERE l.`ID` = 9501 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parlez au long-voyant Nobundo, dans le Hall de Cristal, à l’intérieur de l’Exodar sur l’île de Brume-azur.' WHERE l.`ID` = 9502 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'appel de l\'eau' WHERE l.`ID` = 9502 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Cela fait un moment que vous n’avez pas été $gmis:mise; à l’épreuve. Le long-voyant Nobundo vous réclame. Vous avez dû beaucoup progresser en sagesse, car vous êtes $gappelé:appelée; à apprendre les mystères de l’eau.$B$BVous vous rappelez où le trouver dans le Hall de Cristal à l\'intérieur de l\'Exodar, n’est-ce pas ?' WHERE l.`ID` = 9502 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Récupérer 6 Essences infectes et les remettre à Aqueuse, au Récif caché, près de l’île de Brume-sang.' WHERE l.`ID` = 9503 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'appel de l\'eau' WHERE l.`ID` = 9503 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Dans l’équilibre des éléments, l’eau est la source et la subsistance de toutes les choses vivantes. Elle donne et alimente la vie, et tous en ont besoin pour continuer à exister. Mais lorsqu’elle est polluée, elle peut aussi signifier la fin de la vie.$B$BNous devons déterminer l’étendue des dégâts. Vers le sud-ouest se trouve une étendue d’eau contaminée, que l’on appelle le Bassin souillé. Allez-y, et extrayez l’essence infecte des esprits des eaux qui y vivent.' WHERE l.`ID` = 9503 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Remplir la Gourde en peau vide et retourner voir Aqueuse, au Récif caché, près de l’île de Brume-sang.' WHERE l.`ID` = 9504 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'appel de l\'eau' WHERE l.`ID` = 9504 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'C’est pire que je ne le craignais. La corruption est extrêmement puissante. Si nous ne réagissons pas, elle risque de s’étendre aux courants océaniques et de se propager à travers tout Azeroth !$B$BIl va nous falloir un échantillon de l’eau la plus pure pour contrecarrer sa malignité. Il y a des ruines dans la partie non corrompue de cette île, au sud-est. C’est là que vivent les nagas irécailles. Allez-y et puisez à leur fontaine.$B$BServez-vous de cette gourde en peau pour récupérer l’échantillon. Hâtez-vous, $n !' WHERE l.`ID` = 9504 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez les Plans diaboliques au Redresseur de torts Vedaar au Camp de bûcherons Chanteguerre, en Orneval.' WHERE l.`ID` = 9520 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Les plans diaboliques' WHERE l.`ID` = 9520 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Le démon a laissé tomber ce parchemin qui, par le plus grand des hasards, est écrit en commun ! Les deux individus qui y sont cités, Diathorus et Gorgannon, sont les deux infâmes seigneurs de l’effroi qui dirigent les démons des environs.$B$BLes plans décrivent les préparatifs d’une attaque démoniaque sur le Chant des forêts au nord, là où les draeneï ont récemment établi un camp.$B$BCes plans intéresseraient sûrement le redresseur de torts Vedaar, au camp de bûcherons Chanteguerre.' WHERE l.`ID` = 9520 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parlez au lieutenant Coursaurore à la retraite des Pérégrins.' WHERE l.`ID` = 9617 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Aller voir les pérégrins' WHERE l.`ID` = 9617 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Le lieutenant Coursaurore, de la Retraite des pérégrins, a demandé à tous les chasseurs valides de se présenter à elle. Allez la voir, $n, ce sera bon pour vous. Coursaurore est un phare de sagesse pour tous ceux qui suivent notre voie.$B$BLa Retraite des pérégrins se trouve au sud de Lune-d’Argent.' WHERE l.`ID` = 9617 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parlez au chevalier-seigneur Vaillessang, place des Pérégrins, à Lune-d\'argent.' WHERE l.`ID` = 9677 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le chevalier-seigneur Vaillessang vous réclame' WHERE l.`ID` = 9677 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '$n, vous avez excellé dans les premières étapes de votre formation et vous êtes $gdistingué:distinguée; parmi ceux qui souhaitent devenir des chevaliers de sang. Vous êtes $gprêt:prête; à entamer la phase suivante de votre enseignement, et à cette occasion le chevalier-seigneur Vaillessang lui-même a demandé à vous parler.$B$BJe ne doute pas que le chevalier-seigneur Vaillessang souhaite vous mettre à l\'épreuve pour évaluer vos capacités et votre entraînement. Vous le trouverez au quartier général des chevaliers de sang, place des Pérégrins à Lune-d’Argent. Mes souhaits vous accompagnent, $n.' WHERE l.`ID` = 9677 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Utilisez le Calice chatoyant sur les Magistères elfes de sang pour le remplir et retournez voir le chevalier-seigneur Vaillessang à Lune-d’Argent.' WHERE l.`ID` = 9684 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Revendiquer la Lumière' WHERE l.`ID` = 9684 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Prenez ce calice, $n. Sa magie vous permettra de saisir les derniers vestiges de Lumière qui entourent ces magistères. Ils surveillaient autrefois le naaru captif et une partie de son énergie est demeurée en eux.$B$BElle suffira tout juste à rendre la vie à votre camarade défunt.$B$BNe vous en faites pas pour les magistères, $n. Je veille à ce qu’on s’occupe d’eux, et le seigneur Solanar m’assure que dame Liadrin est en ce moment même à la recherche d’une nouvelle source d’énergie.' WHERE l.`ID` = 9684 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez le Calice chatoyant rempli à l\'auberge de Lune-d’Argent et utilisez ses pouvoirs magiques pour ressusciter Sangrias Mortelame.' WHERE l.`ID` = 9685 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La rédemption des morts' WHERE l.`ID` = 9685 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Pendant que vous prépariez le calice, j\'ai envoyé un groupe d\'initiés récupérer Sangrias Mortelame. Vous le trouverez au dernier étage de l\'auberge de Lune-d\'argent avec quelqu\'un à ses côtés. Allez-y le plus vite possible et libérez les pouvoirs magiques du calice pour le ramener à la vie.$B$BLe temps presse, $n. S\'il reste mort trop longtemps, pas même la Lumière ne pourra le faire revenir à nous. Retournez me voir lorsque vous aurez ressuscité Mortelame.' WHERE l.`ID` = 9685 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Présentez-vous au maître Kelerun Deuillessang.' WHERE l.`ID` = 9690 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La deuxième épreuve' WHERE l.`ID` = 9690 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '$gInitié:Initiée; $n, vous avez travaillé dur pour maîtriser les pouvoirs de la Lumière gagnés par nos magistères. Vous avez découvert la source de nos capacités et les devoirs d’un chevalier de sang.$B$BLe temps est venu de vous soumettre à la seconde épreuve et de briguer le statut d’adepte au sein des chevaliers de sang. L’épreuve sera dirigée par le maître Kelerun Deuillessang dans un lieu situé au nord de la ville. Partez vers le nord à travers les ruines de Lune-d’Argent, puis prenez le chemin vers l’est juste avant le pont de l’île de Haut-Soleil.' WHERE l.`ID` = 9690 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Retournez voir le chevalier-seigneur Vaillessang à Lune-d’Argent.' WHERE l.`ID` = 9691 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Retour à Lune-d\'argent' WHERE l.`ID` = 9691 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Retournez à Lune-d’Argent et rendez-vous promptement auprès du chevalier-seigneur Vaillessang. Votre arrivée suffira à le tenir au courant du dénouement de cette épreuve.$B$BIl vous dira quelles sont les tâches qu’il vous reste à effectuer pour mériter pleinement le rang d’adepte. Relevez la tête, $n. Nombreux sont ceux qui se soumettent à cette épreuve, mais rares ceux qui en ressortent pour raconter leur succès.' WHERE l.`ID` = 9691 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parlez à Mahuram Sabot-robuste à Thrallmar dans la péninsule des Flammes infernales.' WHERE l.`ID` = 9733 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Prévenir le Cercle cénarien' WHERE l.`ID` = 9733 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'L\'Expédition cénarienne est devenue une organisation de grande taille disposant d\'un large degré d\'autonomie. Ces événements sont cependant suffisamment graves pour que nous devions en informer le Cercle cénarien.$B$BNe vous inquiétez pas, je ne vous demanderai pas de vous rendre à Reflet-de-Lune. Nous avons des émissaires pas plus loin que dans la péninsule des Flammes infernales.' WHERE l.`ID` = 9733 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Retournez voir Ysiel Chantelevent au Refuge cénarien dans le marécage de Zangar.' WHERE l.`ID` = 9734 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Retour au marécage' WHERE l.`ID` = 9734 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Retournez auprès d\'Ysiel et dites-lui que nous lui offrirons de l\'aide dès que possible.$B$BDes affaires à Reflet-de-Lune et en Silithus ont tenu nos membres occupés, mais nous ferons de notre mieux pour envoyer les ressources nécessaires au Refuge cénarien.' WHERE l.`ID` = 9734 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Le seigneur Solanar Hargnessang de Lune-d\'argent veut que vous lui apportiez une fiole d\'Eau bénite de la Main de Tyr.' WHERE l.`ID` = 9735 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Les vrais maîtres de la Lumière' WHERE l.`ID` = 9735 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Un maître chevalier de sang se montre incroyablement habile dans le maniement de la Lumière, et il l\'utilise d\'une façon que les autres soi-disant « paladins » ne pourraient jamais comprendre. Cela ne les empêche pas de nous mépriser pour avoir libéré le véritable potentiel de la Lumière.$B$BNous devons leur envoyer un message pour leur montrer que l\'on ne plaisante pas avec nous. Ce que j\'ai en tête ne sera ni rapide ni facile, mais si vous êtes suffisamment $gdévoué:dévouée;, la première étape sera d\'infiltrer l\'aile de la bibliothèque de l\'Abbaye de la Main de Tyr et de vous procurer une fiole d\'eau bénite de la Main de Tyr.' WHERE l.`ID` = 9735 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Utilisez la Mixture d\'extinction près de la flamme éternelle dans la chapelle d\'Alonsus pour ôter la protection de la Lumière. Vainquez quiconque tentera de défendre la chapelle.' WHERE l.`ID` = 9737 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Les vrais maîtres de la Lumière' WHERE l.`ID` = 9737 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Notre moyen d\'utiliser la Lumière est le seul véritable, $n. Pour montrer à ces autres qui osent s\'appeler « paladins » leur égarement, j\'ai l\'intention d\'envoyer un message dont le sens ne pourra leur échapper.$B$BLa chapelle d\'Alonsus, où l\'Ordre de la Main d\'argent a été fondé, semble insensible à la destruction de Stratholme. La flamme éternelle de la chapelle lui octroie la protection de la Lumière, mais lorsque vous aurez utilisé la mixture pour éteindre la flamme, cette protection aura disparu. Elle brûlera, et notre souveraineté sur la Lumière sera prouvée à la face du monde.' WHERE l.`ID` = 9737 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parlez à la chasseresse Kella Arquenuit près de l\'Amarrage de Valaar.' WHERE l.`ID` = 9757 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Aller trouver la chasseresse Kella Arquenuit' WHERE l.`ID` = 9757 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'La chasseresse Kella Arquenuit cherche à partager son savoir auprès de tous les jeunes chasseurs qui en sont dignes. Elle est celle qui vous enseignera l\'art d\'apprivoiser les bêtes, le sujet qui devrait être votre priorité à ce stade de votre formation.$b$bVous pourrez trouver Kella près de l\'Amarrage de Valaar, les quais à l\'ouest de l\'Exodar.' WHERE l.`ID` = 9757 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez les Ordres de Luanga à Kurgatok au Fort des Brise-Pierres, dans la Forêt de Terokkar.' WHERE l.`ID` = 9985 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'hôte de la cité cachée' WHERE l.`ID` = 9985 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous êtes incapable de lire les étranges inscriptions sur le parchemin, mais il porte un sceau compliqué qui implique qu’il a été rédigé par un arakkoa de haut rang. Luanga a peut-être organisé la capture et l’interrogatoire de Dugar, mais on dirait qu’il prenait ses ordres de quelqu’un d’autre.$B$BVous vous rappelez que Rokag a dit que Kurgatok avait étudié l’arakkoa. Il pourra peut-être déchiffrer le contenu du parchemin.' WHERE l.`ID` = 9985 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez 30 Plumes d\'arakkoa à Malukaz au fort des Brise-Pierres.' WHERE l.`ID` = 9989 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Des esprits étrangers' WHERE l.`ID` = 9989 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'À mon arrivée en Outreterre, j’ai écouté les voix des esprits, et j’ai fait des découvertes stupéfiantes. Avec le temps, j’ai aussi remarqué qu’il y avait des esprits inaudibles.$B$BMalgré tous mes efforts, il m’a été impossible de prendre contact avec l’esprit d’un ancêtre arakkoa. Leur magie est complètement différente de la nôtre. Mais leurs esprits ne sont sans doute pas hors de portée.$B$BRapportez-moi les plumes de nombreux arakkoa. Cela me fournira peut-être le lien dont j’ai besoin.' WHERE l.`ID` = 9989 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Récupérez 6 Artéfacts tuurem sur les Charognards tuurem et les Chasseurs tuurem et apportez-les à Rakoria au fort des Brise-Pierres.' WHERE l.`ID` = 10032 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Artéfacts de Tuurem' WHERE l.`ID` = 10032 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Avez-vous remarqué le comportement des Perdus de Tuurem ? Ils errent dans les ruines à la recherche du moindre débris des objets fabriqués par les Draeneï.$B$BLeurs maîtres Roués sont plus intelligents. Ils ont tourné le dos à leurs anciennes vies pour devenir quelque chose de complètement différent.$B$BJe pense que nous pourrions exploiter l’obsession des Perdus et récupérer des reliques draeneï chez eux. À quoi bon risquer nos vies en combattant les Roués, alors qu’il suffit de bien choisir ses cibles ?' WHERE l.`ID` = 10032 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Traversez la Porte des ténèbres et parlez à Nazgrel à Thrallmar.' WHERE l.`ID` = 10046 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'À travers la Porte des ténèbres' WHERE l.`ID` = 10046 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Il y a deux semaines, nos éclaireurs nous ont annoncé qu’une forte troupe de l’Alliance, sous les ordres du commandant Romus, avait quitté Rempart-du-Néant. Beaucoup d’hommes et de matériel, un officier fameux… Elle ne peut avoir qu’un objectif : l’Outreterre.$B$BLe chef de guerre a expédié sa propre troupe à travers la Porte des ténèbres, mais vu ce qu’envoie l’Alliance, il serait peut-être bon d’envoyer nos propres renforts.$B$BFranchissez la Porte des ténèbres et présentez-vous à Nazgrel, à Thrallmar.' WHERE l.`ID` = 10046 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Grelag veut que vous vainquiez 12 Fantassins inflexibles, 10 Ensorceleurs inflexibles et 5 Chevaliers inflexibles à l\'Armurerie de l\'expédition, au sud du bastion de l\'Honneur.' WHERE l.`ID` = 10061 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Les Inflexibles' WHERE l.`ID` = 10061 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Quand les Gangr’orcs Mâche-les-os ont attaqué l\'armurerie de l\'expédition, la garnison est tombée très rapidement. La bataille fut sanglante et féroce et il n\'y eut aucun survivant.$B$BLes morts ont été enterrés, mais leurs esprits continuent de hanter ces ruines. J\'ai récemment reçu des visions indiquant que ces esprits pourraient bientôt devenir une menace pour Thrallmar.$B$BIl n\'y a qu\'une seule solution. Nous devons donner le repos à ces esprits. Vous devez les affronter et les vaincre.' WHERE l.`ID` = 10061 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Triomphez des fantômes de l\'archimage Xintor et du lieutenant-commandant Thalvos, puis retournez voir Grelag sur la Crête brise-échine.' WHERE l.`ID` = 10062 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Tourné vers le commandement' WHERE l.`ID` = 10062 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'En dépit de vos efforts, les perturbations continuent à l’armurerie de l’expédition. Personne ne sait au juste ce qui s’y est passé, ni ce qui lie l’esprit des soldats morts à ces ruines.$B$BNous n’avons peut-être pas choisi la bonne approche. Mes visions suggéraient que les fantômes étaient liés aux ruines. Et s’ils étaient plutôt liés à leurs chefs ?$B$BL’archimage Xintor et le lieutenant-commandant Thalvos étaient très proches de leurs hommes. Triompher de leurs fantômes pourrait suffire à apaiser les autres.' WHERE l.`ID` = 10062 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Fouillez le camp le plus au nord le long du Rempart du sud à la recherche de traces du soldat Imarion.' WHERE l.`ID` = 10122 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'À portée de la citadelle' WHERE l.`ID` = 10122 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Chaque jour, la citadelle des Flammes infernales ouvre ses portes et toujours plus de Gangr’orcs se déversent dans les camps qu\'ils ont établis le long des remparts au sud de la forteresse.$B$BJ\'ai envoyé l\'un de mes meilleurs éclaireurs, le soldat Imarion, afin qu\'il surveille leurs déplacements, leurs préparatifs et leur nombre, mais il n\'est pas revenu faire son rapport.$B$BImarion devait concentrer ses efforts sur le camp le plus au nord le long du Rempart du sud, près de l\'endroit où il rejoint la Citadelle. Trouvez-le, $n. Sans les informations qu\'il possède, nous sommes des cibles faciles.' WHERE l.`ID` = 10122 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Fouillez le camp le plus au nord le long du Rempart du nord à la recherche de traces de l\'éclaireuse Makha.' WHERE l.`ID` = 10150 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'À portée de la citadelle' WHERE l.`ID` = 10150 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Chaque jour, la citadelle des Flammes infernales ouvre ses portes et toujours plus de Gangr’orcs se déversent dans les camps qu\'ils ont établis le long des remparts au sud de la forteresse.$B$BJ\'ai envoyé l\'une de mes meilleures pisteuses, l\'éclaireuse Makha, afin qu\'elle surveille leurs déplacements, leurs préparatifs et leur nombre, mais elle n\'est pas revenue faire son rapport.$B$BMakha devait concentrer ses efforts sur le camp le plus au nord le long du Rempart du nord, près de l\'endroit où il rejoint les rochers. Trouvez-la, $n. Sans les informations qu\'elle possède, nous sommes des cibles faciles.' WHERE l.`ID` = 10150 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Tuez 10 Gardes de la Main-Brisée, 10 Berserkers de la Main-Brisée et 5 Acolytes de la Main-Brisée, puis faites votre rapport au garde de pierre Ambelan au Poste de Brise-échine près de Zeth\'Gor.' WHERE l.`ID` = 10152 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le flanc ouest' WHERE l.`ID` = 10152 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'En plus d\'autres instructions, ces ordres commandent aux Gangr’orcs restants de préparer leur équipement et leurs paquetages pour une attaque à venir.$B$BD\'après les plans, les forces de Nekrogg le Mène-guerre doivent constituer le flanc ouest d\'une attaque en tenaille sur Thrallmar.$B$BLa garnison de la ville se concentre sur le mur oriental, et une attaque de l\'ouest serait dévastatrice. Thrallmar ne peut espérer tenir que si les forces de l\'ouest sont tenues à l\'écart de la bataille.' WHERE l.`ID` = 10152 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez 30 Plumes d\'arakkoa à Malukaz au fort des Brise-Pierres.' WHERE l.`ID` = 10196 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Plus de plumes d\'arakkoa' WHERE l.`ID` = 10196 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'J\'ai réussi à attirer les esprits arakkoa plus près de moi, mais ils se montrent toujours très timides. Peut-être que si j\'améliorais mon déguisement, ils m\'approcheraient plus volontiers pendant la transe.$B$BMais pour cela, il me faudrait davantage de plumes comme celles que vous m\'avez déjà apportées. Si vous deviez trouver plus de plumes, je serais très heureux de vous en débarrasser.' WHERE l.`ID` = 10196 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Tuez 15 Sapeurs gan\'arg et retournez voir le contremaître Razelcraz.' WHERE l.`ID` = 10214 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Mineur, tu dors, ton wagon va trop vite' WHERE l.`ID` = 10214 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'La mine a été envahie par une bande de voyous gan’arg, et par-dessus le marché, les péons ont décidé que c\'était l\'heure de la sieste ! Je ne sais pas comment ils peuvent dormir avec tout le boucan qui vient de la mine, mais ce n’est pas mon problème.$B$BSi on ne se débarrasse pas vite de ces fichus gan’arg, Thrallmar tombera à court de minerai. J’ai déjà demandé de l’aide au commandant de la garde Krunk, mais il m’a dit qu’il ne pouvait pas m\'envoyer d’hommes, la ville étant attaquée sans arrêt. Acceptez-vous de me donner un coup de main ?' WHERE l.`ID` = 10214 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Tuez 6 Gangregardes de l\'invasion et retournez voir l\'émissaire de l\'Aube d\'argent Fièrepuits.' WHERE l.`ID` = 10259 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Dans la brèche' WHERE l.`ID` = 10259 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Les combats font rage sans cesse à la Porte ! L\'Aube d\'argent livre une bataille désespérée, et si nous perdons, alors le feu démoniaque ne connaîtra plus de fin.$B$BAidez-nous, $n. Pénétrez dans la brèche et apportez votre aide à nos frères et sœurs. Aidez-les à endiguer le raz-de-marée des ténèbres ! L\'Aube d\'argent a besoin de vous. Le monde a besoin de vous !' WHERE l.`ID` = 10259 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Retournez voir le jeune dragon Andormu, aux Grottes du temps dans le désert de Tanaris.' WHERE l.`ID` = 10285 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Retour vers Andormu' WHERE l.`ID` = 10285 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Cette voie temporelle a été rétablie et l\'assaut du Vol Infini contre Hautebrande a été écrasé.$B$BRetournez voir Andormu sur-le-champ. Il attend votre venue dans le repaire du maître.' WHERE l.`ID` = 10285 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Allez parler à Jol, au Sanctum des anachorètes de l\'Exodar.' WHERE l.`ID` = 10366 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'La voie de la Lumière et de la pureté n\'est guère aisée, $n. Même moi, je dois parfois lutter pour la suivre.$b$bVous devriez rendre visite à mon maître, Jol, à l\'Exodar. Elle m\'a formé au début de mon voyage, et je pense qu\'elle trouvera en vous $gun nouvel:une nouvelle; élève $gpréféré:préférée;.$b$bVous trouverez Jol sous la Voûte des lumières de l\'Exodar au Sanctum des redresseurs de torts, une pièce entourée d\'une lumière étincelante.' WHERE l.`ID` = 10366 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à Yorus Brasselorge à l\'Auberge de Comté-du-Lac, dans les Carmines.' WHERE l.`ID` = 10371 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Yorus Brasselorge' WHERE l.`ID` = 10371 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Un guerrier nain nommé Yorus Brasselorge a lancé un défi à tous les bons guerriers de l\'Alliance.$B$BIl attend à l\'Auberge de Comté-du-Lac, dans les Carmines, dans les Royaumes de l’est. Le voyage sera peut-être long, mais si vous voulez vous mettre à l’épreuve, $n, il peut en valoir la peine.' WHERE l.`ID` = 10371 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Trouvez le commandant Ashlam Vaillepoing. Il s\'est installé au Camp du Noroît, au nord des montagnes d\'Alterac.' WHERE l.`ID` = 10373 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Un appel aux armes : les Maleterres' WHERE l.`ID` = 10373 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Oyez ! Oyez ! Héros, écoutez bien ce message !$B$BLe royaume de Hurlevent appelle à prendre les armes ! Tous les individus en état de se battre sont priés de prendre les armes contre la sombre menace du Fléau dans les terres du nord des royaumes de l\'Est ! Les rumeurs parlent d’une nouvelle incursion venant des ruines des Maleterres !$B$BHéros du royaume, allez trouver le commandant Ashlam Vaillepoing qui s\'est établi au camp du Noroît, au nord des Montagnes d\'Alterac !' WHERE l.`ID` = 10373 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Partez à la recherche du Grand exécuteur Derrington. Son camp de base se trouve à la Barricade, à l’est des Clairières de Tirisfal et de Fossoyeuse.' WHERE l.`ID` = 10374 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Un appel aux armes : les Maleterres' WHERE l.`ID` = 10374 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Héros du royaume, écoutez-moi ! La Horde vous somme d\'agir vite !$B$BLa mobilisation générale de tous les individus valides a été lancée pour prendre les armes contre le Fléau ! Des rumeurs annoncent de nouvelles menaces venant des ruines des royaumes de l\'Est. L\'ennemi serait à l\'est de Fossoyeuse, dans les marches septentrionales de la région aujourd\'hui appelée les Maleterres !$B$BHéros du royaume, présentez-vous au grand exécuteur Derrington, qui a installé son camp de base à la Barricade, à l\'est des clairières de Tirisfal !' WHERE l.`ID` = 10374 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Les perles de guerre en obsidienne' WHERE l.`ID` = 10375 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous avez fait vos preuves auprès de mon peuple, $n. Il est temps à présent de montrer que vous êtes $gprêt:prête; à rester à nos côtés, même face au plus fort des ennemis.' WHERE l.`ID` = 10375 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Hello. You should find out about those wabbits.' WHERE l.`ID` = 10383 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parlez à Aurine Braselune en bas de la Foudreflèche, au Raz-de-Néant.' WHERE l.`ID` = 10441 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Colporter la marchandise' WHERE l.`ID` = 10441 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '<Audi baisse à nouveau la voix.>$B$BMaintenant que nous avons la marchandise, je vais envoyer la plupart des pièces à la Zone 52. Il y en a assez pour plus d\'un générateur, ce qui nous offre une occasion parfaite de faire des affaires.$B$BJ\'ai vu la représentante de l\'Expédition cénarienne en train d\'essayer de négocier. Faites-lui savoir que nous pouvons lui fournir ce qu\'elle cherche à un prix très raisonnable. Elle n\'a aucune raison de continuer à traiter avec ces fourbes d\'éthériens.' WHERE l.`ID` = 10441 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parlez au long-voyant Nobundo, dans le Hall de Cristal, à l’intérieur de l’Exodar sur l’île de Brume-azur.' WHERE l.`ID` = 10490 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'appel de l\'eau' WHERE l.`ID` = 10490 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Je sens que cela fait un moment que vous n’avez pas été $gmis:mise; à l’épreuve. Le long-voyant Nobundo vous réclame.$B$BVous avez dû beaucoup progresser en sagesse, car vous êtes $gappelé:appelée; à apprendre les mystères de l’élément eau.$B$BJ\'imagine que vous vous souvenez comment prendre le bateau depuis Auberdine à Sombrivage en Kalimdor pour retourner à l\'Exodar. Vous vous rappelez sûrement aussi de l\'endroit où se trouve le long-voyant dans le Hall de Cristal à l\'intérieur de l\'Exodar, n\'est-ce pas ?' WHERE l.`ID` = 10490 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parlez au long-voyant Nobundo, dans le Hall de Cristal, à l’intérieur de l’Exodar sur l’île de Brume-azur.' WHERE l.`ID` = 10491 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'appel de l\'air' WHERE l.`ID` = 10491 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '$n, une fois encore le long-voyant Nobundo vous réclame. Il est temps pour vous d’apprendre les secrets de l’air, le dernier des éléments !$B$BJe veux que vous sachiez que lorsque je regarde tout ce que vous avez accompli jusqu’ici, j’éprouve une grande fierté. Je sens que de grandes choses vous attendent.$B$BPrenez le bateau depuis Auberdine, à Sombrivage en Kalimdor. Traversez la mer Voilée et allez trouver le long-voyant à l\'intérieur du Hall de Cristal de l\'Exodar sur l\'île de Brume-azur.' WHERE l.`ID` = 10491 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à l’Archidruide Fandral Forteramure à Darnassus.' WHERE l.`ID` = 10520 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'aide à l\'archidruide Forteramure' WHERE l.`ID` = 10520 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Pardonnez-moi, $c, mais j\'aimerais prendre quelques instants de votre temps si la chose est possible.$B$BLe Cercle cénarien à Darnassus recherche des $gaventuriers aguerris tels:aventurières aguerries telles; que vous pour lui prêter main-forte dans des recherches capitales. Bien que je ne connaisse pas les détails, je peux vous dire que l\'archidruide Fandral Forteramure en personne mène ces recherches.$B$BSi cela vous intéresse, allez directement lui parler à l\'Enclave cénarienne à Darnassus.' WHERE l.`ID` = 10520 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Erelan, à Tranquillien, veut que vous retrouviez la Tête d\'archéologue réduite dans l\'un des coffres de Zeb\'Tela ou Zeb\'Nowa.' WHERE l.`ID` = 10548 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La triste vérité' WHERE l.`ID` = 10548 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous vous rappelez du gros marchand dont je vous ai parlé, celui qui cherchait cette bague ? Il s\'avère qu\'il a envoyé son fils, un archéologue, pour la trouver, et ça ne s\'est pas très bien passé, dans le sens qu\'ils l\'ont tué et qu\'ils ont réduit sa tête.$b$bVous allez peut-être me trouver froid, calculateur, et d\'une insensibilité rare, mais il est prêt à payer un bon paquet pour récupérer la tête de son fils. Ce serait une tâche parfaite pour vous !$b$bAvancez vers l\'est jusqu\'à ce que vous trouviez les ruines trolles de Zeb\'Tela et Zeb\'Nowa. Vous la trouverez forcément dans l\'un des coffres là-bas.' WHERE l.`ID` = 10548 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Le commandant de corps Danath Trollemort du bastion de l\'Honneur dans la péninsule des Flammes infernales veut que vous deveniez $gRévéré:Révérée; par le bastion de l\'Honneur en combattant des Gangr\'orcs à l\'intérieur des Salles brisées de la citadelle des Flammes infernales.' WHERE l.`ID` = 10558 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Révéré par le bastion de l\'Honneur' WHERE l.`ID` = 10558 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous avez fait la preuve de votre engagement pour notre cause, $n. $GUn homme tel:Une femme telle; que vous pourrait un jour devenir un grand chef.$B$BContinuez à combattre nos ennemis dans les Salles brisées, et vous gagnerez l\'admiration de mes hommes. Si vous êtes à la hauteur de mes attentes, j\'aurai des missions plus importantes à vous confier.' WHERE l.`ID` = 10558 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Nazgrel, à Thrallmar dans la péninsule des Flammes infernales, veut que vous deveniez $gRévéré:Révérée; par Thrallmar en combattant les Gangr\'orcs à l\'intérieur des Salles brisées de la citadelle des Flammes infernales.' WHERE l.`ID` = 10559 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Révéré par Thrallmar' WHERE l.`ID` = 10559 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous avez prouvé votre valeur à maintes reprises, $c. Mais d\'autres épreuves vous attendent.$B$BContinuez de combattre la Gangr\'Horde à l\'intérieur des Salles brisées de la citadelle des Flammes infernales et votre nom sera connu de chacun des partisans de Thrall sur ces terres.' WHERE l.`ID` = 10559 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'A\'dal, de Shattrath, veut que vous deveniez $gRévéré:Révérée; par les Sha\'tar en vainquant les forces de Kael\'thas à l\'intérieur du Donjon de la Tempête.' WHERE l.`ID` = 10560 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Révéré par les Sha\'tar' WHERE l.`ID` = 10560 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '<Les sonorités mélodiques et apaisantes émises par A\'dal deviennent plus sourdes, plus sombres.>$B$B<Vous contemplez soudain la grande construction naaru connue sous le nom de donjon de la Tempête. Elle est maintenant habitée par les troupes de Kael\'thas, et sa puissance est exploitée à des fins criminelles. A\'dal promet de vous confier des missions plus importantes quand vous aurez participé à la reconquête du donjon de la Tempête.>' WHERE l.`ID` = 10560 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Andormu à l\'intérieur des Grottes du temps à Tanaris veut que vous deveniez $gRévéré:Révérée; par les Gardiens du temps en continuant à défendre les évènements de Hautebrande d\'antan et du Noir marécage à l\'intérieur des Grottes du temps.' WHERE l.`ID` = 10561 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Révéré par les Gardiens du temps' WHERE l.`ID` = 10561 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous nous avez prouvé votre valeur, $R. Cette ligne temporelle n\'est pas encore en sécurité cependant.$B$BNous avons besoin de champions véritables et vous pourriez bien être $gl\'un:l\'une; d\'entre eux.$B$BContinuez à défendre les évènements du passé contre les intrus et vous obtiendrez la renommée que vous méritez.' WHERE l.`ID` = 10561 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Percez les secrets du Temple d’Atal’Hakkar pour libérer Atal\'alarion et récupérer dans sa chair la Liane putride. Retournez voir Melhar à la Barricade quand vous aurez terminé cette tâche.' WHERE l.`ID` = 10593 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Un mal ancien' WHERE l.`ID` = 10593 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Si vous souhaitez transformer ces pierres en arme contre le Fléau, vous devez vous procurer quelque chose d’aussi vil qu’elles pour les fortifier.$B$BUn mal ancien réside dans les profondeurs du temple d’Atal’hakkar au marais des Chagrins. Libérez la créature qui s\'y trouve et détruisez-la. Ne rapportez qu’une petite fraction de son incarnation à Mehlar Aubelame. Mes gardes remettront directement les fragments de pierre du Fléau à Mehlar.' WHERE l.`ID` = 10593 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La prospection des matières premières' WHERE l.`ID` = 10610 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Rendez-vous aux Grottes du temps et persuadez Medivh d’accepter votre Clé de l’apprenti réparée.' WHERE l.`ID` = 10737 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le toucher du maître' WHERE l.`ID` = 10737 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'J\'ai reconstitué la clé que j\'utilisais quand j\'étais apprenti. Apparemment, elle est entièrement fonctionnelle en tant que clé. Mais pour ce qui est d\'ouvrir Karazhan, elle n\'est peut-être qu\'un vieux bout de métal.$B$BSans le consentement de Medivh, cette clé n\'a aucune valeur. Oui, bien sûr que je sais que Medivh est mort. Cela rend les choses plus difficiles, pas impossibles.$B$BIl existe en Azeroth un endroit appelé les Grottes du temps, gardé par le Vol de bronze. Trouvez le moyen d\'y entrer, voyagez dans le temps et allez voir Medivh pour qu\'il active la clé.' WHERE l.`ID` = 10737 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez votre Bague d\'éternité à Soridormi aux Grottes du temps après être $gdevenu Exalté:devenue Exaltée; auprès de la Balance des sables.' WHERE l.`ID` = 10746 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ) Karazhan: LAB - E - Anneau Exalté - Lanceur' WHERE l.`ID` = 10746 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vos exploits dépassent mes espoirs les plus fous, $n.$B$BVous vous promenez dans et hors du temps avec autant d\'aise que tous les dragons de bronze que je connais. Votre destinée est celle d\'un pouvoir immense, et je suis plus qu\'heureuse de vous aider sur votre chemin.$B$BContinuez à servir la Balance des sables et je déchaînerai le plein potentiel de votre don.' WHERE l.`ID` = 10746 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
