UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Mon savoir alchimique est très étendu. Cela implique toutefois qu’il est de nature générale. Si vous désirez vous spécialiser, vous devrez trouver d’autres maîtres qui se consacrent à des champs d’études plus réduits.$B$BSi vous souhaitez vous spécialiser dans la transmutation, je vous conseille de rechercher l’assistance de l’éthérien appelé Zarevhi. Il réside dans la Foudreflèche, au Raz-de-Néant.$B$BSa maîtrise de la transmutation est proprement... suffocante ! Voyez ce que vous pourrez apprendre auprès de lui, mais prenez garde : les éthériens sont durs en affaires.' WHERE l.`ID` = 10907 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Protégez l\'Esprit de Clintar Marcherêve pendant qu\'il recueille les reliques d\'Aviana, puis allez trouver la Garderêve Lurosa.' WHERE l.`ID` = 10965 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
