UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '<Vous transmettez à Clintar les instructions de Morthis. Il vous écoute en opinant, mais semble visiblement inquiet.>$B$BJe ne peux pas m’extraire complètement du Rêve d’émeraude pour vous aider, mais un fragment de mon esprit va vous guider dans votre recherche des reliques. Gardez-le avec soin, $r, car il est très fragile.$B$BLe Rêve d’émeraude est devenu un endroit étrange et dangereux. Son emprise est forte, et je ne pourrai pas retrouver ma plénitude tant que le Rêve ne sera revenu à la normale. Ce que vous voyez autour de vous n’est qu’un écho de la réalité du rêve !' WHERE l.`ID` = 10965 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez les Reliques d\'Aviana à Morthis Murmedaile au Refuge cénarien dans le marécage de Zangar.' WHERE l.`ID` = 10978 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Retourner voir Morthis Murmedaile' WHERE l.`ID` = 10978 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Maintenant que nous avons récupéré les reliques, vous devez vous dépêcher de partir d\'ici. Clintar a risqué sa vie et celle des garderêves pour vous aider, $n, mais il doit maintenant consacrer toute son énergie au combat contre la puissance qui a envahi le Rêve d\'émeraude.$B$BRapportez les reliques à Morthis Murmedaile, et expliquez-lui ce que vous avez vu ici. Il pourra peut-être nous aider à identifier la force qu\'affronte Clintar.' WHERE l.`ID` = 10978 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Allez parler à Arthorn Chant-du-vent au Bosquet éternel dans les Tranchantes.' WHERE l.`ID` = 10979 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'En route pour le Bosquet éternel' WHERE l.`ID` = 10979 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Êtes-vous $gsûr:sûre; d\'avoir bien aperçu un corbeau dans le refuge des saisons ?$B$BVoilà qui est troublant. Nous ne pouvons pas faire grand-chose pour aider Clintar et les garderêves directement, mais si nous pouvons en apprendre plus sur ce qui menace le Rêve d\'émeraude, nous pourrons peut-être y mettre un terme.$B$BNous recevons des rapports qui font état d\'une résurgence d\'un ancien culte arakkoa dans les Tranchantes. Il s\'agit du culte d\'un dieu corbeau. Rendez-vous au Bosquet éternel, et allez trouver Arthorn Chant-du-vent. Il existe peut-être un lien entre ce qui se passe là-bas et dans le Rêve d\'émeraude !' WHERE l.`ID` = 10979 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Utilisez un Œil de raie de l\'éther avec votre Pierre de prophète pour voir les fantômes du culte du corbeau. Cherchez l\'esprit de Sai\'kkal l\'Ancien dans la Cime du vortex et interrogez-le au sujet du livre du corbeau, puis retournez auprès d\'Arthorn Chant-du-vent.' WHERE l.`ID` = 10980 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le Livre du Corbeau' WHERE l.`ID` = 10980 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'D\'après ce que vous me dites, les soupçons de Morthis semblent plausibles, mais nous avons besoin de certitudes.$B$BAu cours de ses recherches, Timeon a découvert des indices de l\'existence d\'un « livre du corbeau » qui aurait servi de recueil d\'écritures sacrées aux arakkoa.$B$BLes esprits arakkoa ne se révèleront pas à vos yeux. Emportez cette pierre sur les hauts pics de l\'ouest des Tranchantes, au sud du Bois aux corbeaux, procurez-vous un œil de raie de l\'éther, et combinez-les pour améliorer votre vue. Cherchez le fantôme que Timeon a identifié comme Sai\'kkal l\'Ancien.' WHERE l.`ID` = 10980 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Allez parler à la Gardienne Elaira sur la Crête du Crépuscule, en Nagrand.' WHERE l.`ID` = 10986 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Des yeux dans le ciel' WHERE l.`ID` = 10986 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Localiser les fragments du Livre du Corbeau, s\'ils ne sont pas détruits, sera bien difficile. Notre meilleur espoir est de faire appel à des yeux plus perçants que les vôtres.$B$BDans l\'ouest de Nagrand, sur la bordure est de la crête du Crépuscule, la gardienne Elaira étudie les diverses espèces d\'oiseaux de la faune locale. Allez la trouver, et voyez si elle peut vous aider à mettre à contribution l\'acuité visuelle des oiseaux.' WHERE l.`ID` = 10986 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Utilisez le Filet à crécerelles pour capturer une Crécerelle sauvage, et ramenez-la à la Gardienne Elaira sur la Crête du Crépuscule.' WHERE l.`ID` = 10987 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La chasse à la crécerelle' WHERE l.`ID` = 10987 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir la Gardienne Elaira à la Crête du Crépuscule, en Nagrand.' WHERE l.`ID` = 10987 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Les crécerelles sauvages de Nagrand ont la vue la plus perçante de tous les oiseaux de proie de la région. Mais à cause de leur petite taille, elles ont été chassées de la plupart des zones par les grands venterocs.$B$BEn général, les crécerelles font leurs nids ici, sur la crête du Crépuscule. Si vous réussissez à en attraper une, je la dresserai à dénicher les fragments de votre tablette.$B$BMais ce ne sera pas facile. Les crécerelles sont très craintives, et s\'enfuiront à votre approche. je vous suggère d\'en bloquer une dans un coin, ou d\'approcher $gcamouflé:camouflée; pour arriver à portée de lancer votre filet.' WHERE l.`ID` = 10987 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Rassemblez 8 Pierres du Corbeau à Skettis et apportez-les à Arthorn Chant-du-vent au Bosquet éternel dans les Tranchantes.' WHERE l.`ID` = 10988 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Les pierres du Corbeau' WHERE l.`ID` = 10988 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'J\'ai dressé votre crécerelle à répondre à un sifflement bien précis. Quand il en entendra le son, l\'oiseau vous rejoindra et vous guidera vers le fragment de tablette le plus proche. Arthorn nous a fait savoir que les fragments que vous cherchez sont enterrés dans la région de Skettis, au sud-est de la forêt de Terokkar, c\'est donc là que l\'oiseau vous attendra.$B$BQuand vous aurez trouvé toutes les pierres, rendez le sifflet à Arthorn et elle s\'occupera de libérer l\'oiseau dans de bonnes conditions.$B$BPassez le bonjour à Arthorn de ma part quand vous la verrez.' WHERE l.`ID` = 10988 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Terrassez le Gardien de l\'Aigle et emparez-vous de l\'Essence de l\'Aigle. Utilisez le Sifflet à crécerelle d\'Arthorn pour appeler la Crécerelle d\'Arthorn afin de transmettre la nouvelle de votre succès.$B$BSi vous perdez le Sifflet à crécerelle d\'Arthorn, retournez voir Arthorn Chant-du-vent au Bosquet éternel pour le faire remplacer.' WHERE l.`ID` = 10990 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'essence de l\'aigle' WHERE l.`ID` = 10990 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir Crécerelle d\'Arthorn.' WHERE l.`ID` = 10990 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Le Livre du Corbeau nous dit que ses fidèles avaient capturé et enchaîné les esprits de trois oiseaux rivaux dans de petits autels de pierre. Un gardien fut assigné à chaque autel, pour empêcher que les ennemis du Corbeau ne viennent délivrer les esprits.$B$BLe premier de ces autels est celui de l\'esprit de l\'Aigle. Il se trouve dans les collines au sud du lac Jorune et à l\'ouest du fort des Brise-pierres dans la forêt de Terokkar.$B$BLa tablette dit que l\'aigle s\'est battu avec bravoure, mais qu\'il a été submergé par le nombre de ses ennemis. L\'armure et l\'endurance de votre forme d\'ours conviennent bien à un tel combat.' WHERE l.`ID` = 10990 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Terrassez le Gardien de l\'Épervier et emparez-vous de l\'Essence de l\'Épervier. Utilisez le Sifflet à crécerelle d\'Arthorn pour appeler la Crécerelle d\'Arthorn afin de transmettre la nouvelle de votre succès.$B$BSi vous perdez le Sifflet à crécerelle d\'Arthorn, retournez voir Arthorn Chant-du-vent au Bosquet éternel pour le faire remplacer.' WHERE l.`ID` = 10991 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
