UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir Crécerelle d\'Arthorn.' WHERE l.`ID` = 10991 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '<L\'oiseau parle avec la voix d\'Arthorn.>$B$BLe deuxième esprit enchaîné par les disciples du corbeau était l\'Épervier.$B$BIl a été vaincu et emprisonné près de Skettis, pour que les prêtres-corbeaux ne l\'oublient pas tant qu\'ils détiendraient le pouvoir.$B$BVous trouverez l\'autel de l\'épervier sur la rive du lac Ere\'Noru, au nord-ouest de Skettis.$B$BPour vaincre son gardien, vous devrez utiliser les forces de l\'épervier à votre avantage. Employez la vitesse et la grâce de votre forme de félin pour le battre avant qu\'il n\'atteigne le sommet de sa force !' WHERE l.`ID` = 10991 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
