UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'essence du faucon' WHERE l.`ID` = 10992 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir Arthorn Chant-du-vent au Bosquet éternel, dans les Tranchantes.' WHERE l.`ID` = 10992 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '<La voix d\'Arthorn s\'adresse à vous.>Le dernier des esprits dont parle le Livre du Corbeau, qui est aussi le plus puissant, est celui du faucon. Il a été emprisonné loin de Skettis, dans un autel se trouvant sur une île isolée au sud-est d\'Auchindoun.$B$BJe pense que la description correspond à l\'île que nous appelons la halte Aile-du-chagrin.$B$BLa tablette dit que le gardien du faucon était quasiment invulnérable aux attaques des serres de l\'oiseau. Pour ce combat, renoncez aux attaques physiques au profit de la magie. Ne répétez pas l\'erreur du faucon.' WHERE l.`ID` = 10992 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez le Colis d\'Arthorn à Morthis Murmedaile au Refuge cénarien.' WHERE l.`ID` = 10993 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le retour au Refuge cénarien' WHERE l.`ID` = 10993 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Apportez les essences à Morthis Murmedaile, et exposez-lui nos découvertes sur le dieu corbeau.$B$BLui mieux que quiconque saura faire usage des essences et de ces informations pour débusquer Anzu. Hâtez-vous d\'y aller, nous ne savons pas combien de temps Clintar et les garderêves pourront tenir face aux assauts du corbeau !$B$B<Arthorn pose sa main sur votre bras avant que vous ne vous retourniez pour partir.>$B$BS\'il vous plaît, $n, dites à Morthis à quel point je vous ai $gaidé:aidée;. Je crains que mon rôle dans l\'accomplissement de ces travaux ne lui échappe !' WHERE l.`ID` = 10993 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez une Pierre de lune de Furie-du-Sud à Morthis Murmedaile au Refuge cénarien.' WHERE l.`ID` = 10994 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La chasse à la pierre de lune' WHERE l.`ID` = 10994 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Si l\'on combine les essences avec une gemme rare appelée pierre de lune de Furie-du-Sud, il sera possible d\'en déchaîner la puissance quand vous serez $gprêt:prête; à défier Anzu.$B$BLe seul problème, c\'est qu\'on ne trouve ces gemmes que sur la rive du fleuve qui se trouve en Azshara, sur les falaises près de sa source.$B$BLe dernier groupe d’elfes de la nuit qui est parti en chercher a connu un sort tragique. Leur bateau est toujours ancré dans le fleuve, près de l’endroit où ils ont aperçu la pierre de lune. Gardez les yeux bien ouverts et approchez de ce site par la terre depuis Azshara.' WHERE l.`ID` = 10994 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parlez à Morthis Murmedaile pour recevoir une Pierre de lune imprégnée d\'essence.' WHERE l.`ID` = 11011 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Une vigilance éternelle' WHERE l.`ID` = 11011 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Votre victoire sur Anzu, le dieu corbeau, est incontestablement un exploit remarquable. Je crains cependant qu\'il ne renonce pas à revenir en Outreterre.$B$BAussi longtemps qu\'il aura des fidèles ici, il recommencera. Gardez la pierre de lune imprégnée d\'essence, au cas où nous entendrions à nouveau parler d\'Anzu.' WHERE l.`ID` = 11011 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Allez parler à Mog\'dorg le Ratatiné. Il se trouve au sommet de la tour située du côté est du Cercle de sang dans les Tranchantes.' WHERE l.`ID` = 11022 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Parler à Mog\'dorg' WHERE l.`ID` = 11022 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '$GRoi:Reine; $n ! Vous parler à Mog\'dorg Ratatiné avant de partir à Ogri\'la !' WHERE l.`ID` = 11022 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez 10 échantillons d\'Étoffe du feu-sorcier à Jonathan Lecraft.' WHERE l.`ID` = 11088 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]Oublier son entraînement' WHERE l.`ID` = 11088 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir Jonathan LeCraft à l\'Île des concepteurs.' WHERE l.`ID` = 11088 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Filez-moi plein de feu-sorcier et vous oublierez tout.' WHERE l.`ID` = 11088 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Démasquez 5 Agitateurs des déserteurs puis retournez voir Calia Hastings près des quais de Theramore.' WHERE l.`ID` = 11126 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Des traîtres parmi nous' WHERE l.`ID` = 11126 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Ravie de vous rencontrer, $c. Je suis venue à Theramore pour contribuer à éradiquer le problème des déserteurs. Non seulement des hommes ont abandonné leur poste, mais certains sont revenus discrètement en ville.$B$BCes agents des déserteurs répandent des mensonges et de la propagande, dans l\'espoir de convaincre d\'autres soldats de rejoindre leurs rangs.$B$BIl y en a à pratiquement chaque poste de garde de toute la ville et des docks. Trouvez-les, démasquez-les et discréditez-les. À ce stade, en faire davantage serait prendre le risque d\'éveiller plus de sympathie pour eux.' WHERE l.`ID` = 11126 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Remettez la Propagande des déserteurs à Calia Hastings près des quais de Theramore.' WHERE l.`ID` = 11128 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Guerre de propagande' WHERE l.`ID` = 11128 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Les agents des déserteurs ne se contentaient pas de bonimenter les gardes, loin de là. Nous avons trouvé un certain nombre de tracts qu\'ils ont réussi à faire passer dans un bateau, sur les quais.$B$BLe bateau qu\'ils ont utilisé est encore à Theramore, sur le quai le plus éloigné. Si vous réussissez à vous introduire à bord et à vous emparer du reste de leurs tracts de propagande, leurs agents perdront leur outil le plus efficace. Faites attention ! L\'équipage est composé de corsaires expérimentés, et la cargaison est probablement entreposée dans les quartiers du capitaine.' WHERE l.`ID` = 11128 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Calia Hastings veut que vous distribuiez les Pamphlets trafiqués à 6 Gardes de Theramore. Ensuite, retournez la voir près des quais de Theramore.' WHERE l.`ID` = 11133 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Discréditer les déserteurs' WHERE l.`ID` = 11133 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir Calia Hastings sur l\'Île de Theramore, dans le Marécage d\'Âprefange.' WHERE l.`ID` = 11133 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'J\'ai modifié les tracts que vous avez subtilisés aux amis mercenaires des déserteurs sur les quais. Désormais, quiconque les lira aura une vue bien différente des déserteurs et de leurs intentions.$B$BSi nous en distribuons assez aux gardes, les déserteurs seront bien trop déstabilisés pour réussir à étendre à nouveau leur influence dans nos murs.$B$B<Calia vous tend un paquet de pamphlets trafiqués.>$B$BPourquoi ne pas vous y mettre pendant que je prépare la prochaine étape de notre plan ?' WHERE l.`ID` = 11133 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`AreaDescription` = 'Observation de l\'île d\'Alcaz' WHERE l.`ID` = 11142 AND l.`locale` = 'frFR' AND (l.`AreaDescription` IS NULL OR l.`AreaDescription` = '' OR BINARY l.`AreaDescription` = BINARY q.`AreaDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parlez à Cassa Cramoissaile et utilisez l’un de ses griffons pour survoler l’île d’Alcaz. Lorsque vous aurez achevé vos observations, parlez à dame Jaina Portvaillant à Theramore.' WHERE l.`ID` = 11142 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]Survoler l\'île d\'Alcaz' WHERE l.`ID` = 11142 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir Dame Jaina Portvaillant sur l\'Île de Theramore, dans le Marécage d\'Âprefange.' WHERE l.`ID` = 11142 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'On dirait que Renn a eu une bonne intuition au sujet d\'Alcaz. Nous devons inspecter l\'île, mais il nous faudrait toute une brigade pour y arriver par la force.$B$BLes défenses de Theramore ne peuvent pas se permettre une telle mobilisation, alors j\'ai négocié avec Cassa Cramoissaile, l\'apprentie du maître des griffons de Theramore, l\'utilisation d\'une de ses bêtes pour un repérage aérien d\'Alcaz.$B$BL\'île d\'Alcaz contient la clé du mystère de l\'implication des Défias dans cet enlèvement.' WHERE l.`ID` = 11142 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Présentez-vous au Capitaine Darill à la Halte nord.' WHERE l.`ID` = 11143 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]Un lien Sinistre' WHERE l.`ID` = 11143 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'J\'ai parlé à l\'inspecteur Tarem au sujet des preuves que vous avez rassemblées dans les ruines de l\'auberge du Repos ombragé. Il a l\'air certain que les traces de sabots et le bouclier que vous avez trouvés là-bas désignent le clan tauren Totem-sinistre.$B$BEt avec les rapports qui signalent un accroissement de l\'activité des Totems-sinistres dans le marécage, cela ne peut pas être une simple coïncidence. Je vais vous envoyer voir le capitaine Darill, qui est une sorte d\'expert du clan Totem-sinistre. Suivez la route hors de la ville, au nord, vers la Tour de la halte nord. C\'est le deuxième avant-poste que vous trouverez sur la route.' WHERE l.`ID` = 11143 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Le Sergent Lukas, de la Tour de la halte nord, veut que vous capturiez 6 raptors. Vous pouvez capturer des Raptors Rougefange ou des Hurleurs Rougefange, au choix.' WHERE l.`ID` = 11146 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]Rapt de raptor' WHERE l.`ID` = 11146 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Le bout de marécage au nord-est est habité par une variété particulièrement hargneuse de raptors. Ils nous ont déjà coûté la vie de plusieurs soldats pas très attentifs, mais je pense qu’on pourrait les retourner contre nos voisins du Totem-sinistre.$B$BPrenez cette corde et utilisez-la pour capturer des raptors ou des hurleurs Rougefange que vous aurez soumis. Mieux vaut ne pas tenter de capturer une de ces bestioles avant de l’avoir copieusement affaiblie en combat. Ça devrait être une sacrée baston.' WHERE l.`ID` = 11146 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Brogg de Bourbe-à-brac veut que vous apportiez le repos à 10 Esprits Cognepierre.' WHERE l.`ID` = 11159 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]Les esprits du bastion Cognepierre' WHERE l.`ID` = 11159 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Brogg a fini le totem qui va donner du repos aux esprits des amis. Quand les draconiens ils sont venus, ils ont tué tous les Cognepierres qui ont pas s\'enfui. Brogg il a s\'enfui avec le seigneur Mok\'Morokk et il avait de l\'espoir de faire une contre-attaque avec les autres Cognepierres enfuis.$B$BMais la contre-attaque est jamais venue, et les esprits des Cognepierres morts hantent encore pour Brogg et les autres. Portez ce totem au nord dans les ruines Cognepierres, et utilisez-le près des squelettes des ogres pour faire venir les esprits sur vous. Il faut tuer les esprits pour donner le repos avec les os.' WHERE l.`ID` = 11159 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez 10 Essences de draconien noir à Brogg à Bourbe-à-brac.' WHERE l.`ID` = 11161 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]L\'essence de l\'ennemi' WHERE l.`ID` = 11161 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Pour faire le totem que Brogg a besoin pour le rituel, Brogg doit avoir des essences des créatures qui ont tué les amis. La haine et la colère des ennemis, elle va faire grandir la magie de la vengeance.$B$BTrouvez des queues-cendrées ou des éclaireurs ou des plaiedécailles des Crins-de-feu, et utilisez le totem de Brogg sur leurs corps. Les draconiens ils donnent leurs essences que quand ils sont morts.$B$BCes créatures, elles sont plein dans l\'Antre des flammes au nord-ouest, et dans les ruines des Cognepierres au nord.' WHERE l.`ID` = 11161 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Plantez la Bannière cognepierre près de l’entrée du Repaire d\'Onyxia, attendez la réponse d\'Onyxia, puis rendez la bannière à Brogg de Bourbe-à-brac.' WHERE l.`ID` = 11162 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]Un défi au Vol noir' WHERE l.`ID` = 11162 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Brogg est content quand il pense qu\'il va faire sa vengeance sur les draconiens noirs dans le marécage. $n a donné beaucoup d\'aide pour préparer ça. Vous aidez encore ?$B$BPrenez la bannière du clan de Brogg et allez à l\'est jusqu\'à la caverne qui est comme une bouche de dragon. Devant la caverne, mettez la bannière des Cognepierres et donnez le défi de Brogg à Onyxia.$B$BBrogg et les Cognepierres, ils vont reprendre leur terre !' WHERE l.`ID` = 11162 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Moxie Grilledacier vous demande de dissoudre 10 limons avant de retourner la voir à l\'Épave de Beezil.' WHERE l.`ID` = 11174 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]Prévention de la corrosion' WHERE l.`ID` = 11174 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Jetez un œil à ce coin ! Ça grouille de limons. Si on ne trouve pas un moyen de les tenir, ils vont faire rouiller tous les débris et la cargaison du zeppelin !$B$BJe ne peux pas rentrer les mains vides, $c ! Aidez-moi à dissoudre ces limons avant qu’ils aient tout digéré !$B$BUne fois chargé, cet appareil pourra concentrer de l’énergie sur les limons et les faire exploser. La batterie du zeppelin, quoique fragmentée, devrait suffire à le charger. La partie qui est près de l’épave fonctionne en permanence, mais les autres morceaux sont plus imprévisibles.' WHERE l.`ID` = 11174 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez le Sang de Zul\'jin à Budd à son campement dans les Terres fantômes, à l\'extérieur de Zul\'Aman.' WHERE l.`ID` = 11178 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le sang du seigneur de guerre' WHERE l.`ID` = 11178 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Alors que vous examinez la fiole palpitante, vos pensées vous ramènent au petit bonhomme désagréable à l’extérieur de Zul’Aman.$B$BVous êtes $gimpatient:impatiente; de voir la tête que fera Budd en voyant ça !' WHERE l.`ID` = 11178 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Mordant Grimsby du manoir des Flammeroles vous demande de collecter des informations auprès de 10 Carcasses ressuscitées ou Esprits ressuscités.' WHERE l.`ID` = 11180 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Qui hante la Colline des sorcières ?' WHERE l.`ID` = 11180 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'J\'ai voyagé jusqu\'ici pour rendre visite à Jarl dans son nouveau chez-soi, et, depuis, c\'est un spectacle d\'horreur en continu ! Il se passe quelque chose de terrible ici, et il n\'est pas possible que je sois le seul à m\'en apercevoir…$B$BAvez-vous vu les fantômes et les corps qui traînent du côté de la Colline des sorcières ? J\'ai le pressentiment que si quelqu\'un sait ce qui s\'est passé ici, ce sera eux. Trouvez les esprits et carcasses ressuscités dans cette zone, donnez-leur le repos éternel en les terrassant, et voyez ce qu\'ils peuvent vous apprendre avant que ce mal ne consume Jarl !' WHERE l.`ID` = 11180 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter 9 branches de Sorbier à Mordant Grimsby au Manoir des Flammeroles.' WHERE l.`ID` = 11181 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La plaie de la sorcière' WHERE l.`ID` = 11181 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Au cours de ma carrière d’herboriste, j’ai souvent pu observer que la nature fournit de subtils remèdes aux problèmes les plus fâcheux. J’ai lu quelque part que les mages de campagne et les féticheurs utilisent fréquemment la fumée d’une plante appelée le sorbier des oiseleurs pour faire sortir le mal de sa cachette.$B$BSi c’est vrai, cela veut dire que cette plante doit pousser près des eaux peu profondes de la Colline des sorcières. Vous devriez pouvoir le reconnaître à ses larges feuilles et à sa tige centrale rouge. Rapportez-moi autant de ces plantes que vous pourrez en trouver, $n. C’est probablement notre seul espoir.' WHERE l.`ID` = 11181 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Mordant Grimsby au Manoir des Flammeroles veut que vous plantiez la torche au bout du quai et que vous abattiez tout ce qui pourrait apparaître.' WHERE l.`ID` = 11183 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Nettoyer la Colline des sorcières' WHERE l.`ID` = 11183 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'La torche est prête. Plantez-la au bout du quai et tenez-vous $gprêt:prête; à affronter ce qui surgira.$B$BJe n’ai aucune idée de ce que la fumée de la torche pourra révéler... pour autant qu’elle révèle quoi que ce soit. Je dois dire que je me méfie un peu de ce genre de magie populaire, mais nous n’avons pas le temps de trouver autre chose. Pour vous et pour Jarl, je vous souhaite bonne chance.' WHERE l.`ID` = 11183 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez la Lettre scellée à Nazeer Pique-sanglante à Mur-de-Fougères.' WHERE l.`ID` = 11186 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]Des signes de trahison ?' WHERE l.`ID` = 11186 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Trouvée sur le corps d\'un apothicaire des Réprouvés, cette lettre laisse supposer l\'existence d\'une correspondance occulte entre Fossoyeuse et les dirigeants du clan Totem-sinistre.$B$B« Pour témoignage de notre bonne foi et en symbole du lien de confiance nouvellement établi entre nous, nous détachons l\'apothicaire Cylla pour vous aider à combattre nos ennemis communs sur la terre de Kalimdor. Personne ne résistera à l\'association de nos puissances et de nos déterminations. »$B$BNazeer Pique-sanglante de Mur-de-Fougères saura peut-être quoi faire de l\'information.' WHERE l.`ID` = 11186 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez 4 récipients d’Huile de batteur à Babs Patranivelle au phare près de Theramore.' WHERE l.`ID` = 11192 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]L\'huile de batteur' WHERE l.`ID` = 11192 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Le vieux journal trouvé dans le phare indique que la lampe était alimentée par de l\'huile extraite de la graisse des batteurs qui vivent le long de la côte.$B$B<Babs fait la grimace à l\'idée d\'une technologie aussi arriérée.>$B$BJe suppose que c\'est une solution pratique, malgré son inélégance. D\'après le journal, c\'est l\'huile des batteurs des boues les plus jeunes qui donne le meilleur résultat. Ils vivent juste sous les docks de Theramore.$B$BAccepteriez-vous de m\'aider à réapprovisionner le phare en huile ?' WHERE l.`ID` = 11192 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter « Créatures ignobles des profondeurs » à Michael « Crado » Crowe sur les docks de Theramore.' WHERE l.`ID` = 11193 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]Créatures ignobles des profondeurs' WHERE l.`ID` = 11193 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Parlez à Michael « Crado » Crowe sur l\'Île de Theramore, dans le Marécage d\'Âprefange.' WHERE l.`ID` = 11193 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous savez, c\'est vraiment ahurissant, tout ce qu\'on peut trouver dans ce vieux phare. Après avoir allumé la lampe, j\'ai remarqué ce livre dans une des vieilles malles, là-haut.$B$B<Babs brandit le livre en en citant le titre avec emphase.>$B$B« Créatures ignobles des profondeurs ! »$B$BJe pense que si jamais je voyais une de ces créatures, je m\'évanouirais ! Je suis sûre qu\'il y a moyen de bien rigoler en lisant ce livre, mais je n\'ai tout simplement pas le temps en ce moment.$B$BMais il y a quelqu\'un qui apprécierait sans doute beaucoup, je pense... Le poissonnier des quais, Michael « Crado » Crowe. Il collectionne les livres anciens.' WHERE l.`ID` = 11193 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parlez à Nat Pagle au Point d’accostage de Nat, au Marécage d\'Âprefange.' WHERE l.`ID` = 11194 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]Il existe ?' WHERE l.`ID` = 11194 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Oh, je ne doute pas que Babs et vous ayez bien rigolé à la lecture des descriptions et des croquis du livre, mais avez-vous pris le temps de réfléchir au fait qu\'il puisse y avoir une part de vérité dans ces légendes ?$B$BSi vous tendez l\'oreille, je suis sûr que vous pourrez encore entendre des marins parler de Tethyr, la créature marine qui d\'après le livre vit juste ici ! Bien sûr, si vous voulez en avoir le cœur net, vous pouvez toujours demander au vieux Nat Pagle.$B$BIl tient un modeste camp de pêcheur sur une petite île de la crique du Mascaret, au sud-ouest, de l\'autre côté de la baie d\'Âprefange.' WHERE l.`ID` = 11194 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez la Poupée vaudou en lambeaux à Eskrokar à Shattrath.' WHERE l.`ID` = 11195 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Jouer à la poupée' WHERE l.`ID` = 11195 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'J’suis touché, $n, et c’est la vérité. J’me rappelle pas d’la dernière fois qu’$gun:une:r; $r a sorti Zungam du pétrin.$B$BJ’ai chipé ça sur un d’ces sauvages pendant qu’y m’enchaînait. Ça à l’air de rien, mais si ça vaut quequ’chose, mon bon ami Eskrokar saura l’dire !$B$BSi vous sortez d’ici $gvivant:vivante;, ça vaut p’têt la peine d’lui amener à Shattrath.' WHERE l.`ID` = 11195 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Remettez le Plan de bataille du Totem-sinistre à Krog, du village de Mur-de-Fougères.' WHERE l.`ID` = 11201 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]Le complot totem-sinistre' WHERE l.`ID` = 11201 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Maintenant que les activités des Totems-sinistres dans les Mille pointes ont éclaté au grand jour, beaucoup de taurens les considèrent avec suspicion. On a vu des membres de haut rang de leur clan commettre des meurtres ou des enlèvements pour servir leurs intérêts, et j\'ai bien peur que nous devenions leur prochaine cible.$B$BSabot-Noir, au nord-est, près du marais Bleu, est un nouveau camp totem-sinistre. Leurs chefs, les anciens, auront des ordres des Pitons-du-Tonnerre. Voyez si vous réussissez à vous emparer de ces ordres et à les rassembler pour apprendre quels sont les plans des Totems-sinistres.' WHERE l.`ID` = 11201 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parlez à Tabetha dans sa ferme du Bourbier.' WHERE l.`ID` = 11203 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]À la recherche de Tabetha' WHERE l.`ID` = 11203 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Les armes dont vous vous êtes $gemparé:emparée; à Sabot-Noir n\'ont jamais servi au combat au-delà de quelques passes d\'entraînement, ce qui signifie que les Totems-sinistres qui ont détruit l\'auberge du Repos ombragé sont encore dans la nature.$B$BAu sud, au cœur du Bourbier, vit Tabetha la sorcière. Bien qu\'elle soit humaine, elle s\'est comportée de manière honorable avec nous, et a même enseigné à certains de nos mages.$B$BDemandez-lui son aide pour débusquer la bande de Totems-sinistres responsables de la destruction de l\'auberge. Il ne faut pas laisser l\'Alliance penser que nous étions complices de l\'attaque.' WHERE l.`ID` = 11203 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler à Krog au village de Mur-de-Fougères.' WHERE l.`ID` = 11204 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]Retourner voir Krog' WHERE l.`ID` = 11204 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'J\'espère avoir pu vous aider, et je suis désolé de ne pas avoir plus d\'informations à vous apporter. Mes apprentis et moi produisons un tel volume d\'armes et armures qu\'il nous est presque impossible de retenir les détails concernant une pièce en particulier.$B$BNon seulement nous équipons les braves qui défendent les terres des taurens, mais les Totems-sinistres ont également un grand faible pour mon travail. Un guerrier expérimenté sait reconnaître un bon artisan.' WHERE l.`ID` = 11204 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Brûlez la Tente nord, la Tente est et la Tente nord-est du Poste de Navrecorne, puis revenez voir Tabetha dans sa ferme.' WHERE l.`ID` = 11205 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]Rasez le poste de Navrecorne !' WHERE l.`ID` = 11205 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Pas besoin d\'une scrutation magique pour voir les problèmes que posent mes nouveaux « voisins ». Et si c\'est bien le groupe qui a incendié l\'auberge du Repos ombragé, comme vous l\'affirmez, alors il n\'y a aucune raison de continuer à tolérer leur présence ici.$B$BPrenez cette torche et rasez leur campement ! Vous trouverez le poste de Navrecorne juste au nord de ma ferme, près de la route. Vous ne pouvez pas le rater : les Totems-sinistres ont merveilleusement annoncé leur présence avec ces totems qu\'ils aiment tant.' WHERE l.`ID` = 11205 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Retourner voir Krog au village de Mur-de-Fougères.' WHERE l.`ID` = 11206 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]Justice est faite !' WHERE l.`ID` = 11206 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Je doute que les Totems-sinistres abandonnent leur campagne visant à chasser les humains du marécage, même si j\'ai l\'impression que vous vous en fichez. Mais au moins, nous nous sommes chargés des coupables des crimes perpétrés à l\'auberge du Repos ombragé.$B$BAllez dire à votre chef que sa soif de vengeance a été apaisée.' WHERE l.`ID` = 11206 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Moxie Grilledacier à l\'Épave de Beezil veut que vous retrouviez 8 morceaux de Cargaison de zeppelin.' WHERE l.`ID` = 11207 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = '[PÉRIMÉ]Sauvez la cargaison !' WHERE l.`ID` = 11207 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Ce zeppelin transportait du ravitaillement pour six mois vers Bourbe-à-brac ! Bien sûr, ils ont pu faire un peu de troc pour subvenir à leurs besoins, mais ils ne tiendront pas éternellement.$B$BJ’ai été envoyée ici pour récupérer ce qui peut l’être de la cargaison, mais les débris sont éparpillés dans toute la zone de marécage. Je crains qu’il n’en reste pas grand-chose après l’accident, mais vous pourriez m’aider à récupérer ce qu’il en reste ?' WHERE l.`ID` = 11207 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parler au Major Mills sur les quais de Theramore.' WHERE l.`ID` = 11210 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
