UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Le Professeur Calvert veut que vous preniez le vol pour le Terrain d\'atterrissage de Rive-du-lac et que vous parliez au Pilote Vic, une fois rendu là-bas.' WHERE l.`ID` = 13052 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
