UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous avez bien aidé Wes à remettre la machine volante en état de marche, c\'est du bon travail.$B$BSi vous voulez continuer à nous aider, il y a une étrange formation climatique qui se dirige vers nous, venant du nord-ouest. Un pilote est prêt à travailler pour moi, mais j\'ai bien peur qu\'il n\'ait besoin d\'un copilote.$B$BSi vous vous en sentez capable, vous pouvez prendre le vol à destination du terrain d\'atterrissage de Rive-du-lac. Dites à Vic que c\'est moi qui vous envoie.' WHERE l.`ID` = 13052 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`AreaDescription` = 'Vol d\'essai' WHERE l.`ID` = 13053 AND l.`locale` = 'frFR' AND (l.`AreaDescription` IS NULL OR l.`AreaDescription` = '' OR BINARY l.`AreaDescription` = BINARY q.`AreaDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Aidez Zak Tremblerouage à réussir le Vol d\'essai.' WHERE l.`ID` = 13053 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'À la recherche de survivants' WHERE l.`ID` = 13053 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir Max « l\'Honnête » à la Chute de Bor, dans les Pics Foudroyés.' WHERE l.`ID` = 13053 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Gretchen Pfutincelle veut utiliser ma machine volante pour chercher des survivants parmi les membres de son expédition. Apparemment, elle pense qu\'ils sont gardés prisonniers dans le village au nord.$B$BMais il y a un hic. Je n\'ai pas de co-pilote. Si vous êtes $gpartant:partante;, je serais plus qu\'heureux de vous apprendre une ou deux manœuvres.$B$BQu\'en dites-vous, $n ? Ça vous tente ?' WHERE l.`ID` = 13053 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Présentez-vous à Thrall à Fort Grommash à Orgrimmar.' WHERE l.`ID` = 13257 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Héraut de guerre' WHERE l.`ID` = 13257 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Le chef de guerre a besoin de vous, $gchampion:championne;. Orgrimmar est sous loi martiale. Tous les marchands et les services ont été annulés car le chef de guerre s\'attend à un inévitable conflit.$B$BJe ne peux pas vous en dire beaucoup plus - pas pour l\'instant. Et pas ici.$B$BLe chef de guerre a ordonné que nos champions les plus puissants se présentent dans sa salle du trône. Partez maintenant, $n ! Prenez le portail vers Orgrimmar et rejoignez Thrall.' WHERE l.`ID` = 13257 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Prenez le Portail vers Fossoyeuse situé à Fort Grommash et faites votre rapport à Vol\'jin.' WHERE l.`ID` = 13266 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Une vie sans regrets' WHERE l.`ID` = 13266 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Le jour de ma mort, j\'espère être capable de dire que j\'ai vécu une vie sans regrets. Ceux qui porteront mon deuil sauront que j\'étais un chef de guerre qui a pris des décisions servant au mieux son peuple.$B$BMais cette trahison de Varimathras et Putrescin... Tout ce travail que nous avons fait réduit à néant.$B$B<Thrall laisse échapper un puissant soupir.>$B$BJustice doit être faite.$B$BDes portails pour Fossoyeuse vont être momentanément activés. Vol\'jin vous attend. Je vous rejoindrai là-bas bientôt. Ensemble, nous remettrons les choses en ordre, $n.' WHERE l.`ID` = 13266 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Aidez Thrall et Sylvanas à reprendre Fossoyeuse pour la Horde.$B$BSi vous réussissez, allez voir Thrall.' WHERE l.`ID` = 13267 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La bataille pour Fossoyeuse' WHERE l.`ID` = 13267 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'La totalité de Fossoyeuse est contrôlée par Varimathras. Nos soldats se tiennent prêts, attendant que le chef de guerre donne l\'ordre d\'attaquer.$B$BAidez la Horde à reprendre Fossoyeuse et gagnez votre place parmi nos plus grands champions ! Si vous survivez à l\'assaut, présentez-vous à Thrall.$B$BAllez voir le chef de guerre quand vous serez $gprêt:prête; à commencer.' WHERE l.`ID` = 13267 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le candidat de Pandchourie' WHERE l.`ID` = 13303 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir Jonathan LeCraft.' WHERE l.`ID` = 13303 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Récupérez le bouclier de Fordragon sur le champ de bataille à Angrathar, le Portail du Courroux, et rapportez-le au roi Varian Wrynn au Donjon de Hurlevent à Hurlevent.' WHERE l.`ID` = 13347 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Renaître de ses cendres' WHERE l.`ID` = 13347 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Notre destin est gravé dans nos âmes à notre naissance. La chute de Bolvar, bien que tragique, était inévitable.$B$BTout ce que vous pouvez faire désormais c\'est honorer votre héros, $n. Récupérez le bouclier de Bolvar sur le champ de bataille et rapportez-le à votre roi. Quand vous présenterez le bouclier à Varian, dites-lui ceci : « Tout n\'est pas perdu. Des cendres des défunts naitra une force qui unira les nations et purgera le mal de ce monde ».$B$BIl ne doit pas perdre espoir. Partez maintenant, $n. Votre peuple a besoin d\'un héros. Il a besoin de vous.' WHERE l.`ID` = 13347 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Utilisez le portail de Fort Grommash pour retourner au Donjon de Hurlevent et porter le message de Thrall au Roi Varian Wrynn.' WHERE l.`ID` = 13370 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Un coup royal' WHERE l.`ID` = 13370 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Votre champion, Bolvar, est mort en défendant notre monde. La Horde est triste face à la perte d\'un si grand héros, mais la Horde n\'était pas responsable des attaques lâches faites par Putrescin au portail du Courroux. Nous avons également perdu de grands héros à cause de cette trahison.$B$BDites à votre roi que nous ferons tout ce qui est en notre pouvoir pour conduire devant la justice les auteurs de cet acte déloyal. Nous ferons tout ce que nous pourrons pour éviter un conflit avec l\'Alliance, mais nous n\'hésiterons pas à nous défendre si on nous provoque.' WHERE l.`ID` = 13370 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Utilisez le portail vers Fossoyeuse créé dans le donjon de Hurlevent pour vous téléporter à Fossoyeuse. Présentez-vous à Broll Mantelours lorsque vous arriverez à destination.' WHERE l.`ID` = 13371 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le temps des meurtres' WHERE l.`ID` = 13371 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'J\'ai envoyé Broll et Valeera à Fossoyeuse avant que vous ne quittiez Orgrimmar. En fait, ils sont déjà à l\'entrée des égouts menant aux ruines, attendant les ordres.$B$BDame Portvaillant va ouvrir un portail menant à nos troupes postées à l\'extérieur de Fossoyeuse. Allez-y et présentez-vous à Broll. Jaina et moi vous suivrons bientôt.' WHERE l.`ID` = 13371 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'L\'Ingénieur marginal Tezzla vous demande de tuer des Soldats d\'infanterie du bombardement, des Gargouilles embusquées, des Factionnaires couvegivres et des Machines de guerre du Fléau.' WHERE l.`ID` = 13374 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Équipés pour la révolte !' WHERE l.`ID` = 13374 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '$n, seuls nos meilleurs pilotes reçoivent de telles missions, au plus profond du territoire ennemi avec uniquement le pouvoir de la technologie infraverte pour se protéger !$B$BDemandez un autre bombardier à Séhouf, et cette fois, faites-lui traverser la vallée de l\'Espoir perdu. Dans cette mission, vous avez à la fois des cibles au sol et dans le ciel, donc gardez les yeux ouverts et vos boucliers à pleine puissance !$B$BBonne chance !' WHERE l.`ID` = 13374 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`AreaDescription` = 'Aider le roi Varian Wrynn' WHERE l.`ID` = 13377 AND l.`locale` = 'frFR' AND (l.`AreaDescription` IS NULL OR l.`AreaDescription` = '' OR BINARY l.`AreaDescription` = BINARY q.`AreaDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Aidez le Roi Varian Wrynn et Dame Jaina Portvaillant à conduire le Grand apothicaire Putrescin devant la justice ! Retournez voir le Roi Varian Wrynn si vous réussissez.' WHERE l.`ID` = 13377 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La bataille pour Fossoyeuse' WHERE l.`ID` = 13377 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir le Roi Varian Wrynn au Donjon de Hurlevent, à Hurlevent.' WHERE l.`ID` = 13377 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Dans les profondeurs des entrailles de Fossoyeuse se cache l\'assassin responsable de la mort de Bolvar et de nos courageux soldats au portail du Courroux.$B$BVarian a amené avec lui la pleine puissance de l\'Alliance pour participer à la curée. Rejoignez-le et dame Portvaillant dans cette chasse à l\'homme et gagnez votre place parmi les plus grands champions de l\'Alliance !$B$BParlez au roi Varian Wrynn quand vous serez $gprêt:prête;.' WHERE l.`ID` = 13377 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Kibli Killohertz vous demande de tuer des Soldats d\'infanterie du bombardement, des Gargouilles embusquées, des Factionnaires couvegivres et des Machines de guerre du Fléau.' WHERE l.`ID` = 13381 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Une nouvelle cible' WHERE l.`ID` = 13381 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Mettez vos chaussettes porte-bonheur, $n, et faites vos prières. La prochaine mission mettra votre esprit et votre courage à l\'épreuve, comme le ferait une visite de la belle-famille !$B$BDemandez un autre bombardier à Karen No. Conduisez-le au-delà du Bombardement, au-dessus de la vallée de l\'Espoir perdu. Vous aurez plus de cibles cette fois, à la fois sur terre et dans les airs. Gardez vos boucliers levés et vos armes chargées, $n ! Je vous verrai quand ça sera fait.' WHERE l.`ID` = 13381 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Kibli Killohertz vous a demandé de tuer 50 Soldats d\'infanterie du bombardement, 20 Gargouilles embusquées, 12 Factionnaires couvegivres et 12 Machines de guerre du Fléau.' WHERE l.`ID` = 13382 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Objectif Killo : la vallée de l\'Espoir perdu' WHERE l.`ID` = 13382 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Le combat continue ! Vos nouveaux ordres sont arrivés : une mission de bombardement à longue distance passant par le Bombardement et la vallée de l\'Espoir perdu. Lorsque vous serez $gprêt:prête;, demandez un bombardier à Karen, et faites pleuvoir bombes et fusées sur le Fléau !' WHERE l.`ID` = 13382 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'L\'Ingénieur marginal Tezzla vous a demandé de bombarder 50 Soldats d\'infanterie du bombardement, 10 Capitaines du bombardement et 20 Gargouilles embusquées.' WHERE l.`ID` = 13406 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Profiter de l\'onde : le Bombardement' WHERE l.`ID` = 13406 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous avez envie de vous échauffer avec une petite mission de bombardement ? Voici vos ordres. Nos bombardiers sont appareillés.' WHERE l.`ID` = 13406 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Votre Jeune peau-de-venin veut que vous le nourrissiez de 12 Œufs de silithide.' WHERE l.`ID` = 13916 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Pochés, brouillés ou crus ?' WHERE l.`ID` = 13916 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'L\'estomac du jeune peau-de-venin gargouille, tandis qu\'il gesticule pour attirer votre attention. Il commence à gribouiller des dessins de silithides dans la poussière, puis ajoute des ovales au-dessous d\'eux. Le ravasaure vous regarde avec espoir en montrant les cercles.$B$BIl ne peut s\'agir que d\'œufs de silithides. Le Repaire nuisible, dans l\'ouest de Tanaris, près de la frontière du cratère d\'Un\'Goro, sera probablement l\'endroit idéal pour trouver les œufs qui font tant envie à votre peau-de-venin.' WHERE l.`ID` = 13916 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Votre Jeune peau-de-venin veut que vous le nourrissiez de 10 morceaux de Viande de silithide.' WHERE l.`ID` = 13917 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Des larves gorishi' WHERE l.`ID` = 13917 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Le jeune peau-de-venin vous regarde avec espoir, puis commence à dessiner dans la poussière.$B$BLes dessins du jeune ravasaure semblent représenter divers gros insectes, peut-être les silithides gorishi. Le raptor finit son gribouillage, puis le montre d’un geste de son petit bras, fait claquer ses mâchoires et se lèche les babines.$B$BIl doit vouloir que vous vous rendiez dans la Balafre sinueuse, au centre de la région sud du cratère d\'Un\'Goro, et que vous récupériez de la viande de silithide. Lorsque vous aurez la viande, donnez-la à manger à votre jeune peau-de-venin affamé.' WHERE l.`ID` = 13917 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Collectez 6 Gangremousses.' WHERE l.`ID` = 13939 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Les petits bonshommes en gangremousse' WHERE l.`ID` = 13939 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir Tarindrella à Sombrevallon.' WHERE l.`ID` = 13939 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'J’espérais ne jamais devoir revenir à Teldrassil pour une si triste tâche. J’espérais que la corruption aurait complètement disparu. Mais quelque chose d’innommable subsiste.$B$BLa corruption des gangremousses pernicieuses menace toujours de retourner contre nous de paisibles créatures. Les grells et les grellides ont encore investi les lieux et menacent les résidents de Sombrevallon.$B$BAttaquez les grells et les grellides, $n, et voyez s’ils ont bel et bien été victimes des sortilèges de la gangremousse pernicieuse. Quand nous serons sûrs de ce qu’il en est, nous saurons comment procéder.' WHERE l.`ID` = 13939 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez la Glande à venin congestionnée à Dirania Brillargent au pied d\'Aldrassil.' WHERE l.`ID` = 13941 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
