UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Githyiss la Vile était connue pour posséder un venin plus violent que celui des autres Tissebois. Dirania Brillargent, au pied d’Aldrassil, pourra certainement fabriquer un antidote très puissant à partir de la glande à venin congestionnée de Githyiss. Elle pourrait même vous offrir une récompense…' WHERE l.`ID` = 13941 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parlez à Gwen Armstead à Triste-bourg.' WHERE l.`ID` = 13972 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
