UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Votre mission, si vous arrivez à lire ceci alors que je suis en combat, consiste à tuer cinq de ces maudits kobolds qui me maintiennent tout le temps en combat.$B$BRien que le fait de pouvoir lire ceci est une grande VICTOIRE ! Dan est génial, pas vrai ?!!' WHERE l.`ID` = 13996 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'ELM Cible d’hébétement veut que vous tuiez 5 ELM attaquants pour Dan et la Grande Justice !' WHERE l.`ID` = 13997 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
