UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Dan est le programmeur le plus génial du monde... du monde de Warcraft !$B$BCe n’était bizarre que vous ne soyez pas capable de discuter avec moi pendant que je me battais ? C’est fini, mon ami, car Dan a largement amélioré l’un de mes flags de créature !$B$BFêtez cela avec moi en dégommant ces immondes créatures qui viennent sans arrêt me combattre.' WHERE l.`ID` = 13997 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
