UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Atteignez le Niveau 3 pour apprendre la Charge. Ensuite, exercez-vous à utiliser la Charge contre un Worgen croc-de-sang.' WHERE l.`ID` = 14266 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'À la charge !' WHERE l.`ID` = 14266 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous êtes toujours en vie, $n ! Ça en dit long sur mon enseignement !$B$BEt encore, nos leçons ont été interrompues. Mais à mesure que vous apprendrez par vous-même, vous découvrirez de nouvelles techniques.$B$BAllez donc gagner plus d’expérience, apprenez une nouvelle compétence, puis essayez-la contre les worgens croc-de-sang qui sont à l’ouest.' WHERE l.`ID` = 14266 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Atteignez le Niveau 3 pour apprendre Éviscération, puis exercez-vous à utiliser Éviscération contre un Worgen croc-de-sang.' WHERE l.`ID` = 14272 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L’éviscération' WHERE l.`ID` = 14272 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Heureuse de vous voir en vie !$B$BBien sûr que non, je n’ai pas l’or que je vous dois. Vous croyez vraiment que c’est le moment de parler de ça ?$B$BJ’ai une idée ! Je peux vous apprendre un truc ou deux qui pourraient vous sauver la peau au milieu de tout ce carnage.$B$BEn apprenant à combattre, vous découvrirez de nouvelles choses. Allez gagner de l’expérience, et quand vous aurez appris une nouvelle technique, essayez-la contre les worgens croc-de-sang. Je vous observerai.' WHERE l.`ID` = 14272 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Atteignez le Niveau 3 pour apprendre la Corruption, puis utilisez-la contre un Worgen croc-de-sang.' WHERE l.`ID` = 14274 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Alors c’était vrai ! Vous êtes $gvivant:vivante; !$B$BJe n’ai jamais eu l’occasion de vous mettre au courant de ma plus grande découverte. Une fois mon entraînement commencé, la voix de Balcephoth a résonné au plus profond de mon âme… il m’a enseigné les secrets interdits de…$B$Bla corruption !$B$BPartez, accumulez de l’expérience, et vous aussi, peut-être, découvrirez un nouveau sort. Vous pourrez ensuite l’utiliser contre les worgens croc-de-sang, à l’ouest d’ici.' WHERE l.`ID` = 14274 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Atteignez le Niveau 3 pour apprendre le Tir assuré. Ensuite, exercez-vous au Tir assuré 2 fois contre un Worgen croc-de-sang.' WHERE l.`ID` = 14276 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le tir assuré' WHERE l.`ID` = 14276 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'J’ai une bonne et une mauvaise nouvelle.$B$BLa mauvaise, c’est que les bois sont encore plus infestés de worgens que la ville… Du coup, on n’a aucun endroit sûr où se planquer.$B$BLa bonne nouvelle, c’est que vous commencez à connaître la musique. Plus vous gagnez en expérience, plus vous apprenez de nouvelles choses.$B$BDès que vous aurez découvert votre première nouvelle compétence, faites-vous la main contre les worgens croc-de-sang à l’ouest.' WHERE l.`ID` = 14276 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Atteignez le Niveau 3 pour apprendre le Mot de l’ombre : Douleur, puis utilisez-le à deux reprises contre un Worgen croc-de-sang.' WHERE l.`ID` = 14279 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Apprendre le mot' WHERE l.`ID` = 14279 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous avez beaucoup à apprendre, $n. Et j’ai de nombreuses choses à vous enseigner.$B$BCependant, nous vivons des temps troublés, et j’ai bien peur que vous ne deviez découvrir beaucoup de choses par vous-même.$B$BNe craignez rien, $gmon frère:ma sœur;. La Lumière nous guidera à travers cette épreuve.

Allez, engrangez de l’expérience et apprenez une nouvelle compétence, puis utilisez-la contre les worgens croc-de-sang à proximité.' WHERE l.`ID` = 14279 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Atteignez le Niveau 3 pour apprendre la Nova de givre, puis utilisez-la contre un Worgen croc-de-sang.' WHERE l.`ID` = 14281 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Nova de givre' WHERE l.`ID` = 14281 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Une dure tâche nous attend, $n. Nous devrons lui consacrer toute notre puissance mentale sans restriction.$B$BÀ mesure que vous gagnerez en puissance, de nouveaux chemins menant aux arcanes s’ouvriront à vous. Vous développerez des sorts vous étant jusqu’alors inconnus.

Allez, accumulez de l’expérience, puis utilisez vos nouvelles connaissances contre les worgens croc-de-sang.' WHERE l.`ID` = 14281 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Atteignez le Niveau 3 pour apprendre l’Éclat lunaire, puis utilisez-le contre un Worgen croc-de-sang.' WHERE l.`ID` = 14283 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Éclat lunaire' WHERE l.`ID` = 14283 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Nous avons déjà failli connaître l’extinction, $n. Mais nous autres druides, gardiens des anciennes traditions, avons sauvé notre peuple de la famine.$B$BLorsque nous nous sommes coupés du monde extérieur et que nos récoltes n’ont rien donné, c’est notre ordre qui en a appelé à la bénédiction de la terre pour sauver la moisson.$B$BTout comme nos pouvoirs ont sauvé la moisson, en grandissant, votre puissance développera votre connexion à nos arts anciens.

Allez, travaillez vos pouvoirs, et utilisez vos connaissances ainsi acquises contre les worgens croc-de-sang.' WHERE l.`ID` = 14283 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter le Petit parchemin à Bragor Poing-de-sang, à Fossoyeuse.' WHERE l.`ID` = 14352 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Une alliance impie' WHERE l.`ID` = 14352 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir Bragor Poing-de-sang au Quartier royal, à Fossoyeuse.' WHERE l.`ID` = 14352 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Madame,$B$BVous savez exactement ce que nous sommes en train d’offrir. L’opportunité de prendre les Tarides et les terres au-delà n’est pas à négliger. Nous ne demandons que votre aide en retour. Nous ne vous demandons que votre aval pour mener nos actions dans la zone, en toute liberté.$B$BS’il vous plaît, donnez-nous l’occasion de pouvoir en discuter plus avant. Nous possédons une grande puissance, et nous sommes prêts à la partager avec ceux qui auront la sagesse de nous rejoindre. Je resterai à l’extérieur des Souilles de Tranchebauge, pour le moment.$B$BJe vous salue respectueusement,$BAmbassadeur Malcin' WHERE l.`ID` = 14352 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez la Tête de l’ambassadeur Malcin à Bragor Poing-de-sang, à Fossoyeuse.' WHERE l.`ID` = 14353 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Une alliance impie' WHERE l.`ID` = 14353 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir Bragor Poing-de-sang au Quartier royal, à Fossoyeuse.' WHERE l.`ID` = 14353 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Il paraîtrait que ce Malcin se trouve près des souilles de Tranchebauge. Il doit mourir, sans l’ombre d’un doute.$b$bMes contacts, à Orgrimmar, m’ont révélé que leurs éclaireurs avaient trouvé des traces de peste, là-dessous. Et les tranchecrins montrent aussi des signes d’infestation ; ils sont bien plus puissants. Je ne sais pas ce que le Fléau fabrique là-bas, mais il faut y mettre fin. Maintenant.$B$BTrouvez ce Malcin et tuez-le. Revenez me voir quand il sera mort.' WHERE l.`ID` = 14353 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Trouver la Lettre de recommandation d\'Astor et l\'apporter à Mennet Carkad dans le Quartier des Voleurs.' WHERE l.`ID` = 14420 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Les nécrotraqueurs' WHERE l.`ID` = 14420 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Si vous voulez rejoindre les nécrotraqueurs, la garde d\'élite de la Dame noire, vous devez prouver votre valeur.$b$bJe ne vais pas vous mentir, $n, cette tâche pourrait bien signifier votre mort.$b$bIl y a certaines choses auxquelles il faut prêter attention. J\'ai besoin des effets personnels d\'Astor Hadren, un messager qui voyage entre les Pins-Argentés et Fossoyeuse. Je vous laisse le choix de la méthode.$b$bMoins vous en saurez, mieux ça vaudra pour vous. Réussissez et je vous en dirai plus.' WHERE l.`ID` = 14420 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Le Thrall de test veut que vous tuiez un truc.' WHERE l.`ID` = 14425 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La première quête' WHERE l.`ID` = 14425 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Bonjour $n, ceci est un test. Acceptez-la et tuez des trucs.' WHERE l.`ID` = 14425 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apporter le Totem de Vent-du-faucon à Ahmo Corne-Tonnerre à Sabot-de-Sang. Suivre la route hors du camp Narache.' WHERE l.`ID` = 14437 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Les rites de la Terre-mère' WHERE l.`ID` = 14437 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir Ahmo Corne-Tonnerre à Sabot-de-Sang, en Mulgore.' WHERE l.`ID` = 14437 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Il vous faut encore subir deux épreuves pour achever les Rites de la Terre-mère. Il est temps pour vous d\'élargir votre expérience, $n.$b$bVoyagez jusqu\'au village de Sabot-de-Sang et trouvez Ahmo Corne-Tonnerre. Là, vous devrez continuer votre périple et gagner l\'approbation des aînés des Pitons-du-Tonnerre.$b$bPortez ce totem à Ahmo ; il reconnaîtra mes gravures et vous aidera dans votre quête.$b$bSuivez la route hors de Camp Narache et hâtez-vous. Ne vagabondez pas de-ci de-là, vous vous perdriez.' WHERE l.`ID` = 14437 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Obtenez une Clé grossière sur l’un des Hurans dos-hirsutes, et servez-vous-en pour ouvrir la Cage de Huran où est enfermé le Brave Corne-pointue.' WHERE l.`ID` = 14454 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le guerrier capturé' WHERE l.`ID` = 14454 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Les Hurans ont rasé nos bâtiments, mais ils ont aussi fait des prisonniers taurens. Je les ai vus s’emparer du brave Corne-pointue, l’un de nos jeunes maîtres des guerriers. Ils l’ont enfermé dans l’une de leurs immondes cages. Je vous en prie, trouvez une clé sur l’un de leurs cadavres, et sauvez-le !' WHERE l.`ID` = 14454 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Obtenez une Clé grossière sur l’un des Hurans dos-hirsutes, et servez-vous-en pour ouvrir la Cage de Huran où est enfermé Bowe Corne-de-l’Aube.' WHERE l.`ID` = 24446 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le marche-soleil capturé' WHERE l.`ID` = 24446 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Les Hurans ont rasé nos maisons, mais ils ont aussi emmené des Taurens en captivité. Je les ai vus capturer Bowe Corne-de-l’Aube, l’un de nos jeunes maîtres des paladins, et le mettre dans une de leurs cages immondes. S’il vous plaît, trouvez une clé sur le cadavre de l’un des Hurans, et allez le sauver !' WHERE l.`ID` = 24446 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Lisez la Rune investie, puis parlez à Teo Martel-tempête, à Courbenclume.' WHERE l.`ID` = 24494 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Rune investie' WHERE l.`ID` = 24494 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '$n, on m’a donné cette rune pour que je vous la donne à mon tour. Prenez le temps de la lire, à l’occasion. Je pense qu’elle vient de Teo, le maître des chamans. Jetez-y un œil, puis allez lui parler à Courbenclume.' WHERE l.`ID` = 24494 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Lisez la Rune des Arcanes, puis parlez à Teegli Merrowith, dans la Vallée des Frigères.' WHERE l.`ID` = 24496 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Rune des Arcanes' WHERE l.`ID` = 24496 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '$n, on m’a donné cette rune pour que je vous la donne à mon tour. Prenez le temps de la lire, à l’occasion. Je pense qu’elle vient de Teegli, le maître des mages. Jetez-y un œil, puis allez lui parler à Courbenclume.' WHERE l.`ID` = 24496 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Atteignez le Niveau 3 pour apprendre la Nova de givre. Réussissez à la lancer 2 fois sur les Mannequins d’entraînement, à l’entrée de Courbenclume.' WHERE l.`ID` = 24526 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Remplir le grimoire' WHERE l.`ID` = 24526 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Excellent ! Commençons, voulez-vous ?$b$bÀ mesure que vous gagnerez en puissance, votre lien aux arcanes se renforcera et vous aurez accès à de nouveaux sorts et compétences.

Allez donc accumuler de l’expérience, vous comprendrez mieux. Revenez me voir quand vous aurez découvert quelque chose, et faites-moi la démonstration de votre savoir nouvellement acquis sur ces mannequins d’entraînement.' WHERE l.`ID` = 24526 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Atteignez le Niveau 3 pour apprendre l’Éviscération, puis utilisez 3 fois cette technique sur les Mannequin d’entraînement à l’entrée de Courbenclume.' WHERE l.`ID` = 24532 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Éviscérer l’ennemi' WHERE l.`ID` = 24532 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'En gagnant en expérience, on se rend compte que de nouvelles compétences s’ouvrent à nous. 

Notamment, vous apprendrez à utiliser des manœuvres de combat pour affaiblir un adversaire, avant de lui asséner une technique dévastatrice.

Partez donc engranger de l’expérience, apprenez à utiliser cette tactique, puis essayez-la sur nos mannequins d’entraînement.' WHERE l.`ID` = 24532 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parlez à Winnoa Forêt-de-Pins aux Champs du Sang, afin de défendre les portes de Mulgore contre les assaillants.' WHERE l.`ID` = 24568 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Aux portes !' WHERE l.`ID` = 24568 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '$n, ils sont en train de se rassembler aux portes ! L’Alliance essaye de pénétrer en Mulgore. Son infanterie risque de submerger nos gardes.$B$BNous n’avons pas grand-chose pour tenir les murailles, en dehors de quelques pots d’eau bouillante… Il faudra que cela suffise à repousser les assaillants jusqu’à ce que de l’aide arrive.$B$BEn attendant, il nous faut quelqu’un pour coordonner nos défenses. Vous n’avez qu’un mot à dire et je vous donne une vue aérienne du champ de bataille.$B$BNous avons besoin de vous, $n !' WHERE l.`ID` = 24568 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Faites votre rapport à Zen\'aliri au Camp retranché des Marshal.' WHERE l.`ID` = 24688 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous avez déjà rencontré l’un de mes nouveaux étudiants, le jeune Worgen Garl. Mon autre élève est un Troll du nom de Zen’aliri. Il campe actuellement avec les explorateurs de l’expédition Marshal, à l’ouest.$b$bApportez-lui ces résultats, $n, et dites-lui de les lire attentivement.' WHERE l.`ID` = 24688 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
