UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Salutations. Moi, unité A-Mi 01. Vous… $r ?$B$BMission A-mi : étudier gorilles locaux. Mission réussie. A-mi a récolté données et maintenant, les apporter à Karna.$b$bMaintenant, temps de retourner près Karna. Vous venir ? Nous partir tout de suite si vous être $gprêt:prête;.' WHERE l.`ID` = 24716 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
