UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Après une analyse attentive de la carte, vous comprenez que vous avez découvert les plans du chef de guerre dos-hirsute pour assiéger le camp Narache.$b$bLe chef Vent-du-faucon pourrait certainement tirer profit de ces informations !' WHERE l.`ID` = 24857 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
