UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Ces suceurs de sang du Fléau qui se font appeler les San’layn me fichent la chair de poule. On avait envoyé l’un de nos meilleurs hommes pour les garder à l’œil. Mais ce matin, il a été négligent et s’est fait prendre. La reine en personne l’interroge en ce moment, et ses cris résonnent dans la salle Cramoisie. S’il vous plaît, sauvez-le avant qu’il ne soit trop tard !' WHERE l.`ID` = 24874 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez 1 tas de Guano du kraal à Zan’do, à la Halte de Pierre-feu.' WHERE l.`ID` = 24898 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Corvée de guano' WHERE l.`ID` = 24898 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Des cochons, y’a pas que ça à Tranchebauge, $gmon frère:ma sœur;. Y’a aussi des chauves-souris… Et si vous y allez de toute façon pour buter quelques hurans, pourquoi que vous me ramèneriez pas un peu de guano ?$b$bDu guano, ouais. De la fiente. Hé, me regardez pas comme ça. Ça fouette, mais c’est une substance puissante et qui est essentielle pour les rituels… Les rituels qui donnent assez de force à la terre pour pas se déchirer sous les pieds de tous les imbéciles qui jouent à la guéguerre dans le coin.$b$bZ’avez juste à apporter un tas de guano à Zan’do, dac’ ?' WHERE l.`ID` = 24898 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez 1 tas de Guano du kraal au Maître apothicaire Faranell à Fossoyeuse.' WHERE l.`ID` = 24899 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Corvée de guano' WHERE l.`ID` = 24899 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir le maître-apothicaire Faranell dans les montagnes d’Alterac.' WHERE l.`ID` = 24899 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Comme vous pouvez le constater, $n, nous préparons de très… intéressantes expérimentations à la Société royale des apothicaires.$B$BEn tant que Maître, mon travail est de superviser les plus ambitieuses de nos tentatives alchimiques. Tellement de travail et si peu de temps !$B$BVous avez l’air d’avoir beaucoup voyagé, $c. Peut-être pourriez-vous m’aider.$B$BJ’ai besoin d’une substance rare. C’est un matériau infect, qui provient d’une espèce rare de chauves-souris que l’on trouve dans la fosse connue sous le nom de kraal de Tranchebauge. Apportez-moi du guano de chauve-souris du kraal afin que nous puissions nous mettre au travail…' WHERE l.`ID` = 24899 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Tuez Meven Korgal, le messager, au Camp des croisés, et récupérez toutes les informations que vous pourrez trouver.' WHERE l.`ID` = 25033 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
