UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir l\'Exécuteur Arren au Glas, dans les Clairières de Tirisfal.' WHERE l.`ID` = 25033 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Des rapports de mes supérieurs à Brill indiquent qu\'un agent de la Croisade écarlate a été dépêché du monastère Écarlate et envoyé ici, au Glas. Selon ces rapports, le messager achemine d\'importantes informations. Je n\'ai pas plus de détails, mais quoi que ce soit dont il s\'agisse, nous devons les obtenir !$b$bVous êtes la personne la plus qualifiée que je puisse envoyer, $n. Trouvez ce messager et rapportez-moi toute information en sa possession.' WHERE l.`ID` = 25033 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Gavan Griseplume veut que vous utilisiez le sapta élémentaire et le totem de purification du sac de fournitures du Cercle terrestre pour soumettre 20 Esprits de la terre agités.' WHERE l.`ID` = 25055 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Élémentaire, mon cher…' WHERE l.`ID` = 25055 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Les éléments sont en effervescence, $c. Les tremblements de terre qui frappent la région et menacent de détruire Forgefer ne sont pas naturels. Le Cercle terrestre est convaincu que nous devons apaiser les éléments avant qu’Azeroth soit réduite à néant. Nous avons besoin de votre aide, $n. Je vais vous confier un sac de fournitures du Cercle terrestre. Il contient deux objets : du sapta élémentaire et un totem de purification. Utilisez le sapta pour voir dans le monde élémentaire, ensuite, utilisez le totem pour dominer les esprits de la terre agités.' WHERE l.`ID` = 25055 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Le Voyant Bahura veut que vous utilisiez le sapta élémentaire et le totem de purification du sac de fournitures du Cercle terrestre pour soumettre 20 Esprits de la terre agités.' WHERE l.`ID` = 25092 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Élémentaire, mon cher…' WHERE l.`ID` = 25092 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Les éléments sont en effervescence, $c. Les tremblements de terre qui frappent la région et les feux qui menacent de réduire Orgrimmar en cendres ne sont pas naturels. Le Cercle terrestre est convaincu que nous devons apaiser les éléments avant qu’Azeroth soit réduite à néant. Nous avons besoin de votre aide, $n. Je vais vous confier un sac de fournitures du Cercle terrestre. Il contient deux objets : du sapta élémentaire et un totem de purification. Utilisez le sapta pour voir dans le monde élémentaire, ensuite, utilisez le totem pour dominer les esprits du feu agités.' WHERE l.`ID` = 25092 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Écouter le discours prononcé par un Auspice funeste dans la Vieille ville et obtenir des copies des pamphlets « Feu élémentaire pour l\'âme », « Que signifie pour moi « La Fin de Toutes Choses » ? » et « Comment trouver la sécurité et le réconfort dans un monde condamné ».' WHERE l.`ID` = 25253 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Funestes auspices' WHERE l.`ID` = 25253 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Des auspices funestes à Hurlevent, ça n\'a rien de nouveau, mais les derniers arrivés m\'inquiètent. Ils se sont installés dans la Vieille ville et semblent parfaitement coordonnés.$B$BJ\'ai pensé les embarquer ou au moins interrompre leurs activités, mais ils iraient se terrer dans un coin. Nous devons en découvrir autant que possible sur eux. Pourriez-vous aller dans la Vieille ville, écouter les idées que répandent ces auspices funestes et récupérer quelques-uns de leurs pamphlets ?' WHERE l.`ID` = 25253 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Placardez 5 Affiches d\'avertissement dans la Vallée de la Force, la Herse ou la Vallée de l\'Honneur.' WHERE l.`ID` = 25254 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Ne tombez pas dans le panneau' WHERE l.`ID` = 25254 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Nous devons agir pour amoindrir l\'intérêt de ce culte de l\'apocalypse, mais j\'hésite à lancer une action avant de savoir qui se cache réellement derrière ce groupe.$B$BMes hommes ont placé des marques dans les zones très fréquentées d\'Orgrimmar. Prenez ces affiches et placardez-les partout où vous apercevez des marques. Cela ne découragera pas les plus déterminés, mais c\'est une première étape pour percer le culte à jour. La Horde a suffisamment à faire, sans que des personnes mal intentionnées répandent des mensonges délibérés.' WHERE l.`ID` = 25254 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Placardez 5 Affiches d\'avertissement dans le Quartier Commerçant, la Place de la Cathédrale, la Vieille ville ou le Quartier des Mages, à Hurlevent.' WHERE l.`ID` = 25282 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Ne tombez pas dans le panneau' WHERE l.`ID` = 25282 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Nous devons agir pour amoindrir l\'intérêt de ce culte de l\'apocalypse, mais j\'hésite à lancer une action avant de savoir qui se cache réellement derrière ce groupe.$B$BMes hommes ont placé des marques dans les zones très fréquentées de la ville. Prenez ces affiches et placardez-les partout où vous apercevez des marques. Cela ne découragera pas les plus déterminés, mais c\'est une première étape pour percer le culte à jour. Le roi a suffisamment d\'ennemis sans que son peuple se retourne contre lui.' WHERE l.`ID` = 25282 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parlez à un Auspice funeste dans la Herse d’Orgrimmar, ou volez une robe dans une caisse près d’un Auspice funeste afin de rejoindre le culte, puis revêtez votre Robe de recrue.' WHERE l.`ID` = 25288 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'infiltration du Culte' WHERE l.`ID` = 25288 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'De nombreuses rumeurs circulent dans Orgrimmar à propos de l\'origine et des pratiques du culte. Il n\'y a qu\'un seul moyen de connaître la vérité sur ce groupe, $n. Vous allez les rejoindre.$B$BRapprochez-vous de l\'un des auspices funestes de la Herse et dites-lui que vous souhaitez rejoindre son groupe. Avec un peu de chance, il vous donnera des instructions pour vous présenter à l\'un des chefs du culte et vous dira où se cachent les membres. Revêtez les vêtements que l\'auspice vous fournira probablement, vous en aurez besoin pour approcher la planque du groupe.' WHERE l.`ID` = 25288 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parlez à un Auspice funeste dans la Vieille ville de Hurlevent, ou volez une robe dans une caisse près d’un Auspice funeste pour rejoindre le culte, puis revêtez la Robe de recrue de l\'apocalypse que vous obtiendrez.' WHERE l.`ID` = 25290 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L\'infiltration du Culte' WHERE l.`ID` = 25290 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Il devient difficile d\'empêcher les sectateurs d\'approcher les habitants et des rumeurs se répandent dans toute la ville. Je veux que vous rejoigniez le culte et que vous appreniez autant de choses que possible.$B$BApprochez l\'un des auspices funestes dans la Vieille ville et dites-lui que vous souhaitez rejoindre son groupe. L\'auspice vous fournira probablement une tenue et des instructions pour rencontrer d\'autres sectateurs dans l\'une de leurs cachettes. Suivez ces instructions, $n. C\'est la seule façon de gagner leur confiance.' WHERE l.`ID` = 25290 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Revêtez le Déguisement du Culte et allez parler aux Sectateurs Kagarn, Agtar, Tokka et Rokaga à la Ferme Rêche-pourceau, en Durotar.' WHERE l.`ID` = 25293 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Disparitions' WHERE l.`ID` = 25293 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Non seulement le culte sème la zizanie et la paranoïa, mais on nous signale également de nombreuses disparitions. Des pères, des mères, des sœurs et des frères ont selon toute vraisemblance disparu, mais je suis persuadé que nous pourrions les trouver dans l\'une des bases du culte à l\'extérieur de la ville. Si je vous donne les noms de certains disparus, pourriez-vous essayer de les retrouver au camp des sectateurs à la ferme Rêche-pourceau, au sud d\'Orgrimmar ? Vous aurez besoin de la robe d\'un des auspices funestes de la Herse pour vous fondre dans la masse.' WHERE l.`ID` = 25293 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'En apprendre plus sur les plans du culte devant l\'autel à l\'est de la Ferme Rêche-pourceau.' WHERE l.`ID` = 25343 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le plan du maître' WHERE l.`ID` = 25343 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir la Surveillante Jintak à la Ferme Rêche-pourceau.' WHERE l.`ID` = 25343 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous vous intégrez parfaitement ici, $n, mais nous faisons plus que répandre la bonne parole et vaquer à nos occupations quotidiennes. Je suis certaine que vous en avez un peu entendu parler lorsque vous êtes $garrivé:arrivée;.$B$BComme vous le savez, la fin du monde arrive, et ceux qui n\'y sont pas préparés mourront dans d\'atroces souffrances.$B$BNous avons reçu un don, l\'opportunité de devenir quelque chose de plus grand et de plus puissant. Le surveillant Golbaz se prépare à entamer un rituel devant l\'autel qui se trouve juste à l\'est de la ferme. Attendez-le là-bas et apprenez-en plus sur vos nouveaux frères et sœurs.' WHERE l.`ID` = 25343 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez les Appareils élémentaires au Garde de sang Torek dans la Vallée de la Force, à Orgrimmar.' WHERE l.`ID` = 25347 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le plan de l\'apocalypse' WHERE l.`ID` = 25347 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Le premier lot d\'appareils élémentaires est prêt. Vous aurez pour tâche de les cacher dans Orgrimmar. Ces appareils libéreront des élémentaires de feu au moment opportun. Ne vous inquiétez pas, $n, vous serez loin et en sécurité lorsque cela se produira.$B$BNe faites rien qui pourrait attirer l\'attention sur vous.$B$B<La surveillante vous tend un paquet contenant plusieurs de ces appareils élémentaires. C\'est justement le genre de preuve que le garde de sang Torek espérait que vous découvririez. Vous devriez lui apporter les appareils.>' WHERE l.`ID` = 25347 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Détruisez les Appareils élémentaires pour en libérer les élémentaires prisonniers. Tuez 5 Élémentaires de feu déchaînés.' WHERE l.`ID` = 25348 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Déstabiliser le Marteau du crépuscule' WHERE l.`ID` = 25348 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous ne devez pas être la seule personne qu\'ils ont envoyée à Orgrimmar pour cacher ces appareils contenant des élémentaires de feu. Nous devons trouver et désactiver les autres appareils avant que leurs élémentaires captifs ne soient libérés et ne réduisent la ville en cendres.$B$BEn savez-vous suffisamment sur ces appareils pour les détruire ? Vous devez casser ces engins avant que les élémentaires prisonniers n\'atteignent leur puissance maximale. Ils devraient être assez faciles à vaincre si vous ouvrez les appareils avant terme. Les sectateurs en ont probablement disséminé dans toute la ville.' WHERE l.`ID` = 25348 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parlez à Garrosh Hurlenfer au Fort Grommash dans la Vallée de la Sagesse, à Orgrimmar.' WHERE l.`ID` = 25351 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Avertir nos chefs' WHERE l.`ID` = 25351 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous avez défendu avec succès Orgrimmar contre la menace que représentait le culte du Marteau du crépuscule, $n, et sans blesser un seul de nos citoyens. Cependant, nos ennemis ne resteront pas calmes bien longtemps. Cho\'Gall n\'est pas du genre à accepter facilement la défaite.$B$BGarrosh Hurlenfer est un célèbre héros de la Horde et il saura comment traiter ce problème. Allez à la vallée de la Sagesse et parlez-lui dans le fort Grommash. Dites au jeune Hurlenfer que nos ennemis se sont démasqués et que nous devons nous préparer à leur retour.' WHERE l.`ID` = 25351 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Revêtez le Message de l\'apocalypse et rendez-vous à la tour est et la tour ouest des zeppelins, ainsi que sur la place de Tranchecolline.' WHERE l.`ID` = 25380 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Répandre la bonne parole' WHERE l.`ID` = 25380 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Bienvenue dans la ferme, $n. Ici, tout le monde travaille pour gagner son pain. Certains s\'occupent des animaux, tandis que d\'autres sont responsables de nos projets de construction. D\'autres encore transmettent notre message au peuple. Je pense que ce serait un bon début pour vous.$B$BPrenez ce panneau sur lequel est inscrit un court message présentant nos convictions. Portez-le, puis rendez-vous aux tours des zeppelins à l\'est et à l\'ouest des portes d\'Orgrimmar, ainsi que sur la place de Tranchecolline, au sud.' WHERE l.`ID` = 25380 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Samir veut que vous alliez chercher 3 Morceaux de ferraille fendus dans le ventre d’Épaulards frénétiques de la Forêt de Varech’thar.$b$bVous pouvez attirer les épaulards grâce aux Entrailles de pinceur prélevées sur des Pinceurs claqueclap.' WHERE l.`ID` = 25384 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Matières premières' WHERE l.`ID` = 25384 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Merci, $c. On vous doit la vie.$b$bCependant, si nous voulons un jour revoir la surface, nous allons devoir nous battre, et cela implique de se fabriquer des armes et des armures.$b$bAvant que vous me retrouviez, j’ai vu un épaulard dévorer un soldat, entre deux eaux.$b$bJe parierais bien que si vous ouvrez le ventre de quelques-unes de ces bêtes, vous tomberez sur quantité de déchets métalliques qui pourraient m’être utiles pour fabriquer des armes.$b$bSi vous ne voulez pas nager vers la surface pour atteindre les épaulards, vous pouvez toujours en attirer ici avec quelques entrailles…' WHERE l.`ID` = 25384 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Procurez-vous le Harpon rouillé et 3 Rouleaux de corde.' WHERE l.`ID` = 25413 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Changement de plans' WHERE l.`ID` = 25413 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'D’accord, $ggamin:gamine;. Il y a un léger changement dans le plan…$b$bJe pense avoir trouvé le moyen d’achever ce monstre, et vous allez m’y aider.$b$bVoilà comment je vois les choses : vous m’êtes redevable tant que mon travail ici n’est pas terminé, et vous pouvez être $gcertain:certaine; que je ne quitterai pas cet endroit sans mon antiquité.$b$bTout d’abord, je veux que vous alliez fouiller ces épaves pour me trouver une longueur de bonne vieille corde et un harpon utilisable.$b$bEnsuite… euh, je vous expliquerai la suite le moment venu.' WHERE l.`ID` = 25413 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Prélevez 3 Tendons de requin sur des Batteurs voraces et 2 Pinces de crabe tranchantes sur des Glisseurs pince-de-sabre.$b$bLes Batteurs voraces peuvent aussi être invoqués à l’aide d’Entrailles de crabe.' WHERE l.`ID` = 25435 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Monture en écaille' WHERE l.`ID` = 25435 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Salut, camarade.$b$bMon nom à moi, c’est Rendel.$b$bOn dirait que Moanah et moi, on tombe à pic, hein ?$b$bErunak ne plaisantait pas quand il a dit que c’était une question de vie ou de mort !$b$bPendant qu’il tente de nous trouver un logement, je vais essayer de trouver une bestiole qui puisse vous servir de monture.$b$bAlors, je ne suis peut-être pas un expert de la vie sous l’eau, mais j’ai remarqué que les Nagas savent se débrouiller dans ce milieu.$b$bDégottez-moi quelques matériaux pour fabriquer des rênes et je ferai des miracles.' WHERE l.`ID` = 25435 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Test de ciblage de Ron' WHERE l.`ID` = 25457 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Terminez cette quête.' WHERE l.`ID` = 25457 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Tuez 15 Anguilles de n’importe quelle sorte dans la Forêt de Varech’thar.' WHERE l.`ID` = 25474 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'On prend de l\'anguille et on recommence' WHERE l.`ID` = 25474 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`PortraitGiverName` = 'Une anguille' WHERE l.`ID` = 25474 AND l.`locale` = 'frFR' AND (l.`PortraitGiverName` IS NULL OR l.`PortraitGiverName` = '' OR BINARY l.`PortraitGiverName` = BINARY q.`PortraitGiverName`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`PortraitGiverText` = 'Misérable engeance…' WHERE l.`ID` = 25474 AND l.`locale` = 'frFR' AND (l.`PortraitGiverText` IS NULL OR l.`PortraitGiverText` = '' OR BINARY l.`PortraitGiverText` = BINARY q.`PortraitGiverText`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Les anguilles sont parmi les créatures les plus répugnantes d’Azeroth.$b$bBien sûr, certains vous diront qu’elles ne les dérangent pas, et d’autres vous diront carrément qu’elles ne sont pas désagréables à regarder.$b$bIls mentent tous.$b$bLa vérité, c’est que personne n’aime les anguilles. Même les anguilles n’aiment pas les anguilles !$b$bIl ferait mieux vivre en Azeroth si personne n’avait à craindre la possibilité de se faire mordre au visage par une anguille surgie du fond d’un trou.' WHERE l.`ID` = 25474 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Utilisez 6 morceaux de Viande de tortue pour confectionner un Appât à requin.' WHERE l.`ID` = 25497 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
