UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Un bien curieux passe-temps' WHERE l.`ID` = 25961 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir Elendri Front-doré au nord des Jardins de Quel’Dormir.' WHERE l.`ID` = 25961 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Ha ! Non mais vous avez vu le capitaine me lancer des regards salaces et vous envoyer jouer les $gentremetteurs:entremetteuses; ? J’ai presque perdu tout espoir de lui faire comprendre que ces ruines nous donnent l’occasion de faire quelque chose de constructif, malgré tout ce chaos.$b$bEn fait, j’espérais que vous referiez surface, si vous me passez l’expression, parce que vous semblez être la seule personne à laquelle je puisse me fier. J’ai repéré plusieurs tablettes comme celle-ci disséminées dans les ruines et j’ai bricolé un kit de frottage pour les retranscrire. Vous vous sentez à la hauteur de la tâche ?' WHERE l.`ID` = 25961 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Atteignez le Niveau 3 pour apprendre le Mot de l’ombre : Douleur, puis lancez-le 5 fois sur des Mannequins d’entraînement à La Nouvelle-Brikabrok.' WHERE l.`ID` = 26200 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Les arts du prêtre' WHERE l.`ID` = 26200 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous savez, en vous aventurant dans le monde et en gagnant en puissance, vous vous découvrirez également de nouveaux pouvoirs inconnus.$B$BAlors pourquoi ne pas vous promener un peu et gagner de l’expérience ? Vous n’aurez qu’à revenir me montrer ce que vous aurez appris !' WHERE l.`ID` = 26200 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Emparez-vous du Trésor des Mosh’Ogg dans les ruines derrière le Tertre des Ogres mosh\'Ogg.' WHERE l.`ID` = 26412 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le trésor des Mosh’Ogg' WHERE l.`ID` = 26412 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Dites donc... Vous savez pour les Ogres ? J\'ai eu un bon tuyau d\'un gars qui s’appelle Mok\'thardin. Il paraît qu\'ils planquent un truc spécial, un artéfact magique, dans leur grotte. Mais on ne la fait pas à Krapouille. J’suis capable de renifler l’argent à dix lieues et j’vous parie tout ce que vous voulez que ce bidule ogre vaut une petite fortune !$B$BJ’vous donne un indice : j’les ai vus qui gardaient un coffre dans les sortes de ruines, derrière leur tertre. Est-ce que ça vous dirait d’aller me le chercher ?' WHERE l.`ID` = 26412 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Relwyn Sombrétoile, du Camp de Brassenoire, vous a demandé de récupérer 8 Troncs cérébraux corrompus.' WHERE l.`ID` = 26459 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Recherches sur la corruption' WHERE l.`ID` = 26459 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Ces imbéciles d’elfes de sang peinent avec la magie démoniaque. N’ont-ils pas vu ce qui est arrivé aux nagas et aux satyres de Kalimdor ?$b$bJe crains que les elfes de sang ne subissent pareille transformation. Azeroth ne supporterait pas la naissance d’une autre race de monstres abjects.$b$bJe souhaite étudier les troncs cérébraux des satyres et des nagas afin de découvrir ce qui attend les Sin’dorei. Vous trouverez des satyres et des nagas dans les profondeurs de Brassenoire, juste à l’ouest.' WHERE l.`ID` = 26459 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Utilisez la Torche à tiki pour bouter le feu à 8 Masques tiki à Jintha’Alor.' WHERE l.`ID` = 26522 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Les masques du mal' WHERE l.`ID` = 26522 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez auprès de Kotonga à Jintha’Alor dans les Hinterlands.' WHERE l.`ID` = 26522 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Les Vilebranches ont accroché leurs masques de tiki le long des murs de Jintha’Alor, mais les esprits ne vont plus les protéger bien longtemps.$b$bPrenez cette torche quand vous irez casser du Vilebranche, $c. Boutez le feu à leurs masques de tiki. Je regarderai d’ici le spectacle de leurs protections et de leurs sorts disparaître au fur et à mesure que leur magie vaudou hérétique s’envolera en fumée.' WHERE l.`ID` = 26522 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Remettez la Tablette de Shadra au Maître des griffons Hachegriffe.' WHERE l.`ID` = 26527 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le maître des griffons Hachegriffe' WHERE l.`ID` = 26527 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Si ça ne tenait qu’à moi, je réduirais cette tablette en petits morceaux. Malheureusement, ce n’est pas le cas. Le maître des griffons Hachegriffe doit l’examiner.$b$bVous devez retourner au Nid-de-l’aigle avec la tablette. Le maître des griffons est dans la volière, en train de s’occuper de ses bêtes.$b$bFaites vite… et ne quittez pas cette tablette des yeux une seule seconde !' WHERE l.`ID` = 26527 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Libérez 3 Druides asservis du Camp de base de la KapitalRisk.' WHERE l.`ID` = 26764 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L’exfiltration' WHERE l.`ID` = 26764 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir Krazek au camp de l’Expédition de Nesingwary, en Strangleronce septentrionale.' WHERE l.`ID` = 26764 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous avez peut-être remarqué que la KapitalRisk a complètement fait raser tous les arbres autour de son camp de base, à l’est. Comme elle ne manque une occasion de faire des profits, leur contremaître a réduit des druides en esclavage et les force à faire repousser la forêt pour que la compagnie puisse la raser à nouveau !$B$BPersonnellement, je trouve ce procédé parfaitement odieux, et pas seulement parce que je n’y ai pas pensé le premier.$B$BVous devriez libérer quelques-uns de ces druides, je suis sûr qu’ils l\'apprécieront.' WHERE l.`ID` = 26764 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Allez voir Rhyanda à l’intérieur d’Aldrassil, au Sombrevallon.' WHERE l.`ID` = 26841 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le cachet interdit' WHERE l.`ID` = 26841 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Ce cachet m’a été donné par un messager de notre maître des mages, Rhyanda. Elle souhaiterait vous parler, dès que vous aurez un moment à lui accorder. Lisez le message et rapportez-le-lui.' WHERE l.`ID` = 26841 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Fouillez le Gouffre de Ragefeu pour retrouver le cadavre de Maur Totem-sinistre, et regardez s\'il possède des objets intéressants.' WHERE l.`ID` = 26859 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'À la recherche de la sacoche perdue' WHERE l.`ID` = 26859 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Les troggs ne sont pas la seule chose qui intéresse Magatha à propos du gouffre de Ragefeu. Elle a entendu dire que l’un de ses serviteurs, un certain Maur Totem-sinistre, avait trouvé quelque chose d’étrange là-bas, mais il n’est jamais revenu pour lui montrer ce que c’était. Elle aimerait que l’on retrouve le corps de Maur, s’il existe encore, et le moindre signe de ce qu’il a pu trouver lorsqu’il a tenté de parler aux troggs.$B$BRapportez à Magatha tous les objets intéressants, et je suis sûr qu’elle se montrera très généreuse quand elle vous récompensera.$B$BCherchez le gouffre dans les recoins les plus sombres d’Orgrimmar.' WHERE l.`ID` = 26859 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parlez à Muyoh.' WHERE l.`ID` = 26874 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Réveiller Naralex' WHERE l.`ID` = 26874 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Maintenant que les seigneurs-Croc sont morts, allez parler à Muyoh. Il vous aidera à réveiller Naralex et à mettre un terme à ce cauchemar.' WHERE l.`ID` = 26874 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Atteignez le Niveau 3 pour apprendre la Corruption, puis lancez 5 fois ce sort sur un Mannequin d’entraînement, près de l’entrée de Courbenclume.' WHERE l.`ID` = 26904 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Peu de personnes, surtout parmi nos alliés, comprennent vraiment la nature des pouvoirs que nous manions. Ils nous méprisent parce que nous cultivons une connaissance qu’ils sont trop faibles pour utiliser correctement.$B$BÀ mesure que vous gagnerez en puissance, vous découvrirez de nouveaux sorts et amplifierez votre pouvoir.

Gagnez plus d’expérience, puis revenez me voir lorsque vous aurez appris un nouveau sort. Ainsi, nous verrons si vous avez la carrure nécessaire pour parfaitement maîtriser la magie noire.' WHERE l.`ID` = 26904 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Atteignez le Niveau 3 pour apprendre la Corruption, puis lancez 5 fois ce sort sur un Mannequin d’entraînement, au sud de l’entrée de l’Abbaye de Comté-du-Nord.' WHERE l.`ID` = 26914 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Nous devons surveiller notre langage aux abords de l’abbaye, mais que cela ne vous détourne pas du chemin de l’apprentissage du pouvoir.$B$BÀ mesure que vous gagnerez en puissance, vous commencerez à entendre les voix de la corruption vous offrir l’accès à leur puissante magie noire.

Allez donc emmagasiner de l’expérience et apprendre un nouveau sort. Une fois cela fait, exercez-vous à l’utiliser sur les mannequins d’entraînement.' WHERE l.`ID` = 26914 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Atteignez le Niveau 3 pour apprendre la Nova de givre, puis exercez-vous à la lancer 2 fois sur un Mannequin d’entraînement, au sud de l’entrée de l’Abbaye de Comté-du-Nord.' WHERE l.`ID` = 26916 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'L’apprentissage des Arcanes' WHERE l.`ID` = 26916 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'En tant que mage, vous apprendrez nombre de sorts au fur et à mesure que votre compréhension des arcanes s’affirmera. Il vous suffit de gagner de l’expérience, et les secrets des arcanes s’imposeront d’eux-mêmes à vous.

Vous verrez. Allez donc développer vos pouvoirs, et revenez me montrer ce que vous aurez appris.' WHERE l.`ID` = 26916 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Atteignez le Niveau 3 pour apprendre la Nova de givre, puis cherchez un Mannequin d’entraînement et utilisez ce nouveau sort 2 fois.' WHERE l.`ID` = 26940 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Nova de givre' WHERE l.`ID` = 26940 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Nous sommes les héritiers d’une tradition de la magie arcanique et votre chemin ne sera pas sans embûches. Les critiques nous imputant les actions de nos prédécesseurs sont nombreuses, mais nos talents sont une chose nécessaire.$b$bBien qu’il vous faille faire preuve de prudence, il est important de développer vos pouvoirs, pour ainsi renforcer votre lien aux arcanes et accéder à de nouveaux sorts.

Gagnez de l’expérience en utilisant vos sorts, puis revenez me montrer ce que vous avez appris.' WHERE l.`ID` = 26940 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Atteignez le Niveau 3 pour apprendre la Charge, puis trouvez un Mannequin d’entraînement et exercez-vous à la Charge.' WHERE l.`ID` = 26945 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Apprendre de nouvelles techniques' WHERE l.`ID` = 26945 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'À mesure que vous surmonterez les défis qui vous attendent, vous apprendrez de nouvelles techniques.$B$BPartez, accumulez de l’expérience, et découvrez une nouvelle compétence. Ceci fait, revenez me faire une démonstration sur l’un des mannequins d’entraînement.' WHERE l.`ID` = 26945 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Atteignez le Niveau 3 pour apprendre le Tir assuré, puis trouvez un Mannequin d’entraînement sur le côté nord-ouest du Point d’impact et utilisez cette nouvelle compétence 5 fois.' WHERE l.`ID` = 26963 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
