UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Un messager était à votre recherche il y a peu, $n. J’ai cru comprendre qu’il était envoyé par le maître des prêtres, la prophétesse Plume-de-corbeau. Si cette lettre est bien d’elle, à votre place, j’irais immédiatement la voir.' WHERE l.`ID` = 27014 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
