UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Un messager était à votre recherche il y a peu, $n. J’ai cru comprendre qu’il était envoyé par le maître des paladins, le marche-soleil Helaku. Si c’est bien lui qui vous adresse cette lettre, je vous enjoins d’aller immédiatement le voir.' WHERE l.`ID` = 27015 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
