UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Voici venu le moment de votre première leçon, $n. Votre apprentissage sera long jusqu’à ce que vous maîtrisiez complètement toutes les techniques du chasseur, mais chacune des nouvelles compétences que vous apprendrez vous rapprochera du but.$B$BAllez donc gagner plus d’expérience et découvrir une nouvelle compétence. Revenez ensuite l’utiliser sur ces mannequins d’entraînement.' WHERE l.`ID` = 27021 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Atteignez le niveau 3 pour apprendre Mot de l’ombre : Douleur. Utilisez-le 5 fois sur un Mannequin d’entraînement du Camp Narache.' WHERE l.`ID` = 27066 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
