UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous avez fait du bon travail, $n, le meilleur que j’ai vu de la part de quelqu’un qui n’est pas de chez nous.$b$bDame Portvaillant a demandé que je la tienne informée de cette situation délicate et je ne lui ai pas parlé depuis longtemps.$b$bJe m’apprêtais à lui envoyer mon rapport, mais il me semble plus approprié que ce soit vous qui lui parliez. Vous répondrez mieux à ses questions que moi.' WHERE l.`ID` = 27289 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Récupérez 4 Notes du Totem-sinistre sur des Anciens du Totem-sinistre, et combinez-les pour obtenir le Plan de bataille du Totem-sinistre.' WHERE l.`ID` = 27309 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
