UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir Krog dans le Marécage d\'Âprefange.' WHERE l.`ID` = 27309 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Maintenant que les activités des Totems-sinistres dans les Mille pointes ont éclaté au grand jour, beaucoup de taurens s’en méfient. Nous avons vu des membres éminents de leur clan commettre des meurtres ou des enlèvements pour servir leurs intérêts, et j\'ai bien peur que nous soyons leur prochaine cible.$B$BAu nord-est, près du marais Bleu, se trouve Sabot-Noir. C’est un nouveau camp totem-sinistre d’une certaine ampleur. Leurs chefs, les anciens, doivent recevoir leurs ordres des Pitons-du-Tonnerre. Voyez si vous réussissez à vous emparer de ces ordres et à les analyser pour comprendre les plans des Totems-sinistres.' WHERE l.`ID` = 27309 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Utilisez le Signal d\'attaque du sommet de l\'une des tours de la Porte du Crépuscule.' WHERE l.`ID` = 27588 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
