UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Maintenant que vous avez attiré Brise-crâne la Montagne loin de la porte du Crépuscule, il faut que vous donniez le signal à nos forces de lancer l\'assaut.' WHERE l.`ID` = 27588 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Trouvez Maître Mathias Shaw dans la Citadelle du Crépuscule, dans les Hautes-terres du Crépuscule.' WHERE l.`ID` = 27637 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Rien que Mathias et vous' WHERE l.`ID` = 27637 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'C\'est un terrible coup pour nous. Maudit Cho\'gall !$B$BHeureusement que le commandant d\'escouade vous avait dit où trouver maître Shaw.' WHERE l.`ID` = 27637 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Perturbez les rituels des sectateurs dans la Herse, la Vallée de l’Honneur, et près de la Porte de l’Ouest de la ville en lisant une formule inexacte du Livre des Incantations.' WHERE l.`ID` = 27799 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
