UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir le Garde de sang Torek dans la Vallée de la Force.' WHERE l.`ID` = 27799 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Maintenant que vous connaissez le rituel, il est temps pour vous de le réaliser dans la ville. Des dizaines de nos frères se sont déjà frayé un chemin jusqu’aux sites de rituel.$B$BJe veux que vous vous rendiez aux sites du rituel du portail au deuxième niveau de la Herse, dans la vallée de l’Honneur, près du hall des Braves et de la porte de l’Ouest d’Orgrimmar. Les équipes déjà sur place auront effectué une grande partie des préparatifs, et tout ce que vous avez à faire, c’est de lire le dernier passage du livre d’incantations.$B$BLa ville sera bientôt consumée par les flammes.' WHERE l.`ID` = 27799 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Enfilez votre Robe de recrue, rendez-vous à la Ferme Rêche-pourceau et récupérez le Livre des Incantations aurpès de la Surveillante Jintak. Lisez un passage du Livre des Incantations près de l’Autel de sectateur pour vous exercer à réaliser le rituel.' WHERE l.`ID` = 27800 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Dissimulation' WHERE l.`ID` = 27800 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Nous avons capturé de nombreux sectateurs, mais ils semblent malgré tout assurés de leur victoire. Nous devons en apprendre davantage sur le rituel mentionné par le sectateur que vous avez interrogé.$B$BCes rituels doivent se trouver au centre de leurs projets d’attaque sur Orgrimmar.$B$BPrenez l’une des robes des sectateurs que vous avez appréhendés, ce n’est pas comme s’ils allaient encore en avoir besoin. Enfilez-la, et retournez à l’avant-poste des sectateurs à la ferme Rêche-pourceau, en Durotar, et voyez ce que vous pouvez apprendre au sujet de ces rituels et de leur rôle dans les machinations du culte.' WHERE l.`ID` = 27800 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Utilisez les Menottes lourdes pour appréhender 5 Sectateurs infiltrés, puis conduisez-les auprès du Gardien Gartok Ragepoing à l’Arène des Valeureux, dans la Vallée de l’Honneur d’Orgrimmar. Après avoir amené vos prisonniers, interrogez l\'un des Sectateurs en détention.' WHERE l.`ID` = 27802 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Appréhender les infiltrateurs' WHERE l.`ID` = 27802 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'La note que vous avez trouvée ne peut signifier qu’une seule chose. La proclamation du chef de guerre est arrivée trop tard ; leurs infiltrateurs sont déjà à l’œuvre dans la ville.$B$BCette note contient des instructions et indique les lieux de réunion des sectateurs, mais elle ne précise pas leurs intentions. Nos ennemis sont devenus plus rusés. Tous les traquer ne sera pas aisé, mais nous devons en capturer un maximum. Utilisez ces menottes pour appréhender les infiltrateurs, puis livrez-les au gardien Gartok Ragepoing à l’arène des Valeureux, dans la vallée de l’Honneur.' WHERE l.`ID` = 27802 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Obtenez du Pain des morts et donnez-le à l’Esprit de worgen joyeux, dans le cimetière de Darnassus.$b$bUtilisez un Chrysanthème orange pour voir l’esprit.' WHERE l.`ID` = 27846 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Les morts reconnaissants' WHERE l.`ID` = 27846 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'C’est bon de pouvoir à nouveau rendre visite à ses amis et à sa famille. Si bon que je pense avoir exagéré… J’ai déjà mangé tout ce qu’ils m’avaient donné !$b$bJe peux vous demander d’aller me rechercher de ce délicieux pain des morts ? Je vous en serais très reconnaissante…$b$bJe pense que Chapman en vend la recette.' WHERE l.`ID` = 27846 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez le manuel intitulé « Fouilles efficaces » à Belloc Brillelame à l\'Accostage de Schnottz.' WHERE l.`ID` = 27925 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
