UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Le chef de guerre somme tout aventurier digne de ce nom de se rendre immédiatement à la Scholomance, à l\'est d\'Andorhal !$B$BDe récentes activités nécromantiques dans la zone indiquent la présence du sombre maître Gandling et un effort renouvelé pour entraîner de puissants sorciers pour le Fléau. Si vous acceptez, rendez-vous dans la Scholomance pour débarrasser les maleterres de ce bastion du mal.' WHERE l.`ID` = 28083 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Trouvez Bahrum Martelforge.' WHERE l.`ID` = 28236 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Toi, le frère que j\'ai perdu' WHERE l.`ID` = 28236 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Mon frangin Bahrum, il a disparu !$B$BY f\'sait partie des premiers éclaireurs. Les autres, ils sont revenus sans problème, mais lui on l\'a pas r\'vu. P\'têt ben qu\'il traînasse quelque part, mais c\'est mon seul frangin et j\'ai promis à maman de m\'occuper de lui. Vous voulez bien l\'retrouver ?' WHERE l.`ID` = 28236 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Harrison Jones veut que vous reveniez lui parler dans une semaine ou deux.' WHERE l.`ID` = 28240 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'À court d\'idée' WHERE l.`ID` = 28240 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Écoutez, $n.$B$BVous savez que je vis pour vous distraire et que je m\'efforce de vous trouver d\'agréables occupations et tout et tout.$B$BMais là, je n\'ai vraiment plus aucune idée.$B$BC\'est tout !$B$BD\'habitude, quand je fais une quête avec vous, j\'ai toujours une idée qui me vient sur ce que je pourrais vous donner à faire ensuite, ce qui me laisse le temps d\'inventer un objectif conséquent, mais pas plus.$B$BJe suis à court d\'idée. Absolument aucune inspiration. Je ne pourrais même pas émettre une idée pour me sauver la vie.$B$BOh, attendez ! Je sais ce que nous pouvons faire !$B$BRevenez me parler dans une semaine ou deux...' WHERE l.`ID` = 28240 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Le Commandant Schnottz a juste envie d\'une accolade…' WHERE l.`ID` = 28255 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Et ensuite, hum ?' WHERE l.`ID` = 28255 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Comment les choses font-elles tourner ? Hum ?$B$BFais-che m\'en prendre à mon maître des ténèbres, qui que ce soit ?$B$BFais-che apprendre à defenir un chef plus sensible et plus compatissant ? Fais-che émigrer si loin que ch\'en perdrai mon adorable chargon ?$B$BOu bien fais-je épouser mes aspirations et aller de l\'afant coûte que coûte, chamais satisfait tant qu\'Azeroth ne sera pas toute à moi ?$B$BEt ensuite, hum ?$B$BPeut-être que les choses prendront forme la semaine prochaine...$B$B...ou alors la semaine d\'après encore...' WHERE l.`ID` = 28255 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
