UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Depuis Jaedenar, sa forteresse au nord-ouest, le Conseil des ombres corrompt cette forêt qui fut jadis magnifique.$b$bEt aujourd’hui, c’est l’un des nôtres qui est porté disparu. Nous avons envoyé à Jaedenar Andalar Vallombreuse, l’un de nos éclaireurs, en espérant réduire l’effectif de notre ennemi en toute discrétion.$b$bCela fait des jours que nous n’avons plus de nouvelles de lui et nous craignons le pire. Néanmoins, il subsiste encore une maigre chance pour qu’il soit en vie. Je vous en prie, $n, mettez-vous immédiatement à sa recherche et trouvez-le !' WHERE l.`ID` = 29028 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Approchez 5 fois votre Bébé de Terriers couverts de neige dans le nord de Berceau-de-l’Hiver pour l’aider à apprendre à chasser les Lièvres arctiques.' WHERE l.`ID` = 29039 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
