UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Les éthériens de Shaffar ont complètement bloqué les accès des tombes-mana. Heureusement, j\'ai un plan. Même si on ne peut pas passer par la porte principale, il y a forcément plusieurs transporteurs à l\'intérieur.$B$BJe veux que vous dégagiez d\'abord la voie pour mon équipe, et ensuite que vous activiez l\'un des transporteurs pour nous téléporter à l\'intérieur.$B$BActivez le téléporteur dans la dernière salle avant les appartements de Shaffar une fois que vous aurez fait le ménage. Ne vous inquiétez pas, je vous le revaudrai...' WHERE l.`ID` = 29572 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Tuez l’Exarque Maladaar et retournez voir l’Esprit draeneï à l’intérieur des Cryptes Auchenaï.' WHERE l.`ID` = 29597 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La mort de l’exarque' WHERE l.`ID` = 29597 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez auprès de l’Esprit draeneï à l’intérieur des Cryptes Auchenaï.' WHERE l.`ID` = 29597 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'L’exarque Maladaar accomplit sa tâche impie dans les profondeurs des cryptes. Il représente une menace pour nos deux mondes et doit être arrêté.$B$BVous devez le vaincre pour le bien de tous, vivants et morts.' WHERE l.`ID` = 29597 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Guide pratique de Sombrelune' WHERE l.`ID` = 29601 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Avez-vous un exemplaire du Guide pratique de Sombrelune, l’$gami:amie; ? C’est un livre très utile, à avoir toujours sur soi.$B$BIl vous aidera à trouver et identifier des reliques de valeur lors de vos voyages en Azeroth. Les descriptions détaillées qu’il contient vous permettent de décider rapidement si vous venez de découvrir votre millième bouton de cuivre ou si vous êtes $gtombé:tombée; sur une relique rare que les collectionneurs de la foire de Sombrelune s\'arrachent.' WHERE l.`ID` = 29601 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Présentez-vous au Grand ancien Chute des Nuages aux Terres du Banquet, dans la Forêt de Jade.' WHERE l.`ID` = 29638 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'C’est la fin de votre entraînement, $gjeune homme:jeune fille;. Le cycle a été complété. Heureusement, ce cycle se termine comme il a commencé… par un banquet.$b$bJe vous retrouverai aux terres du Banquet. Je serai probablement en train de danser sur une table.' WHERE l.`ID` = 29638 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Voyagez à travers les Grottes du temps jusqu\'au Noir Marécage pendant l\'ouverture de la Porte des ténèbres et parlez à Sa\'at.' WHERE l.`ID` = 29673 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le Noir marécage' WHERE l.`ID` = 29673 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Le Vol draconique infini a abandonné toute tentative de subtilité. Ils prévoient de détruire le Gardien, Medivh, et d’empêcher l’ouverture de la Porte des ténèbres. De prime abord, cela pourrait sembler être une sacrée aubaine pour les troupes de l’Alliance, mais le résultat serait catastrophique et mènerait à la perte de votre monde.$B$BVous devez vous rendre dans la voie temporelle qui mène au Noir marécage. Dirigez-vous à l\'ouest, puis au sud, passez devant mon futur moi, et vous atteindrez le tunnel où vivent les créatures du marécage. Traversez-le et parlez à Sa’at.' WHERE l.`ID` = 29673 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Tyrith veut que vous utilisiez l\'orb sur le balcon de la Terrasse des Magistères.' WHERE l.`ID` = 29683 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La clairvoyance du clairvoyant' WHERE l.`ID` = 29683 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir Kalecgos à la Terrasse des Magistères.' WHERE l.`ID` = 29683 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '<Tyrith s\'adresse à vous en grimaçant de douleur.>$b$bAllez sur la terrasse... Utilisez l\'orbe.$b$b…Ils…alimentent le puits de soleil...$b$b<Tyrith suffoque.>$b$bVite... Il faut les arrêter... avant qu\'ils ne...$b$b<Tyrith meurt.>' WHERE l.`ID` = 29683 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Rapportez la Hache de Nazgrim au Général Nazgrim.' WHERE l.`ID` = 29693 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La lame du général' WHERE l.`ID` = 29693 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Tandis que vous reprenez petit à petit vos esprits et que vous observez les environs, un objet attire votre attention parmi les débris de l’épave.$b$bIl vous semble que c’est la première fois que vous voyez la hache de Nazgrim libérée de sa poigne de fer. Quelque part, cela rend votre situation encore plus perturbante…$b$bVous savez que mort ou vif, le général exigerait que cette arme retourne en sa possession.' WHERE l.`ID` = 29693 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Reprenez 100 Étoiles de lancer de Kiryn des mains des Lutins des bois sournois.' WHERE l.`ID` = 29696 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Mes étoiles !' WHERE l.`ID` = 29696 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Un certain nombre d’objets appartenant à Kiryn ont été disséminés dans la nature par des lutins des bois, mais cet objet vous semble plus important que les autres.$b$bCe sac pendait autrefois à sa ceinture, rempli d’étoiles de lancer. Sans lui, elle ne disposera que d’un arsenal réduit.$b$bSi vous pouviez reprendre ses armes des mains des petites pestes qui peuplent la région, cela jouerait en votre faveur.' WHERE l.`ID` = 29696 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Tuez 8 Entourloupeurs feuillus au sud de la Hutte de la Sorcière de jade.' WHERE l.`ID` = 29722 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Une leçon de bravoure' WHERE l.`ID` = 29722 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Pouvez-vous m’apprendre à être courageux comme vous ?$b$bQuand nous avons fait une blague à la sorcière, nous avons énervé une bande d’entourloupeurs feuillus. Je crois que la sorcière leur a jeté un sort.$b$bPouvez-vous me montrer comment leur faire face ?' WHERE l.`ID` = 29722 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Placez 4 Dynamites de fortune près de l’épave du navire au Déclin du Saphir. Les Dynamites de fortune doivent être placées à au moins 10 mètres l’une de l’autre.' WHERE l.`ID` = 29728 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Une preuve explosive' WHERE l.`ID` = 29728 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Je dois vous demander de faire encore une chose pour moi, $n.$B$BNous ne pouvons nous permettre que quelqu’un trouve nos effets personnels à bord de ce navire. Donc, nous devons le détruire.$B$BJ’ai bricolé de la dynamite de fortune à partir de ce que vous avez pu récupérer.$B$BPlacez-la à bord du navire, peu importe l\'endroit, mais évitez de poser les charges trop près les unes des autres.$B$BIl est possible que ces explosifs soient un petit peu… heu… instables, donc il vaut mieux les espacer, en cas de détonation prématurée…' WHERE l.`ID` = 29728 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Utilisez le Distributeur de drones gobelins près de la Racine visible pour récupérer des fournitures.$b$bREMARQUE : chaque utilisation nécessite une Queue de glisseur des falaises.' WHERE l.`ID` = 29732 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Ce qui descend doit remonter !' WHERE l.`ID` = 29732 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Rivett a laissé ce qui semble être une pièce d’équipement de valeur. Le long de son fuselage, vous déchiffrez les inscriptions suivantes : distributeur de drones gobelins.$b$bAprès quelques réglages, le distributeur est paramétré pour envoyer des drones en direction du camp de base de Nazgrim.$b$bFacile !$b$bMais il y a quand même un hic. Les seules caisses de ravitaillement qui vaillent le coup d’être emportées sont passées par-dessus la corniche de la falaise, en contrebas du point d’impact.$b$bTandis que vous réfléchissez au problème, vous apercevez du coin de l\'œil la longue queue ondulée d’un glisseur des falaises…' WHERE l.`ID` = 29732 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Un bon départ' WHERE l.`ID` = 29766 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Malgré cette difficile situation, nos ordres restent les mêmes. Nous devons cartographier ces terres et les préparer pour l\'arrivée de la flotte de Hurlenfer.$b$bMais avant tout, il faut se charger de ces sauvages !$b$bVous voyez les cadavres que j’ai disposés en petits tas autour du camp ? Je veux que vous en fassiez de véritables montagnes !$b$bC’est la Horde que nous représentons !$b$bCes vermines n’ont pas encore appris à nous craindre, mais nous aurons bientôt dissipé ce malentendu…' WHERE l.`ID` = 29766 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Mettez une claque au buffle.' WHERE l.`ID` = 29773 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Wugou, l’esprit de la terre' WHERE l.`ID` = 29773 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '$n ! Bon, le point positif, c\'est que trouver Wugou a été assez simple. Le réveiller, par contre, c’était une autre paire de manches. Il risque d\'être endolori, avec tous les coups que j’ai dû lui donner pour essayer de le sortir du sommeil.$B$BEt vous, $n, avez-vous le sommeil lourd ? Qu’est-ce qui vous réveille le matin ?$B$BPour ma part, sortir du lit a toujours bien fonctionné, donc je me suis dit que nous allions faire pareil ! J’ai noué des cordes au char à bœufs. Il n’y a plus qu’à le faire avancer et cela devrait être bon ! Voudriez-vous mettre une claque au buffle pour qu’il démarre ?' WHERE l.`ID` = 29773 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Kilix le Démêleur, à la Fosse de Narjun, veut que vous tuiez le Héraut Volazj et les trois Oubliés qui l’accompagnent à Ahn’Kahet.' WHERE l.`ID` = 29810 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Les sans-visage' WHERE l.`ID` = 29810 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir Kilik le Démêleur dans la Fosse de Narjun, dans la Désolation des dragons.' WHERE l.`ID` = 29810 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Lorsque mon peuple a commencé à perdre du terrain dans sa lutte contre les morts-vivants, il a creusé plus profondément. Trop profondément.$b$bSans le vouloir, nous avons exposé un filament de la volonté du Dieu très ancien. Il s’est manifesté sous la forme de créatures que nous appelons les sans-visage.$b$bNous ne pouvions pas nous battre sur deux fronts, pas contre des ennemis si puissants. Cette malchance nous a valu de perdre la guerre contre les morts-vivants, puis notre demeure.$b$bPénétrez dans Ahn’kahet, $c, et nettoyez notre ancien foyer de ces atrocités sans visages.' WHERE l.`ID` = 29810 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'L’archimage Bérinand vous a demandé de parler au mage de guerre Kaitlyn, dans le Nexus.' WHERE l.`ID` = 29820 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Dans le Nexus' WHERE l.`ID` = 29820 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'J’ai envoyé le mage de guerre Kaitlyn dans le Nexus pour enquêter sur le chaos du domaine de Malygos, mais cela fait plusieurs jours que je n’ai pas de nouvelles d’elle.$B$BÇela vous dérangerait-il de vous rendre là-bas et de lui proposer votre aide ? Je suis sûr qu\'elle en aura besoin... si elle ne s\'est pas déjà fait manger par les dragons bleus.' WHERE l.`ID` = 29820 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apportez le Parchemin illisible au Chroniqueur Cho.' WHERE l.`ID` = 29837 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le parchemin sacré' WHERE l.`ID` = 29837 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Les mystérieuses inscriptions du parchemin témoignent d’une élégance dont Yoggtord et son gang ne semblent pas capables.$b$bVous pensez qu’il s’agit d’une marchandise volée, comme tout ce que les Hozen possèdent.$b$bLe propriétaire légitime de ce parchemin vit peut-être toujours dans le coin…' WHERE l.`ID` = 29837 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Explorez la région.' WHERE l.`ID` = 29841 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Tâter le terrain[TEMP]' WHERE l.`ID` = 29841 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Grrr !!$b$bChaque fois qu’on tue un de ces claque-gadoue, deux autres surgissent des bois pour prendre sa place. Je n’irai pas le crier sur tous les toits, mais il est évident que nous ne tiendrons plus très longtemps, ici, $n.$b$bIl est de mon devoir de tenir nos positions et de protéger ce qui reste de nos effets personnels. Quant à vous, partez en éclaireur dans la région pour trouver une solution à notre problème de primates.$b$bNe tardez pas. Tous nos espoirs reposent sur vous…' WHERE l.`ID` = 29841 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Servez-vous des bougies pour méditer au Cairn de sang.' WHERE l.`ID` = 29842 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Chercher des réponses' WHERE l.`ID` = 29842 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '<Cho subit patiemment les flots de questions qui sortent de votre bouche avant de prendre la parole.>$b$bLes questions se bousculent, honorable $gvoyageur:voyageuse;…$b$bAvant toute chose, vous devez apprendre quelles questions poser avant que votre esprit puisse discerner le mensonge de la vérité.$b$bJ’ai terminé ma méditation quotidienne, cependant, mes bougies sont restées au cairn de sang.$b$bAllez là-bas. Faites le vide dans votre esprit. Nous nous reparlerons quand vous serez $gprêt:prête; à m’écouter.' WHERE l.`ID` = 29842 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Servez-vous de la Bougie de méditation au Cairn d’ossements.' WHERE l.`ID` = 29856 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le cairn d’ossements' WHERE l.`ID` = 29856 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Votre esprit semblait en paix.$b$bVous pensiez que vous étiez $gconcentré:concentrée;. C’est peut-être le bourdonnement des insectes à proximité qui vous a $gplongé:plongée; dans les bras de Morphée. Ça ne peut pas être autre chose !$b$bDu coin de l\'œil, vous apercevez une autre formation de pierres, juste au nord d’ici.$b$bC’est peut-être plus tranquille là-bas…' WHERE l.`ID` = 29856 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Récoltez 6 Lotus zen.' WHERE l.`ID` = 29886 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Médecine zen' WHERE l.`ID` = 29886 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Votre ami Taylor est dans un état critique. Malheureusement, le poison hozen a infecté ses blessures, et il est très difficile de le soigner.$b$bHeureusement, après des générations à combattre les Hozen, mon peuple a réussi à créer des traitements pour guérir ce type de blessures.$b$bIl me faut des fleurs qui poussent à la surface du lac de Verre.$b$b$n, allez vite m’en chercher quelques-unes. La vie de votre amiral en dépend.' WHERE l.`ID` = 29886 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Tuez 7 Batteurs de grève jinyu à La Poisseuse.' WHERE l.`ID` = 29938 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Amis et ennemis' WHERE l.`ID` = 29938 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Poukants de jinyu grouker neveux de Koh Koh !$b$bLokdu tuer plein de hozen, déjà. Mais maintenant, lokdu tuer plein de jinyu !' WHERE l.`ID` = 29938 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
