UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Parlez avec Daggle Marchebombe, dans les Étendues sauvages de Krasarang.' WHERE l.`ID` = 30125 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Trois mots : sang de tigre !$b$bÇa va se vendre mieux que la saronite au marché noir. Tout particulièrement une fois que j’aurai fini de répandre la rumeur sur comment ça vous fortifie, tout ça, tout ça.$b$bLe problème, c’est que je suis à court de munitions. Pourriez-vous rapporter quelques fioles de sang de tigre pour moi ? Je vous ferai profiter de l’arnaque.' WHERE l.`ID` = 30125 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Tuez 8 Chasseurs de carpes.' WHERE l.`ID` = 30126 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La maîtrise des grues' WHERE l.`ID` = 30126 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Parlez avec Daggle Marchebombe, dans les Étendues sauvages de Krasarang.' WHERE l.`ID` = 30126 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Le truc avec la chasse aux grues, c’est qu’il faut des munitions, et j’en ai pas. Pour chasser avec Nesingwary, il faut prouver que vous avez le niveau et que vous savez fanfaronner.$b$bPas de chasse, pas de fanfaronnade. Et j’aime tellement me vanter que là, ça va plus.$b$bPuis-je vous engager pour tuer quelques chasseurs de carpes ? Vous les trouverez le long de la rivière à l’ouest d’ici.' WHERE l.`ID` = 30126 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Tuez 8 Loups gueule-tonnerre.' WHERE l.`ID` = 30194 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Un tonnerre envahissant' WHERE l.`ID` = 30194 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'L’un des loups gueule-tonnerre qui rôdent de l’autre côté de la rivière a encore tué un yack des villageois ce matin. Ces maudits loups s’enhardissent !$B$BC’est là le signe qu’ils se reproduisent au-delà de ce que le val peut supporter. Il est temps de réduire leur nombre à nouveau.$B$BJ’apprécierais vraiment que vous m’aidiez.' WHERE l.`ID` = 30194 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Ramassez 12 Pommettes.' WHERE l.`ID` = 30231 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Récolte de pommettes' WHERE l.`ID` = 30231 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Il me faut plus de pommettes ! Vous pourriez aller en faire tomber quelques-unes des arbres, s’il vous plaît ?$B$BPrenez ceci, je m’en sers pour la récolte. La tâche est bien plus facile quand les fruits viennent à vous !' WHERE l.`ID` = 30231 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Tuez 6 Mogu shao-tien au lac Blanc-Pétale.' WHERE l.`ID` = 30281 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Approche silencieuse' WHERE l.`ID` = 30281 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '<Il se penche et dessine la silhouette d’un mogu, montre le lac à l’ouest, fait glisser le plat de sa dague sur sa gorge et vous regarde, dans l’expectative. Il semble vouloir que vous alliez tuer des mogu au lac Blanc-Pétale.>' WHERE l.`ID` = 30281 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Brûlez 10 Bannières shao-tien.' WHERE l.`ID` = 30282 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Nettoyage par le feu' WHERE l.`ID` = 30282 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Les mogu entendent s’approprier le lac à l’ouest en y plantant leurs immondes bannières. Prenez cette torche et montrez-leur ce que nous pensons de leurs torchons !' WHERE l.`ID` = 30282 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Détruisez les Statues rituelles de Shao-Tien.' WHERE l.`ID` = 30283 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Pierre tombée' WHERE l.`ID` = 30283 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Ces mogu me font parfois pitié… Peut-être qu’en arrachant l’esprit d’autres races, ils essaient de régler des problèmes survenus dans leur enfance ? Peut-être devrions-nous nous montrer plus compréhensifs, sachant d’où leur vient tant d’agressivité ?$B$BSinon, nous pouvons aussi nous contenter de détruire leurs statues de vol d’âme près du lac… Franchement, cela me semble bien plus amusant !' WHERE l.`ID` = 30283 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Tuez 8 Dévoreurs pâlelames dominés.' WHERE l.`ID` = 30292 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Dominer les dominés' WHERE l.`ID` = 30292 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Les mogu contrôlent les sauroks du lac à l’ouest et les retournent contre nous ! Mais ces reptiles étaient déjà nos ennemis avant, donc je ne suis pas certain que les mogu aient bien réfléchi à ce qu’ils font.$B$BEnfin, de nous deux, c’est davantage Anji la combattante. Moi, je prône plus l’amour et la paix. Je cherche donc quelqu’un qui saura manier les armes, lancer des sorts et pousser des cris de guerre à ma place.$B$BPourriez-vous aller tuer quelques sauroks pour moi ?' WHERE l.`ID` = 30292 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Battez 8 Défenseurs possédés du Lac Blanc-Pétale jusqu’à ce qu’ils échappent à l’emprise des mogu.' WHERE l.`ID` = 30293 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Esclave de l’ennemi' WHERE l.`ID` = 30293 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir Kun Clair d’Automne à la Pagode dorée, dans le Val de l’Éternel printemps.' WHERE l.`ID` = 30293 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Les torve-esprits shao-tien ont asservi nos défenseurs au lac Blanc-Pétale, à l’ouest. Rendez-vous sur place et éliminez les mogu qui les contrôlent, mais surtout, ne faites pas de mal à nos troupes ! Tuez plutôt ceux qui les contrôlent, cela devrait libérer nos hommes de leur joug mental.$B$BMieux vaut agir sans tarder. Anji risque de se rendre bientôt sur place et j’avoue que je ne l’ai pas épousée pour sa capacité à rester modérée dans le feu de l’action.' WHERE l.`ID` = 30293 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Soignez 6 Défenseurs blessés.' WHERE l.`ID` = 30312 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Second départ' WHERE l.`ID` = 30312 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Une unité a bêtement voulu lancer un assaut sur l’escalier Doré par l’entrée est, et s’est fait bombarder par les canons. Ceux qui ont réussi à revenir sont mal en point, et il reste des blessés sur le champ de bataille.$b$bVoici quelques bandages. Utilisez-les, ou n’importe quelle autre technique de soin, pour aider nos défenseurs blessés à rentrer à l’abri.$b$bFaites vite, s’il vous plaît. Ils ne survivront pas longtemps.' WHERE l.`ID` = 30312 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Pénétrez dans des Vortex des esprits et libérez 15 Esprits pandarens à l’intérieur.' WHERE l.`ID` = 30320 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Esprits libres' WHERE l.`ID` = 30320 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Je suis tombée sur l’une des dagues du Fauche-âme shao-tien. Elle rayonne d’une puissante magie. Il paraît qu’elle permet d’entrer dans les vortex des âmes.$B$BLes mogu utilisent ces lames pour soumettre les esprits à leur volonté, mais j’espère que vous pourrez l’utiliser pour les libérer.$B$BPénétrez dans n’importe quel vortex que vous verrez sur l’escalier Doré et libérez tous les esprits.' WHERE l.`ID` = 30320 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Collectez 6 Têtes de bourbécailles sur les Frappeurs bourbécailles dans la Rivière de Krasarang.' WHERE l.`ID` = 30375 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
