UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Retournez voir Anduin Wrynn au Refuge des Rougeailes.' WHERE l.`ID` = 30375 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Les rivières du coin grouillent de serpents de mer venimeux. Plusieurs évacués ont été mordus alors qu’ils fuyaient le temple et certains sont déjà en train de succomber au poison.$B$BNous leur administrons un anti-venin aussi vite que possible, mais il nous faut davantage de glandes à venin.$B$BJe ne vais pas vous demander de leur retirer leurs glandes sur le terrain, ça prendrait trop de temps. Contentez-vous de rapporter leurs têtes et je m’occuperai du reste.' WHERE l.`ID` = 30375 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parlez à la Matrone Vi Vinh au Sanctuaire des Sept-Étoiles, dans le Val de l’Éternel printemps.' WHERE l.`ID` = 30630 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Dans le val' WHERE l.`ID` = 30630 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Ah, j’attendais votre venue, $gvoyageur:voyageuse;.$b$bJ’aurais aimé faire votre connaissance en des temps moins troublés, mais hélas, je crains que la situation sans le val soit pour le moins funeste.$b$bMais ne parlons pas de cela maintenant. Allez voir la matrone Vi Vinh au sanctuaire des Sept-Étoiles.$b$bElle devrait pouvoir vous accueillir.' WHERE l.`ID` = 30630 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
