UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Sauvez et défendez les soigneurs jusqu’à ce que la blessure de Shen Zin Su soit guérie.' WHERE l.`ID` = 30817 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La guérison de Shen Zin Su' WHERE l.`ID` = 30817 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Et voilà à quoi mène l’imprudence. Comment a-t-il pu croire que c’était une solution valable ?$B$BPeu importe, nous n’avons pas le temps. Nous devons sauver Shen Zin Su.$B$BTrouvez autant de soigneurs que vous le pourrez ! Sauvez-les, soulagez-les, faites tout ce que vous pouvez pour qu’ils viennent ici soigner cette blessure.$B$BIl faut protéger les soigneurs à tout prix !' WHERE l.`ID` = 30817 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Retournez au Temple des Cinq matins. Un chariot vous attend près du Point d’impact du Brûleciel pour vous y conduire.' WHERE l.`ID` = 30818 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'C’est ton destin !' WHERE l.`ID` = 30818 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '$n, je suis heureuse que le plan ait fonctionné, mais c’était tout juste. Shen Zin Su et nous serions en train de couler vers le fond de l’océan, sans votre intervention. Je ne crois pas que je pourrai jamais pardonner à Ji son imprudence.$B$BNous aurons tout le temps d\'y repenser, mais pour l’instant, nous devons retourner au temple des Cinq matins. Allons leur annoncer que Shen Zin Su est sauvé, puis nous discuterons du sort de nos nouveaux alliés.' WHERE l.`ID` = 30818 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Distribuez 8 tonnelets de Spiritueux de Panse de Fer à des Tirailleurs de Lumière-du-Soir et des Forestiers de Lumière-du-Soir à proximité.' WHERE l.`ID` = 30974 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'C’est bon pour le moral !' WHERE l.`ID` = 30974 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Ces tonneaux contiennent ma plus mauvaise cuvée. Pas mal comme alcool à brûler, mais hors de question de boire cette horreur.$B$BCependant, j’ai puisé dans mes réserves de spiritueux et j’en ai envoyé un stock au milieu des autres tonneaux… à l’intention des soldats les plus méritants ! De quoi leur remonter un peu le moral entre deux échauffourées.$B$BVous pourriez vous charger de les leur livrer ?' WHERE l.`ID` = 30974 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parlez au Commandant Bagran.' WHERE l.`ID` = 31033 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Recherche aventuriers : gouffre de Ragefeu' WHERE l.`ID` = 31033 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Le chef de guerre a demandé que tous les aventuriers aptes au combat se dirigent immédiatement vers le gouffre de Ragefeu, juste sous la ville d’Orgrimmar !$b$bLes sombres chamans sont sur le point de lancer une attaque, et les gardes de la ville ne les retiendront plus très longtemps ! Si vous le souhaitez, dirigez-vous vers le gouffre de Ragefeu et parlez au commandant Bagran, chef de l’initiative de défense, pour supprimer définitivement cette menace qui plane sur Orgrimmar.' WHERE l.`ID` = 31033 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Lisez le Parchemin élégant et parlez à Ting le Ventre gaillard au Glas.' WHERE l.`ID` = 31146 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
