UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Ah, pendant que vous vous occupiez du Fléau, ce parchemin est arrivé pour vous. Il est de Ting, la visiteuse pandarène. Les moines parviennent peut-être à lire ce charabia, mais j’en suis incapable. Vous devriez aller lui parler. Elle est à l’auberge, juste là-bas.' WHERE l.`ID` = 31146 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
