UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'On m’a donné cette rune pour vous, $n. Prenez le temps de la lire. Je pense qu’elle provient de Lo, notre visiteur venu du bout du monde. Jetez-y un coup d’œil et allez le retrouver à l’intérieur de Courbenclume.' WHERE l.`ID` = 31150 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
