UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous allez vous améliorer au combat, vous allez faire des trucs nouveaux, des trucs dingues.$B$BVous voulez voir ? Vous avez qu’à vous entraîner.$B$BEt après, vous revenez me voir et vous me montrez.' WHERE l.`ID` = 31162 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
