UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Ne manquez pas de profiter de l’entraînement d’un maître si vous voulez progresser dans votre classe. Les jeunes moines de l’île de Haut-Soleil sont formés par Pao, notre visiteuse pandarène. Parlez-lui et voyez ce qu’elle peut vous apprendre.$B$BComme tous les maîtres de l’île de Haut-Soleil, Pao se trouve à l’intérieur de la Flèche solaire, au rez-de-chaussée.' WHERE l.`ID` = 31170 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Tuez 12 Mineurs d’ambre asservis ou Fouette-esclaves vos’thik, et libérez le parangon, Korven le Premier.' WHERE l.`ID` = 31174 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
