UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Un autre parangon se signale à nous.$B$BCette fois, les émanations proviennent du Vor de l’angoisse, un ancien lac au sud.$B$BIl ne sera guère aisé de le trouver, car le chemin est surveillé par nos ennemis.$B$BJe vous confie cette tâche. Si vous l’accomplissez, vous vivrez.$B$BSi vous échouez, j’enverrai quelqu’un d’autre.' WHERE l.`ID` = 31174 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Préparez un Steak de tigre grillé au feu de bois pour le Maître du grill. Il devra d’abord vous apprendre la Voie du Grill et la recette.' WHERE l.`ID` = 31469 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Apportez le Steak de tigre grillé au feu de bois au Maître du grill.' WHERE l.`ID` = 31469 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'La Voie du grill pandarène permet de produit de la nourriture qui augmente votre force physique. Apprenez la recette du steak de tigre grillé au feu de bois auprès du maître du grill et montrez-lui les résultats de votre apprentissage.' WHERE l.`ID` = 31469 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Apprenez la recette des Œufs à la coque auprès de la Guide des voies, puis apportez-lui en 5.' WHERE l.`ID` = 31485 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Donnez les 5 Œufs à la coque au Guide des Voies.' WHERE l.`ID` = 31485 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Je ne suis pas un grand maître comme mes frères et sœurs. Mais je suis un excellent enseignant. Si vous vous appliquez, je peux débloquer votre potentiel caché, même si vous n’êtes pas très $gexpérimenté:expérimentée;.$b$bSi vous avez la volonté d’apprendre, prouvez-moi que vous pouvez au moins suivre des instructions simples. Apprenez la recette des œufs à la coque, préparez-en cinq et apportez-les-moi. J\'ai quelques œufs frais que je peux vous vendre un bon prix.' WHERE l.`ID` = 31485 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Parlez à Anduin à la Porte des Astres vénérables.' WHERE l.`ID` = 31518 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Le val de l\'Éternel printemps' WHERE l.`ID` = 31518 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Les portes n\'ont pas été ouvertes depuis des générations, $n.$b$bJe ne manquerais ça pour rien au monde, et vous y serez aussi ! Retrouvez-moi à la frontière sud du sommet de Kun-Lai. Je vous y attendrai.' WHERE l.`ID` = 31518 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
