UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Un défi de taille : Yan Zhu le Déballonné' WHERE l.`ID` = 31519 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '$n, il faut que vous rassembliez un groupe qui n’a pas froid aux yeux et que vous vous rendiez à la brasserie Brune d’Orage. Quand vous y serez, activez l’orbe de défi et vaporisez Yan Zhu le Déballonné.$b$bRevenez me voir quand vous aurez accompli ce défi et je vous donnerai une belle récompense.' WHERE l.`ID` = 31519 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
