UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'J’ai peur de ne plus rien avoir à vous apprendre, $n. Néanmoins, votre parcours de $gdresseur:dresseuse; est loin d’être terminé !$B$BAllez vous présenter à Audrey Burnhep à Hurlevent. Elle connaît la plupart des meilleurs dresseurs d’Azeroth et elle vous aidera à vous perfectionner davantage.' WHERE l.`ID` = 31990 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
