UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '$n, il faut que vous rassembliez un groupe de braves et que vous les meniez au temple du Serpent de jade. Une fois là-bas, activez l’orbe de défi et terrassez le sha du doute.$b$bRevenez me voir quand vous aurez accompli ce défi et je vous récompenserai généreusement.' WHERE l.`ID` = 31998 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
