UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Répandez du Désinsecteur sur 5 Araignées de schiste agitées et éradiquez 12 Éclats de schiste.' WHERE l.`ID` = 32236 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
