UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '$C, par vos yeux, j’ai vu les combats le long de la côte et contemplé le cours épique des affrontements de par le monde. Vous avez été très $gpatient:patiente;… et plus qu’$gédifiant:édifiante;.$b$bJ’ai aussi tenu votre roi à l’œil. Ça vous intéresserait d’entendre ce que j’ai appris ?' WHERE l.`ID` = 32390 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
