UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = '<Le son des tambours de guerre retentit au loin.>$b$b$C, vous tombez toujours à pic. Hurlenfer attaque son propre peuple.$b$bIl va pas tarder à découvrir ce qu’il en coûte de se frotter aux Sombrelances. Venez ! Battez-vous avec nous ! Montrez-lui le véritable esprit de la Horde !' WHERE l.`ID` = 32813 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
