UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Commandant, il y a un problème.$b$bNous avons trouvé un endroit à Talador pour installer un avant-poste, mais les membres de l’équipe envoyée sur place pour lancer la construction n’arrivent pas à se mettre d’accord. Cela risque de retarder sérieusement nos plans si l’on n’y met pas bon ordre rapidement.$b$bPrenez un griffon pour rejoindre Talador et allez parler au contremaître Eksos avant que cela n’empire.' WHERE l.`ID` = 34565 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
