UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'L’esprit de cet architecte, il cherche pas à nous combattre. Peut-être que le brouillard qui trouble son esprit, on pourrait le dissiper et découvrir ce qui s’est passé.$B$BJe parie qu’un de ces paysans morts-vivants il doit avoir sur lui un des schémas de l’architecte ou quelque chose qu’on pourrait lui montrer afin de lui éclaircir les idées.$B$BÇa vaut la peine d’essayer.' WHERE l.`ID` = 35340 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Rendez-vous dans le Néant distordu.' WHERE l.`ID` = 35387 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'À travers le Néant' WHERE l.`ID` = 35387 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Les rituels du Vide ont été interrompus, mais les balises qu’on trouve sur les sites de rituel sont toujours alimentées en énergie ténébreuse. Il ne peut y avoir qu’une explication à cela : l’énergie qui les alimente provient directement du Néant distordu.$b$bLe seul moyen d’interrompre le flux d’énergie du Vide qui parvient aux balises consiste à se rendre dans le Néant distordu et à contrer la puissance qui s’y est installée !$b$bUtilisez une balise pour vous rendre dans le Néant distordu. Sur place, utilisez la pierre chamanique qui nous a été remise par les fureurs pour me contacter.$b$bQue la Lumière soit avec vous.' WHERE l.`ID` = 35387 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Détruisez $oa Créatures du Vide.' WHERE l.`ID` = 35388 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'La marche du Vide' WHERE l.`ID` = 35388 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Des légions de terreurs du Vide font route vers Oshu’gun afin de s’y sacrifier au seigneur du Vide Invalidus.$b$bChaque fois que l’une d’elles meurt, Invalidus devient un peu plus puissant. On dirait que ces créatures inférieures ne sont là que pour nourrir le seigneur du Vide.$b$bNous devons empêcher Invalidus de devenir trop puissant, sans quoi il deviendra vite impossible de l’arrêter.$b$bTuez autant de créatures du Vide que vous le pourrez, afin de ralentir la croissance d’Invalidus. Pendant ce temps-là, je vais chercher un moyen de provoquer une rencontre avec lui avant qu’il ne soit trop tard pour intervenir.' WHERE l.`ID` = 35388 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Éliminez les Chanteguerres supervisant les rituels.' WHERE l.`ID` = 35389 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Faire taire l’appel' WHERE l.`ID` = 35389 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Les chamans chanteguerres se servent des éléments pour canaliser l’énergie ténébreuse du Vide.$b$bLe chamanisme n’est pas mon domaine, mais je sais que la plupart des clans orcs eux-mêmes réprouvent ce genre de pratiques. Le pouvoir du Vide s’oppose à celui de la Lumière ; c’est une source d’entropie et de destruction.$b$bCes rituels affaiblissent la barrière séparant notre monde du Néant distordu. Si rien ne vient interrompre ces rituels, notre terre sera bientôt envahie par les créatures du Néant distordu.$b$bTuez les chamans chargés d’accomplir ces rituels avant qu’ils ne signent notre arrêt de mort à tous !' WHERE l.`ID` = 35389 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Invoquez et affrontez Invalidus.' WHERE l.`ID` = 35390 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Ténèbres sur Oshu’gun' WHERE l.`ID` = 35390 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestCompletionLog` = 'Il me faudrait du texte' WHERE l.`ID` = 35390 AND l.`locale` = 'frFR' AND (l.`QuestCompletionLog` IS NULL OR l.`QuestCompletionLog` = '' OR BINARY l.`QuestCompletionLog` = BINARY q.`QuestCompletionLog`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Le seigneur du Vide Invalidus s’est installé au sommet du pic d’Oshu’gun, où il se nourrit des âmes des morts.$b$bLes terreurs du Vide que vous avez abattues n’étaient là que pour alimenter le monstre.$b$bSi nous n’agissons pas au plus vite, Invalidus deviendra si puissant qu’il nous faudra une armée pour l’arrêter.$b$bSur chacun des sites de rituel, on trouve un cristal doté de pouvoirs du Vide. Perturbez l’un de ces cristaux du Vide, et Invalidus ressentira votre présence.$b$bTenez-vous $gprêt:prête;… Invalidus tentera instantanément de venir dévorer votre âme.' WHERE l.`ID` = 35390 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogDescription` = 'Détruisez les Totems rituels.' WHERE l.`ID` = 35391 AND l.`locale` = 'frFR' AND (l.`LogDescription` IS NULL OR l.`LogDescription` = '' OR BINARY l.`LogDescription` = BINARY q.`LogDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`LogTitle` = 'Interrompre les rituels' WHERE l.`ID` = 35391 AND l.`locale` = 'frFR' AND (l.`LogTitle` IS NULL OR l.`LogTitle` = '' OR BINARY l.`LogTitle` = BINARY q.`LogTitle`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Sous la montagne d’Oshu’gun, les Chanteguerres se livrent à des rituels ténébreux.$b$bLes chamans chanteguerres comptent renforcer leur clan en s’alimentant de la puissance du Vide qui niche au cœur d’Oshu’gun.$b$bJ’ignore la nature exacte de cette puissance… mais j’ai bien peur qu’elle soit en relation avec K’ure, le naaru mourant.$b$bNous devons interrompre les rituels des Chanteguerres, sans quoi la barrière séparant notre monde du Néant distordu disparaîtra.$b$bTrouvez les totems rituels utilisés pour canaliser cette énergie et détruisez-les.' WHERE l.`ID` = 35391 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
