UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Vous êtes $gcertain:certaine; de ne pas vouloir vous en départir ? Je vous en donnerai un bon prix !$B$BD’accord, d’accord… si vous tenez tant à retrouver son propriétaire, vous devriez aller faire un tour à Wor’gol.$B$BD’après la rumeur, on y trouve un maître-artisan spécialisé dans le travail des métaux précieux et des gemmes.$B$BMais si vous changez d’avis, vous savez où me trouver…' WHERE l.`ID` = 36461 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'On dirait que l’enclos de combat a de la visite, aujourd’hui, et que quelqu’un cherche la bagarre. Montrez-leur ce dont est capable $gun maître:une maîtresse; des combats de mascottes !' WHERE l.`ID` = 36570 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
