UPDATE `quest_template_locale` l JOIN `quest_template` q ON q.`ID` = l.`ID` SET l.`QuestDescription` = 'Les Crins-de-Sang ont tué plusieurs de nos initiés lorsque ils nous ont tendu une embuscade pendant notre rituel à Brèche-aux-Corbeaux. Il faut leur apprendre que la nuée ne laissera jamais un tel crime impuni !$b$bNous tuerons un individu de leur tribu par membre de la nuée tombé !$b$bRendez-vous dans leur foyer maudit de la vallée Crin-de-Sang et massacrez-en autant que vous le pourrez.' WHERE l.`ID` = 36796 AND l.`locale` = 'frFR' AND (l.`QuestDescription` IS NULL OR l.`QuestDescription` = '' OR BINARY l.`QuestDescription` = BINARY q.`QuestDescription`);
